To establish a connection between $\E$-martingales and the vertical Dupire derivative, we have to extend the path space $\cX=C(\R;X)$ to  the space $\mathscr{X}_{\mathrm{D}}\coloneqq D(\R, X)$   of all \emph{c\`adl\`ag paths} from $\R$ to $X$, endowed with Skorohod's $J_1$-metric. For the definition of the metric in $\mathscr{X}_{\mathrm{D}}$, we refer to \cite[Appendix B.2]{dkk}.

\begin{defn}
Let $V: [0,T] \to C_b(\mathscr{X}_{\mathrm{D}})$ be adapted. We say that $V$ is \emph{vertically differentiable in the Dupire sense}
if for every $t\in [0,T]$, every $v\in X=\R^d$,  and every $\x\in\mathscr{X}_{\mathrm{D}}$ the limit
\[
\partial_{\x}^v V(t) \coloneqq \lim_{h\downarrow 0} \frac{V(t, \tau^t(\x)+ h v\one_{[t,\infty)}) - V(t,\x)}{h}
\]
exists. In this case, the function $\partial_{\x}^v V$ is called the \emph{vertical Dupire  derivative} of $V$ in direction $v$,
and we define 
\[ \nabla_\x V := \big( \partial_\x^{e_j} V\big)_{j=1,\dots,d}\,,\]
where $e_j,\,j=1,\dots, d$, denotes the $j$-th unit vector in $\R^d$. The second vertical derivative 
\[ \nabla_\x^2 V = \big( \partial_\x^{e_j}  \partial_\x^{e_k}V\big)_{j,k=1,\dots,d}\]
 is defined by iteration. The function $V$ is said to be of class $\C^{1,2}(\cX_{\mathrm D})$ if the derivatives $\dt V$, $\nabla_\x V$
and $\nabla_{\x}^2V$ exist and are jointly continuous in $(t,\x)\in [0,T]\times \cX_{\mathrm D}$ (see \cite[Section~1.3]{Cont-Perkowski19} for details). If additionally the restrictions of these derivatives to $\cX$ belong to $C_{b,\mathrm{loc}}([0,T)\times\cX)$,
we write $V\in \C^{1,2}(\cX_{\mathrm D})\cap \C^{1,2}_{b,\mathrm{loc}}(\cX)$.
In the following, $\operatorname{tr}(\cdot)$ stands for the trace of a matrix.
\end{defn}
% \color{blue}
% Is $\C^{1,2}(\cX_{\mathrm D})\cap \C^{1,2}(\cX)$ still a good name? Maybe better $\C^{1,2}(\cX_{\mathrm D})\cap \C^{1,2}_{b,\mathrm{loc}}(\cX)$
% \color{black}

\begin{thm}\label{Thm:Ito-Dupire}
    Let $V\colon [0,T]\to C_b(\cX)$ be adapted, and assume that for each $t\in [0,T]$, the function $V(t)$ admits an extension to $V(t)\in C_b(\cX_{\mathrm D})$ such that $V$ is of class $\C^{1,2}(\cX_{\mathrm D})\cap \C^{1,2}_{b,\mathrm{loc}}(\cX)$. Let $\E$ be the expectation operator related to the It\^o diffusion \eqref{eq-sde} as discussed above. 
    \begin{enumerate}
[\upshape (a)]
\item Define 
   \[ \Psi(t,\x) := \dt V(t,\x)+\langle b(\x(t)), \nabla_\x V(t,\x)\rangle 
   + \tfrac 12\operatorname{tr} \Big( \sigma(\x(t))\sigma(\x(t))^\top \nabla_\x^2 V(t,\x)\Big).\]
   Then $\Psi\in C_{b,\mathrm{loc}}([0,T)\times \cX) \cap \mathfrak{L}^1(0,T;C_b(\cX))$ is adapted 
   and  $M(t):=V(t)-\int_0^t \Psi(s)\,ds$ is an $\E$-martingale.
\item $V$ is continuously $\E$-differentiable with $\partial_t^\E V = \Psi$, and $U(t):= \Theta_{-t}V(t)$ is the unique continuous 
mild solution of the FVP \eqref{eq:FVP:A*}. 
\item $V$ is an $\E$-martingale if and only if for all $\x\in \cX$, $V$ is a solution of the Dupire equation
   \[ \dt V(t,\x) + \langle b(\x(t)), \nabla_\x V(t,\x)\rangle 
   + \tfrac 12\operatorname{tr} \Big( \sigma(\x(t))\sigma(\x(t))^\top \nabla_\x^2 V(t,\x)\Big)=0.\]
\end{enumerate}
\end{thm}

We remark that this result also yields a description of the operator $\A-\mathbb{L}$. Assume that in the 
situation of Theorem~\ref{Thm:Ito-Dupire}, the pointwise classical derivative of  $U(t):=\Theta_{-t} V(t)$ 
exists on $[0,T)$ and belongs to $C_{b,\mathrm{loc}}([0,T)\times X)$. Then we can apply Theorem~\ref{t.martDupire}
and get
\begin{align*}
& \big(\Theta_t (\A-\mathbb{L} ) \Theta_{-t} V\big) (t,\x) =  \Psi(t,\x)-\dt V(t,\x) \\
& \qquad =
\langle b(\x(t)), \nabla_\x V(t,\x)\rangle 
   + \tfrac 12\operatorname{tr} \Big( \sigma(\x(t))\sigma(\x(t))^\top \nabla_\x^2 V(t,\x)\Big).
\end{align*}
For $F:= U(t)$ with fixed $t\in [0,T]$, this implies
\[ (\A-\mathbb L)F(\x) = \langle b(\x(0)), \nabla_\x^0 F(\x)\rangle 
   + \tfrac 12\operatorname{tr} \Big( \sigma(\x(0))\sigma(\x(0))^\top (\nabla_\x^0)^2 F(\x)\Big).\]
Here, $\nabla_\x^0$ stands for the vertical Dupire derivative at $t=0$, i.e.,
\[ \nabla_{\x}^0 F (\x)\coloneqq \Big(\lim_{h\downarrow 0} \frac{F(\tau(\x)+ h e_j\one_{[0,\infty)})- F(\x)} {h}\Big)_{j=1,\dots,d}\,,\]
and $ (\nabla_\x^0)^2 $ is defined by iteration.


\begin{proof}[Proof of Theorem~\ref{Thm:Ito-Dupire}]
    (a). By the conditions on $V$ and on the coefficients $b$ and $\sigma$, we immediately get that $\Psi\in C_{b,\mathrm{loc}}([0,T)\times \cX)\cap \mathfrak{L}^1(0,T;C_b(\cX))$. 
    It is easily seen that $\nabla_\x V$ and $\nabla_\x^2V$ are 
    adapted.    To show that $M$ is an $\E$-martingale, we apply Lemma~\ref{l.pmartingale}. For this, we note that, as $\sigma\sigma^\top$ is uniformly positive definite, we can apply the support theorem of Stroock--Varadhan \cite[Theorem~3.1]{Stroock-Varadhan72} to see that $P\circ (X^{x})^{-1}$ has full support $\{\x^+\in \cX^+: 
    \x(0)=x\}$ for all $x\in X$. Therefore, we can argue as in Example~\ref{Ex:4.5} to see that 
    $\E|F|=0$ implies $F=0$ for $F\in C_b(\cX)$. 

    It remains to show that $M$ is a $\P^\x$-martingale for all $\x\in\cX$. As explained above, this is equivalent to the condition that $M(\cdot, \x\otimes_0 X^{\x(0)})$ is a $P$-martingale for all $\x\in\cX$. To prove this, we apply the pathwise 
    It\^o formula for path-dependent functionals (\cite[Theorem~3]{Cont-Fournie10}, see also \cite[Theorem~1.10]{Cont-Perkowski19}) and obtain for all paths $\y = \x\otimes_0 X^{\x(0)}$ 
    \begin{equation}\label{eq:6.8}
    \begin{aligned}
        V(t,\y) - V(0,\y) & = \int_0^t  \dt V(s,\y) \mathrm{d}s+ 
        \int_0^t \tfrac12  \operatorname{tr} \big( \nabla_\x^2 V(s,\y) \mathrm{d}[\y]_s\big) \\
        & \quad + \int_0^t \langle\nabla_\x V(s,\y) \mathrm{d}\y(s)\rangle .
    \end{aligned}
    \end{equation}
    For general paths $\y$ with finite quadratic variation, the last integral is defined as the limit over Riemannian sums. However, as we can see from \cite[Proposition~7]{Cont-Fournie10}, for 
    continuous semi-martingales, this coincides with the It\^o integral. Using \eqref{eq-sde}, the last integral
    in \eqref{eq:6.8} equals
    \[ \int_0^t \langle b(\y(s)), \nabla_\x V(s,\y)\rangle  \mathrm{d}s
    + \int_0^t \langle \nabla_\x V(x,\y), \sigma(\y(s)) \mathrm{d}B_s\rangle.\]
Moreover, it is known that for the It\^o diffusion, the quadratic variation
is given by 
\[  [\y]_t =  \int_0^t \sigma(\y(s))\sigma(\y(s))^\top \mathrm{d}s.\]
With this and the definition of $\Psi$, we see that 
\[ M(t,\y)-M(0,\y) = \int_0^t \langle \nabla_\x V(x,\y), \sigma(\y(s)) \mathrm{d}B_s\rangle\quad  \text{ for } \y=\x\otimes X^{\x(0)},\]
and therefore $M$ is a $\P^\x$ martingale for all $\x\in\cX$. Now we can apply Lemma~\ref{l.pmartingale} to get a).


(b). This follows from Theorem~\ref{t:Edifferentiable}.

(c). Due to (a), $V$ is an $\E$-martingale if and only if $t\mapsto \int_0^t\Psi(s)\mathrm{d}s$ is an $\E$-martingale. 
By Corollary~\ref{cor:quadraticvariation}, this is equivalent to $\int_0^\cdot \Psi(s)\mathrm{d}s \equiv 0$ and therefore to $\Psi\equiv 0$.
\end{proof}


\begin{rem}
   a)  The above theorem shows, in particular, that every solution of the Dupire equation is directly connected with a mild solution of \eqref{eq:FVP:A*} and therefore with the semigroup $\S$. Here, the rather strong assumptions on the smoothness of $V$ are only needed for the formulation of the Dupire equation and the application of the It\^o formula for path-dependent functionals, whereas the connection between $\E$-martingales and mild solutions hold in a very general setting. 

   b) In the case where the It\^o diffusion is given by the one-dimensional Brownian motion, one obtains the path-dependent heat equation 
   \[ \dt V(t,\x) + \partial_{\x}^2 V(t,\x) = 0\]
   which was considered, e.g.,  in \cite{Peng-Song-Wang23}, where we write $\partial_\x$ instead of $\nabla_\x$ 
   if $d=1$. 
\end{rem}

\begin{example}\label{Ex:Support-condition}
The following example illustrates the role of the support condition on $\E$. Consider \eqref{eq-sde} for $d=1$
with $\sigma\equiv 0$ and with $b\colon\R\to\R$ being a bounded and strictly decreasing Lipschitz function with
$b(0)=0$
(e.g., $b(x)=-\arctan x$). Then $X^x$ is the unique solution of the ordinary differential equation
\[ \frac{d}{dt}\, X^x_t = b(X^x_t),\quad X_0^x=x.\]
Due to the sign condition on $b$, we see that for initial value $x\in\R$, the function
$t\mapsto |X_t^x|$ is decreasing on $[0,\infty)$. We define, e.g., 
\[ V(t,\x) :=  \min\{ (|\x(t)|-|\x(0)|)^+, 1\}\]
for $t\in [0,T]$ and $\x\in\cX$. Then $V\colon[0,T]\to C_b(\cX)$ is adapted, and 
\[ V(t,\x\otimes_0 X^{\x(0)}) = 0\]
for all $t\in [0,T]$ and $x\in\cX$. Therefore, $V$ is a $\P^\x$-martingale for all $\x\in\cX$. However, for 
$\x(t)=t$, we get \[\E V(t,\x) = V(t, \x\otimes_0 X^{\x(0)}) = V(t,\x\otimes_0 0)=0 < \min\{t,1\} = V(t,\x)\]
for $t\in (0,T]$. Therefore, $V$ is no $\E$-martingale.

Similarly, let $V$ be a smooth function  as in Theorem~\ref{Thm:Ito-Dupire}, and assume that 
 $V$ is a $\P^\x$-martingale for all $\x\in \cX$. Then the Dupire equation in Theorem~\ref{Thm:Ito-Dupire} (c)
is satisfied for all paths of the form $\x\otimes_0 X^{\x(0)}$, but in general not for all $\x\in\cX$.
\end{example}



