\title{Controllable Sequences of Minimal Length for Discrete-Time Switched Linear Control Systems.}

\author{Paolo Mason and Antoine Girard\thanks{Universit\'e Paris-Saclay, CNRS, CentraleSup\'elec,  Laboratoire des signaux et syst\`emes, 91190, Gif-sur-Yvette, France, {\tt paolo.mason@centralesupelec.fr, antoine.girard@centralesupelec.fr}}}


