\subsection{The proof of \cref{prop:Frechet_derivative}}\label{proof:G_F_diff}
\begin{proof}
 For any $(\bdomega,\bx)\in\mathbb{T}^n$, $K^{[q]}(\bdf)(\bdomega,\bx)$ can be rewritten as the function $H_q:\Real^D\rightarrow\Real$ which is given by
    \begin{align*}
       \bdz &\longmapsto \ln \int_{0}^{E_{\max}} s^{[q]}(E)\exp\left(-\sum_{d=1}^D  b_d(E) z_d \right)\rmd E,
    \end{align*}
    where $\bdz=[z_1,\ldots,z_D]^{\tra}$ and $z_d=\Xray f_d(\bdomega,\bx)$. It is easy to compute that 
    \begin{equation}\label{eq:partial_Hq}
        \frac{\partial H_q(\bdz)}{\partial z_d} = -\int_{0}^{E_{\max}} \frac{s^{[q]}(E)\exp\left( -\sum_{d=1}^D  b_d(E) z_d\right)}{ \int_{0}^{E_{\max}} s^{[q]}(E)\exp\left(-\sum_{d=1}^D  b_d(E) z_d \right) \rmd E} b_d(E)\rmd E.
    \end{equation} 
    By \cref{eq:partial_Hq} and the nonnegative bounded property of functions $\{b_d\}_{d=1}^D$, we have 
    \begin{equation}\label{eq:nabla_Hq}
        \|\nabla H_q(\bdz)\|_1 =\sum_{d=1}^D \left|\frac{\partial H_q(\bdz)}{\partial z_d}\right| \le \sum_{d=1}^D \sup_{E} b_d(E).
    \end{equation} 
    Notice that $K^{[q]}(\bzero)(\bdomega,\bx)=0$ for any $(\bdomega,\bx)\in\mathbb{T}^n$, and using  \cref{eq:nabla_Hq}, we obtain  
    \begin{multline}\label{eq:K_qf}
        \big{|} K^{[q]}(\bdf)(\bdomega,\bx) \big{|}  = \big{|} K^{[q]}(\bdf)(\bdomega,\bx)-K^{[q]}(\bzero)(\bdomega,\bx)\big{|}    =\left|H_q(\bdz) - H_q(0) \right|\\ \le \left(\sup_{\bdz}\|\nabla H_q(\bdz)\|_1\right)\|\bdz\|_1 \le \left(\sum_{d=1}^D \sup_{E} b_d(E)\right) \sum_{d=1}^D\left|\Xray f_d(\bdomega,\bx)\right|. 
    \end{multline}
    Consequently, for any $\bdf\in\mathcal{F}^D$, by \cref{eq:K_qf}, we have 
    \begin{align*}
        \|K^{[q]}(\bdf)\|_{\mathcal{G}} &= \left(\int_{\mathbb{S}^{n-1}}\int_{\bdomega^{\perp}} \big{|}  K^{[q]}(\bdf)(\bdomega,\bx) \big{|}^2  \rmd \boldsymbol{\mu}_{\bx} \rmd \bdomega\right)^{1/2} \\
        &\le  \left(\sum_{d=1}^D \sup_{E} b_d(E)\right) \left( \int_{\mathbb{S}^{n-1}}\int_{\bdomega^{\perp}} \Bigl(\sum_{d=1}^D \left|\Xray f_d(\bdomega,\bx)\right|\Bigr)^2 \rmd \boldsymbol{\mu}_{\bx} \rmd \bdomega \right)^{1/2} \\
        &\le  \sqrt{D}\left(\sum_{d=1}^D \sup_{E} b_d(E)\right) \left( \int_{\mathbb{S}^{n-1}}\int_{\bdomega^{\perp}} \sum_{d=1}^D \left|\Xray f_d(\bdomega,\bx)\right|^2 \rmd \boldsymbol{\mu}_{\bx} \rmd \bdomega \right)^{1/2} \\
        &\le \sqrt{D}\left(\sum_{d=1}^D \sup_{E} b_d(E)\right) \sum_{d=1}^D \|\Xray f_d\|_{\mathcal{G}}, 
    \end{align*}
    where $\rmd \boldsymbol{\mu}_{\bx}$ denotes the Euclidean measure on the hyperplane $\bdomega^{\perp}$. Since $\Xray f_d\in\mathcal{G}$ for each $d$, we obtain $K^{[q]}(\bdf)\in\mathcal{G}$. 

    For any $\bdh=[h_1,\ldots,h_D]^{\tra}  \in \mathcal{F}^D$, by the chain rule, we compute 
    \begin{equation}\label{eq:G_derivative_K}
    \partial_{\varepsilon} K^{[q]} (\bdf + \varepsilon \bdh)\mid_{\varepsilon=0} = - \int_0^{E_{\max}}  \Phi^{[q]}(\bdf; E) \left( \sum_{d=1}^D b_d(E) \Xray h_d\right) \rmd E,
    \end{equation}
    where $\Phi^{[q]}(\bdf; E)$ is given as in \cref{eq:Phi_f} such that  
    \[\int_{0}^{E_{\max}} \Phi^{[q]}(\bdf; E) \rmd E = 1 \quad \text{for}~ q=1,\ldots,Q.
    \]
    Then, from \cref{eq:G_derivative_K}, we have the following estimate 
    \begin{align}\label{eq:G_derivative_K_estimate}
    \big\|\partial_{\varepsilon} K^{[q]} (\bdf + \varepsilon \bdh)\mid_{\varepsilon=0}\big\|_{\mathcal{G}}&=\big\|\sum_{d=1}^D \int_0^{E_{\max}}  \Phi^{[q]}(\bdf; E) b_d(E)  \Xray h_d \rmd E\big\|_{\mathcal{G}}\\ &\le \left(\sup_{d,E} b_d(E)\right)\sum_{d=1}^D \big\| \int_0^{E_{\max}}  \Phi^{[q]}(\bdf; E)  \Xray h_d \rmd E\big\|_{\mathcal{G}} \nonumber\\ &= \left(\sup_{d,E} b_d(E)\right) \sum_{d=1}^D \left\|\Xray h_d\right\|_{\mathcal{G}}\nonumber\\
    &\le \left( \sup_{d,E} b_d(E)\right) C  \sum_{d=1}^D \|h_d\|_{\mathcal{F}}.\nonumber
    \end{align}
Note that the last inequality follows readily from the result in \cite[theorem 2.10]{natterer2001mathematical}, and   the $C$ is a positive constant depending only on the $\alpha = -1/2$ and the domain $\domain$. Hence, using \cref{eq:G_derivative_K} and \cref{eq:G_derivative_K_estimate}, we conclude that $K^{[q]}$ is G\^ateaux differentiable, and its G\^ateaux derivative is computed as \cref{eq:Frech_deriva}. 

Furthermore, from the continuity of $\Xray$, it is easy to obtain that the mapping $\bdf \mapsto \Diff K^{[q]} (\bdf,\cdot)$ is continuous. By \cite[proposition 3.2.15]{Nonlinear_ana07}, $K^{[q]}$ is Fréchet differentiable and its Fréchet derivative is equal to $\Diff K^{[q]}(\bdf,\cdot)$. By the definition of the norm of Cartesian space, we can further prove that $\bdK$ is also Fréchet differentiable. 
\end{proof}

\subsection{The proof of \cref{lem:continuous}}\label{proof:cc_lemma}
\begin{proof}    
For any $\bdf$ and $(\bdomega,\bx)$, we can define the matrix 
\[
\Psi(\bdf)(\bdomega,\bx) := \bigl(\psi^{[q]}_d(\bdf)(\bdomega,\bx)\bigr)\in\Real^{Q\times D},
\] 
where
\begin{equation*}
    \psi^{[q]}_d(\bdf)(\bdomega,\bx) = \int_{0}^{E_{\max}} \Phi^{[q]}(\bdf; E)(\bdomega,\bx) b_d(E)\rmd E.
\end{equation*}
Since $\Phi^{[q]}(\bdf; \,\cdot\,)$ as given in \cref{eq:Phi_f} is a nonnegative normalized function with respect to $E$, together with the given conditions, we have
\begin{align*}
    \|\Psi(\bdf)(\bdomega,\bx) - \bvarphi\|_F^2&=\sum_{q=1}^Q \sum_{d=1}^D \left(\int_0^{E_{\max}}  \big(\Phi^{[q]}(\bdf; E)(\bdomega,\bx) - \Phi^{[q]}(\hat{\bdf}; E)\big)  b_d(E) \rmd E\right)^2\\
    &\le \eta^2 \sum_{q=1}^Q \sum_{d=1}^D \left(\int_0^{E_{\max}}  \Phi^{[q]}(\hat{\bdf}; E) b_d(E) \rmd E\right)^2 = \eta^2 \|\bvarphi\|_F^2.
\end{align*}
Subsequently, for any $\bdz\in\Real^D$, by Cauchy--Schwarz inequality and the property of matrix norm, we have
\begin{align*}
\|(\Psi(\bdf)(\bdomega,\bx)- \bvarphi)\bdz\|_2 
&\le \|\Psi(\bdf)(\bdomega,\bx)- \bvarphi\|_2  \|\bdz\|_2 
\le \|\Psi(\bdf)(\bdomega,\bx)- \bvarphi\|_F \|\bdz\|_2 \\
& \le \eta\|\bvarphi\|_F \|\bdz\|_2 \le \eta\kappa_F(\bvarphi) \|\bvarphi\bdz\|_2.
\end{align*}
Hence, for any $\bdf,\bdh\in\mathcal{F}^D$, based on the formula of Fréchet derivative of $\bdK$ and the above estimation, we obtain
\begin{align*}
\big\| \Diff \bdK(\bdf,\bdh) - \Diff \bdK(\hat{\bdf},\bdh)\big\|_{\mathcal{G}^Q}^2 &= \int_{\mathbb{S}^{n-1}} \int_{\bdomega^{\perp}} \left\|\left(\Psi(\bdf)(\bdomega,\bx)- \bvarphi\right)\bXray\bdh(\bdomega,\bx)\right\|_2^2 \rmd \boldsymbol{\mu}_{\bx} \rmd \bdomega \\
&\le \int_{\mathbb{S}^{n-1}} \int_{\bdomega^{\perp}} (\eta\kappa_F(\bvarphi))^2 \|\bvarphi\bXray\bdh(\bdomega,\bx)\|_2^2 \rmd \boldsymbol{\mu}_{\bx} \rmd \bdomega \\
&= (\eta\kappa_F(\bvarphi))^2 \|\Diff \bdK(\hat{\bdf},\bdh)\|_{\mathcal{G}^Q}^2,
\end{align*}
where $\bXray\bdh(\bdomega,\bx)=[\Xray h_1(\bdomega,\bx),\ldots,\Xray h_D(\bdomega,\bx)]^{\tra}\in\Real^D$. The desired result is obtained. 
\end{proof}

\subsection{The proof of \cref{lem:discrete}}\label{proof:dd_lemma}
\begin{proof}
    Notice that for any $\mtbf$, $\mtbw_j^{[q]}(\mtbf) \ge\bzero$ and $\bigl({\mtbw_j^{[q]}(\mtbf)}\bigr)^{\tra} \boldsymbol{1}=1$, which means that $\mtbw_j^{[q]}(\mtbf) \in \Real^M_+ $ is in the unit simplex. Hence, by the gradient calculation in \cref{subsubsec:dd_alg}, and using the given conditions, we obtain
    \begin{align*}
        \big\|\nabla \mtbK(\hat{\mtbf}) - \nabla \mtbK(\mtbf)\big\|_F^2 =& \sum_{q=1}^Q \sum_{j=1}^{J_q} \|\nabla K_j^{[q]}(\hat{\mtbf}) - \nabla K_j^{[q]}(\mtbf)\|_2^2\\ 
        =& \sum_{q=1}^Q \sum_{j=1}^{J_q} \sum_{d=1}^D |\big(\mtbw_j^{[q]}(\hat{\mtbf}) - \mtbw_j^{[q]}(\mtbf)\big)^{\tra} \mtbb_d \mtbp^{[q]}_j |^2 \\ 
        =& \sum_{q=1}^Q \sum_{j=1}^{J_q} \sum_{d=1}^D |\mtbb_d^{\tra} {\hat{\mtbw}}^{[q]} - \mtbb_d^{\tra}{\mtbw_j^{[q]}(\mtbf)} |^2 \|\mtbp^{[q]}_j\|_2^2 \\ 
        \le&\sum_{q=1}^Q \sum_{j=1}^{J_q} \sum_{d=1}^D \tilde{\eta}^2 |\mtbb_d^{\tra} \hat{\mtbw}^{[q]} |^2 \|\mtbp^{[q]}_j\|_2^2 \\ 
        =& \tilde{\eta}^2\|\nabla \mtbK(\hat{\mtbf})\|_F^2.
    \end{align*}
    Consequently, by the property of the matrix norm, the above estimate in order, we have 
    \begin{align*}
        \big\|\nabla \mtbK(\hat{\mtbf})\bdh - \nabla \mtbK(\mtbf)\mtbh\big\|_2 &\le \|\nabla \mtbK(\hat{\mtbf}) - \nabla \mtbK(\mtbf)\|_F \|\mtbh\|_2 
        \le \tilde{\eta} \|\nabla \mtbK(\hat{\mtbf})\|_F \|\mtbh\|_2 \\ 
        &\le \tilde{\eta} \|\nabla \mtbK(\hat{\mtbf})\|_F \sigma_{\min}^{-1}\bigl(\nabla \mtbK(\hat{\mtbf})\bigr) \|\nabla \mtbK(\hat{\mtbf})\mtbh\|_2 \\ 
        &= \tilde{\eta} \kappa_F(\mtbP\otimes \bphi) \|\nabla \mtbK(\hat{\mtbf})\mtbh\|_2,
    \end{align*}
which completes the proof.
\end{proof}


