\section{The Taylor dg algebra}\label{s_taylor_tate}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Fix an ideal $I$ generated by $\f=f_1,\ldots,f_n$ in a unique factorization domain $Q$. 
When $Q$ is a polynomial ring over a field and $f_1, \ldots, f_n$ are monomials, there is a well-known construction of Taylor~\cite{Taylor} producing a dg algebra resolution for $Q/I$. We will use this construction in a more general setting.

\begin{notation}\label{signnotation}
Let $[n]$ denote the ordered set $\{ 1, \ldots, n \}$. All subsets $J = \{j_1, \ldots, j_s\} \subseteq [n]$ inherit an ordering $j_1 < \cdots < j_s$ from $[n]$.
The cardinality of $J$ is denoted by $|J|=s$. 
If $J$ and $L$ are disjoint subsets of $[n]$, we write
\vspace{-0.8em}
    \[
    {\sgn(J,L)}=(-1)^\varepsilon \quad \text{where}\quad \varepsilon = \left| \{(j,\ell) \,:\, j\in J,\ \ell\in L, \text{ and } j>\ell\}\right|.
    \]
When $J$ and $K$ are not disjoint, we set $\sgn(J,K) = 0$.
These signs satisfy 
    \[ \sgn(J,L)\sgn(L,J)=(-1)^{|J||L|} \vspace{-0.5em}\]
    and 
\[ \sgn(J,K)\sgn(J,L)=\sgn(J, K \cup L) \quad \text{for mutually disjoint } J, K, L \subseteq[n].\]
\end{notation}

\begin{construction}\label{taylor}
Let $Q$ be a UFD and let $f_1, \ldots, f_n \in Q$ be such that $I = (f_1, \ldots, f_n)$ is a proper ideal of $Q$.
We can choose a finite list of nonassociate irreducibles $x_1,\ldots, x_d$ so that each $f_j$ can be written as
\[
f_j = u_j x_1^{a_{j1}} \cdots x_d^{a_{jd}} \quad \text{ for some }a_{ji} \geqslant 0 \text{ and some } u_j \in Q^\times\,.
\]
Given a subset $J$ of $[n]$, set
\[
f_J\colonequals x_1^{a_{J1}}\cdots x_d^{a_{Jd}}\quad\text{where }a_{Ji}=\max\{a_{ji}:j\in J\}\,.
\]
In particular, $f_j=u_jf_{\{j\}}$. 

The \textbf{Taylor complex on $\f$} (with respect to $x_1,\ldots,x_d$) is a  free $Q$-complex $T=T(\f)$, defined as follows. As a free graded $Q$-module, $T^\natural =\bigwedge_Q (\shift Q^{\oplus n}),$ where we fix the basis in degree $i$ given by
\[
\{b_J: J\subseteq[n]\text{ with }|J|=i\}\,.
\]
The differential on $T$ is the $Q$-linear map determined by 
\[
\partial(b_J) = \sum_{i=1}^s (-1)^{i-1} \, \frac{f_J}{f_{J \smallsetminus \{ j_i \}}} \, b_{J \smallsetminus \{ j_i \}}\quad \text{with }J=\{j_1 < \cdots < j_s\}\,.
\]
We equip the Taylor complex with a $Q$-bilinear product, defined on basis elements by
\[
b_J\cdot b_{K} = {\sgn(J,K)} \,  \frac{f_J f_{K}}{f_{J\cup K}} \, b_{J\cup K}\,.
\]
Note that 
\[
b_J\cdot b_{K}=0 \quad \text{if } J \cap K \neq \varnothing.
\]
\end{construction}

\begin{remark}\label{remark product in taylor gcd}
Note that, up to a unit, ${f_J f_{K}}/{f_{J\cup K}}=\gcd(f_J, f_K)$.
\end{remark}

While Taylor's original construction is written for the case of monomials, the standard proof that $T$ is a dg algebra applies more generally \cite{Taylor}:

\begin{proposition}
The Taylor complex $T = T(\f)$ of \cref{taylor} is a dg $Q$-algebra with $\H_0(T)=Q/(\f)$.
\end{proposition}
\begin{proof}
  First, we check $T$ is a complex. To this end, observe that given $J=\{j_1, \ldots, j_s\}$ with $j_1<\cdots<j_s$ we have 
    \begin{align*}\del^2(b_J)&=\sum_{i=1}^s(-1)^{i-1} \frac{f_J}{f_{J \smallsetminus \{ j_i \}}} \, \del(b_{J \smallsetminus \{ j_i \}})\\
    &=\sum_{i=1}^s(-1)^{i-1} \, \frac{f_J}{f_{J \smallsetminus \{ j_i \}}}\left(\sum_{1\les \ell<i} (-1)^{\ell-1} \, \frac{f_{J\smallsetminus \{j_i\}}}{f_{J \smallsetminus \{ j_i,j_\ell \}}} \, b_{J \smallsetminus \{ j_i,j_\ell \}} +\sum_{i< \ell\les s} (-1)^{\ell} \,\frac{f_{J\smallsetminus \{j_i\}}}{f_{J \smallsetminus \{ j_i,j_\ell \}}} \, b_{J \smallsetminus \{ j_i,j_\ell \}} \right)  \\
    &=\sum_{1\les \ell< i \les s}
    (-1)^{i+\ell} \, \frac{f_J}{f_{J\smallsetminus \{j_i\}}}
    \frac{f_{J\smallsetminus \{j_i\}}}{f_{J \smallsetminus \{ j_i,j_\ell \}}} \, b_{J \smallsetminus \{ j_i,j_\ell \}}+ 
    (-1)^{i+\ell-1} \, \frac{f_J}{f_{J\smallsetminus \{j_\ell\}}}\frac{f_{J\smallsetminus \{j_\ell\}}}{f_{J \smallsetminus \{ j_i,j_\ell \}}}\, b_{J \smallsetminus \{ j_i,j_\ell \}}\\
    &=0.
    \end{align*}
    The last equality follows from
    \vspace{-0.5em}
    \[
    \frac{f_J}{f_{J\smallsetminus \{j_i\}}}
    \frac{f_{J\smallsetminus \{j_i\}}}{f_{J \smallsetminus \{ j_i,j_\ell \}}}=\frac{f_J}{f_{J\smallsetminus \{j_\ell\}}}\frac{f_{J\smallsetminus \{j_\ell\}}}{f_{J \smallsetminus \{ j_i,j_\ell \}}}.
    \]
This shows that $T$ is a complex. 
Moreover, since $\del(b_{\{i\}})=f_i$ up to unit multiple, then $\H_0(T)=Q/(\f)$.

    To prove that the product is associative, by $Q$-linearity it suffices to check that
    \[
    (b_J\cdot b_{K})\cdot b_{L} =  b_J\cdot (b_{K}\cdot b_{L})
    \]
    for all subsets $J,K,L\subseteq [n]$. If $J$, $K$, and $L$ are not pairwise disjoint, both sides are zero by definition, and the equality follows, so we may assume that $J$, $K$, and $L$ are pairwise disjoint. The desired equality becomes
    \[
    {\sgn(J,K)\sgn(J\cup K,L)} \, \frac{f_J f_{K} f_{J\cup K} f_L }{f_{J\cup K} f_{{J\cup K\cup L}}} = {\sgn(J,K\cup L)\sgn(K,L)} \, \frac{f_J  f_{K\cup L} f_{K} f_L }{f_{{J\cup K\cup L}} f_{K\cup L} }\,.
    \]
    Note that this does indeed hold, as sign rules of \cref{signnotation} give
    $${\sgn(J,K)\sgn(J\cup K,L)} = {\sgn(J,K\cup L)\sgn(K,L)}$$
    and two fractions simplify to the same. 


    It only remains to check that the Leibniz rule holds, and for this there are three cases to consider. If $J\cap K$ contains at least two elements then by definition
    \[
    \partial(b_J\cdot b_{K})=\partial(0)=0 \quad \text{and}\quad \partial(b_J)\cdot b_{K} + (-1)^{|J|} b_J\cdot \partial(b_{K})=0.
    \]
    If there is exactly one element $j\in J\cap K$ then $\partial(b_J\cdot b_{K})=0$, while
\begin{align*}
    \partial(b_J)\cdot b_{K} + (-1)^{|J|} b_J\cdot \partial(b_{K}) &= \sgn( \{ j \},J\smallsetminus \{ j \}) \frac{f_J}{f_{J\smallsetminus \{j\}}} b_{J \smallsetminus \{ j \}} \cdot b_{K} \\
    &\hspace{10mm} + (-1)^{|J|}\sgn(\{j\},K\smallsetminus \{ j \})\frac{f_K}{f_{K\smallsetminus \{j\}}} b_{J}\cdot b_{K \smallsetminus \{ j \}}\\
    &= \sgn( \{ j \},J\smallsetminus \{ j \})\sgn(J\smallsetminus \{j\},K)\frac{f_J f_{J \smallsetminus \{ j \}}f_{K}}{f_{J \smallsetminus \{ j \}}f_{J\cup K\smallsetminus \{j\}}}  b_{J\cup K\smallsetminus \{j\}}\\
    &\hspace{10mm} +(-1)^{|J|}\sgn(\{j\},K\smallsetminus \{ j \})\sgn(J,K\smallsetminus \{j\})\frac{f_J f_{K}f_{K \smallsetminus \{ j \}}}{f_{J\cup K\smallsetminus \{j\}}f_{K \smallsetminus \{ j \}}}   b_{J\cup K\smallsetminus \{j\}}\\
    &= (-1)^{|J\smallsetminus\{j\}|}\sgn(J\smallsetminus \{j\},K\smallsetminus \{j\})\frac{f_J f_{J \smallsetminus \{ j \}}f_{K}}{f_{J \smallsetminus \{ j \}}f_{J\cup K\smallsetminus \{j\}}}  b_{J\cup K\smallsetminus \{j\}}\\
    &\hspace{10mm} +(-1)^{|J|}\sgn(J\smallsetminus\{j\},K\smallsetminus \{ j \})\frac{f_J f_{K}f_{K \smallsetminus \{ j \}}}{f_{J\cup K\smallsetminus \{j\}}f_{K \smallsetminus \{ j \}}}   b_{J\cup K\smallsetminus \{j\}}\\
    &=0\,.
\end{align*}
Here we have combined signs using the rules from \cref{signnotation}. 
Finally, we verify the Leibniz rule when $J\cap K=\varnothing$. In this case
\begin{align*}
    \partial(b_J\cdot b_{K}) &= {\sgn(J,K)} \partial\left(\frac{f_J f_{K}}{f_{J\cup K}}  \, b_{J\cup K}\right)\\
    &= {\sgn(J,K)} \sum_{j\in J\cup K} \sgn(\{j\},J\cup K) \frac{f_{J\cup K}f_J f_{K}}{f_{J \cup K\smallsetminus \{ j \}}f_{J\cup K}} \, b_{J\cup K\smallsetminus\{j\}}\\
    &= {\sgn(J\smallsetminus\{j\},K)} \sum_{j\in J} \sgn(\{j\},J) \frac{f_{J\cup K}f_J f_{K}}{f_{J \cup K\smallsetminus \{ j \}}f_{J\cup K}} \, b_{J\cup K\smallsetminus\{j\}}\\
    &\hspace{15mm}  + {\sgn(J,K)} \sum_{j\in K} \sgn(\{j\},K) (-1)^{|J|}\frac{f_{J\cup K}f_J f_{K}}{f_{J \cup K\smallsetminus \{ j \}}f_{J\cup K}} \, b_{J\cup K\smallsetminus\{j\}}\\
    &= \partial(b_J)\cdot b_{K} + (-1)^{|J|} b_J\cdot \partial(b_{K})\,,
\end{align*}
again making use of the sign tricks from \cref{signnotation}.
\end{proof}

\begin{example}\label{e_taylor_2}
When $n=2$, then $T = T(\f)$ can be taken to have the form
\[
    0 \to
    Q\xra{\begin{pmatrix} -f_2'\\f_1' \end{pmatrix}}
    Q^2 \xra{\begin{pmatrix} f_1 & f_2\end{pmatrix}}
    Q \to
    0
  \]
  where $f_i=df_i'$ for $d$ a greatest common divisor of $f_1,f_2$; cf.\@ \cref{e_homotopies}. In particular, note that $T$ is the minimal free resolution of $R.$ The dg algebra structure describe in \cref{taylor}, is the same as the one viewing the complex above as a Hilbert--Burch resolution (see, for instance, \cite[Example~2.1.2]{Avramov:2010}). 
  \end{example}

\begin{remark}
\label{taylor_resolution}
    When $\f$ is a $Q$-regular sequence, the Taylor complex $T$ on $\f$ is the Koszul complex and hence a free resolution of $Q/(\f)$ over $Q$. Moreover, whenever $\f$ is a list of monomials in a regular sequence, the complex $T$ is a free resolution of $Q/(\f)$ over $Q$; this is a well-known result of Taylor \cite{Taylor}. Note however that $T$ can be a resolution even when $\f$ is not of this form; see \cref{e_taylor_2} below. There are however many examples where $\H_i(T)\neq 0$ for some $i>0.$ A comprehensive study of the structure of $T$, at this level of generality, is reserved for another occasion.
\end{remark}

Below is an explicit example when $I$ is a monomial ideal.

\begin{example}
    Let $Q=k[x,y,z]$ and $I=(yz,xz,xy)$, then the Taylor complex for $I$ is the Taylor resolution:
	$$T\!: \, \xymatrix@C=5mm{0 \ar[r] & Q b_{123} \ar[rr]^-{\begin{pmatrix} 1 \\ -1 \\ 1 \end{pmatrix}} && Qb_{23} \oplus Q b_{13} \oplus Q b_{12} \ar[rrrr]^-{\begin{pmatrix}  0 & -x & -x \\ -y & 0 & y \\ z & z & 0 \end{pmatrix}} &&&& Q b_1 \oplus Q b_2 \oplus Q b_3 \ar[rrr]^-{\begin{pmatrix} yz & xz & xy \end{pmatrix}} &&& Q \ar[r] & 0.}$$
    Left multiplication by $b_1$ on $T$ is given by the following: 
    $$\xymatrix@C=5mm{
0 \ar[r] & Q b_{123} \ar[r] & Q b_{23} \oplus Q b_{13} \oplus Q b_{12} \ar[dd]^-{\begin{pmatrix} yz \\ 0 \\ 0 \end{pmatrix}} \ar[r] 
& Q b_1 \oplus Q b_2 \oplus Q b_3 \ar[r] \ar[dd]^-{\begin{pmatrix} 0 & 0 & 0 \\ 0 & 0 & y \\ 0 & z & 0 \end{pmatrix}} 
& Q \ar[dd]^-{\begin{pmatrix} 1 \\ 0 \\ 0 \end{pmatrix}} \ar[r] & 0 \\ \\ 
& 0 \ar[r] & Q b_{123} \ar[r] & Q b_{23} \oplus Q b_{13} \oplus Q b_{12} \ar[r] & Q b_1 \oplus Q b_2 \oplus Q b_3 \ar[r] & Q \ar[r] & 0.
}$$
So for example, $b_1 \cdot b_2 = z b_{12}$.
\end{example}

We will now adjoin variables (polynomial in even degrees and exterior in odd degrees) to the Taylor complex to construct a dg algebra resolution of $R$ over $Q$ \cite{Tate:1957,Avramov:2010}. In general, this resolution will be quite large, but as we will see in the next section, this resolution will be helpful for our purposes.

\begin{construction}[Taylor model]\label{taylor-tate}
    Let $Q$ is a commutative base ring that is either local or a nonnegatively graded algebra with $Q_0$ a field. Let $\m$ denote the unique maximal ideal of $Q$, in the local case, or the irrelevant maximal ideal of $Q$ in the graded setting. In either case, $k=Q/\m$ is the residue field of $Q$. 
Let $I$ be a proper ideal in $Q$, minimally generated by $f_1, \ldots, f_n$, and $R = Q/I$.

Fix a Taylor complex $T$ for $R$ over $Q$. A {\bf Taylor model} for $R$ over $Q$ is the complex $T[X]$ obtained from $T$ by adding polynomial variables in even degrees $i \geqslant 2$ and exterior variables in odd degrees $i \geqslant 3$ in the sense of Tate \cite{Tate:1957} to form a dg algebra resolution for $R$ over $Q$.
In more detail, $X = X_{\geqslant 2} = \bigcup_{i \geqslant 2} X_i$ is a set of variables, with $X_i$ a set of variables of degree $i$. For each $i \geqslant 1$, we fix cycles $z_1, \ldots, z_m$ whose homology classes minimally generate $H_i(T[X_{\leqslant i}])$, and take $X_{i+1} = \{ x_1, \ldots, x_m \}$, then we set
$$T[X_{\leqslant i+1}] = T[X_{\les i}][x_1, \ldots, x_m \mid \partial(x_j) = z_j].$$
Now define $T[X] \colonequals \operatorname{colim} T[X_{\les i}];$ in particular, Taylor models exist.
\end{construction}

