\begin{lemma}\label{lemma isolated in degree 2}
    Suppose that there exist $i \neq j$ with the following properties:
    \begin{itemize}
    \item The GCD graph of $\f$ contains an edge between $i$ and $j$.
    \item For all $\ell \in [n] \smallsetminus \{i, j \}$, the GCD graph of $\f$ contains an edge between $\ell$ and exactly one of $i$ or $j$. 
    \end{itemize}
    Then $\V_R(R)$ is full.
\end{lemma}

\begin{proof}
    We will show that $\{ i, j \}$ is an isolated vertex of the Taylor graph on $\f$, which by \Cref{isolated vertex implies full support} implies that $R$ has full support.
    By \Cref{no differentials 2 to 1} there are no edges of the form $\{i , j \} \longrightarrow \{ \ell \}$ for all $\ell \in [4]$.

    For $\ell \in [n] \smallsetminus \{ i , j \}$, there is an edge $\{ i, j\} \longrightarrow \{ i, j,\ell \}$ if and only if $\gcd(f_i, f_\ell)$ and $\gcd(f_j, f_\ell)$ are both units. However, we assumed that (exactly) one of these is not a unit, and thus there is no such edge. We have now shown that there are no edges out of $\{ i, j \}$, and thus $b_{\{ i, j \}}$ is a cycle in $\widehat{\cC}_{E_{a}}(T)$ for all $a \in \A^n_k$.

    Our assumption that $i$ and $j$ are connected in the GCD graph means that $\gcd(f_i, f_j)$ is a nonunit, and thus the Taylor graph does not contain the edges $\{ i \} \longrightarrow \{ i, j \}$ and $\{ j \} \longrightarrow \{ i, j \}$. 

    It remains to look at potential edges of the form $\{i, j, k\} \longleftarrow \{i, j, \ell \}$ for some $\ell \notin \{ i, j\}$. The Taylor graph contains this edge if and only if $f_\ell$ divides $f_{\{ i, j \}}$. Our assumption on the GCD graph implies that one of $\gcd(f_i, f_\ell)$ of $\gcd(f_j, f_\ell)$ is a unit. But if $\gcd(f_i, f_\ell)$ is a unit and $f_\ell$ divides $f_{\{ i, j \}}$, we must have that $f_\ell$ divides $f_{j}$, which is impossible since we chose $f_1, \ldots, f_n$ to be minimal generators of $I$. We conclude that there is no edge in the Taylor graph of $I$ of the form $\{i, j, k\} \longleftarrow \{i, j, \ell \}$, and this finishes our proof that $\{ i, j \}$ is an isolated vertex in the Taylor graph of $\f$. By \Cref{isolated vertex implies full support}, the support of $R$ is full.
\end{proof}

The last main result of this section is a classification of the varieties realizable as $\V_R(R)$ for some $R$ defined by monomials for small values of $n$. The next lemma will help with that classification.

\begin{lemma}
\label{monomial tor independent}
Let $R$ have regular presentation $Q/I$, with $I$ generated by monomials $\f=f_1,\ldots,f_n$ {on a} regular sequence $\bm{x} = x_1, \ldots, x_d$ of $Q$. 
If $f_1,\ldots,f_m$ are monomials on $x_1,\ldots,x_c$ and $f_{m+1},\ldots, f_n$ are monomials on $x_{c+1},\ldots,x_d$, then under the homeomorphism $\A_k^{n}\cong \A_k^{m}\times_k  \A_k^{n-m}$ we have $\V_R(R)\cong \V_{R_1}(R_1)\times_k \V_{R_2}(R_2)$,
where $R_1$ and $R_2$ have regular presentations $Q/(f_1,\ldots,f_m)$ and $Q/(f_{m+1},\ldots, f_n)$, respectively. 
\end{lemma}

\begin{proof}
It suffices to show that \cref{tor independent gives union of varieties} applies, as $\Tor^Q_i(R_1,R_2)=0$ for $i>0$, in this setting. Indeed, the assumptions on $\f$ provide an isomorphism of dg $Q$-algebras:
    \[
    T(\f)\cong T(f_1,\ldots,f_m)\otimes_Q T(f_{m+1},\ldots,f_n)\,.
    \]
    Moreover, each Taylor complex above only has homology in degree zero since $\f$ is a list of monomials on a regular sequence of $Q$ \cite{Taylor}.
\end{proof}

\begin{theorem}\label{th_nleq4}
Let $R$ be a local or positively graded ring, with a minimal regular presentation $Q/I$. Let $I$ be minimally generated by a list of monomials $\f=f_1,\ldots,f_n$  on a regular sequence of $Q$. 

If $n\leqslant 4$, then the cohomological support variety of $R$ is a coordinate subspace
\[
\V_R(R) = \left\{ a\in \mathbb{A}_k^n\mid a_i=0 \text{ for all } i\in S\right\}
\]
where $S\subseteq\{ 1,\ldots, n\}$ and $c= |S|$ is the largest codimension of an embedded deformation of $R$.
\end{theorem}

\begin{remark}
\Cref{th_nleq4} is false when $n$ is larger than $4$. For instance, the the support variety of the monomial ring $R$ of \Cref{lucho_example} is a union of two hypersurfaces.
\end{remark}

\begin{proof}[Proof of \cref{th_nleq4}]
If $\Gamma_{\f}$ is disconnected, we can write $I$ as a sum of two ideals $I_1$ and $I_2$ in a smaller number of generators that satisfy the hypothesis of \cref{monomial tor independent}, so the support of $R$ can be computed from the supports of $Q/I_1$ and $Q/I_2$. Note that the join of coordinate subspaces is a coordinate subspace, so this reduces the problem to a smaller value of $n$. Thus we may assume that the GCD graph of $\f$ is connected.

When $n \leqslant 3$, every connected graph with three vertices or fewer has a vertex connected to all others, and so by part \cref{keylemitem3} of \cref{key lemma} we get $\V_R(R)=\mathbb{A}^n$. Hence we need only to consider the case when $n=4$.

