\section{Preliminaries}

A {\em (strongly continuous) action} of the circle group $\mathbb{T}$ on a C*-algebra $A$ is a group ho\-mo\-mor\-phism $\alpha:\mathbb{T}\to {\rm Aut}(A)$ such that the map $\mathbb{T}\times A\ni (g,a)\mapsto\alpha_g(a):=\alpha(g)(a)\in A$ is continuous. A~C*-algebra equipped with a $\mathbb{T}$-action is called a {\em $\mathbb{T}$-C*-algebra}. Now, let $A$ and $B$ be $\mathbb{T}$-C*-algebras equipped with actions $\alpha$ and $\beta$, respectively. A $*$-homomorphism $\pi:A\to B$ is called {\em $\mathbb{T}$-equivariant} if $\pi\circ \alpha_g=\beta_g\circ \pi$ for all $g\in G$.

\subsection{Cuntz--Pimsner algebras}

General theory of Hilbert modules and C*-correspondences 
can be found in~\cite{enchilada}. The pioneering idea of 
associating C*-algebras to C*-correspondences is due to 
Pimsner~\cite{pimsner}. Here we follow~\cite{katsura0}.

A {\em C*-correspondence} over a C*-algebra $A$ is a 
(right) Hilbert $A$-module $X$ together with a~left action 
implemented by a $*$-homomorphism 
$\varphi_X:A\to \mathcal{L}(X)$, where $\mathcal{L}(X)$ is 
the C*-algebra of adjointable operators on $X$. We will often write 
$a\cdot \xi$ to denote $\varphi_X(a)(\xi)$, where $a\in A$ 
and $\xi\in X$. Next, consider the set $\mathcal{K}(X):=\overline{\rm span}\{\theta_{\xi,\eta}~:~\xi,\eta\in X\}$, where
\[
\theta_{\xi,\eta}(\zeta):=\xi\cdot\langle\eta,\zeta\rangle,\qquad \zeta\in X.
\]
Then $\mathcal{K}(X)$ is a closed ideal of $\mathcal{L}(X)$ and elements of $\mathcal{K}(X)$ are called {\em compact operators on $X$}. 
\begin{definition}\label{correp}
(\cite[Definition~2.1]{katsura0})
A~{\em representation} of a C*-correspondence $X$ over $A$ on a C*-algebra $B$ is a pair $(\psi^1,\psi^0)$ consisting of a linear map $\psi^1:X\to B$ and a $*$-homomorphism $\psi^0:A\to B$ satisfying
\begin{enumerate}
\item[(R1)] $\psi^1(a\cdot \xi)=\psi^0(a)\psi^1(\xi)$ for all $a\in A$ and $\xi\in X$.
\item[(R2)] $\psi^0(\langle\xi,\eta\rangle)=\psi^1(\xi)^*\psi^1(\eta)$ for all $\xi,\eta\in X$.
\end{enumerate} 
\end{definition}
For a C*-correspondence $X$ over $A$, the Katsura ideal of $A$ is given by
\[
J_X:=\{a\in A~:~\varphi(a)\in\mathcal{K}(X)\text{ and }ab=0\text{ for all $b\in\ker\varphi$}\}.
\]
Next, for every representation $(\psi^1,\psi^0)$ of $X$ on $B$, we define a $*$-homomorphism $\psi^{(1)}:\mathcal{K}(X)\to B$ by the formula 
\[
\psi^{(1)}(\theta_{\xi,\eta}):=\psi^1(\xi)\psi^1(\eta)^*
\]
for all $\xi,\eta\in X$.
\begin{definition}(\cite[Definition~3.4]{katsura0})
A representation $(\psi^1,\psi^0)$ of a C*-correspondence $X$ over $A$ on a C*-algebra $B$ is {\em covariant} if $\psi^0(a)=\psi^{(1)}(\varphi_X(a))$ for all $a\in J_X$. 
\end{definition}

\begin{definition}(\cite[Definition~3.5]{katsura0}, cf.~\cite{pimsner})
The {\em Cuntz--Pimsner algebra} $\mathcal{O}_X$ associated to a correspondence $X$ over $A$ is the C*-algebra $C^*(t^1_X,t^0_X)$ generated by the universal covariant representation $(t^1_X,t^0_X)$ of $(X,A)$. 
\end{definition}
By universality, for every covariant representation $(\psi^1,\psi^0)$ of $X$ on $B$, there is a~unique $*$-ho\-mo\-mor\-phism $\psi:\mathcal{O}_X\to B$ onto the C*-algebra $C^*(\psi^1,\psi^0)$ (generated by the images of $\psi^1$ and $\psi^0$) such that $\psi\circ t^1_X=\psi^1$ and $\psi\circ t^0_X=\psi^0$. Next, the formulas
\begin{equation}\label{cuntzgauge}
\alpha_z(t^0_X(a)):=t^0_X(a),\qquad \alpha_z(t^1_X(\xi)):=zt^1_X(\xi),\qquad z\in\mathbb{T},\quad a\in A,\quad \xi\in X,
\end{equation}
give rise to an action $\alpha:\mathbb{T}\to{\rm Aut}(\mathcal{O}_X)$, called the~{\em gauge action}. A  $*$-homomorphism between Cuntz--Pimsner algebras which is $\mathbb{T}$-equivariant with respect to gauge actions is called {\em gauge-equivariant}. If $I$ is an ideal of $\mathcal{O}_X$ such that $\alpha_z(I)\subseteq I$ for all $z\in\mathbb{T}$, then $I$ is {\em gauge-invariant}.

\subsection{Topological graphs}

We refer the reader to~\cite{katsura1,katsura2,katsura3} for an extensive study of topological graphs and their C*-algebras (note, however, that we use a different source-range convention). A {\em topological graph} $E$ is a~quadruple $(E^0,E^1,s_E,r_E)$, where $E^0$ and $E^1$ are locally compact Hausdorff spaces and $s_E,r_E:E^1\to E^0$ are continuous maps such that $r_E$ is a local homeomorphism. We call $E^0$ the {\em vertex space}, $E^1$ the {\em edge space}, and $s_E$ and $r_E$ the {\em source} and the {\em range} map, respectively.

Let us recall the construction of the C*-algebra of a topological graph. Let $A_E:=C_0(E^0)$ and for continuous functions $\xi,\eta\in C(E^1)$ define the following function on $E^0$:
\begin{equation}\label{inner}
\langle \xi,\eta\rangle(v):=\sum_{e\in r^{-1}_E(v)}\overline{\xi(e)}\eta(e).
\end{equation}
Next, define the following subspace of the space of bounded functions on $E^1$:
\[
X_E:=\left\{\xi\in C_b(E^1)~:~\langle\xi,\xi\rangle\in A_E\right\}.
\] 
Then $(X_E,A_E)$ is a C*-correspondence with the $A_E$-valued inner-product~\eqref{inner} and the actions
\[
(\xi\cdot f)(e):=\xi(e)f(r_E(e)),\qquad (f\cdot\xi)(e):=f(s_E(e))\xi(e),\qquad f\in A_E,\quad \xi\in X_E.
\]
The {\em C*-algebra $C^*(E)$ of a topological graph $E$} is the Cuntz--Pimsner algebra of the C*-cor\-re\-spon\-dence $X_E$ over $A_E$~(see~\cite[Section~2]{katsura1}).  The class of C*-algebras of topological graphs includes graph C*-algebras and homeomorphism C*-algebras. 
\vspace*{2mm}

\noindent{\bf Notation}. In what follows, let $\varphi_E$ denote the map defining the left action on $X_E$ and let $(t_E^1,t_E^0)$ denote the universal covariant representation.
\vspace*{2mm}

One distinguishes the following subsets of the vertex space $E^0$:
\begin{align*}
E_{\rm fin}^0&:=\{v\in E^0~:~\text{there is a neighborhood $V$ of $v$ such that $s_E^{-1}(V)$ is compact}\},\\
E^0_{\rm inf}&:=E^0\setminus E^0_{\rm fin},\qquad E_{\rm sink}^0:=E^0\setminus \overline{s_E(E^1)},\\
E_{\rm reg}^0&:=E^0_{\rm fin}\setminus \overline{E^0_{\rm sink}},\qquad E_{\rm sing}^0:=E^0\setminus E^0_{\rm reg}.
\end{align*}
The elements of $E_{\rm sink}^0$ are called {\em sinks}, the elements of $E^0_{\rm inf}$ are called {\em infinite emitters}, the elements of $E_{\rm reg}^0$ are called {\em regular}, and those of $E^0_{\rm sing}$ are called {\em singular}.

A subset $Y^0$ of $E^0$ is {\em positively invariant} if $r_E(e)\in Y^0$ implies $s_E(e)\in Y^0$ for every $e\in E^1$ and {\em negatively invariant} if for all $v\in Y^0\cap E^0_{\rm reg}$ there is $e\in E^1$ satisfying $s_E(e)=v$ and $r_E(e)\in Y^0$. We say that $Y^0$ is {\em invariant} if it is both positively and negatively invariant.
\begin{definition}
(\cite[Definition~2.3]{katsura3})
An {\em admissible pair} $\rho$ is a pair $(Y^0,Z^0)$ of closed subsets of $E^0$ such that $Y^0$ is invariant and $Y^0_{\rm sing}\subseteq Z^0\subseteq E^0_{\rm sing}\cap Y^0$.
\end{definition}



Let $I$ be a gauge-invariant ideal of $C^*(E)$. By~\cite[Proposition~2.8]{katsura3}, there is an admissible pair $\rho_I=(Y^0_I,Z^0_I)$ given by
\begin{align}\label{admideal}
Y^0_I&:=\{v\in E^0~:~f(v)=0\text{ for all }f\in C_0(E^0)\text{ such that }t^0_E(f)\in I\},\\
Z^0_I&:=\{v\in E^0~:~f(v)=0\text{ for all }f\in C_0(E^0)\text{ such that }t^0_E(f)\in I+\Phi_E(\mathcal{K}(X_E))\}.\nonumber
\end{align}
Conversely, given an admissible pair $\rho=(Y^0,Z^0)$, there exists an associated gauge-invariant ideal $I_\rho$  (see~\cite[Proposition~3.5]{katsura3}). We do not need the invoke the explicit form of this ideal here. Instead, we will rely on the following theorem.

\begin{theorem}\label{idealclass}
{\rm (\cite[Theorem~3.19]{katsura3})}
The assignments $I\mapsto \rho_I=(Y^0_I,Z^0_I)$ and $\rho=(Y^0,Z^0)\mapsto I_\rho$ give rise to an inclusion-reversing one-to-one correspondence between the set of gauge-invariant ideals and the set of admissible pairs.
\end{theorem}

Next, we need morphisms between topological graphs. 
Recall that a continuous map $f:X\to Y$ between locally compact Hausdorff spaces is {\em proper} if $f^{-1}(K)$ is compact for every compact subset $K$ of $Y$.
\begin{definition}\label{factorkatsura}
(\cite[Definition~2.1, Definition~2.6]{katsura2})
A {\em regular factor map} $m:E\to F$ between topological graphs $E$ and $F$ is a pair of proper continuous maps $m^1:E^1\to F^1$ and $m^0:E^0\to F^0$ such that
\begin{enumerate}
\item[(F1)] $r_F(m^1(e))=m^0(r_E(e))$ and $s_F(m^1(e))=m^0(s_E(e))$ for all $e\in E^1$.
\item[(F2)] If $x\in F^1$ and $v\in E^0$ satisfies $r_F(x)=m^0(v)$, then there exists a unique element $e\in E^1$ such that $m^1(e)=x$ and $r_E(e)=v$.
\item[(F3)] $m^0(E^0_{\rm sing})\subseteq F^0_{\rm sing}$.
\end{enumerate}
\end{definition}
\begin{remark}
The definition of regularity in~\cite[Definition~2.6]{katsura2} is slightly different. However, it is equivalent to our definition due to~\cite[Lemma~2.7]{katsura2}.
\end{remark}
Given a regular factor map $m:E\to F$, one defines the maps
\begin{equation}\label{precomp}
\mu^0:A_F\to A_E,\qquad (\mu^0(f))(v):=f(m^0(v)),\qquad
\mu^1:X_F\to X_E,\qquad (\mu^1(\xi))(e):=\xi(m^1(e)).
\end{equation}
The following result justifies the definition of a regular factor map.
\begin{proposition}\label{functc*}
{\rm (\cite[Proposition~2.10]{katsura2})}
Let $m:E\to F$ be a regular factor map. Then there exists a unique gauge-equivariant $*$-homomorphism $\mu:C^*(F)\to C^*(E)$ such that $\mu\circ t_F^i=\mu^i$, $i=0,1$, where $\mu^0$ and $\mu^1$ are defined by~\eqref{precomp}.
\end{proposition}


