\section{Attaching subgraphs along factor maps}

Adjunction spaces are fundamental in topology, in particular, in the theory of CW-complexes (see, e.g.~\cite{t-td08}). In this section, we introduce the notion of an adjunction graph which enables us to glue  topological graphs.

\subsection{Regular closed subgraphs}
Open subgraphs of topological graphs were defined in~\cite[Definition~5.1]{katsura2}. Here we study well-behaved closed subgraphs. 
\begin{definition}
We say that a topological graph $G$ is a {\em subgraph} of a topological graph $F$, denoted $G\subseteq F$, if there are topological embeddings $G^1\subseteq F^1$ and $G^0\subseteq F^0$ such that $s_F|_{G^1}=s_G$ and $r_F|_{G^1}=r_G$. A~subgraph $G$ of $F$ is called {\em closed} if the subspaces $G^1\subseteq F^1$ and $G^0\subseteq F^0$ are closed. Finally, a~closed subgraph $G$ of $F$ is called {\em regular} if $G^0$ is a negatively invariant subset of $F^0$ and $r_F^{-1}(G^0)\subseteq G^1$.
\end{definition}

Next, we prove several useful results regarding regular closed subgraphs.
\begin{proposition}\label{injreg}
Let $G$ be a closed subgraph of a topological graph $F$. The following are equivalent:
\begin{enumerate}
\item[{\rm (1)}] $G\subseteq F$ is  regular,
\item[{\rm (2)}] the embeddings $G^1\subseteq F^1$ and $G^0\subseteq F^0$ give rise to a regular factor map $m:G\to F$.
\end{enumerate}
\end{proposition}
\begin{proof}
Note that the associated closed embeddings $m^1$ and $m^0$ are automatically proper. Similarly, the condition (F1) for $m$ is satisfied due to the assumption that the source and range maps on $G$ are the restrictions of the source and range maps on $F$.  Let us show that $m$ satisfies (F2) if and only if $r_F^{-1}(G^0)\subseteq G^1$. First, if $r_F(e)\in G^0$ for some $e\in F^1$, then $e\in G^1$ by (F2). Conversely, assume that $r_F^{-1}(G^0)\subseteq G^1$. Since $G^1=r_G^{-1}(G^0)\subseteq r_F^{-1}(G^0)$, we obtain that $G^1=r_F^{-1}(G^0)$. Hence, if $e\in F^1$ satisfies $r_F(e)\in G^0$, then $e\in r_F^{-1}(G^0)=G^1$, which shows the condition (F2) for $m$. Notice that the condition $r_F^{-1}(G^0)\subseteq G^1$ is stronger than positive invariance of $G^0\subseteq F^0$. By~\cite[Proposition~2.2]{katsura3}, the negative invariance of $G^0$ is equivalent to the condition (F3) for $m$.
\end{proof}


\begin{proposition}\label{facregsub}
Let $m:G\to E$ be a regular factor map. Then
\[
m(G):=(m^1(G^1),m^0(G^0),s_E|_{m^1(G^1)},r_E|_{m^1(G^1)})
\]
is a regular closed subgraph of $F$.
\end{proposition}
\begin{proof}
To prove that $m(G)$ is a subgraph, note that $r_E(m(G)^1)\subseteq m(G)^0$ and $s_E(m(G)^1)\subseteq m(G)^0$ due to the condition (F1) for $m$. Since $m^0$ is a~proper map, we infer that $m^0(G^0)$ is closed in~$E^0$. Therefore, $m(G)$ is a~closed subgraph of $E$. To conclude regularity of $m(E)$, we have to prove that $r_E^{-1}(m^0(G^0))\subseteq m^1(G^1)$ and that $m^0(G^0)$ is negatively invariant. Let $e\in E^1$ be such that $r_E(e)=m^0(g)$ for some $g\in G^0$. Then there is $a\in G^1$ such that $m^1(a)=e$ by (F2). To prove negative invariance, note that if $v\in m^0(G^0)\cap E^0_{\rm reg}$ then there is $g\in G^0$ such that $m^0(g)=v$. Since $m$ is regular, it follows that $g\in G^0_{\rm reg}$. In turn, there exists $a\in G^1$ such that $s_G(a)=g$. Hence, $s_E(m^1(a))=m^0(s_G(a))=m^0(g)=v$. Furthermore, $r_E(m^1(a))\in m^0(E^0)$, so $m^0(E^0)$ is negatively invariant.
\end{proof}

\begin{proposition}
Let $E$ and $F$ be topological graphs, let $G$ be a regular subgraph of $E$, and let $m^0:E^0\to F^0$ and $m^1:E^1\to F^1$ be a pair of continuous maps. If $m=(m^1,m^0)$ satisfies any of the conditions {\rm (F1)-(F3)} of a regular factor map then so does the restriction of $m$ to $G$.
\end{proposition}
\begin{proof}
Let $m|_G$ denote the restriction of $m$ to $G$. The condition (F1) for $m|_G$ follows from the same condition for $m$ and the fact that $G$ is a subgraph of $E$. Next, let $x\in F^1$ be such that $r_F(x)=m^0(v)$ for some $v\in G^0$. If $m$ satisfies (F2), then for $m:E\to F$ there is a unique $e\in E^1$ such that $m^1(e)=x$ and $r_E(e)=v$. Since $r_E^{-1}(G^0)\subseteq G^1$, we conclude that $e\in G^1$. Hence, $m|_G$ satisfies (F2). Similarly, the condition (F3) for $m|_G$ follows from the same condition for $m$ and  invariance of $G^0$ in $F^0$: 
\[
m^0|_{G^0}(G^0_{\rm sing})=m^0(G^0_{\rm sing})\subseteq m^0(E^0_{\rm sing})\subseteq F^0_{\rm sing}.
\]
\end{proof}
\begin{proposition}\label{subp}
Let $G$ be a regular closed subgraph of $F$ and let $p:F\to E$ be a regular factor map. Then $p(G)$ is a regular closed subgraph of $p(F)$.
\end{proposition}
\begin{proof}
Since $G$ is a closed subset of $F$ and $p$ satisfies (F1), $p(G)$ is a closed subgraph of $p(F)$. Next, we will prove that $r_{p(F)}^{-1}(p(G)^0)\subseteq p(G)^1$. If $e\in r_{p(F)}^{-1}(p(G)^0)$, there are some $x\in F^1$ and $g\in G^0$ such that $e=p^1(x)$ and $r_{p(F)}(e)=r_{p(F)}(p^1(x))=p^0(r_F(x))=p^0(g)$. Hence, $r_F(x)\in G^0$, which implies that $x\in G^1$ by the inclusion $r_F^{-1}(G^0)\subseteq G^1$. Consequently, $e\in p(G)^1$. Finally, let $v\in p(G)^0\cap p(F)^0_{\rm reg}$. Then there exists $g\in G^0$ such that $v=p^0(g)$. Since $v\in p(F)^0_{\rm reg}$, we infer that $g\in F^0_{\rm reg}$. By negative invariance of $G^0$ in $F^0$, there is $x\in F^1$ such that $s_F(x)=g$ and $r_F(x)\in G^0$. We have that $s_{p(F)}(p^1(x))=p^0(s_F(x))=p^0(g)=v$ and $r_{p(F)}(p^1(x))=p^0(r_F(x))\in p(G)^0$. Therefore, $p(G)^0$ is negatively invariant in $p(F)^0$, which ends the proof.
\end{proof}

\subsection{Adjunction graphs}
Now, we turn our attention to pushouts of topological graphs. In the category of (discrete) directed graphs and graph homomorphisms, pushouts come from the corresponding pushouts of the vertex and edge spaces in the category of sets and maps (see, e.g.~\cite{ek-79}). The situation is more complex in the context of topological graphs. For starters,  pushouts of locally compact Hausdorff spaces might be ill-behaved, i.e. result in spaces which are neither locally compact nor Hausdorff. 
Therefore, we consider the following special case. Let $X$ and $Y$ be topological spaces, let $A$ be a closed subspace of $Y$, and let $f:A\to X$ be a~continuous map. The {\em adjunction space} $X\cup_f Y$ (see, e.g.~\cite[p.~7]{t-td08}) is the quotient space of the disjoint union $X\sqcup Y$, where the quotient map is given by the relation $f(a)\sim a$ for all $a\in A$. The map $f$ is often called the {\em attaching map}. Note that $X\cup_fY=X\sqcup (Y\setminus A)$ as sets. 
The canonical map $X\to X\cup_f Y$ is a~closed embedding, so we can view $X$ as a~closed subspace of $X\cup_f Y$. Similarly, one defines the map
\begin{equation}\label{canadjmap}
p:Y\hookrightarrow X\sqcup Y\longrightarrow X\cup_fY,
\end{equation}
where the second arrow is the defining quotient map. Note that $p$ restricted to $Y\setminus A$ is an open embedding. %Given continuous maps $g:X\to Z$ and $h:Y\to Z$ such that $g(f(a))=h(a)$, the map $g\sqcup h$ descends to the unique continuous map $g\cup_f h:X\cup_f Y\to Z$.

If $X$ and $Y$ are Hausdorff, then $X\cup_f Y$ is again Hausdorff (see, e.g.~\cite[Proposition 1.2.4(3)]{t-td08}). 
The following result is probably well known but since we could not find a reference, we provide a~proof.
\begin{proposition}\label{adjprop}
Let $X$ and $Y$ be locally compact Hausdorff spaces, let $A$ be a closed subspace of~$Y$, and let $f:A\to X$ be a proper map. Then $X\cup_f Y$ is a locally compact Hausdorff space.
\end{proposition}
\begin{proof}
We already know that $X\cup_f Y$ is Hausdorff so we only need to check whether every point has a~compact neighborhood. The fact that $f$ is closed combined with the definition of the topology on $X\cup_f Y$ implies that the subspaces $X\setminus f(A)$ and $Y\setminus A$ can be identified with open subsets of locally compact Hausdorff spaces $X$ and $Y$, respectively. Hence, it suffices to find compact neighborhoods of the points $f(a)\in f(A)\subseteq X\cup_f Y$. Let $K$ be a compact neighborhood of $f(a)$ in $X$. We can choose $K$ such that $K\subseteq f(A)$ because $f(A)$ is closed in $X$. Next, properness of $f$ implies that $f^{-1}(K)$ is a compact neighborhood of $a$ in $A\subseteq Y$.  Therefore, the image of the compact set $K\sqcup f^{-1}(K)$ under the quotient map is a compact neighborhood of $f(a)$ in $X\cup_f Y$.
\end{proof}
\begin{remark}
If $f$ is not proper, then $X\cup_f Y$ might not be locally compact even when $X$ is compact Hausdorff  and $Y$ is second-countable locally compact Hausdorff as the following example\footnote{We owe this example to Alexander Ravsky.} shows: $X=\{0\}\sqcup\{1/n~:~n\in\mathbb{N}\}$, $A=\{0\}\times\mathbb{N}\subseteq X\times\mathbb{N}=Y$, and $f:A\ni (0,n)\mapsto 1/n\in X$.
\end{remark}

Let us introduce an analog of the adjunction space for topological graphs using the notions of a~closed subgraph and a~factor map. Let $E$ and $F$ be topological graphs. Next, let $G$ be a closed subgraph of $F$ and let $m^0:G^0\to E^0$ and $m^1:G^1\to E^1$ be continuous maps. Then, we can consider adjunction spaces $E^0\cup_{m^0}F^0$ and $E^1\cup_{m^1}F^1$ and their defining quotient maps
\begin{equation}\label{quotadj}
q^0:E^0\sqcup F^0\longrightarrow E^0\cup_{m^0}F^0,\qquad q^1:E^1\sqcup F^1\longrightarrow E^1\cup_{m^1}F^1.
\end{equation}
Furthermore, we can view $E^0$ and $E^1$ as closed subspaces of $E^0\cup_{m^0}F^0$ and $E^1\cup_{m^1}F^1$, respectively, and we have the canonical maps
\begin{equation}\label{canmapp}
p^0:F^0\longrightarrow E^0\cup_{m^0}F^0,\qquad p^1:F^1\longrightarrow E^1\cup_{m^1}F^1,
\end{equation}
defined analogously to~\eqref{canadjmap}. Let us also mention that the diagrams 
    \[
    \begin{tikzcd}[ampersand replacement=\&]
	\& {(E\cup_mF)^0} \\
	{E^0} \&\& {F^0} \\
	\& {G^0}
	\arrow[, right hook->, from=2-1, to=1-2]
	\arrow["m^0", <-, from=2-1, to=3-2]
	\arrow["p^0", <-, from=1-2, to=2-3]
	\arrow[, right hook->, from=3-2, to=2-3]
\end{tikzcd}\qquad  \text{and}\qquad 
\begin{tikzcd}[ampersand replacement=\&]
	\& {(E\cup_mF)^1} \\
	{E^1} \&\& {F^1} \\
	\& {G^1}
	\arrow[, right hook->, from=2-1, to=1-2]
	\arrow["m^1", <-, from=2-1, to=3-2]
	\arrow["p^1", <-, from=1-2, to=2-3]
	\arrow[, right hook->, from=3-2, to=2-3]
\end{tikzcd}
\]
are pushout diagrams in the category of topological spaces and continuous maps.

To obtain a topological graph from the above data, we need the source and range maps. In the definition below, we provide sufficient assumptions to ensure that the resulting spaces are locally compact Hausdorff and the range map is a local homeomorphism.

\begin{definition}\label{adjgraph}
Let $E$ and $F$ be topological graphs and let $G$ be a closed subgraph of $F$ such that $r_F^{-1}(G^0)\subseteq G^1$. 
Furthermore, let $m^0:G^0\to E^0$ and $m^1:G^1\to E^1$ be a~pair of proper maps satisfying (F1). The {\em adjunction graph} $E\cup_m F$ is defined as follows:
\[
(E\cup_mF)^0:=E^0\cup_{m^0}F^0,\qquad (E\cup_mF)^1:=E^1\cup_{m^1}F^1,
\]
\[
s_\cup(e):=\begin{cases}s_E(e) & e\in E^1\\ p^0(s_F(e)) & e\in F^1\setminus G^1\end{cases},\qquad\text{and}\qquad r_\cup(e):=\begin{cases}r_E(e) & e\in E^1\\ r_F(e) & e\in F^1\setminus G^1\end{cases},
\]
where $p^0:F^0\to E^0\cup_{m^0}F^0$ is defined by~\eqref{canmapp}. When $m$ is injective, we write $E\cup F:=E\cup_mF$ and call $E\cup F$ the {\em union graph} of $E$ and $F$. In this case, we also identify $G$ with the {\em intersection graph} $E\cap F$.
\end{definition}
We emphasize that the need for $E\cap F$ to be a closed subgraph in both $E$ and $F$ is dictated by the fact that general unions might not be pushouts.
\begin{proposition}
The adjunction graph $E\cup_mF$ is a~topological graph. 
\end{proposition}
\begin{proof}
The spaces $(E\cup_mF)^0$ and $(E\cup_mF)^1$ are locally compact Hausdorff due to Proposition~\ref{adjprop}. Since $r_F^{-1}(G^0)\subseteq G^1$, we infer that $r_F(F^1\setminus G^1)\subseteq F^0\setminus G^0$. Recall that we can view $E^0$ and $F^0\setminus G^0$ as subspaces of $E^0\cup_{m^0}F^0$. Hence, the image of $r_\cup$ is contained in $E^0\cup_{m^0}F^0$. The source map is automatically well defined but one has to use $p^0$ because there are edges in $F^1$ that start in $G^0$ and do not belong to $G^1$. 

Continuity of $s_\cup$ is equivalent to the continuity of the maps
\[
E^1\hookrightarrow E^1\cup_{m^1}F^1\overset{s_\cup}{\longrightarrow} E^0\cup_{m^0}F^0\qquad\text{and}\qquad  F^1\overset{p^1}{\longrightarrow} E^1\cup_{m^1}F^1\overset{s_\cup}{\longrightarrow} E^0\cup_{m^0}F^0.
\]
The first map coincides with $s_E$ by definition. As for the second map, it coincides with $p^0\circ s_F$ due to the condition (F1) for $m$. A similar argument proves the continuity of $r_\cup$.

Let $U\subseteq E^1\cup_{m^1}F^1$ be an open subset. It is clear that
\[
r_\cup(U)=r_E((q^1)^{-1}(U)\cap E^1)\sqcup r_F((q^1)^{-1}(U)\cap (F^1\setminus G^1))\subseteq E^0\cup_{m^0}F^0,
\]
where $q^1:E^1\sqcup F^1\to E^1\cup_{m^1}F^1$ is the quotient map~\eqref{quotadj}.
Recall that $U$ is open in $E^1\cup_{m^1}F^1$ if and only if $(q^1)^{-1}(U)\cap E^1$ is open in $E^1$ and $(q^1)^{-1}(U)\cap F^1$ is open in $F^1$. Since $G^1$ is a closed subset of $F^1$ and both $r_E$ and $r_F$ are local homeomorphisms, we conclude that $r_\cup$ is also a local homeomorphism. 
\end{proof}

