\section{An application}\label{S6}
We consider a one-dimensional single-species reaction-diffusion-advection model from \cite{book}.
\begin{equation}
\left\{
\begin{array}{llll}
u_t=u_{xx}+2sm_x(x)u_x+u(\sigma(x)-u),& 0<x<1,\ t>0,\\
u_x(0,t)=u_x(1,t)=0,& t>0,\\
u(x,0)=u_0(x)\ge,\not\equiv 0.
\end{array}\right.\label{E0}
\end{equation}
Here, $u(x,t)$ represents the population density. The function \( m(x) \in C^1([0,1])\) represents the driving force of external environmental factors on species advection, such as wind and water currents, and the parameter $s$ characterizes the advection strength. The space dependent function $\sigma\in C ([0,1])$ quantifies environmental suitability in space, integrating growth-promoting and resource-limiting factors. To compare the effects of different advection mechanisms, we fix the function $\sigma(x)$ and impose the following structural conditions for mathematical analysis.
\begin{assumption}\label{A:s}
For the constants $0<a<b<1$, $\sigma\in C ([0,1])$ satisfies the following conditions.
%(1) $\sigma(x)\in C[0,1]$ with $\sigma(x)<\sigma(a)=\sigma(b)$ for $x\in [0,a)\cup(b,1]$.

(1) The total mass of $\sigma(x)$ is positive: $\int_a^b \sigma(x)\mathrm{d} x>0$.

(2) The maximum $\sigma^{*}\triangleq\max_{x\in [a,b]} \sigma(x)$ satisfies $\frac{\pi^2}{(b-a)^2}-\sigma^{*}>0$.

(3) For small $\varepsilon>0$, $\sigma(x)$ is negative on $[a,a+\varepsilon)\cup(b-\varepsilon,b]$ and positive on $(a+\varepsilon,b-\varepsilon)$. Additionally, $\sigma(x)<\sigma(a)=\sigma(b)<-\frac{32}{3}(b-a-4\varepsilon)^{-2}$ for $x\in [0,a)\cup(b,1]$.
\end{assumption}
To proceed, we define $\tilde{\lambda}^{\mathcal{N}}$ and $\tilde{\lambda}^{\mathcal{D}}$ as the principal eigenvalues of the equations
$$
-\phi_{xx}-\sigma(x)\phi=\tilde{\lambda}\phi,\quad a<x<b,
$$
with Neumann boundary conditions ($\phi_x(a)=\phi_x(b)=0$) and Dirichlet boundary conditions ($\phi(a)=\phi(b)=0$), respectively. Then we have the following lemma.
\begin{lemma}\label{611}
For $\sigma$ satisfying Assumption \ref{A:s}, the following holds
$$\tilde{\lambda}^{\mathcal{N}}<0<\tilde{\lambda}^{\mathcal{D}}<-\sigma(x),\quad x\in[0,a]\cup[b,1].$$
%where $\lambda^{\mathcal{D}}$ and $\lambda^{\mathcal{N}}$ are defined in \eqref{vd} and \eqref{vn}, respectively.
\end{lemma}

\begin{proof}
Notice that the variational characterizations of $\tilde{\lambda}^{\mathcal{D}}$ and $\tilde{\lambda}^{\mathcal{N}}$ are same as the ones in \eqref{vd} and \eqref{vn} with $d=1$ and $c(x)\triangleq -\sigma(x)$, that is,
\begin{equation*}
\tilde{\lambda}^{\mathcal{D}}=\min_{\phi\in H_0^1((a,b))\atop\int_a^b\phi^2\mathrm{d} x=1}\int_a^b(|\phi'|^2-\sigma(x)|\phi|^2)\mathrm{d} x
\,\text{ and }\,\,
\tilde{\lambda}^{\mathcal{N}}=\min_{\phi\in H^1((a,b))\atop\int_a^b\phi^2\mathrm{d} x=1}\int_a^b(|\phi'|^2-\sigma(x)|\phi|^2)\mathrm{d} x.
\end{equation*}
Then testing with the constant function $\phi\equiv1$ on $[a,b]$ in the variational formula with condition (1) of Assumption \ref{A:s}, we obtain $\tilde{\lambda}^{\mathcal{N}}<0$.

Let $v$ be the eigenfunction corresponding to $\tilde{\lambda}^{\mathcal{D}}$. Since $v(a)=v(b)=0$, the Poincar\'{e} inequality  yields $\int_a^b |v'(x)|^2\mathrm{d} x \ge \frac{\pi^2}{(b-a)^2}\int_a^b v^2 \mathrm{d} x$. Substituting this into the variational formula for $\tilde{\lambda}^{\mathcal{D}}$ and using condition (2) in Assumption \ref{A:s}, we derive
$$
\tilde{\lambda}^{\mathcal{D}}\ge \frac{\int_a^b [\frac{\pi^2}{(b-a)^2}-\sigma(x)]v^2 \mathrm{d} x}{\int_a^b v^2 \mathrm{d} x}\ge \frac{\pi^2}{(b-a)^2}-\sigma^*>0.
$$


By condition (3) of Assumption \ref{A:s}, it suffices to show $\tilde{\lambda}^{\mathcal{D}}<-\sigma(a)$ to complete the proof. We construct a test function $\bar{v}$ as follows:
\begin{equation}\label{test1}
\bar{v}(x) = \left\{ \begin{array}{lcl}
0, && x\in[a,a+2\varepsilon),\\
\frac{x-a-2\varepsilon}{\delta}, && x\in[a+2\varepsilon,a+2\varepsilon+\delta),\\
1, & & x\in [a+2\varepsilon+\delta,b-2\varepsilon-\delta],\\
-\frac{x-b+2\varepsilon}{\delta}, & & x\in(b-2\varepsilon-\delta,b-2\varepsilon], \,\, \\
0,&& x\in[b-2\varepsilon,b], \end{array} \right.
\end{equation}
where $\delta=\frac{3}{8}(b-a-4\varepsilon)$ and $\epsilon>0$ is small enough. Substituting $\bar{v}$ into the variational formula for $\tilde{\lambda}^{\mathcal{D}}$ in \eqref{vd}, we get
\begin{align*}
\tilde{\lambda}^{\mathcal{D}}&\leq
\frac{\int_{a+2\varepsilon+\delta}^{a+2\epsilon} \delta^{-2} \mathrm{d} x-\int_{a+2\varepsilon}^{b-2\varepsilon} \sigma(x)\bar{v}^2\mathrm{d} x
+\int_{b-2\varepsilon-\delta}^{b-2\epsilon} \delta^{-2} \mathrm{d} x}{\int_{a+2\varepsilon}^{b-2\varepsilon} \bar{v}^2 \mathrm{d} x}\\
&=\frac{2\delta^{-1}-\int_{a+2\varepsilon}^{b-2\varepsilon} \sigma(x)\bar{v}^2\mathrm{d} x}{b-a-4\varepsilon-\frac{4}{3}\delta}\\
&\leq
\frac{2\delta^{-1}+(b-a-4\varepsilon-\frac{4}{3}\delta)\max_{x\in[a+2\varepsilon,b-2\varepsilon]}[-\sigma(x)]}
{b-a-4\varepsilon-\frac{4}{3}\delta}\\
&\leq 2\delta^{-1}(b-a-4\varepsilon-\frac{4}{3}\delta)^{-1}=\frac{32}{3}(b-a-4\varepsilon)^{-2}<-\sigma(a),
\end{align*}
where the last two inequalities follow from condition (3) in Assumption \ref{A:s}. This completes the proof.
\end{proof}



To see the impact of advection on population dynamics, we first consider a unidirectional advection term for comparison.


\textbf{Unidirectional advection ($m_x(x)\equiv-1$).}
In this case, the long-term population dynamics are determined by the stability of the trivial solution \( u\equiv0 \), which is determined by the principal eigenvalue of the associated  linearized equation of \eqref{E0}: % The  eigenvalue problem is written as:
\begin{equation}
\left\{
\begin{array}{l}
 -\phi_{xx}+2s\phi_x-\sigma(x)\phi=\lambda_1(s)\phi,\quad 0<x<1, \\
\phi_x(0 )=\phi_x(1 )=0,
\end{array}\right.\label{Ee}
\end{equation}
where $\lambda_1(s)$ is the principal eigenvalue with eigenfunction $\phi$.
The following theorem provides an explicit criterion for population persistence or extinction when the advection strength is large by [Theorem 1.1 \cite{CL}].
\begin{proposition}\label{p5}
For the eigenvalue problem \eqref{Ee} and model \eqref{E0} with $m_x(x)\equiv-1$, the following results hold. \\
(i) If $\sigma(0)>0$, then there exists $S>0$ such that for $s>S$, we have $\lambda_1(s)<0$, and \eqref{E0}  has a unique positive steady state $u^*$, which is globally asymptotically stable.\\
(ii) If $\sigma(0)<0$, then there exists $S>0$ such that for $s>S$, we have $\lambda_1(s)>0$, and \eqref{E0} has no positive steady state. All nonnegative solutions to \eqref{E0} decay exponentially to zero as $t\to \infty$.
\end{proposition}
 This proposition provides a criterion for the long-term dynamics of the equation with large advection. Simply speaking, when the advection rate \( s \) is sufficiently large, the species can persist if \( \sigma(0) > 0 \),
while will go extinct if \( \sigma(0) < 0 \). If we consider the interval as a river segment where $x=0$ corresponds to the upstream source and $x=1$ corresponds to the end of downstream.
Then Proposition \ref{p5} asserts that if the advection rate $s$ is large, the species can persist only if the some resource is supplied at the upstream source; otherwise, the species will go extinct in the river.
 %Now we give the proof.
\begin{proof}
From Theorem 1.1 in \cite{CL}, we directly obtain that
$$
\lim_{s\to\infty}\lambda_1(s)=-\sigma(0).
$$
If $\sigma(0)>0$, there exists $S>0$, such that $\lambda_1(s)<0$, for $s>S$. According to Proposition 3.2 of \cite{book}, we can immediately derive (i). Similarly, if $\sigma(0)<0$, there exists $S>0$, such that $\lambda_1(s)>0$, for $s>S$, leading to (ii) in view of Proposition 3.1 of \cite{book}.
\end{proof}

\textbf{Case of complex advection (infinitely oscillating $m$).}
If the advection velocity field has complex structure like the potential function $m^*$ constructed in the proof of Theorem \ref{robin} in Section 5, the population dynamics can become complex. %?We now state the following theorem and write the detailed assumption situation the prove of Theorem \ref{subseqs} in the finally for reading friendly?

For the constructed potential function $m^*$, the eigenvalue problem of \eqref{E0} can be written as
\begin{equation}
\left\{
\begin{array}{l}
-\phi_{xx}-2sm^*_x \phi_x+c(x)\phi=\lambda_1(s;m^*)\phi(x),\quad 0<x<1,\\
\phi_x(0)=\phi_x(1)=0,
\end{array}\right.\label{E:example}
\end{equation}
where $c(x):= -\sigma(x)$ and $\lambda_1(s;m^*)$ is the principal eigenvalue of problem \eqref{E:example}.
%Note that $\tilde{c}(x)$ is a fixed function that will be determined later.


We use Lemma \ref{611} and Theorem \ref{robin} to derive the following results that characterizing the population dynamics of \eqref{E0}, when the potential function $m^*$ has infinitely many oscillation.
%Keep this lemma in mind and we would easily obtain the following theorem.
\begin{proposition}\label{6}
For the eigenvalue problem \eqref{E:example} and model \eqref{E0} with $m(x)=m^*(x)$, under Assumption \ref{A:s}, the following results hold.  \\
(i) There exists a subsequence $\{s_i\}_{i=1}^{\infty}$ of $s\to\infty $, and an integer $I_0\in\mathbb{N}$, such that
 $\lambda_1(s_i;m^*)<0$ for  $i>I_0$. Along this sequence $\{s_i\}_{i>I_0}$, equation \eqref{E0}  has a unique positive steady state $u^*$, which is global asymptotically stable.\\
 (ii) There exists a subsequence $\{s_j\}_{j=1}^{\infty}$  of $s\to\infty $, and an integer $J_0\in\mathbb{N}$, such that
 $\lambda_1(s_j;m^*)>0$ for  $j>J_0$.
 Along this sequence $\{s_j\}_{j>J_0}$,
equation \eqref{E0} has no positive steady state, and all nonnegative solutions decay exponentially to zero as $t\to \infty$.%, and $\{s_j\}_{j>J_0}$.
\end{proposition}
\begin{proof}

%Recall the function $m^*(x)$ is constructed through infinite folding of $m_1$ following the proof of Theorem \ref{robin} and the function $\sigma(x)$ satisfy \ref{A:s}.

Applying Theorem \ref{robin} and  Lemma \ref{611}, we can find two subsequences $\{s_i\}_{i=1}^\infty$ and $\{s_j\}_{j=1}^\infty$ such that
$$
 \lim_{i\to\infty}\lambda_1(s_i;m^*)=\tilde{\lambda}^{\mathcal{N}}<0,\quad\quad  \lim_{j\to\infty}\lambda_1(s_j;m^*)=\tilde{\lambda}^{\mathcal{D}}>0.
$$
Therefore, there exist $I_0$ and $J_0$ such that
$\lambda_1(s_i;m^*)<0$ for  $i>I_0$, and $\lambda_1(s_j;m^*)>0$ for  $j>J_0$.
Applying Proposition 3.1 and Proposition 3.2 in \cite{book} along these subsequences $\{s_i\}_{i=1}^\infty$ and $\{s_j\}_{j=1}^\infty$, we could complete the proof.
\end{proof}
Proposition \ref{6} indicates that when the potential function is complex and the advection strength is strong, both persistence and extinction of the population are possible because the associated principal eigenvalue changes sign, which leads to a shift of the stability$\setminus$instability as $s$ increases.

For more clearly explanation, we consider the following example of $\sigma$.
\begin{example}
Let $a=\frac{1}{4}$, $b=\frac{3}{4}$. We construct a symmetric function $\sigma(x)$ on $[0,1]$, i.e.,  $\sigma(\frac{1}{2}-x)=\sigma(\frac{1}{2}+x)$, with the following piecewise form
\begin{equation*}
\sigma(x) = \left\{ \begin{array}{lcl}
-96, && x\in[0,\frac{1}{4}),\\
3072 x-864, && x\in[\frac{1}{4},\frac{9}{32}),\\
-512(x-\frac{1}{2})^2+\frac{49}{2}, & & x\in [\frac{9}{32},\frac{1}{2}].
\end{array} \right.
\end{equation*}
\end{example}
It is easy to verify that the above constructed $\sigma(x)$ satisfies Assumption \ref{A:s}. For this specific $\sigma(x)$, when $m_x=-1$, Proposition \ref{p5} shows that the population extinction occurs if the advection strength is large enough; while when $m=m^*$, Proposition \ref{6} asserts that the population dynamic become indeterminable for large advection strength, where either persistence or extinction is possible.


