We denote by $\pee\!_\mu$ the path-space measure of the process $\{\eta_n,n\in\N\}$ starting from $\eta_0$ distributed according to $\mu$.
For a local function $h: \Omega_{S\!T}\to\R$, we define similarly, as in Section \ref{pcasect}, the oscillation $\delta_{x,n} h$, and the Gaussian concentration bound
where now $\|\delta h\|_2^2=\sum_{(x,n)\in\Zd\times\N} (\delta_{x,n} h)^2$.
\subsection{Contraction properties}
The following lemma is taken from \cite[Lemma 2, p. 136)]{lms}.
\bl\label{contlem}
Let $f:\Omega_S\to\R$ be a local function.
Then
\be\label{maeslem}
\delta_x (Pf) \leq \sum_{y\in\Zd} \sum_{A\ni x-y} |r\!_A|\, \delta_y (f),\;\forall x\in\Zd.
\ee
\el
The following corollary gives an estimate of the $\ell^2$-norm of $\delta(Pf)$.
\bc\label{contcol}
Define
$\psi(x)= \sum_{A\ni x} |r\!_A|$, $x\in\Zd$.
Let $f:\Omega_S\to\R$ be a local function. Then we have the estimate
\be\label{twonorm}
\|\delta (Pf)\|_2^2\leq \|\psi\|_1^2 \,\|\delta f\|_2^2,
\ee
where
\[
\|\psi\|_1= \sum_{x\in\Zd} \psi(x)= \sum_{A\Subset\Zd} |A||r\!_A|.
\]
As a consequence, we have
%\be\label{bawaf}
\[
\|\delta (P^n f)\|_2^2
\leq 
\|\psi\|_1^{2n} \|\delta f\|_2^2,\; \forall n\geq 1.
\]
%\ee
\ec
\bpr
Notice that by the definition of $\psi$, the right-hand side of \eqref{maeslem} reads
$\sum_{y\in\Zd} \psi(x-y)\, \delta_y f= (\psi*\delta f)_x$. Because $\delta_x (Pf)\geq 0$ for all $x$,  we then have the estimate
\[
\|\delta (Pf)\|_2^2=\sum_{x\in\Zd}(\delta_x(Pf))^2\leq \sum_{x\in\Zd}(\psi*\delta f)_x^2= \|\psi*\delta f\|_2^2\leq \|\psi\|_1^2\, \|f\|_2^2\,,
\]
where in the last step we used Young's convolution inequality. We then obtain
\[
\|\psi\|_1=\sum_{x\in\Zd}\psi(x)= \sum_{x\in\Zd}\sum_{A\ni x} |r_A|
= \sum_{A\Subset \Zd} |A|\, |r_A|.
\]
The last statement follows by iteration:
\[
\|\delta (P^n f)\|_2^2
\leq 
\| \psi\|_1^2 \|\delta (P^{n-1} f)\|_2^2\leq\cdots\leq 
\|\psi\|_1^{2n} \|\delta f\|_2^2
\]
\epr
For later convenience we abbreviate
\be\label{kappa}
\kappa= \|\psi\|^2_1=\bigg(\,\scaleto{\sum_{A\Subset\Zd}}{22pt} |A|\, |r_A|\bigg)^2,
\ee
which by \eqref{twonorm} can be thought of as a contraction coefficient.
When $\kappa<1$ we say that the PCA is contractive, which implies uniqueness of the stationary measure $\mu$ and exponentially fast convergence to $\mu$ in the course of time.

\medskip

%{\color{blue}Dans \cite{lms}, il y a deux autres conditions : \\
%$\sum_A |r_A|<1$ et $\sum_y \sup_\si \Big| \sum_{A\ni y} r_A \si\!_A\Big|<1$. \\
%A comparer avec $\kappa<1$.}

%In a later section (section \ref{relaxsec} below) we will also use the $\ell^2$-norm of $\psi$, i.e.,
%\[
%\label{l2normpsi}
%\|\psi\|^2_2=\sum_{x\in\Zd}\psi(x)^2= \sum_{x\in\Zd}\sum_{A, B\ni x}|r_B| |r_A|= \sum_{A, B} |A\cap B| \, |r_A r_B|.
%\]
