\section{GCB and time-evolution under a PCA}\label{pcaev}

\subsection{Propagation of GCB}
The first result shows that if we start from a probability measure satisfying $\gcb{C}$, then this property is conserved under the PCA evolution, with the associated constant evolving in time in a controlled manner, determined by the contraction coefficient $\kappa$ in \eqref{kappa}.

%%%% THEOREM
\bt[GCB is conserved under PCA evolution]\label{conservation}
\leavevmode\\
Let $\mu$ be a probability measure on $\Omega_S$ satisfying $\gcb{C}$, and $P$ the transition operator of a PCA, as
in Section \ref{pcasect}. Then we have the following.
\begin{enumerate}[\textup{(}a\textup{)}]
\item
$\mu P$ satisfies $\gcb{C_1}$ with
\[
C_1 = c+ C\kappa,
\]
where $c$ denotes the constant of the Gaussian concentration bound for a product measure (see Remark \ref{prodrem}, item 2). In particular we can choose $c=1/4$. 
%{\color{red}[On sait que $c=1/8$, pourquoi laisser cette constante $c$ comme si on ne la connaissait pas explicitement ?]}
\item
As a consequence, for all $n\in\N$,  $\mu P^n$ satisfies $\gcb{C_n}$ with
\[
C_n=
\begin{cases}
c\frac{\,\,1-\kappa^n}{1-\kappa} + C\kappa^n & \text{if}\;\; \kappa\not=1,
\\
c\,n+ C  & \text{if}\ \kappa=1.
\end{cases}
\]
\item
If $\kappa <1$, then $\mu P^n\to\nu$ where $\nu$, the unique stationary probability measure, satisfies $\gcb{C_\infty}$ with
\[
C_\infty= \frac{c}{1-\kappa}.
\]
\item Noninteracting case. When $h_x(\si_n)= h_x(\si_{n,x})$, we say that the PCA is non-interacting. In that case, GCB is conserved, and the unique stationary measure is a product measure, hence also satisfies GCB.
\end{enumerate}
\et
%%%% PROOF
\bpr
Let $f:\Omega_S\to\R$ be a local function.
We have
\begin{align}\label{fipo}
\MoveEqLeft\int \mu P (\dd\si) \e^{f(\si)- \int f(\si)\mu P (\dd\sigma) }
\\
&=\int\mu(\dd\si) \int p(\dd\eta|\si) \e^{f(\eta) - \int f(\eta) p(\dd\eta|\si)} \e^{\int f(\eta) p(\dd\eta|\si)- \iint f(\eta) p(\dd\eta|\si) \mu(\dd\si)}.
\nonumber
\end{align}
Now we use that $p(d\eta|\si) $ is a product measure and as a consequence of $\gcb{c}$ we have, uniformly in $\si$:
\be\label{bala}
\int p(\dd\eta|\si) \e^{f(\eta) - \int f(\eta) \, p(\dd\eta|\si)}\leq \exp\left({\tfrac{c}{2}\|\delta f\|_2^2}\right).
\ee
Next, using the fact that $\mu$ satisfies $\gcb{C}$, combined with Corollary \ref{contcol} and \eqref{kappa}, shields
\begin{align}
\nonumber
\MoveEqLeft[4] \int \mu(\dd\si) \e^{\int f(\eta) p(\dd\eta|\si)- \iint f(\eta) p(\dd\eta|\si) \mu(\dd\si)}\\
&=\int \mu(\dd\si) \exp\left({ Pf(\sigma) - \int Pf(\si) \mu (\dd\si)}\right)
\nonumber\\
&\leq  \exp\left({\tfrac{C}{2} \|\delta (P f)\|_2^2}\right)
\nonumber\\
&\leq  \exp\left({\tfrac12 C \kappa\|\delta ( f)\|_2^2}\right).
\label{flipo}
\end{align}
Combining \eqref{bala} and \eqref{flipo}, we find
\[
\int \mu P (\dd\si) \e^{f(\si)- \int \mu P (\dd\sigma) f(\si)} \leq 
\exp\left({ \tfrac12(c+ C\kappa)\|\delta f\|_2^2}\right),
\]
which proves the first statement of the theorem.
The second statement follows by iteration, and the third one by taking the limit $n\to\infty$ which is possible when $\kappa<1$.
In case the PCA is non-interacting, a product measure is mapped to a product measure. Moreover, by the non-interacting property, we have for all $k\in \N$
and $x\in\Zd$ that $(\delta P^k f)_x\leq \delta_x f$ and $\delta_\si P^k$ is a product measure for all $k\in\N$.
Therefore, in that setting we can repeat \eqref{fipo}, \eqref{bala}, \eqref{flipo}, replacing $P$ by $P^k$ to conclude that $\mu P^k$ satisfies GCB with constant $C_k= C + c$.
\epr

\subsection{GCB of the space-time measure}

Our second main result shows that for a contractive PCA, {\em i.e.}, when $\kappa<1$, a space-time measure $\pee\!_\mu$ satisfies $\gcb{C}$ if
and only if the starting measure $\mu$ satisfies $\gcb{C'}$. One direction of this equivalence is obvious, because the Gaussian concentration bound
for $\pee\!_\mu$ immediately implies the Gaussian concentration bound for the single-time (at time zero) marginal $\mu$. The other implication is less obvious and shows that space-time Gibbs measures associated to PCA's are special ({\em i.e.}, not like generic Gibbs measures, see Section 4.1 below).


\bt\label{spacetime}
Consider a contractive PCA with transition operator $P$, that is, suppose that $\kappa<1$ (see \eqref{kappa} for the definition).
Let $\mu$ denote a probability measure on $\Omega_S$ and let $\pee\!_\mu$ denote the corresponding path-space measure.
Assume that $\mu$ satisfies $\gcb{C}$. Then there exists $C'$ such that  $\pee\!_\mu$ satisfies $\gcb{C'}$.
As a consequence, for the unique stationary measure $\nu$, the corresponding path-space measure
$\pee\!_\nu$ satisfies $\gcb{C'}$.
\et
\bpr
The consequence follows immediately from the fact that in the contractive regime $\kappa<1$, the
unique stationary measure satisfies $\gcb{C}$ for some $C>0$ by Theorem
\ref{conservation}.
We start by considering a local function $f(\si_0,\si_1)$ depending on the space-time configuration at times zero and one and estimate its centered moment generating function.
This example will make clear how to deal with a local function depending on the space-time configuration at times zero up to $n$.
We first fix some notation.
We define for a function $f: \Omega_{S\!T}\to\R$ its oscillation vector at time $n\in\N$ by
\[
%\label{vark}
\delta_{x}^n f= \sup_{\si\in \Omega_{S\!T}} \big(f(\si^{\scaleto{(x,n)}{6pt}})- f(\si)\big).
\]
We think of this as a vector indexed by $n$, and with $x$ the ``running'' index.
We have obviously
\[
%\label{obvi}
\|\delta f\|_2^2 = \sum_{x\in\Zd,\, n\in\N} (\delta_{x}^{n} f)^2= \sum_{n\in\N} \|\delta^n f\|_2^2,
\]
where, with small abuse of notation,
\[
\|\delta^n f\|_2^2= \sum_{x\in\Zd} (\delta_{x}^{n} f)^2
\]
denotes the $\ell^2$-norm of the vector $\delta^n f$.

Let $f:\Omega_{S\!T}\to\R$ be of the form $ f(\si_0, \si_1)$. Then we write
\begin{align}\label{barastra}
\MoveEqLeft[4]\int \exp \left( f(\si_0, \si_1)- \int f \dd\pee_\mu\right) \dd\pee\!_\mu(\si_0, \si_1)=
\nonumber\\
& \hspace{-1.5cm} \iint \mu(\dd\si_0)\, p(\dd\si_1|\si_0)\left[ \exp \left(f(\si_0, \si_1)-  \int p(\dd\si_1|\si_0)\, f(\si_0, \si_1)\right)\right.
\nonumber\\
& \hspace{-1cm}\left.\exp \left( \int p(\dd\si_1|\si_0)\, f(\si_0, \si_1)-\iint\mu(\dd\si_0) \, p(\dd\si_1|\si_0)\, f(\si_0, \si_1)\right)\right].
\end{align}
Using that $p(\dd\si_1|\si_0)$ is a product measure which therefore satisfies $\gcb{c}$, we start then by estimating
\begin{align}\label{inner}
\MoveEqLeft[4] \int p(\dd\si_1|\si_0)\,\exp \left(f(\si_0, \si_1)-  \int p(\dd\si_1|\si_0)\, f(\si_0, \si_1)\right)
\nonumber\\
&\leq \exp \big(\tfrac12 c\|\delta f_{\si_0}\|_2^2\big)\,,
\end{align}
where $f_{\si_0}:\Omega_S\to\R$ is the function defined by $f_{\si_0} (\si)= f(\si_0, \si)$.
As a consequence, we have for all $\si_0\in\Omega_S$ the estimate $\delta_x f_{\si_0}\leq \delta_{x}^1 f$, and therefore,
\[
\|\delta f_{\si_0}\|_2^2\leq \|\delta^1 f\|_2^2\,.
\]
Next, using the fact that $\mu$ satisfies $\gcb{C}$ we tackle the second factor in \eqref{barastra} as follows:
\begin{align}\label{outer}
\MoveEqLeft \int \mu(\dd\si_0)\exp \left( \int p(\dd\si_1|\si_0) f(\si_0, \si_1)-\iint\mu(\dd\si_0)\, p(\dd\si_1|\si_0) f(\si_0, \si_1)\right)
\nonumber\\
&=
\int \mu(\dd\si_0) \exp \left(F(\si_0)-\int F(\si_0)\mu(\dd\si_0)\right)
\nonumber\\
&\leq
\exp \left(\tfrac{C}{2} \|\delta F\|_2^2\right),
\end{align}
where we denoted  $F(\si)= \int p(\dd\si_1|\si) f(\si,\si_1)$. Then we are left with estimating $\|\delta F\|_2^2$. We have
\begin{align*}
&F(\si^{\sx})- F(\si)\\
&= \int p(\dd\si_1|\si^{\sx}) \left(f(\si^{\sx},\si_1)- f(\si, \si_1)\right)\\
& \qquad + \int p(\dd\si_1|\si^{\sx}) f(\si,\si_1)- \int p(\dd\si_1|\si) f(\si,\si_1)\\
&\leq \delta_{x,0} f + \big(P (f_\si))[\si^{\sx}]- (P(f_\si)\big) [\si],
\end{align*}
where $f_\si:\Omega\to\R: \eta\mapsto f(\si,\eta)$, and as a consequence,
\[
Pf_\si (\eta)= \int f_\si(\xi) \,p(\dd\xi|\eta)= \int f(\si, \xi)\, p(\dd\xi|\eta).
\]
Therefore, using Lemma \ref{contlem}, we obtain
\be\label{peest}
(P (f_\si))\big(\si^{\sx}\big)- (P(f_\si)) (\si)\leq (\psi*\delta f_\si)_x\leq (\psi* \delta^1 f)_x.
\ee
Combining then \eqref{inner}, \eqref{outer}, \eqref{peest}, we obtain
\[
\log \int \exp \left( f(\si_0, \si_1)- \int f \dd\pee\!_\mu\right) \dd\pee\!_\mu \leq \tfrac{c}{2} \, \big\|\delta^1 f \big\|_2^2+  
\tfrac{C}{2}\Big(\big\|\delta^0 f + \psi* \delta^1 f \big\|_2^2\Big).
\]
Considering now a function $f(\si_0,\si_1,\ldots,\si_n)$, that is, a function of the configuration at times $0$ up to $ n$, we can iteratively proceed as before by writing
\begin{align*}
\MoveEqLeft \int \exp \left( f(\si_0,\ldots,\si_n)- \int f \dd\pee\!_\mu\right) \dd\pee\!_\mu\\
&=\int \mu(\dd\si_0) \int p(\dd\si_1|\si_0)\cdots \int p(\dd\si_n|\si_{n-1})\\
&\qquad \Bigg[\exp\Big(f- \int p(\dd\si_n|\si_{n-1})f(\si_0,\ldots, \si_{n-1},\si_n)\Big)\\
&\;\;\qquad\exp\Bigg(\int p(\dd\si_n|\si_{n-1})f(\si_0,\ldots, \si_{n-1},\si_n)\\
& \quad\qquad\qquad -\int p(\dd\si_{n-1}|\si_{n-2})\, p(\dd\si_n|\si_{n-1})f(\si_0,\ldots, \si_{n-1},\si_n)\Bigg)\\
&\qquad\quad \cdots \exp\left(\int f_{\si_0} \dd\mu-\int f\dd\pee\!_\mu\right)\Bigg].
\end{align*}
Then we estimate the different factors, from inner to outer, by using $\gcb{c}$ for product measures, and for the final (outer) integral
$\gcb{C}$ for the measure $\mu$.
This gives the following estimate
\begin{align}\label{baster}
\MoveEqLeft 2\log\int \exp \left( f(\si_0, \si_1,\ldots,\si_n)- \int f \dd\pee\!_\mu\right) \dd\pee_\mu(\si_0, \si_1,\ldots,\si_n)
\nonumber\\
&\leq
c\, \|\delta^n f\|_2^2
\nonumber\\
&\quad +
c\, \big\|\delta^{n-1}f + \psi* \delta^{n} f\big\|_2^2
\nonumber\\
& \quad\;\, \vdots \nonumber \\
&\quad +
c\, \big\| \delta^1 f + \psi* \delta^2 f + \cdots + (\psi^*)^{n-1}*\delta^n f \big\|_2^2
\nonumber\\
&\quad +  C\,\big\| \delta^0 f + \psi* \delta^1 f + \cdots + (\psi^*)^{n}*\delta^n f \big\|_2^2,
\end{align}
where $(\psi^*)^k$ denotes the $k$-fold convolution power of $\psi$.
We are now left with estimating the rhs of \eqref{baster}.

Now recall the notation \eqref{kappa}, then  we have, by iterative application of Young's inequality,
\begin{equation}\label{kopu}
\|(\psi*)^k*(\delta^j f)\|_2\leq \|\psi\|_1^k\, \|(\delta^j f)\|_2 =\kappa^{k/2}\, \|(\delta^j f)\|_2
\end{equation}
As as consequence, combining \eqref{kopu} with by Minkowski inequality
$\|f+g\|_2\leq \|f\|_2+\|g\|_2$, we can estimate the terms appearing in the rhs of \eqref{baster} as follows
\begin{align*}
& \big\|\delta^{n-1}f + \psi* \delta^{n} f\big\|_2^2 \; \leq \; \big(\big\|\delta^{n-1} f\|_2 + \sqrt{\kappa}\, \|\delta^n f\big\|_2\big)^2\\
& \qquad\qquad \vdots \\
& \big\| \delta^1 f + \psi* \delta^2 f + \cdots + (\psi^*)^{n-1}*\delta^n f \big\|_2^2\\
& \qquad\qquad\qquad\qquad\;\;\;\leq \Big( \big\| \delta^1 f \big\|_2 + \sqrt{\kappa}\,\big\| \delta^2 f \big\|_2 + \cdots + (\sqrt{\kappa})^{n-1} \big\|\delta^n f \big\|_2\Big)^2.
\end{align*}
As a consequence, the sum in the rhs of \eqref{baster} can be estimated by
$\| A v\|_{\R^{n+1}}^2$ where $\|\cdot \|_{\R^{n+1}}$ denotes Euclidean norm in $\R^{n+1}$ and where
$v$ is the vector with elements $v_i= \|\delta^{i}f\|_2$, for $i=0,1,\ldots, n$, and $A$ is the lower triangular $(n+1)\times (n+1)$ matrix whose elements are given by
\begin{align}\label{mat}
A_{i,n-j} &= \sqrt{c} \,\sqrt{\kappa}\,^{n-j}\ \  0\leq i\leq n-1,\ \ 0\leq j\leq i
\nonumber\\
A_{n, n-j} &= \sqrt{C} \,\sqrt{\kappa}\,^{n-j}\ \ \   0\leq k\leq n
\nonumber\\
A_{k,l} &= 0 \ \text{otherwise}.
\end{align}
The Euclidean norm $\|Av\|_2^2$ can therefore be estimated by $\|A\|_2^2\, \|v\|^2$. The matrix norm of $A$ can in turn be estimated by
\[
\|A\|_2^2 \leq \|A\|_\infty \|A\|_1,
\]
where
\[
\|A\|_\infty= \sup_i \sum_j |A_{i,j}|, \ \|A\|_1= \sup_j \sum_i |A_{i,j}|.
\]
Using  \eqref{mat} and the fact that $\kappa<1$, which implies that, for all $j$,
$\sum_{i=0}^j (\sqrt{\kappa})^{i}\leq \frac{1}{1-\sqrt{\kappa}}$, we obtain
\[
\|A\|_2\leq \frac{\sqrt{c}}{1-\sqrt{\kappa}}\vee \frac{\sqrt{C}}{1-\sqrt{\kappa}},
\]
whereas
\[
\| v\|^2= \sum_{k=0}^{n} \|\delta^k f\|_2^2 =  \|\delta f\|_2^2.
\]
As a consequence we obtain as a final estimate for the sum in the rhs of \eqref{baster}
\[
\|A\|_2^2\, \|v\|^2
\leq \left(\frac{\sqrt{c}}{1-\sqrt{\kappa}}\vee \frac{\sqrt{C}}{1-\sqrt{\kappa}}\right)^2\,\|\delta f\|_2^2\,,
\]
which shows that we have the Gaussian concentration bound with constant
\[
C'=\left( \frac{\sqrt{c} \vee \sqrt{C}}{1-\sqrt{\kappa}}\right)^2.
\]
The proof of the theorem is complete.
\epr

\begin{remark}
In the proof of Theorem \ref{spacetime} we used the contractive property $\kappa<1$ only in the estimation of
the norm of the matrix $A$.
As a consequence, we have that, if $\mu$ satisfies $\gcb{C}$, then the joint distribution
of $\si_0,\ldots, \si_n$ (viewed as a measure on $\{-1,1\}^{\Zd\times \{0,\ldots,n\}}$) satisfies $\gcb{\widetilde{C}_n}$
with ${\widetilde{C}_n}= \|A\|^2_2$, with $A$ the matrix given in \eqref{mat}.
If $\kappa<1$, then the matrix norm can be bounded uniformly in $n$, and therefore in that case we indeed can
consider the ``limit'' $n\to\infty$, \em{i.e.}, conclude that $\pee\!_\mu$ satisfies $\gcb{C'}$, with $C'=\sup_n  \widetilde{C}_n$.
\end{remark}
\begin{remark}
Because we have proved that the equivalence ``$\mu$ satisfies GCB with $\pee\!_\mu$ satisfies GCB'' only in the contractive regime, we cannot exclude that there are examples where $\mu$ (a stationary measure) satisfies GCB, but $\pee\!_\mu$ does not satisfy GCB, and possibly there are other stationary measures. As we will see below, in that case we can conclude that at least one of these stationary measures is non-Gibbs.
\end{remark}

\subsection{Relaxation to equilibrium via GCB and contraction estimates}\label{bamba}

In the contractive regime $\kappa<1$, there is a unique stationary measure $\nu$, and
from any initial measures $\mu$ we have that $\mu P^n\to \nu $ exponentially fast.
In this section we show how to quantify the convergence to $\mu$, in terms of a distance
(giving a stronger convergence than weak convergence), under abstract locality and a 
contraction conditions.
We start by defining these locality and contraction conditions.
\bd
\leavevmode
\ben
\item
We then say that the PCA is local with propagation speed $a\in \N$ if for all $n,k\in\N$ and
$f\in \caF_{C_n}$, we have $P^k f\in \caF_{C_{n+ ak}}$. Here as before, $C_n= [-n,n]^d\cap\Zd$.
\item We say that the PCA is contractive with contraction speed $\psi_n:\Zd\to\R^+$ if for all $n\in\N$ we have
\be\label{contspeed}
(\delta (P^n f))\leq \psi_n*\delta f,
\ee
where the inequality has to be interpreted point-wise, \em{i.e.}, $(\delta P^n f)_x\leq (\psi_n*\delta f)_x$, for all $x\in\Zd$.
\een
\ed
The condition on locality is satisfied for finite range PCA's.

In order to formulate our result, we need the following pseudo-distances.
\bd
For $\la\Subset\Zd$ we define
\[
D_{\infty,\la}(\mu,\nu) = \sup \left\{ \int f \dd\mu-\int f \dd\nu: {f\in\caF_\la},  \|\delta f\|_1\leq 1\right\},
\]
\[
D_{2,\la} (\mu,\nu)= \sup\left\{\int f \dd\mu-\int f \dd\nu: {f\in\caF_\la},  \|\delta f\|_2\leq 1\right\}.
\]
\ed
Notice that $D_{\infty,\la}(\mu,\nu), D_{2,\la} (\mu,\nu)>0$ if and only if $\mu_\la \not=\nu_\la$.

The Cauchy-Schwarz inequality  immediately gives
$\|\delta f\|_1\leq \sqrt{|\la|} \|\delta f\|_2$ and, as a consequence,
\[
\frac{D_{2,\la}}{\sqrt{|\la|}}\leq D_{\infty,\la}.
\]

For $\nu,\mu$ translation-invariant probability measures we have (see \cite{collet})
\[
\lim_{\la\uparrow\Zd}D_{\infty,\la}(\nu,\mu)=\bar{d}(\nu,\mu).
\]
The $\bar{d}$-distance is well-known and widely used in ergodic theory, see e.g. \cite{shields}. Convergence in this distance is stronger than weak convergence and  conserves, for instance,  ergodicity, mixing, and the relative entropy density w.r.t.\ a translation-invariant Gibbs measure is a continuous function w.r.t.\ this metric.
Additionally, we prove in \cite{collet} that
\[
\lim_{n\to\infty}\frac{D_{2, C_n}}{\sqrt{|C_n|}} = \bar{d}(\nu,\mu).
\]
Then we have the following result.
\bt
%\label{relax}
Assume the PCA has contraction speed $\psi$, is local with propagation speed $a\in\N$, and has a stationary measure $\mu\in \caI_\tau$ which
satisfies $\gcb{C}$.
Assume additionally that $\mu$ has ``finite energy'', {\em i.e.}, there exists $\rho>0$ such that
\[
\mu(\si_\la)\geq \e^{-\rho|\la|},\;\forall \sigma\in\Omega_S, \la\Subset\Zd.
\]
Then, for every probability measure $\nu$, and for all $n,k\in\N$, we have 
\be\label{dinf}
D^2_{\infty,C_n} (\nu P^k,\mu )\leq  2C \ent_{C_{n+ak}} (\nu|\mu) \,\|\psi_k\|_2^2,
\ee
and
\be\label{2dist}
D^2_{2,C_n} (\nu P^k,\mu )\leq 2C {\ent_{C_{n+ak}} (\nu|\mu)} \, \|\psi_k\|_1^2.
\ee
As a consequence,  for all $n,k\in\N$,
\be\label{dinfconv}
D^2_{\infty,C_n} (\nu P^k,\mu )\leq 2C\rho\, {|C_{n+ak}|}\|\psi_k\|_2^2.
\ee
If $\nu$ is a translation-invariant probability measure, then for all $k\in\N$
\be\label{dbarconv}
\bar{d}\,^2(\nu P^k,\mu)\leq 2C\rho\, \|\psi_k\|_1^2.
\ee
As a consequence, if $\|\psi_k\|_1\to 0$ as $k\to \infty$, then $\nu P^k\to\mu$ in $\bar{d}$-distance.
\et
\bpr
First observe that by the finite energy condition, for every probability measure $\nu$ we have the upper bound
\be\label{finergb}
\frac{\ent_\la(\nu|\mu)}{|\la|}\leq \rho.
\ee
We then start with the variational formula for the relative entropy combined with the locality condition, the stationarity of $\mu$, and \eqref{contspeed} to obtain
\begin{align*}
\ent_{C_{n+ak}} (\nu|\mu) &\geq  \sup_{f\in \,\caF\!_{C_n}}\left( \int P^k f \dd\nu-\int P^k f \dd\mu - \log\int \e^{P^k f-\int f \dd\mu} \dd\mu\right)\\
&\geq \sup_{f\in \,\caF\!_{C_n}}\left( \int f \dd\nu P^k-\int  f \dd\mu - \frac{C}{2}\|\psi_k*\delta f\|_2^2\right).
\end{align*}
Now we use
\[
\|\psi_k*\delta f\|_2^2\leq \|\psi_k\|_2^2\, \|\delta f \|_1^2.
\]
Replacing then $f$ by $\lambda f$ and optimizing over $\lambda$ we obtain
\eqref{dinf}.
If on the other hand we use
\[
\|\psi_k*\delta f\|_2^2\leq \|\psi_k\|_1^2 \,\|\delta f \|_2^2,
\]
and proceed with the same optimization, then we arrive at \eqref{2dist}. The result
\eqref{dinfconv} then follows immediately via \eqref{finergb}, whereas
\eqref{dbarconv} follows by first dividing both sides of \eqref{2dist} by $|C_n|$ and then taking the limit $n\to\infty$, using once more \eqref{finergb}, combined with the fact that for all $k\in \N$ we have
$\tfrac{|C_{n+ak}|}{|C_n|}\to 1$ as $n\to\infty$.
\epr
\br
Notice that if $\kappa<1$ (cf. \eqref{kappa}) then $\|\psi_1\|<\kappa$ and by iteration of Young's inequality we have
\[
\|\psi_k*\delta f\|_2^2\leq \kappa^k \|\delta f\|_2^2\,.
\]
This then leads to exponential convergence in $\bar{d}$-distance, {\em i.e.},
\[
\bar{d}(\nu P^k,\mu)\leq 2C\rho\, \kappa^k.
\]
The exponential convergence in $\bar{d}$-distance for a class of PCA's and interacting particle systems was obtained in \cite{steiff} using coupling methods.
\er


