\subsection{Notation}\label{sec_notation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We denote open balls of radius $ r>0 $ and center $ p\in\R^n $ by $ B_r(p) $.
For a smooth map $ f:\Omega\subseteq \R^m\to\R $ we write
\begin{align*}
	\norm{f}_{C^k(\Omega)}&:=\sum_{\abs{\alpha}\leq k} \sup_{x\in \Omega} \abs{D^\alpha f(x)},\\
	\norm{D^kf}_{C^0(\Omega)}&:=\sum_{\abs{\alpha}= k} \sup_{x\in \Omega} \abs{D^\alpha f(x)},
\end{align*}
and for maps $ f:\Omega\subseteq \S^2\to\R^3 $ we define $ C^k $ norms by fixing charts of $ \S^2 $.
For an interval of radii $ I\subseteq (0,\infty) $ we denote an annulus by $$ \Ann I:=\left\{(x,y)\in\R^2 \ \mid \  \sqrt{x^2+y^2}\in I \right\}. $$
\subsection{Gluing Round Spheres to Catenoids}\label{sec_gluingCatSph}
For the remainder of this section, we fix for all $ \delta>0 $ a gluing function $\phi\in C^\infty(\R,\R)$ with
\begin{align*}
	\phi(x) = \begin{cases}
		0 \quad ,x\leq1-\delta,\\
		1 \quad ,x\geq1+\delta,
	\end{cases}
\end{align*}
and the properties $ \abs{\phi}\leq 1, \abs{\phi'}\leq M\delta^{-1}, \abs{\phi''}\leq M\delta^{-2} $ for some constant $ M>0 $ independent of $ \delta $.
A standard mollifier serves to construct such a function.
\com{One example can be defined as follows.
	\begin{align*}
		c&:=\int_{-1}^{1} e^{\frac{1}{x^2-1}} dx,\\
		f(x)&:= \begin{cases}
			\frac1c e^{\frac{1}{x^2-1}} \quad &, -1<x<1,\\
			0 \quad &, \abs{x}\geq 1,
		\end{cases}\\
		g(x)&:=\int_{-1}^{x} f(s)ds.
	\end{align*}
	The function $ g $ is smooth and satisfies $ \abs{g'}< 1 $ and $ \abs{g''}< 1 $. %numerically
	Now, we can set $ \phi(x):=g\left( \frac{x-t}{\delta} \right) $ which has the stated properties.
}
\begin{defn}\label{def_gluing}
	For $ \delta\in(0,1) $, the gluing function $ \phi:\R \to \R $, the annulus\linebreak $ A:=\Ann[1-\delta,1+\delta] $ and two graphs $ f_1,f_2:A\to\R^3  $ with $ f_i(x,y) = (x,y,u_i(x,y)) $ for some $ u_1,u_2\in C^2(A,\R) $, we define the \textit{$ \delta $-gluing} of $ f_1 $ and $ f_2 $ as the graph $ \tilde{f}(x,y)=(x,y,\tilde{u}(x,y)) $ where $ \tilde{u} $ is defined as
	\begin{align*}
		\tilde{u}(x,y):=\left( 1- \phi\left(\sqrt{x^2+y^2}\right) \right) u_1(x,y) + \phi\left(\sqrt{x^2+y^2}\right) u_2(x,y).
	\end{align*}
\end{defn}
\begin{lem}\label{lem_gluingLemma}
	Let $ \delta\in (0,1) $. Then, there exists some constant $ C(M,\delta)>0 $ such that the following holds. For all $A,f_1,f_2,u_1,u_2 $ as above which in addition satisfy $ \norm{u_i}_{C^2(A)}\leq 1 $, the $ \delta $-gluing $ \tilde{f} $ of $ f_1 $ and $ f_2 $ satisfies
	\begin{align*}
		W(\tilde f) \leq W(f_1)+ C \norm{f_2-f_1}_{C^2(A,\R^3)}.
	\end{align*}
\end{lem}
\begin{proof}
	Consider the involved graphs in polar coordinates $ (x,y)= r(\cos\varphi,\sin \varphi) $. Then, the $ \delta $-gluing $ \tilde{u}(r,\varphi):=u_1(r,\varphi) +  \phi(r)\left( u_2(r,\varphi) - u_1(r,\varphi)  \right) $ has the derivatives
	\begin{align*}
		\partial_r \tilde u &= \partial_r u_1 + \phi \cdot \partial_r(u_2-u_1) + \phi' \cdot (u_2-u_1),\\
		\partial_\varphi \tilde u &= \partial_\varphi u_1 + \phi \cdot \partial_\varphi(u_2-u_1),\\
		\partial_{rr} \tilde u &= \partial_{rr}u_1 + \phi \cdot \partial_{rr}(u_2-u_1) + 2\phi' \cdot \partial_r(u_2-u_1) + \phi'' \cdot (u_2-u_1),\\
		\partial_{\varphi\varphi} \tilde u &= \partial_{\varphi\varphi} u_1 + \phi \cdot \partial_{\varphi\varphi} (u_2-u_1),\\
		\partial_{r \varphi} \tilde u &= \partial_{r \varphi} u_1 + \phi \cdot \partial_{r \varphi} (u_2-u_1) + \phi' \cdot \partial_\varphi (u_2-u_1).
	\end{align*}
	Since $ \delta<1 $ we have $ \abs{\phi},\abs{\phi'},\abs{\phi''}\leq\frac{M}{\delta^2} $. It follows
	\begin{align}\label{eq_gluingLipschitz}
		\norm{D^\alpha \tilde{u} - D^\alpha u_1}_{C^0(A)} \leq \frac{2M}{\delta^2} \norm{u_1 - u_2}_{C^2(A)} = \frac{2M}{\delta^2} \norm{f_1 - f_2}_{C^2(A,\R^3)},
	\end{align}
	for all multiindices $ \alpha $ with $ \abs{\alpha}\leq 2 $. 
	Furthermore, with the assumption $ \norm{u_i}_{C^2(A)}\leq 1$ we have \com{use triangle inequality in the above relations of $ \partial_{\alpha}\tilde u $ to the derivatives of $ u_i $}
	\begin{align}
		\norm{D^{\alpha}\tilde u}_{C^0(A)} \leq \norm{D^{\alpha}u_1}_{C^0(A)} + \norm{D^{\alpha}\tilde u - D^\alpha u_1}_{C^0(A)}
		%\norm{\partial_{r}\tilde u}_{\infty},
		%\norm{\partial_\varphi \tilde u}_{\infty},
		%\norm{\partial_{rr}\tilde u}_{\infty},\norm{\partial_{\varphi\varphi} \tilde u}_{\infty},
		%\norm{\partial_{r \varphi} \tilde u}_{\infty} 
		&\leq 1 + \frac{4 M}{\delta^2}.\label{eq_gluingLipschitzBoundedDomain}
	\end{align}
	Now, the integrand $ H^2\sqrt{\det G} $ of the Willmore energy, with mean curvature $ H $ and first fundamental form $ G $, is a differentiable function of the first and second derivatives of $ u $. Thus, it is Lipschitz on the bounded domain \eqref{eq_gluingLipschitzBoundedDomain} with some Lipschitz constant $ L(M,\delta)>0 $. Together with \eqref{eq_gluingLipschitz} we obtain
	\begin{align*}
		\tilde H^2 \sqrt{\det \tilde G} \leq H_1^2\sqrt{\det G_1} + L \frac{2M}{\delta^2} \norm{f_2 - f_1}_{C^2(A,\R^3)}.
	\end{align*}
	With the area $ 4\pi \delta $ of the annulus we conclude
	\begin{equation*}
		W(\tilde f) \leq W(f_1) + \frac{8\pi L M}{\delta} \norm{f_2 - f_1}_{C^2(A,\R^3)}. \qedhere
	\end{equation*}
\end{proof}
Note that there exist other methods for smoothly gluing two surfaces together that are more efficient in terms of Willmore energy; see \cite{BK_ExistenceWillmore} for an example. The purpose of the gluing defined above is to provide a simple, explicit construction that nonetheless has controlled Willmore energy. %Moreover, unlike the approach in \cite{BK_ExistenceWillmore}, it is applicable at all scales $ \lambda $, $ R $.

Let $\lambda>1, R>1, \delta\in(0,1-1/\lambda)\cap(0,R-1)  $. We want to define the $ \delta $-gluing of one half of a catenoid of scale $1/\lambda$ with a sphere of radius $ R $.
First define 
\begin{align*}
	t_0&:=\frac{\cosh^{-1}(\lambda)}{\lambda},\\
	\theta&:=\arcsin\left(\frac{1}{R} \right),
\end{align*}
and the curves
\begin{align}
	c_1&:[0,\infty)\to \R^2, \qquad t\mapsto\left(\frac{\cosh(\lambda t)}{\lambda} , t-t_0 \right),\label{eq_catenoid}\\
	c_2&:[0,\pi]\to\R^2, \qquad \  t\mapsto R \left( \sin(t), \cos(\theta) - \cos(t)\right).\label{eq_sphere}
\end{align}
The first curve is a catenary and the second the ``east'' half of a circle of radius $R$ and midpoint $ (0,R\cos(\theta))=(0,\sqrt{R^2-1}) $. We have $ c_1(t_0)=c_2(\theta) = (1,0) $. In this intersection point, $ c_1 $ and $ c_2 $ are tangent if and only if $ R = \lambda $. % $ c_1'(t_0)=c'_2(\theta) $ by $ \sinh(\cosh^{-1}(x))=\sqrt{x^2-1} = x\sqrt{1-\frac{1}{x^2}} = \cos(\arcsin(1/x)) $ shows. 
Let $ u_1:[1/\lambda, 1+\delta]\to \R $ and $ u_2:[0,R)\to\R $ be the graph parametrizations of $ c_1 $ and $ c_2 $, i.e.\ $ x\mapsto (x,u_i(x)) $ parametrizes a part of $ c_i $. 
We now extend $ u_1,u_2 $ to rotationally symmetric functions on annuli and construct the gluing $ \tilde u : \Ann[1-\delta, 1+\delta]\to\R $ of $ u_1 $ and $ u_2 $ according to Definition~\ref{def_gluing}. Now, define $ g_\beta(x,y):=(x,y,u_\beta(x,y)) $ on $ \Ann[1/\lambda,R) $ with (see also Figure~\ref{fig_catSpheres})
\begin{align*}
	u_\beta(p):=\begin{cases}
		u_1(p)\qquad&, \abs{p} \in [1/\lambda,1-\delta)\\
		\tilde{u}(p)\qquad &, \abs{p} \in [1-\delta,1+\delta]\\
		u_2(p)\qquad &, \abs{p} \in (1+\delta,R).
	\end{cases}
\end{align*}
Let $ D\subseteq\S^2 $ be a closed topological disk and $ f_\beta:D\to\R^3 $ be any smooth immersion such that the interior of $ D $ contains a closed disk $D_1$ and $f_\beta|_{D_1}$ parametrizes a closed (round) hemisphere of radius $R$ and $ f_\beta|_{D\setminus D_1} $ parametrizes the same surface as $ g_\beta $ (see Figures~\ref{fig_catSpheres} and~\ref{fig_catSpheresZoom}). We call $f_\beta$ a catenoid sphere of type $\beta$.

To define catenoid spheres of type $\alpha$, we repeat the definition above but with the curve $c_2$ adjusted to be
\begin{align*}
	c_2&:[0,\pi]\to\R^2, \qquad \  t\mapsto R \left( \sin(t), \cos(t) - \cos(\theta) \right).
\end{align*}
This is the ``east'' half of a circle of radius $R$ and midpoint $ (0,-R\cos(\theta)) $. Again, we have $ c_1(t_0)=c_2(\theta) = (1,0) $ but $c_1$ and $c_2$ are never tangent in this intersection point. We proceed analogously with the construction and obtain catenoid spheres $f_\alpha$ of type $ \alpha $ (see Figure~\ref{fig_catSpheres}).

