\begin{defn}\label{def_CatSph}
	We define $ \CatSph_\alpha(\lambda,R,\delta) $ (resp.\ $ \CatSph_\beta(\lambda,R,\delta) $) to be the set of all catenoid spheres $ f_\alpha $ (resp.\ $ f_\beta $) of type $ \alpha $ (resp.\ $ \beta $) for given $\lambda>1$, $R>1$, and $\delta\in(0,1-1/\lambda)\cap(0,R-1)$ as defined above. We also set $$ \CatSph(\lambda,R,\delta) := \CatSph_\alpha(\lambda,R,\delta) \cup \CatSph_\beta(\lambda,R,\delta). $$
	We denote by $ W_\alpha(\lambda,R,\delta) $ (resp.\ $ W_\beta(\lambda,R,\delta) $) the Willmore energy of some catenoid sphere $ f\in \CatSph_\alpha(\lambda,R,\delta) $ (resp.\ $ f\in \CatSph_\beta(\lambda,R,\delta) $). We extend these functions by 
	$$ W_\alpha(\lambda,R,0) := W_\beta(\lambda,R,0) := 2\pi \left(1 + \sqrt{1-\frac{1}{R^2}} \right), $$
	which is the Willmore energy of the spherical region in the catenoid sphere before gluing.
\end{defn}

\begin{restatable}{lem}{catenoidSphereShrinking}\label{lem_catenoidSphereShrinking}
	There exists $ \Lambda>0 $ such that the Willmore energy of catenoid spheres satisfies the following.
	\begin{enumerate}[label=\roman*)]
		\item There exists $ \delta_0\in \left(0,\frac12 \right)  $ such that for all $ \delta\in(0,\delta_0) $ the function $ \lambda \mapsto W_\beta(\lambda,\lambda,\delta) $ is increasing on the interval $ [\Lambda,\infty) $.\label{lem_catenoidSphereShrinking_lambdaMonotonicity}
		\item For fixed $ \lambda \geq \Lambda $ we have $$ \lim\limits_{\delta\searrow 0} W_\beta(\lambda,\lambda,\delta) =  W_\beta(\lambda,\lambda,0) < 4\pi. $$\label{lem_catenoidSphereShrinking_deltaToZero}
		\item For fixed $ \delta\in\left(0,\frac12\right) $ we have 
		\begin{align*}
			\lim\limits_{\lambda\to\infty} W_\alpha(\lambda,\lambda,\delta) =
			\lim\limits_{\lambda\to\infty} W_\beta(\lambda,\lambda,\delta) =  4\pi.
		\end{align*}\label{lem_catenoidSphereShrinking_lambdaToInfty}
	\end{enumerate}
\end{restatable}
\begin{proof}
	The Willmore energy of the catenoid vanishes and hence the Willmore energy of the catenoid sphere is the sum 
	\begin{align*}
		W_{\alpha/\beta}(\lambda,\lambda,\delta) = W^{cap}(\lambda,\delta) + W^{glue}_{\alpha/\beta}(\lambda,\delta),
	\end{align*}
	where 
	\begin{align*}
		W^{cap}(\lambda,\delta)&=2\pi \left( 1 + \sqrt{1 - \frac{(1+\delta)^2}{\lambda^2}} \right)
	\end{align*}
	is the energy of the spherical cap without the gluing region, that is, a round sphere of radius $ \lambda $ with a small cap removed whose boundary circle has radius $ 1+\delta $. And $ W^{glue}_{\alpha/\beta}(\lambda,\delta) $ is the energy of the gluing region (the graph over $ \Ann[1-\delta, 1+\delta] $).
	We observe for the cap (recall Definition~\ref{def_CatSph})
	\begin{align}
		\lim_{\delta\searrow 0} W_{cap}(\lambda,\delta) &= W_{\alpha/\beta}(\lambda,\lambda,0),\label{eq_WCapEstimatedDeltaToZero}\\
		\lim_{\lambda\to\infty} W_{cap}(\lambda,\delta) &= 4\pi.\label{eq_WCapEstimatedLambdaToInfty}
	\end{align}
	Using the explicit parametrizations of the sphere and catenoid and the estimations $ \abs{\phi}\leq 1 $, $ \abs{\phi'} \leq \frac{M}{\delta} $ and $ \abs{\phi''} \leq \frac{M}{\delta^2}$ of the gluing function one can show that there exists constants $ \Lambda,C>0 $ such that for all $ \lambda\geq \Lambda $ and $ \delta\in(0,\frac12) $ we have
	\begin{align*}
		W^{glue}_{\alpha}(\lambda,\delta)& \leq C\frac{1}{\delta\lambda^2},\\
		W^{glue}_{\beta}(\lambda,\delta)& \leq C \frac{\delta}{\lambda^2},\\
		\partial_\lambda W^{glue}_{\beta}(\lambda,\delta) &\geq - C \frac{\delta}{\lambda^3}.
	\end{align*}
	See Lemma~\ref{lem_catenoidSpheresShrinkingAppendix} for a proof of these estimations.
	Now, the statements~\ref{lem_catenoidSphereShrinking_deltaToZero} and~\ref{lem_catenoidSphereShrinking_lambdaToInfty} follow immediately and to prove \ref{lem_catenoidSphereShrinking_lambdaMonotonicity} we set $ \delta_0:=\frac{2\pi}{C} $ to obtain for all $ \lambda\geq \Lambda $ and $ \delta\in(0,\delta_0) $
	\begin{align*}
		\partial_\lambda W^{glue}_{\beta}(\lambda,\delta) 
		&\geq - C \frac{\delta}{\lambda^3} \\
		&> - \frac{2\pi}{\lambda^3} \\
		&> -\frac{2\pi(1+\delta)^2}{\lambda^2 \sqrt{\lambda^2-(1+\delta)^2}}\\
		&= -\partial_\lambda W^{cap}(\lambda,\delta),
	\end{align*}
	which yields $ \partial_\lambda W_\beta(\lambda,\lambda,\delta)>0  $ and thus statement~\ref{lem_catenoidSphereShrinking_lambdaMonotonicity}.
\end{proof}
\begin{rem}
	In contrast to Lemma~\ref{lem_catenoidSphereShrinking}~\ref{lem_catenoidSphereShrinking_deltaToZero}, we have $ W_\alpha(\lambda,\lambda,\delta)>4\pi $ for all admissible $ \lambda $ and $ \delta $. This is due to the fact that any catenoid sphere of type $ \alpha $ builds an immersed sphere of the family $ J $ with a copy of its own. And these immersions all have Willmore energy greater than $ 8\pi $ (see Remark~\ref{rem_JW>8pi}).
\end{rem}


\subsection{Global Classification of Singularities below $ 12\pi $}\label{sec_surgery}
The aim of this section is to prove Theorem~\ref{thm_globalSing} by giving a global classification of singularities below $ 12\pi $. By this we do not mean to classify all singular Willmore flows at their singular time, but rather to find a small set of surfaces to which every Willmore flow can be deformed without increasing the Willmore energy. This approach relies on the classification of blow-ups of singular Willmore flows below $ 16\pi $ in \cite{LN}. The blow-up procedure was introduced in \cite{KS_SmallInitial}. We refer to the descriptions in \cite[Section~3.3]{KS_Survey} and \cite[Section~4]{LN}. Consider a maximal Willmore flow $ f:\S^2\times [0,T) $ with $ T\in(0,\infty] $. If $ f_t $ does not converge to a round sphere as $ t\to T $, then there exist sequences $ t_j\in[0,T) $, $ r_j>0 $, $ x_j\in\R^3 $ with $ t_j\to T $ and a rescaled flow
\begin{align}\label{eq_blowup}
	f^j:\S^2 \times \left[ -\frac{t_j}{r_j^4}, \frac{T-t_j}{r^4_j} \right) \to \R^3, \qquad f^j(p,\tau) = \frac{1}{r_j}\left( f(p,t_j+r^4_j\tau) -x_j \right)
\end{align}
\begin{thmCite}\label{thm_LN}\text{(\cite[Theorem~1.6]{LN})}
	If $ W(f_0)<16\pi $, then $ f^j(\cdot,0) $, as above, converges locally smoothly after appropriate reparametrization to either a catenoid, trinoid or Enneper's minimal surface. If $ W(f_0)\leq 12\pi $, then only the catenoid case appears.
\end{thmCite}
Here, \textit{trinoid} refers to any complete genus zero minimal surfaces of total curvature $ -8\pi $ with three ends, as classified in \cite[Theorem~3]{Lopez_CompleteMSTotCurv}.
The details of the convergence in this case are as follows (cf. \cite[Section~4]{KS_SmallInitial}, \cite[Section~3.3]{KS_Survey}). There exists a two-dimensional manifold $ \hat{\Sigma}=\S^2\setminus\{p_1,\dots,p_k\} $ and a limit immersion $ \hat f : \hat \Sigma \to \R^3 $, i.e.\ a catenoid ($ k=2 $), trinoid ($ k=3 $) or Enneper's surface ($ k=1 $). Define the domains $ S_j:=(f^j)^{-1}(B_j(0)) $ and $ \hat S_j:=\hat f^{-1}(B_j(0)). $
There exist open sets $ U_j\subseteq \S^2 $ such that for all $ R>0 $ there exists $ j_R\in\N $ and we have for all $ j\geq j_R $ that $ f^{-1}(B_R(0)) \subseteq U_j $. There exist diffeomorphisms $ \varphi_j: \hat S_j \to U_j $
and a function $ u_j\in C^\infty(\hat{S}_j,\R) $ which satisfy, with some fixed normal $  \hat \nu $ of $ \hat f $, for all $ k\in\N $
\begin{align*}
	f^j \circ \varphi_j = \hat{f} + u_j \hat \nu,\\
	\lim_{j\to \infty} \norm{\hat \nabla ^k u_j}_{L^\infty\left(\hat S_j\right)} = 0.
\end{align*}
This implies the following. For all $ \lambda>0 $, the functions 
$ g_j := f^j \circ \varphi_j : \hat f^{-1}(\overline{B_\lambda(0)}) \to \R^3 $ are defined for sufficiently large $ j\in\N $ and satisfy for all $ k\in\N $
\begin{align}
	\lim_{j\to\infty}\norm{g_j - \hat f}_{C^k\left(\hat S_\lambda,\R^3\right)} =0.
\end{align}
Here and in the following the $ C^k $ norms of immersions defined on subsets of $ \S^2 $ are defined by fixing charts of $ \S^2 $.
\begin{rem}
	In the following we construct a regular homotopy with controlled Willmore energy. By scaling invariance of the Willmore energy, we can scale any homotopy $ f_t $ by a factor $ \lambda_t $ without changing the Willmore energy. Furthermore, the set of diffeomorphisms on $ \S^2 $ has two homotopy classes, orientation preserving and orientation reversing reparametrizations \cite{Smale_DiffS2}. Thus, we can always find a regular homotopy of constant Willmore energy from one immersion $ f $ to a reparametrized $ f \circ \varphi $ of same orientation. In the following we implicitly scale or reparametrize by a homotopy whenever needed.
\end{rem}
\begin{prop}\label{prop_gluingA}
	Let $ f_0:\S^2\to\R^3 $ be a smooth immersion with $ W(f_0)\leq 12\pi $ and $ \delta\in\left(0,\frac14\right) $. Then, there exists $ \Lambda>0 $ such that for all $ \lambda,R\geq \Lambda $ there exists a regular homotopy $ H:\S^2\times [0,1]\to \R^3 $ satisfying the following.
	\begin{enumerate}[label=\roman*)]
		\item $ H_0=f_0 $.
		\item $ W(H_t)<W(f_0) $ for all $ t\in (0,1] $.
		\item Either $ H_1 $ is a round sphere or there exist two closed topological disks $ S_1,S_2\subseteq \S^2 $ with $ S_1\cup S_2 = \S^2 $ and $ S_1\cap S_2 =\partial S_1 = \partial S_2$ such that $ H_1|_{S_1},H_1|_{S_2} \in \CatSph(\lambda,R,\delta) $.
	\end{enumerate} 
\end{prop}
\begin{proof}
	Let $ f:\S^2\times [0,T) \to \R^3 $ be the maximal Willmore flow with initial surface $ f_0 $ and $ T\in (0,\infty] $. Fix some $ s_0\in (0,T)  $ and set 
	$$ \omega:=W(f_0)-W(f_{s_0})>0. $$ 
	Let $ A:=\Ann[1-\delta,1+\delta] $ and $\rho>0 $ sufficiently small such that by Lemma~\ref{lem_gluingLemma} the gluing excess Willmore energy for a $ \delta $-gluing between two graphs $ g_1,g_2 \in C^2(A,\R^3) $ with $ \norm{g_i}_{C^2(A)}\leq 1 $ $ \norm{g_1 - g_2}_{C^2(A,\R^3)}<\rho $ is less than $ \frac{\omega}{5} $.

	\underline{Step 1:} Prepare catenoids and spheres.\\
	Fix $ \Lambda>0 $ sufficiently large such that for $ \lambda,R\geq \Lambda $ catenoids of scale $ \frac{1}{\lambda} $, rotation axis $ (0,0,1) $ and center $ (0,0,c) $ with $ c\in\left[0,\lambda^{-1}\cosh(\lambda)\right] $, and spheres of radius $ R $ and center $ (0,0,m) $ with $ m\in\left[\sqrt{R^2-1},R\right] $ (see \eqref{eq_catenoid} and \eqref{eq_sphere} for $ c=\lambda^{-1}\cosh(\lambda) $ and $ m=\sqrt{R^2-1} $) have graph parametrizations $ u_c, u_s: A \to \R $ over $ A\times\{0\} $, respectively, which satisfy
	\begin{align}
		\norm{u_c}_{C^2\left(A\right)}<\frac{\rho}{8},\label{eq_catCloseToFlatDisk}\\
		\norm{u_s}_{C^2\left(A\right)}<\frac{\rho}{8}.\label{eq_sphereCloseToFlatDisk}
	\end{align}

	\underline{Step 2:} Fix domains and notation for gluing.\\
	Let $ S_1,S_2\subseteq \S^2 $ be the northern and southern closed hemisphere and fix a closed annulus $ C\subseteq \S^2 $ and two disjoint closed disks $ D_1\subseteq S_1,D_2\subseteq S_2 $ such that they overlap in annuli $ C_i:=D_i \cap C $ with nonempty interior (see Figure~\ref{fig_domainsOnS2}).
	To make the gluings of immersions along their graphs over the annulus $ A $ in the following well-defined, we fix once diffeomorphisms $ \psi^+_i,\psi^-_i: A \to C_i $ which are orientation preserving and reversing, respectively.
	We say that an immersion $ h:C_i\to \R^3 $ is a graph over $ A\times\{0\}\subseteq \R^3 $ if $ h\circ \psi^+_i $ or $ h\circ \psi^-_i $ is a graph on $ A $, i.e.\ $ h\circ \psi^{\pm}(p) = (p,u_h(p)) $ for some $ u_h:A\to\R $\com{$ \psi^+ $ or $ \psi^- $ depending on the orientation of $ h $}. In the following, before each gluing, we implicitly assume that by orientation preserving reparametrizations the involved immersions are graphs over $ A $ in the way just defined. The resulting gluing is always an immersion. Outside of the gluing region we recover the involved immersions and inside we obtain a graph, in particular an immersion. \com{Note that we always glue immersed disks to each other along an annulus overlap so that the obtained gluing is an immersed sphere and not of other topology. %But because it is continuous it does not change the topology anyways
	}
	\begin{figure}[H]
		\centering
		\resizebox{0.8\textwidth}{!}{
			\begin{tikzpicture}
				\node[anchor=center] at (-0.2,-0.25) {\includegraphics[width=10cm]{domainsOnS2_image}};

				\def\ampl{7pt}

				% Curly braces and their labels
				\foreach \cx/\cy/\length/\lab in 
				{
					-5/0/2.3/$C$
				} 
				{
					\draw[decorate,decoration={brace,amplitude=\ampl}, mypastel] (\cx,\cy-0.5*\length) -- (\cx,\cy+0.5*\length);
					\node[anchor=east] at (\cx-0.1,\cy) {\small \textcolor{mypastel}{\lab}};
				}

				% Curly braces and their labels
				\foreach \cx/\cy/\length/\lab in 
				{
					-5.8/ 0.9/1.7/$S_1$,
					-5.8/-0.9/1.7/$S_2$
				} 
				{
					\draw[decorate,decoration={brace,amplitude=\ampl}, black] (\cx,\cy-0.5*\length) -- (\cx,\cy+0.5*\length);
					\node[anchor=east] at (\cx-0.1,\cy) {\small \textcolor{black}{\lab}};
				}

				% Mirrored Curly braces and their labels
				\foreach \cx/\cy/\length/\lab in 
				{
					-1.4/ 1.1/1.4/$D_1$,
					-1.4/-1.1/1.4/$D_2$
				} 
				{
					\draw[decorate,decoration={brace,mirror,amplitude=\ampl}, myred] (\cx,\cy-0.5*\length) -- (\cx,\cy+0.5*\length);
					\node[anchor=west] at (\cx+0.15,\cy) {\small \textcolor{myred}{\lab}};
				}
				%other labels
				\node[anchor=center] at (0,2) {\small \textcolor{black}{$f_{t_0}$}};
				\node[anchor=center] at (-3.2,0.45) {\small \textcolor{myblue}{$C_1$}};
				\node[anchor=center] at (-3.2,-1) {\small \textcolor{myblue}{$C_2$}};
				%\node[anchor=center] at (3,3) {\small \textcolor{myred}{$f_{t_0}|_{D_1}$}};
			\end{tikzpicture}
		}
		\caption{The introduced domains on $ \S^2 $ and the immersion $ f_{t_0} $.}\label{fig_domainsOnS2}
	\end{figure}
	\underline{Step 3:} Fix a time right before the singular time.\\
	Fix $ \lambda\geq \Lambda $ and $ \hat f: C \to \R^3 $ which is a parametrization of appropriate orientation\com{which is compatible with $ f_{t_0} $} of a (precise) catenoid piece of scale $ \frac{1}{\lambda} $ in $ \overline{B_2(0)}\subseteq \R^3 $ %not filling th whole ball but enough to cover the graph over $\overline{B_{1+\delta}(0)}$
	such that $ \hat f|_{S_1} $ parametrizes the part in the upper half-space and $ \hat f|_{C_i} $ are graphs over $ A\times \{0\} $. Then, by Theorem~\ref{thm_LN}, there exists $ t_0\in (s_0,T) $ such that with appropriate reparametrization and rescaling of $ f_{t_0} $ the error $ \rho_1:=\norm{f_{t_0} - \hat{f}}_{C^2(C,\R^3)} $ is sufficiently small. We choose it so small that $ f_{t_0}|_{C_i} $ are graphs over $ A\times \{0\} $ (see Figure~\ref{fig_domainsOnS2}) and their graph parametrizations $ v^i_{t_0} $ of $ f_{t_0}|_{C_i} $ and $ \hat u^i $ of $ \hat f|_{C_i} $ in the upper half-space ($ i=1 $) and in the lower half-space ($ i=2 $), satisfy 
	\begin{align}
		\norm{v^i_{t_0}-\hat u^i}_{C^2\left(A\right)}<\frac{\rho}{8}.\label{eq_blowUpCloseToCatenoid}
	\end{align}
	Furthermore, $ \rho_1 $ is chosen such that all $ g:C\to \R^3 $ with $ \norm{\hat f - g}_{C^2(C,\R^3)}\leq \rho_1 $ satisfy 
	\begin{equation}
		W(g)<W(\hat{f})+\frac{\omega}{5}=\frac{\omega}{5}.\label{eq_straightLineToCat}
	\end{equation} 

	\underline{Step 4:} Construct the final homotopy.\\
	We construct three regular homotopies
	\begin{align*}
		H^1&:\S^2\times[0,1]\to\R^3,\\
		H^c&:C \times[0,1]\to\R^3,\quad (p,t)\mapsto f_{t_0}(p)+t\left(\hat{f}(p)-f_{t_0}(p)\right),\\
		H^2&:\S^2\times[0,1]\to\R^3,
	\end{align*}
	where $ H^1,H^2 $ are defined later (see Step 5) and satisfy all of the following (see also Figure~\ref{fig_catenoidSurgery}).
	\begin{enumerate}[label=\roman*)]
		\item $ H^i_0|_{D_i}= f_{t_0}|_{D_i}  $,\label{enum_WFfirst}
		\item $ W(H^i_0) < W(f_{t_0}|_{D_i}) + \frac\omega5, $\label{enum_WFlowEnergy}
		\item $ t\mapsto W(H^i_t)$ is nonincreasing.\label{enum_WFdec}
		\item $ H^i_t|_{C_i} $ is a graph over $ A\times\{0\} $ for all $ t\in[0,1] $\label{enum_WFgraph},
		\item The graph parametrizations $ u^i_t:A\to \R $ of $ H^i_t $ over $ A\times\{0\} $ satisfy\label{enum_WFcloseToFlatDisk}
		$$ \norm{u^i_t}_{C^2(A)} <\frac{\rho}{2},$$
		\item $ H^i_1 $ is a round sphere of radius $ R $ and center $ \left(0,0,\lambda^{-1}\cosh(\lambda) \pm \sqrt{R^2-1}\right) $.\label{enum_WFfinalSphere}
		\label{enum_WFlast}
	\end{enumerate} 
	We glue them together to a regular homotopy $ H:\S^2\times[0,1]\to\R^3 $ which for each time $ t\in[0,1] $ is defined on $ D_i $ to be the $ \delta $-gluing of $ H^i_t|_{D_i} $ with $ H^c_t $ along the graph parametrizations over $ A\times\{0\} $, for $ i=1,2 $. And on $ \S^2\setminus (D_1 \cup D_2) $ it is defined to agree with $ H^c_t $.
	The graph parametrizations $ u^{c,i}_t:A\to \R $ of $ H^c_t $ over $ A\times\{0\} $ satisfy with appropriate reparametrizations $ u^{c,i}_t = v^i_{t_0} + t\left(\hat u^i - v^i_{t_0}\right) $ and thus with \eqref{eq_blowUpCloseToCatenoid} and \eqref{eq_catCloseToFlatDisk}
	\begin{align*}
		\norm{u^{c,i}_t}_{C^2(A)} &\leq \norm{v^i_{t_0} - \hat u^i}_{C^2(A)} + \norm{\hat u^i}_{C^2(A)} + t \norm{\hat u^i - v^i_{t_0}}_{C^2(A)}\\
		&< \frac{\rho}{8} + \frac{\rho}{8} + \frac{\rho}{8} < \frac{\rho}{2}.
	\end{align*}
	Thus, with \ref{enum_WFcloseToFlatDisk} we have $ \norm{u^c_t - u^i_t}_{C^2(A,\R)} < \rho $ and the gluing excess energy of each of the two $ \delta $-gluings remains below $ \frac{\omega}{5} $ for all times. Furthermore, by \eqref{eq_straightLineToCat} we have $ W\left(H^C_t\right)< \frac{\omega}{5} $ and obtain with \ref{enum_WFdec} and \ref{enum_WFlowEnergy}
	\begin{align*}
		W(H_t)&<W(H^1_t)+W(H^C_t)+W(H^2_t) + \frac{2}{5}\omega\\
		&<W(H^1_t)+W(H^2_t)+\frac35\omega\\
		&\leq W(H^1_0)+W(H^2_0)+\frac35\omega\\
		&< W(f_{t_0})+\omega\\
		&< W(f_0).
	\end{align*}
	Now, a concatenation of $ f:\S^2\times[0,t_0]\to\R^3 $ with $ H $ is continuous since \ref{enum_WFfirst} ensures that $ H_0=f_{t_0} $. We obtain a regular homotopy that ends in $ H_1 $ whose Willmore energy remains below $ W(f_0) $. Since $ H^c_1 = \hat f $ is a catenoid of the form \eqref{eq_catenoid} but shifted by $ (0,0,\lambda^{-1}\cosh(\lambda)) $, we conclude with \ref{enum_WFfinalSphere} that $ H_1|_{S_1},H_1|_{S_2}\in\CatSph(\lambda,R,\delta) $.

	\underline{Step 5:} It remains to define $ H^i $, $ i=1,2 $ which satisfy \ref{enum_WFfirst} - \ref{enum_WFlast}.\\ 
	We fix $ i=1 $ and hence consider the graphs in the upper half-space of $ \R^3 $. $ H^2 $ is constructed analogously considering the graphs in the lower half-space. For the purpose of the remaining proof we shift all the immersions by $ -\left(0,0,\lambda^{-1}\cosh(\lambda)\right) $ for the catenoid $ \hat f $ to be of the form \eqref{eq_catenoid} and the sphere obtained in the very end to be of the form \eqref{eq_sphere}.
	The regular homotopy $ H^1 $ will be obtained as a concatenation of multiple steps (see also Figure~\ref{fig_catenoidSurgery})
	\[
	\setlength{\arraycolsep}{ 0.167 em}
	\begin{array}{rlrl}
		\mu     & \mapsto \mu F_0,             & \mu  & \in [1, \bar\mu], \\
		t       & \mapsto \bar\mu F_t,         & t   & \in [0, 1], \\
		\lambda & \mapsto \lambda \bar\mu F_1, & \lambda & \in [1, \bar\lambda], \\
		s       & \mapsto \bar\lambda \bar\mu F_1 + ty, & s & \in [0,1]
	\end{array}
	\]
	the details of which will be laid out in the following.
	\begin{figure}[H]
		\centering
		\begin{tikzpicture}
			\node[anchor=south] at (0,0) {\includegraphics[width=0.95\textwidth]{catenoidSurgery}};

			\def\dx{0.158*\textwidth};

			\node[anchor=north east] at (-2.65*\dx,1.05) {\scalebox{0.4}{ \textcolor{myblue}{$A\times \{0\}$} }};
			\node[anchor=north east] at (-2.8*\dx,2) {\small \textcolor{myred}{$H^1_t$}}; 
			\node[anchor=north east] at (-2.8*\dx,0.7) {\small \textcolor{mypastel}{$H^c_t$}};

