	\end{figure}
	\underline{Step 5.1:} Construct $ H^1_0 $ by gluing in a flat disk and start the Willmore flow.\\
	Let $ d_1 $ be an appropriate parametrization of the flat disk $ \overline{B_{\frac{1+\delta}{2}}(0)}\times\{0\} $ with graph parametrization $ u_d=0 $.
	Let $ H^1_0:\S^2\to \R^3 $ be the gluing of $ d_i $ with $ f_{t_0}|_{D_i} $ along the graphs over $ \Ann\left[\frac{1-\delta}{2},\frac{1+\delta}{2}\right] $. Appropriate choice of $ \lambda,\rho_1 $ can ensure that \eqref{eq_catCloseToFlatDisk} and \eqref{eq_blowUpCloseToCatenoid} equally apply to $ \Ann\left[\frac{1-\delta}{2},\frac{1+\delta}{2}\right] $ instead of $ A $. We obtain
	\begin{align}
		\norm{v^1_{t_0}}_{C^2\left(\Ann \left[\frac{1-\delta}{2},1+\delta\right]\right)} &\leq \norm{v^1_{t_0} - \hat u^1}_{C^2\left(\Ann \left[\frac{1-\delta}{2},1+\delta\right]\right)} + \norm{\hat u^1}_{C^2\left(\Ann \left[\frac{1-\delta}{2},1+\delta\right]\right)} \notag\\
		&< \frac\rho4,\label{eq_t0CloseToDisk}
	\end{align}
	By doubling the scale, this can be made a standard $ \delta $-gluing according to Lemma~\ref{lem_gluingLemma} and thus the gluing excess energy is less than $ \frac{\omega}{5} $. We obtain \ref{enum_WFfirst} and \ref{enum_WFlowEnergy}.
	Defining $ H^2_0 $ analogously, these initial surfaces $ H^1_0,H^2_0 $ have Willmore energy
	\begin{align*}
		4\pi \leq W(H^i_0)< W(f_{t_0}|_{D_i}) + \frac{\omega}{5},
	\end{align*}
	and therefore
	\begin{align*}
		W(H^1_0) &< W(f_{t_0}|_{D_1}) + \frac{\omega}{5}\\
		&\leq W(f_{t_0}) - W(f_{t_0}|_{D_2}) + \frac{\omega}{5}\\
		&< W(f_{t_0}) - \left( W(H^2_0) -\frac{\omega}{5} \right) + \frac{\omega}{5}\\
		&\leq W(f_{t_0}) -4\pi + \frac{2}{5}\omega \\
		&< 12\pi - \omega -4\pi +\frac{2}{5}\omega\\
		&<8\pi.
	\end{align*}
	Therefore, by Theorem~\ref{thm_KS8pi}, the Willmore flow $ \S^2\times[0,\infty)\to\R^3 $ with initial surface $ H^1_0 $ converges smoothly to a round sphere. By monotonically rescaling the time interval $ [0,\infty)\to[0,1) $, we obtain a smooth regular homotopy $ F:\S^2\times [0,1] \to\R^3 $ where we set $ F_1 $ to be the limit round sphere. Now, $ F $ is a regular homotopy of decreasing Willmore energy from $ F_0=H^1_0 $ to a round sphere. In the following, we modify $ F $ only by translation, rotation, scaling and reparametrization. Hence, \ref{enum_WFdec} will remain satisfied.

	\underline{Step 5.2:} Increase scale to ensure low gluing energy.\\
	Let $ p:=d_1^{-1}(0) $ denote the preimage of the center of the flat disk. Then, its tangent space $ T_pF_0 $ is the $ x $-$ y $-plane $ \R^2\times\{0\} $ and by translation and rotation of $ F_t $ we ensure that $ F_t(p)=0 $ and $ T_pF_t = \R^2\times\{0\} \subseteq \R^3$ for all $ t\in[0,1] $. 
	The Willmore flow might converge to a very small sphere or temporarily increase curvature locally which might violate \ref{enum_WFcloseToFlatDisk}. We counteract this by scaling. First note that for $ r\in(0,1+\delta) $ any $ u\in C^2(B_r(0)) $ with $ u(0)=0 $ and $ \nabla u (0) = 0 $ satisfies by Taylor expansion
	\begin{align}\label{eq_C2normBoundBySecDer}
		\norm{u}_{C^2(B_r(0))} \leq \left(\frac{r^2}{2} + r + 1\right)\norm{D^2u}_{C^0(B_r(0))} \leq 4 \norm{D^2u}_{C^0(B_r(0))} .
	\end{align}
	The norm of the second fundamental form $ (p,t)\mapsto \norm{A_t(p)} $ of $ F_t $ in $ p\in \S^2 $ assumes a maximum $ A_{max} $ on the compact spacetime $ \S^2\times[0,1] $. Therefore, by Lemma~\ref{lem_uniformGraphRadius}, there exists a radius $ r\in(0,1) $ such that for all $ t\in[0,1] $ the immersion $ F_t $ is locally a graph over $ B_r(0) \subseteq T_pF_t $ with graph parametrization $ u_t $ satisfying 
	\begin{align*}
		\norm{D^2u_t}_{C^0(B_r)} \leq 5 A_{max}.
	\end{align*}
	We now insert the scaling homotopy $ \mu\mapsto \mu F_0 $, $ \mu\in\left[1,\bar{\mu}\right], $ where $ \bar \mu> \frac{1+\delta}{r} $ and $ \bar\mu > \frac{40}{\rho}A_{max} $. 
	During this scaling \ref{enum_WFcloseToFlatDisk} is satisfied since \eqref{eq_t0CloseToDisk} and \eqref{eq_C2normBoundBySecDer}
	imply for the graph parametrization $ w_\mu(x) = \mu u_0\left(\frac{x}{\mu}\right) $ of $ \mu F_0 $
	\begin{align*}
		\norm{w_\mu}_{C^2(A)} &\leq \norm{w_\mu}_{C^2\left(\overline{B_{1+\delta}(0)}\right)} \\
		&\leq 4 \norm{D^2 w_\mu}_{C^0\left(\overline{B_{1+\delta}(0)}\right)} \\
		&=4 \frac1\mu \norm{D^2 u_0}_{C^0\left(\overline{B_{\frac{1+\delta}{\mu}}(0)}\right)} \\
		&\leq 4 \frac1\mu \norm{D^2 u_0}_{C^0\left(\overline{B_{1+\delta}(0)}\right)} \\
		&=4 \frac1\mu \norm{D^2 u_0}_{C^0\left(\Ann \left[\frac{1-\delta}{2},1+\delta\right]\right)} \\
		&=4 \frac1\mu \norm{D^2 v^1_{t_0}}_{C^0\left(\Ann \left[\frac{1-\delta}{2},1+\delta\right]\right)} \\
		&<4 \frac1\mu \frac\rho8 < \frac\rho2.
	\end{align*}
	Furthermore, we have ensured that after the scaling the graph parametrizations $ z_t(x) = \bar{\mu} u_t\left(\frac{x}{\bar{\mu}}\right)  $ of the scaled Willmore flow $ \bar{\mu} F_t $ over $ A\times\{0\} $ satisfy \ref{enum_WFcloseToFlatDisk}, i.e.\
	\begin{align*}
		\norm{z_t}_{C^2(A)}&\leq \norm{z_t}_{C^2\left(\overline{B_{1+\delta}(0)}\right)} \\
		&\leq 4 \norm{D^2z_t}_{C^0\left(\overline{B_{1+\delta}(0)}\right)}\\
		&=4 \frac{1}{\bar{\mu}} \norm{D^2u_t}_{C^0\left(\overline{B_{\frac{1+\delta}{\bar \mu}}(0)}\right)}\\
		&\leq 4 \frac{1}{\bar \mu} \norm{D^2u_t}_{C^0\left(B_r(0)\right)}\\
		&\leq 4 \frac{1}{\bar \mu} 5 A_{max}\\
		&< \frac\rho2.
	\end{align*} 
	\underline{Step 5.3:} Append final correcting homotopies.\\
	During this regular homotopy we reparametrize $ \bar \mu F_t $ appropriately such that $ \bar \mu F_t|_{C_i} $ is a graph over $ A\times\{0\} $ for \ref{enum_WFgraph} to hold. 
	Finally, we append a scaling regular homotopy that brings the round sphere to any given radius $ R\geq \Lambda $. It now is tangent to the $ x $-$ y $-plane and centered at $ (0,0,R) $ (type $ \beta $) or $ (0,0,-R) $ (type $ \alpha $). Then, we append a translation which shifts the center of the sphere from $ \pm(0,0,R) $ to $ \pm\left(0,0,\sqrt{R^2-1}\right) $. The translation brings the sphere into the form as described in Definition~\ref{def_CatSph}. In the case of the sphere lying entirely above the horizontal plane (type $ \beta $) it is now tangent to the catenoid $ H^c_1 $ in the unit circle $ \S^1 \times \{0\} $. By \eqref{eq_sphereCloseToFlatDisk}, these two steps do not violate \ref{enum_WFcloseToFlatDisk}. Reversing the shift of all surfaces by $ -\left(0,0,\lambda^{-1}\cosh(\lambda)\right) $ we observe that the sphere satisfies \ref{enum_WFfinalSphere}.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm_globalSing}]
	Fix $ \Lambda,\delta_0 $ from Lemma~\ref{lem_catenoidSphereShrinking}~\ref{lem_catenoidSphereShrinking_lambdaMonotonicity} and $ \delta\in(0,\delta_0) $ sufficiently small such that $ \eps:= 4\pi - W_\beta(\Lambda,\Lambda,\delta) $ is positive (see Lemma~\ref{lem_catenoidSphereShrinking}~\ref{lem_catenoidSphereShrinking_deltaToZero}). Then, choose $ \lambda_1>\Lambda $ sufficiently large such that $ W_{\alpha/\beta}(\lambda,\lambda,\delta)< 4\pi + \eps $ for all $ \lambda>\lambda_1 $ (see Lemma~\ref{lem_catenoidSphereShrinking}~\ref{lem_catenoidSphereShrinking_lambdaToInfty}).
	Apply Proposition~\ref{prop_gluingA} for $ \delta_0 $ and $ R=\lambda>\lambda_1 $. Let $ H $ be the obtained homotopy and denote $ g_0:=H_1 $ and $ g^i_0:=H_1|_{S_i} \in\CatSph(\lambda,\lambda,\delta) $, $ i=1,2 $. If $ g^1_0,g^2_0 $ are both catenoid spheres of type $ \alpha $, then $ g_0\in J $ and we are done. We may now assume that $ g^1_0 $ is a catenoid sphere of type $ \beta $. We deform $ g^1_0 $ by a homotopy of catenoid spheres $ g^1_t := \lambda_tf_{\lambda_t} $ with $ f_{\lambda_t}\in \CatSph_\beta(\lambda_t,\lambda_t,\delta) $ and
	$$\lambda_t = (1-t)\lambda + t\Lambda,\quad t\in[0,1]. $$
	By Lemma~\ref{lem_catenoidSphereShrinking} and $ \lambda>\Lambda $ and $\delta<\delta_0 $ this is a regular homotopy of decreasing Willmore energy to an immersion $ g^1_1\in\CatSph_\beta(\Lambda,\Lambda,\delta) $ of Willmore energy $$ W(g^1_1) = W_\beta(\Lambda,\Lambda,\delta)=4\pi - \eps. $$ This regular homotopy leaves the center piece of the catenoid fixed at all times and thus naturally extends to a regular homotopy $ g_t $ which is equal to $ g^1_t $ on $ S_1 $ and $ g^2_0 $ on $ S_2 $. We conclude 
	$$ W(g_1) = W(g^1_1)+W(g^2_0) < 4\pi - \eps + 4\pi + \eps = 8\pi.  $$ 
	Therefore, by Theorem~\ref{thm_KS8pi}, the Willmore flow with initial surface $ g_1 $ yields the last part of the desired homotopy to a round sphere.
\end{proof}
