\corTriplePoints*
\begin{proof}
	By the Li--Yau inequality, it follows immediately that there exists a time $ t\in[0,1] $ with $ W(H_t)\geq 12\pi $. But actually a strict inequality holds, since \cite{S_TriplePoints} implies that there must be an immersion $ H_t $ with a generic triple point, in particular, all immersions in a $ C^\infty $-neighborhood of that immersion have triple points\com{Otherwise a small perturbation would yield a regular homotopy without triple points}. Thus, any Willmore flow started in $ H_t $ must still have energy at least $ 12\pi $ after some time $ \eps>0 $. And since there are no critical points at $ 12\pi $ it follows $ W(H_t)>12\pi $.
\end{proof}

\propLiYauTurningNumber*
\begin{proof}
	First, define for $ r_0>0 $, $ h_0\in\R $ the quarter circles 
	\begin{align*}
		\gamma^I_{r_0,h_0}&:\left[-\frac\pi2,0\right]\to[0,\infty)\times \R,\qquad &t\mapsto  \left(r_0\cos t, r_0\sin t + h_0\right),\\
		\gamma^{II}_{r_0,h_0}&:\left[0,\frac\pi2\right]\to[0,\infty)\times \R,\qquad &t\mapsto  \left(r_0\cos t, r_0\sin t + h_0\right).
	\end{align*}
	Without loss of generality we may assume $ \tau>0 $. Let $ \vartheta:[0,1]\to\R $ be the lift of the tangent angle of $ c $ with $ \vartheta(0)=0 $ and $$ \vartheta(1)=2\pi\tau = 2\pi k + \pi $$ for some $ k\in \N $. Let $ l\in\{0,1,\dots,k\} $ and denote $ c=(r,h) $. The mean value theorem lets us pick $ t_l $ to be the smallest number in $ \vartheta^{-1}(\{2\pi l + \frac\pi2 \}) $. The tangent at $ t_l $ is $ (0,1) $. In the following we construct $ C^1 $-curves which are composed by smooth curves connected to each other at points where their tangent is $ (0,1) $. For $ l\in\{0,1,\dots,k-1\} $ consider the $ C^1 $-curve $ \gamma_l $ obtained as the concatenation of 
	\begin{align*}
		\gamma^I_{r(t_l),h(t_l)},\quad c|_{[t_l,t_{l+1}]},\quad \gamma^{II}_{r(t_{l+1}),h(t_{l+1})}
	\end{align*}
	Now, the turning number of $ \gamma_l $ is $ \frac32 $. In an abuse of notation we identify each curve segment $ \rho $ with the surface obtained by rotating the curve and write $ W(\rho) $ for its Willmore energy. Furthermore, we can approximate piecewise smooth curves by smooth curves. They can be chosen to have Willmore energy arbitrary close to the sum of the energies of each smooth piece. We claim
	\begin{align}\label{eq_turningNumber8pi}
		W(\gamma_l)\geq 8\pi.
	\end{align}
	This can be deduced in two ways.
	First, this is due to the fact that the closed plane curve obtained from mirroring $ \gamma $ has turning number $ 3 $ and thus by Hopf's Umlaufsatz (or Theorem of turning tangents \cite{DC}) has self-intersections. Therefore, the immersion $ f $ is not embedded and by the Li--Yau inequality the claim follows. Second, the surface of revolution and its turning number is preserved under the Willmore flow \cite{Blatt}, hence the Willmore flow with initial surface $ f $ cannot converge to a round sphere and by Theorem~\ref{thm_KS8pi} the claim follows. The two quarter circles produce two round hemisphere and each contributes $ 2\pi $ energy to \eqref{eq_turningNumber8pi}. Hence, we obtain
	$$ W(c|_{[t_l,t_{l+1}]})\geq 4\pi. $$
	Furthermore, we construct two $ C^1 $-spheres of revolution by concatenating
	\begin{align*}
		c|_{[0,t_0]}, \quad \gamma^{II}_{r(t_0),h(t_0)},
	\end{align*}
	and
	\begin{align*}
		\gamma^I_{r(t_k),h(t_k)},\quad c|_{[t_k,1]}.
	\end{align*}
	Both have Willmore energy at least $ 4\pi $ where $ 2\pi $ is contributed by the round hemispheres. Therefore
	\begin{align*}
		W(c|_{[0,t_{0}]}),W(c|_{[t_k,1]}) \geq 2\pi,
	\end{align*}
	and we obtain in total (see Figure~\ref{fig_LiYauTurningNumber} for an example)
	\begin{align*}
		W(f)&\geq W(c|_{[0,t_{0}]}) + \sum_{l=0}^{k-1}W(c|_{[t_l,t_{l+1}]}) + W(c|_{[t_k,1]})\\
		&\geq2\pi + 4\pi k + 2\pi\\
		&= 4\pi \left(\tau +\frac12\right).
	\end{align*}
	\begin{figure}[H]
		\centering
		\begin{tikzpicture}
			\def\d{\textwidth*0.05}
			\node[anchor=south] at (0,0) {\includegraphics[width=0.75\textwidth]{LiYauTurningNumber}};
			\node[anchor=center] at (-6\d,2.25\d) {$ c $};
			\node[anchor=center] at (0.8\d,1.2\d) {$ \gamma_0 $};
			\node[anchor=center] at (4\d,2.55\d) {$ \gamma_1 $};
			\def\x{0.039\textwidth}
			\node[anchor=north] at (0.73,0) {$ W(f) $ \hspace{\x} $ \geq $ \hspace{\x} $ 2\pi $ \hspace{\x} $ + $ \hspace{\x} $ 4\pi $ \hspace{\x} $ + $ \hspace{\x} $ 4\pi $ \hspace{\x} $ + $ \hspace{\x} $ 2\pi $};
		\end{tikzpicture}
		\caption{An example for the proof of Proposition~\ref{prop_LiYauExtensionRotSymm}.}\label{fig_LiYauTurningNumber}
	\end{figure}
	It remains to show the strict inequality. Assume it is an equality, then $ f $ is a critical point of the Willmore energy. Otherwise, the Willmore flow would yield a surface contradicting the inequality since it preserves surfaces of revolution and their turning number. By assumption, $ f $ is not a round sphere. By Bryant's classification \cite{Bryant_Dual}, with $ n:=\left(\tau + \frac12\right)\geq 2 $, the immersion $ f $ has an $ n $-tuple point at which it can be inverted to obtain a complete minimal surface with $ n $ embedded planar ends. But, as a surface of revolution, $ f $ has a full curve of $ n $-tuple points and the minimal surface also has $ n $-tuple points as well as density $ n $ at infinity. This is a contradiction to \cite[Theorem~A]{Kusner_Conformal}.
\end{proof}

Here we present the computations of the Willmore energy of catenoid spheres omitted in Lemma~\ref{lem_catenoidSphereShrinking}.
\begin{lem}\label{lem_catenoidSpheresShrinkingAppendix}
	There exist constants $ \Lambda,C>0 $ such that for all $ \lambda\geq \Lambda $ and $ \delta\in\left(0,\frac12\right) $
	\begin{enumerate}[label=\roman*)]
		\item $ W^{glue}_{\alpha}(\lambda,\delta) \leq C\frac{1}{\delta\lambda^2}, $ \label{lem_catenoidSpheresShrinkingAppendix_alpha}
		\item $ W^{glue}_{\beta}(\lambda,\delta) \leq C \frac{\delta}{\lambda^2}, $ \label{lem_catenoidSpheresShrinkingAppendix_beta}
		\item $ \partial_\lambda W^{glue}_{\beta}(\lambda,\delta) \geq -  C \frac{\delta}{\lambda^3}. $ \label{lem_catenoidSpheresShrinkingAppendix_monotonicity}
	\end{enumerate}
\end{lem}
\begin{proof}
	For a general surface of revolution $ f(t,\varphi) = (r(t)\cos(\varphi),r(t)\sin(\varphi),h(t)) $ where we set $ r(t)=t $ and $ h:I\to\R $ we obtain formulas for its mean curvature $ H $, the mean of the principal curvatures $ \kappa_1 $ and $ \kappa_2 $ and its first fundamental form $ G $. With $ l(t):=\sqrt{1+h'(t)^2} $ we have
	\begin{align*}
		H(t,\varphi) &= \frac12 (\kappa_1(t,\varphi) + \kappa_2(t,\varphi)) \\
		&= \frac12 \left(\frac{h''(t)}{l(t)^3} + \frac{h'(t)}{t l(t)}\right)\\
		&= \frac{t h''(t) + l(t)^2 h'(t)}{2t l(t)^3},\\
		\sqrt{\det G(t,\varphi)}&= \sqrt{l(t)^2 t^2} = t l(t),\\
		H(t,\varphi)^2 \sqrt{\det G(t,\varphi)} &= \frac{(th''(t) + l(t)^2 h'(t))^2}{4tl(t)^5} = \frac{\left( th''(t) + h'(t) + h'(t)^3 \right)^2}{4 t (1+h'(t)^2)^\frac52}.
	\end{align*}
	We first lay out the details of a catenoid sphere of type $ \beta $ and omit the index $ \beta $. Let $ \lambda>1 $ and $ \delta\in\left(0,\frac12\right) $. Let $ u:(1/\lambda,\infty)\to\R $ and $ v:[0,R)\to\R $ be the graph parametrizations of the generating curves $ (t,u(t)) $ of the catenoid and $ (t,v(t)) $ of the sphere in the catenoid sphere construction, respectively (see Definition~\ref{def_CatSph}). We have the catenoid
	\begin{align*}
		u(t):&=\frac{\arccosh(\lambda t) - \arccosh(\lambda)}{\lambda},\\
		u'(t) &= \frac{1}{\sqrt{\lambda^2 t^2 -1}},\\
		u''(t) &= -\frac{\lambda^2 t}{(\lambda^2 t^2 -1)^{\frac32}},\\
		u'''(t) &= \frac{\lambda^2 (2\lambda^2 t^2 +1)}{(\lambda^2 t^2 -1)^{\frac52}},\\
		\partial_\lambda u(t) &= \lambda^{-2}\left( \arccosh(\lambda) - \arccosh(\lambda t) + \lambda t \left(\lambda^2 t^2 -1 \right)^{-\frac12} - \lambda \left(\lambda^2 -1\right)^{-\frac12} \right),\\
		\partial_\lambda u'(t) &= -\frac{\lambda t^2}{(\lambda^2 t^2 -1)^{\frac32}},\\
		\partial_\lambda u''(t) &= \frac{\lambda t (2+ \lambda^2 t^2)}{(\lambda^2 t^2 -1)^{\frac52}},\\
		\partial_\lambda u'''(t) &= -\frac{\lambda (2\lambda^4 t^4 + 11\lambda^2 t^2 +2)}{(\lambda^2 t^2 -1)^{\frac72}},
	\end{align*}
	and the sphere 
	\begin{align*}
		v(t):&= \sqrt{\lambda^2 - 1} - \sqrt{\lambda^2-t^2},\\
		v'(t)&= \frac{t}{\sqrt{\lambda^2-t^2}},\\
		v''(t)&= \frac{\lambda^2}{(\lambda^2-t^2)^{\frac32}},\\
		v'''(t)&= \frac{3\lambda^2 t}{(\lambda^2-t^2)^{\frac{5}{2}}},\\
		\partial_\lambda v(t) &=\frac{\lambda}{\sqrt{\lambda^2-1}} - \frac{\lambda}{\sqrt{\lambda^2-t^2}},\\
		\partial_\lambda v'(t) &= -\frac{\lambda t}{(\lambda^2-t^2)^{\frac32}},\\
		\partial_\lambda v''(t) &= -\frac{\lambda^3 +2 \lambda t^2}{(\lambda^2-t^2)^{\frac52}},\\
		\partial_\lambda v'''(t) &= -\frac{3\lambda t (3\lambda^2 + 2 t^2)}{(\lambda^2-t^2)^{\frac72}},
	\end{align*}
	In the gluing region $ I:=[1-\delta,1+\delta] $ the generating curve $ h:I\to\R^2 $ that interpolates between the catenoid and the sphere is defined and satisfies the following.
	\begin{align*}
		h:&=u + \phi (v-u),\\ 
		h'&=u' + \phi (v'-u') + \phi' (v-u),\\
		h''&= u'' + \phi(v''-u'') + 2\phi' (v'-u') + \phi'' (v-u).\\
		\partial_\lambda h'&= \partial_\lambda u' + \phi \partial_\lambda (v'-u') + \phi' \partial_\lambda(v-u),\\
		\partial_\lambda h''&= \partial_\lambda u'' + \phi \partial_\lambda(v''-u'') + 2\phi' \partial_\lambda(v'-u') + \phi'' \partial_\lambda(v-u).\\
	\end{align*}
	We note that
	\begin{align}\label{eq_hTangentDec}
		\partial_\lambda h' = (1-\phi) \underset{<0}{\underbrace{\partial_\lambda u'}} + \phi \underset{<0}{\underbrace{\partial_\lambda v'}} + \phi' \underset{\leq 0}{\underbrace{\partial_\lambda \left( v - u \right)}} <0,
	\end{align}
	where the last term $ w(t):=\partial_\lambda (v(t)-u(t)) $ is nonpositive due to the fact that $ w(1)=0 $, $ w'(1)=0 $ and $ w''<0 $ which can be directly deduced from the explicit formulas.
	Furthermore, we can infer the asymptotic behavior of the explicit functions by elementary estimations, e.g.\ we get for all $ \lambda\geq 3 $
	\begin{align}\label{eq_WglueElementaryEst}
		\abs{v''(t)}\leq \frac{\lambda^2}{\left(\lambda^2-2^2\right)^{\frac32}} \leq \frac{\lambda^2}{\left( \lambda^2/2 \right)^{\frac32}} \leq \frac{8}{\lambda}.
	\end{align}
	We gather some estimations. In the following we write $ A(\lambda,\delta,t)\lesssim B(\lambda,\delta,t) $ if there exist constants $ \Lambda>0 $ and $ C>0 $ independent of $ \lambda $, $ \delta $ and $ t $ such that $ A(\lambda,\delta,t)\leq C B(\lambda,\delta,t) $ for all $ \lambda\geq\Lambda $, $ \delta\in(0,\frac12) $, $ t\in [1-\delta,1+\delta] $. 
	Using Taylor expansion at $ t=1 $ with the remainder term in Lagrange form and elementary estimations as in \eqref{eq_WglueElementaryEst}, we obtain the following.
	\begin{align*}
		\abs{v''(t)-u''(t)} &\leq \abs{v''(1) - u''(1)} + \delta \max_{\xi\in I} \abs{v'''(\xi)-u'''(\xi)}\lesssim \frac1\lambda + \frac\delta\lambda \\
		&\lesssim \frac1\lambda,\\
		\abs{v'(u) - u'(t)} &\leq \underset{=0}{\underbrace{\abs{v'(1) - u'(1)}}} + \delta \max_{\xi\in I} \abs{v''(\xi)-u''(\xi)}\\
		&\lesssim \frac\delta\lambda,\\
		\abs{v(u) - u(t)} &\leq \underset{=0}{\underbrace{\abs{v(1) - u(1)}}} + \delta \underset{=0}{\underbrace{\abs{v'(1) - u'(1)}}} + \frac{\delta^2}{2} \max_{\xi\in I} \abs{v''(\xi)-u''(\xi)} \\ 
		&\lesssim \frac{\delta^2}{\lambda}.\\%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%d_lambda now
		\abs{\partial_\lambda v''(t)- \partial_\lambda u''(t)} &\leq \abs{\partial_\lambda v''(1) - \partial_\lambda u''(1)} + \delta \max_{\xi\in I} \abs{\partial_\lambda v'''(\xi)- \partial_\lambda u'''(\xi)}\\
		&\lesssim \frac{1}{\lambda^2} + \frac{\delta}{\lambda^2}
		\lesssim \frac{1}{\lambda^2},\\
		\abs{\partial_\lambda v'(u) - \partial_\lambda u'(t)} &\leq \underset{=0}{\underbrace{\abs{\partial_\lambda v'(1) - \partial_\lambda u'(1)}}} + \delta \max_{\xi\in I} \abs{\partial_\lambda v''(\xi)- \partial_\lambda u''(\xi)}\\
		&\lesssim \frac{\delta}{\lambda^2},\\
		\abs{\partial_\lambda v(u) - \partial_\lambda u(t)} &\leq \underset{=0}{\underbrace{\abs{\partial_\lambda v(1) - \partial_\lambda u(1)}}} + \delta \underset{=0}{\underbrace{\abs{\partial_\lambda v'(1) - \partial_\lambda u'(1)}}}\\ &\quad + \frac{\delta^2}{2} \max_{\xi\in I} \abs{\partial_\lambda v''(\xi)- \partial_\lambda u''(\xi)}\\ 
		&\lesssim \frac{\delta^2}{\lambda^2}.\\
	\end{align*}
	We obtain for the interpolating function using $ \abs{\phi}\leq 1 $, $ \abs{\phi'}\lesssim \frac{1}{\delta} $ and $ \abs{\phi''}\lesssim \frac{1}{\delta^2}, $
	\begin{align*}
		\abs{h'(t)} &\lesssim \abs{u'(t)} + \abs{v'(t)-u'(t)} + \frac1\delta \abs{v(t)-u(t)} \lesssim \frac1\lambda + \frac1\lambda + \frac{\delta}{\lambda} \lesssim \frac1\lambda,\\
		\abs{h''(t)} &\lesssim \abs{u''(t)} + \abs{v''(t)-u''(t)} + \frac1\delta \abs{v'(t)-u'(t)} + \frac{1}{\delta^2} \abs{v(t)-u(t)} \lesssim \frac1\lambda,\\
		\abs{\partial_\lambda h'(t)} &\lesssim \abs{\partial_\lambda u'(t)} + \abs{\partial_\lambda v'(t)-\partial_\lambda u'(t)} + \frac1\delta \abs{\partial_\lambda v(t)-\partial_\lambda u(t)}\lesssim \frac{1}{\lambda^2},\\
		\abs{\partial_\lambda h''(t)} &\lesssim \abs{\partial_\lambda u''(t)} + \abs{\partial_\lambda v''(t)-\partial_\lambda u''(t)} + \frac1\delta \abs{\partial_\lambda v'(t)-\partial_\lambda u'(t)}\\ 
		\phantom{\abs{\partial_\lambda h''(t)}}&\phantom{\lesssim \abs{\partial_\lambda u''(t)}} + \frac{1}{\delta^2} \abs{\partial_\lambda v(t)-\partial_\lambda u(t)} \lesssim \frac{1}{\lambda^2},\\
	\end{align*}
	We plug the above estimations into the formula for the gluing energy
	\begin{align}
		W^{glue}(\lambda,\delta) &= \int_{1-\delta}^{1+\delta} \int_{0}^{2\pi} H(t,\varphi)^2 \sqrt{\det G(t,\varphi)}\ d\varphi dt \notag\\
		&=2\pi \int_{1-\delta}^{1+\delta} \frac{\left( th''(t) + h'(t) + h'(t)^3 \right)^2}{4 t (1+h'(t)^2)^\frac52}\ dt \label{eq_Wglue}\\
		&\leq \pi \delta \max_{t\in I}  \left( th''(t) + h'(t) + h'(t)^3 \right)^2,\notag
	\end{align}
	and obtain
	\begin{align}
		W^{glue}_\beta(\lambda,\delta) & \lesssim \delta \left(\frac{1}{\lambda}+ \frac{1}{\lambda} + \frac{1}{\lambda^3}\right)^2 \lesssim \frac{\delta}{\lambda^2},\label{eq_WglueEstimated}
	\end{align}
	which is \ref{lem_catenoidSpheresShrinkingAppendix_beta}.

	To prove \ref{lem_catenoidSpheresShrinkingAppendix_alpha} for type $ \alpha $ we note the few differences from the computations above. Let $ u_\alpha,v_\alpha,h_\alpha $ denote the corresponding catenoid, sphere and interpolating curve of the catenoid sphere of type $ \alpha $. We have $ u_\alpha=u $ and $ v_\alpha=-v $. The only situation where the opposite sign of $ v $ weakens the estimations is where $ v'(1)-u'(1)=0 $ for type $ \beta $ is used. This now becomes
	\begin{align*}
		\abs{v_\alpha'(1)-u_\alpha'(1)}\lesssim \frac1\lambda.
	\end{align*}
	which weakens the following estimations to
	\begin{align*}
		\abs{v_\alpha'-u_\alpha'}&\lesssim \frac1\lambda,\\
		\abs{v_\alpha-u_\alpha}&\lesssim \frac{\delta}{\lambda},\\
		\abs{h'_\alpha}&\lesssim \frac1\lambda,\\
		\abs{h''_\alpha}&\lesssim \frac{1}{\delta \lambda},
	\end{align*}
	and instead of \eqref{eq_WglueEstimated}, we obtain
	$$ W_\alpha^{glue}(\lambda,\delta)\lesssim \delta \left( \frac{1}{\delta \lambda} + \frac1\lambda + \frac{1}{\lambda^3} \right)^2 \lesssim \frac{1}{\delta \lambda^2}, $$
	which is \ref{lem_catenoidSpheresShrinkingAppendix_alpha}.

	It remains to show \ref{lem_catenoidSpheresShrinkingAppendix_monotonicity}.
	Writing $$ J(t):=\left( th''(t) + h'(t) + h'(t)^3 \right)^2, $$ 
	and using \eqref{eq_Wglue}, we obtain
	\begin{align*}
		\partial_\lambda W^{glue}(\lambda,\delta)&= \frac{\pi}{2} \int_{1-\delta}^{1+\delta} \partial_\lambda \left( \frac{J(t)}{t (1+h'(t)^2)^\frac52} \right) dt.
	\end{align*}
	We may use the fact that for functions $ f:\R\to [0,\infty) $, $ g:\R\to (0,\infty) $ with $ g'\leq 0 $ we have
	$$ \left(\frac{f}{g}\right)'=\frac{f'g - fg'}{g^2}\geq \frac{f'}{g}. $$ We have $ \partial_\lambda h' <0 $ by \eqref{eq_hTangentDec} which implies $ \partial_\lambda \left( t \left(1+h'(t)^2\right)^{\frac52} \right) < 0 $ and thus
	\begin{align*}
		\partial_\lambda W^{glue}(\lambda,\delta) &\geq \frac{\pi}{2} \int_{1-\delta}^{1+\delta} \frac{\partial_\lambda J(t)}{ t (1+h'(t)^2)^\frac52}dt.
	\end{align*}
	A case distinction on the sign of $ \partial_\lambda J(t) $ implies with $ t\geq \frac12 $,
	\begin{align*}
		\frac{\partial_\lambda J(t)}{ t (1+h'(t)^2)^\frac52} \geq \min\left\{ 0 , 2 \partial_\lambda J(t) \right\}.
	\end{align*}
	We estimate further
	\begin{align*}
		\abs{\partial_\lambda J(t)}=&2\abs{ \left( th''(t) + h'(t) + h'(t)^3 \right) \left( t \partial_\lambda h''(t) + \partial_\lambda h'(t) + 3h(t)^2\partial_\lambda h'(t) \right) }\\
		&\lesssim \left( \frac1\lambda + \frac{1}{\lambda} + \frac{1}{\lambda^3} \right) \left( \frac{1}{\lambda^2} + \frac{1}{\lambda^2} + \frac{1}{\lambda^4} \right) \lesssim  \frac{1}{\lambda^3},
	\end{align*}
	and obtain
	\begin{align*}
		\partial_\lambda W^{glue}(\lambda,\delta) &\gtrsim \int_{1-\delta}^{1+\delta} \min\left\{ 0, \partial_\lambda J(t) \right\} dt\\
		&\gtrsim \int_{1-\delta}^{1+\delta} -\frac{1}{\lambda^3} dt \\
		&\gtrsim - \frac{\delta}{\lambda^3}
	\end{align*}
	which is \ref{lem_catenoidSpheresShrinkingAppendix_monotonicity}.
\end{proof}


\begin{lem}\label{lem_uniformGraphRadius}
	For all $ A_{\max}>0 $, there exists a radius $ r(A_{\max})>0 $ such that all smooth immersions $ f:\Sigma\to\R^3 $ of a closed surface $ \Sigma $ with second fundamental form $$ \max_{p\in\Sigma}{\norm{A(p)}}\leq A_{\max} $$ are graphs over a ball $ B_r(0)\subseteq T_pf$ \com{$ B_r(0) $ w.r.t $ \norm{\cdot}_{g(p)} $}in the tangent space for all $ p\in\Sigma $ and their graph parametrizations $ u:B_r(0)\to \R $ satisfy 
	\begin{align*}
		\norm{D^2 u}_{C^0(B_r(0))}\leq 5 A_{max}.
	\end{align*}
\end{lem}
\begin{proof}
	By \cite[Theorem~2.4]{Langer_Comp}, for all $ \alpha\in(0,1) $ there exists a radius $ r(\alpha)>0 $ such that for all immersions $ f:\Sigma\to\R^3 $ with $ \norm{A}\leq A_{\max} $ and for all $ p\in\Sigma $ the graph parametrization $ u:B_r(0)\to\R^3 $ satisfies
	\begin{align*}
	 	\norm{Du}_{C^0(B_r(0))}\leq \alpha.
	\end{align*}
	Together with (see e.g.\ \cite[Proof of Lemma~2.2]{Breuning_Comp})
	\begin{align*}
	 	\norm{D^2u}_{C^0(B_r(0))}\leq 4\left(1+\norm{Du}_{C^0(B_r(0))}\right)^{\frac32} \norm{A},
	\end{align*}
	we obtain with appropriate choice of $ \alpha $
	\begin{align*}
		\norm{D^2u}_{C^0(B_r(0))} \leq 4\left(1+\alpha\right)^{\frac32} \norm{A} \leq 5 A_{max}.
	\end{align*}
\end{proof}

