\subsection{Upper bound for Pólya's satisfiability\label{sec-upp}} We begin by extending the argument based on the first eigenvalue
used in~\cite{fs} which was mentioned in the Introduction to see that, in general, not only can P\'{o}lya's conjecture
fail for domains in $\mathbb{S}^{1}\times\R$, but that an inequality of this type cannot hold, even with a smaller constant.

From~\eqref{eigcyl} we have
$$\lambda_1 = \frac{\pi^2}{h^2}$$
and, given any positive constant $C$, by taking $h>\pi^2/(2C)$ we have
\[
 N\left(\lambda_{1}\right) = 1 > \fr{\pi^2}{2C h}= \fr{h}{2C}\lambda_{1}.
\]
We have thus proved the following
\begin{proposition}\label{noweaker}
    Given any positive constant $C$, there exist domains $\Omega$ on the infinite cylinder $\mathbb{S}^{1}\times\R$ for
    which
    \[
     \lambda_{1} < \fr{4C\pi}{|\Omega|}.
    \]
    In particular, P\'{o}lya's conjecture is not satisfied on the cylindrical strip $\ch$ for $h$ larger than $\pi^2/2$.
\end{proposition}

\subsection{Lower bounds for Pólya's satisfiability}
Let
$$R(\lambda) := N(\lambda) - \lambda\frac{h}{2}.$$
P\'{o}lya's conjecture for $\ch$ is then equivalent to $R(\lambda)$ being non-positive.
This can be approximated by counting integer lattice points inside a half-ellipse on the plane using the following construction.
Given an eigenvalue $\lambda$, consider the ellipse centred at the origin defined by the equation
$$e(x, y) := x^2+y^2\frac{\pi^2}{h^2}=\lambda$$
To each integer lattice point $(m, n)\in \Z\times\N$ we associate the eigenvalue
$\lambda_{m,n}:=m^2+n^2\frac{\pi^2}{h^2}$.
In this way $N(\lambda)$ is given by the number of such points lying inside the ellipse 
\[
E = \{(x,y)\in\R\times\R^+_0 : e(x, y)\leq\lambda\},
\]
which are above the horizontal axis.
\begin{figure}[h]
    \centering
    \includegraphics[height=0.25\textheight]{polya_1.png}
    \caption{Lattice points and ellipse for $h=3,\lambda=50$}
\end{figure}
We now consider the portion of this region covered by lattice squares given by
$$Q := \bigcup_{\substack{k,l\in\mathds{Z}\\ [k, k+1]\times[l, l+1]\subset E}}[k, k+1]\times[l, l+1].$$
By excluding lattice points lying on the $y$-axis, we can associate each lattice point in $E$ to a
lattice square in $Q$, thus obtaining
\begin{align*}
N(\lambda)&=|Q|+\left\lfloor \frac{h}{\pi}\sqrt{\lambda} \right\rfloor\\
&\leq |E| + \frac{h}{\pi}\sqrt{\lambda} - (|E|-|Q|)\\
&= \lambda\frac{h}{2} + \frac{h}{\pi}\sqrt{\lambda} - |E\setminus Q|
\end{align*}
and
\begin{align*}
R(\lambda)&=N(\lambda)-\lambda\frac{h}{2}\\
&\leq \frac{h}{\pi}\sqrt{\lambda} - |E\setminus Q|.
\end{align*}
As the ellipse is symmetric with respect to the $y$-axis, for area purposes it is enough to consider
the portions of $E$ and $Q$ in the first quadrant
\begin{align*}
E_+ &= E\cap (\R^+_0\times\R^+_0)\\
Q_+ &= Q\cap (\R^+_0\times\R^+_0)
\end{align*}
and now
\begin{equation}
    R(\lambda) \leq \frac{h}{\pi}\sqrt{\lambda} - 2|E_+ \setminus Q_+|\label{rEstimate}
\end{equation}


\subsubsection{First estimate}
Define $\eln := \left\lfloor \frac{h}{\pi}\sqrt{\lambda} \right\rfloor$ and $\epsilon_n := \frac{h}{\pi}\sqrt{\lambda} - \eln$,
and define by
$$
\begin{array}{lll}
e_x(y):= \sqrt{\lambda-y^2\frac{\pi^2}{h^2}} & \mbox{ and } &
e_y(x):= \frac{h}{\pi}\sqrt{\lambda-x^2}
\end{array}
$$
the two functions describing the portion of the ellipse in the first quadrant.

We will approximate the area of $E_+\setminus Q_+$ by partitioning it into the strips

$$S_j := (E_+ \setminus Q_+)\cap(\R\times[j,j+1])\;,\; j=0,1,\dots,\eln$$

Since all these are convex, for $j < \eln$ we can bound the area of each $S_j$ from below by considering the triangle with vertices at $(e_x(j),j)$, $(e_x(j+1),j+1)$, and $(e_x(j+1), j)$.
Similarly, $|S_{\eln}|$ is bounded by the area of the triangle with vertices at $(e_x(\eln),\eln), (0,\eln +\epsilon_n), (0,\eln)$.
\begin{figure}[h]
    \begin{subfigure}{.5\textwidth}
        \centering
        \includegraphics[height=0.25\textheight]{polya_2a.png}
        \caption{First $R(\lambda)$ estimate for $h=3,\lambda=50$}
    \end{subfigure}%
    \begin{subfigure}{.5\textwidth}
        \centering
        \includegraphics[height=0.25\textheight]{polya_2b.png}
        \caption{First $R(\lambda)$ estimate for $h=2,\lambda=61$}
    \end{subfigure}
    \caption{First $R(\lambda)$ estimates}
\end{figure}
Thus
\begin{align*}
    \frac{1}{2}|E_+ \setminus Q_+|&\geq \frac{1}{2}e_x(\eln)\epsilon_n + \sum_{j=0}^{\eln-1}\fr{1}{2}(e_x(j)-e_x(j+1))\\
    &=\frac{1}{2}\left[e_x(\eln)\epsilon_n + e_x(0)-e_x(\eln)\right]\\
    &=\frac{1}{2}\left[e_x(\eln)(\epsilon_n-1) + \sqrt{\lambda}\right]
\end{align*}
and
\begin{align*}
    R(\lambda) &\leq \frac{h}{\pi}\sqrt{\lambda} - \left[e_x(\eln)(\epsilon_n-1) + \sqrt{\lambda}\right]\\
    &=\left(\frac{h}{\pi}-1\right)\sqrt{\lambda} - \sqrt{\lambda-\frac{\pi^2}{h^2}\left(\frac{h}{\pi}\sqrt{\lambda}-\epsilon_n\right)^2}(\epsilon_n-1)\\
    %&=\left(\frac{h}{\pi}-1\right)\sqrt{\lambda} + \sqrt{\frac{\pi^2}{h^2}\left(2\frac{h}{\pi}\sqrt{\lambda}\epsilon_n-\epsilon_n^2\right)}(1-\epsilon_n)\\
    &\leq\left(\frac{h}{\pi}-1\right)\sqrt{\lambda} + \sqrt{\frac{\pi^2}{h^2}\left(2\frac{h}{\pi}\sqrt{\lambda}\epsilon_n\right)}(1-\epsilon_n)\\
    &=\left(\frac{h}{\pi}-1\right)\sqrt{\lambda} + \sqrt{\frac{\pi}{h}}\sqrt{2\epsilon_n}(1-\epsilon_n)\lambda^{1/4}.
\end{align*}
Note that $f(x) = \sqrt{2x}(1-x)$ is maximal in $[0,1)$ when $x=\frac{1}{3}$, and thus
\begin{align*}
    R(\lambda)&\leq\left(\frac{h}{\pi}-1\right)\sqrt{\lambda} + \sqrt{\frac{\pi}{h}}\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}.
\end{align*}
When $h<\pi$ the coefficient of the leading term is negative and
\begin{align*}
    R(\lambda)\leq 0 &\Leftarrow \left(\frac{h}{\pi}-1\right)\sqrt{\lambda} + \sqrt{\frac{\pi}{h}}\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\leq 0\\
    &\Leftrightarrow \lambda^{1/4}\geq \frac{\sqrt{\pi/h}\left(\fr{2}{3}\right)^{3/2}}{1-h/\pi}\\
    &\Leftrightarrow \sqrt{\lambda}\geq \frac{8\pi^3}{27h(\pi-h)^2}.
\end{align*}
We thus have
\begin{proposition}
    $R(\lambda) \leq 0$ when $h<\pi$ and $\sqrt{\lambda}\geq \fr{8\pi^3}{27h(\pi-h)^2}$.
\end{proposition}

\subsubsection{Second estimate}
Let $\elm := \left\lfloor \sqrt{\lambda} \right\rfloor$ and $\epsilon_m := \sqrt{\lambda} - \elm$.

Let $(m_0,n_0)$ be the point in the ellipse where its slope is $-1$, that is,
$$e_y'(m_0)=-1\;,\;n_0=e_y(m_0),$$
and let
\begin{align*}
m_i&:= \lfloor m_0\rfloor + i\;,\; i=1,2,\dots,\elm-\lfloor m_0+1\rfloor\\
n_j&:= \lfloor n_0\rfloor + j\;,\; j=1,2,\dots,\elm-\lfloor n_0+1\rfloor.
\end{align*}

Similarly to the first estimate, we partition $E_+\setminus Q_+$ into several parts
\begin{align*}
    R_i &:= (E_+\setminus Q_+)\cap([m_i,m_{i+1}]\times\R)\;,\; i=0,1,2,\dots,\elm-\lfloor m_0\rfloor\\
    S_j &:= (E_+\setminus Q_+)\cap(\R\times[n_j,n_{j+1}])\;,\; j=0,1,2,\dots,\eln-\lfloor n_0\rfloor\\
    T&:= (E_+-Q_+)\cap([0,m_0]\times[0,n_0])
\end{align*}
Since all these are convex, we can estimate their area from below using the following triangles (see Figure~\ref{seconRestimate})
\begin{align*}
    R_i \supset & \text{ Triangle with vertices at }(m_i,e_y(m_i)), (m_{i+1},e_y(m_{i+1})), (m_{i+1},e_y(m_i))\\
    S_j \supset & \text{ Triangle with vertices at }(e_x(n_j),n_j), (e_x(n_{j+1}),n_{j+1}), (e_x(n_{j+1}),n_j)\\
    T \supset & \text{ Triangles with vertices at }(m_0, n_0), (m_0, \min\{\lfloor n_0\rfloor,e_y(m_1)\}), (\lfloor m_0 \rfloor, \min\{\lfloor n_0\rfloor,e_y(m_1)\})\\
    &\text{ or }(m_0, n_0), (\min\{\lfloor m_0\rfloor,e_x(n_1)\}, n_0), (\min\{\lfloor m_0\rfloor,e_x(n_1)\}, \lfloor n_0\rfloor)
\end{align*}
