    \end{subfigure}
    \caption{Second $R(\lambda)$ estimates\label{seconRestimate}. $R_i$, $S_j$ and $T$ triangles are shaded with
    vertical lines, horizontal lines, and dots, respectively.}
\end{figure}
to obtain
\begin{align*}
    \left|\bigcup_{i=0}^{\elm-\lfloor m_0 \rfloor} R_i\right|&\geq\sum_{j=0}^{\elm-\lfloor m_0 \rfloor}\frac{1}{2}(e_y(m_i)-e_y(m_{i+1}))(m_{i+1}-m_i)\\
        &= \frac{1}{2}\left[e_y(m_{\elm-\lfloor m_0\rfloor})\epsilon_m + e_y(m_1)-e_y(m_{\elm-\lfloor m_0\rfloor}) + (e_y(m_0)-e_y(m_1))(m_1-m_0)\right]\\
        &= \frac{1}{2}\Big[e_y(\elm)(\epsilon_m-1) + e_y(m_1) + (e_y(m_0)-e_y(m_1))(\lfloor m_0 \rfloor+1-m_0)\Big]\\
        &= \frac{1}{2}\left[\frac{h}{\pi}\sqrt{\lambda - (\sqrt{\lambda}-\epsilon_m)^2}(\epsilon_m-1)
        + e_y(m_0) - (e_y(m_0)-e_y(m_1))(m_0-\lfloor m_0 \rfloor)\right]\\
        &= \frac{1}{2}\left[-\frac{h}{\pi}\sqrt{2\sqrt{\lambda}\epsilon_m - \epsilon_m^2}(1-\epsilon_m)
        + n_0 - (n_0-e_y(m_1))(m_0-\lfloor m_0 \rfloor)\right]\\
        &\geq \frac{1}{2}\left[-\frac{h}{\pi}\sqrt{2\epsilon_m}(1-\epsilon_m)\lambda^{1/4}
        + n_0 - (n_0-e_y(m_1))(m_0-\lfloor m_0 \rfloor)\right].
\end{align*}
We again use the fact that $f(x)=\sqrt{2x}(1-x)$ attains its maximum in $[0,1)$ when $x=\frac{1}{3}$, and thus
\begin{align*}        
    \left|\bigcup_{i=0}^{\elm-\lfloor m_0 \rfloor} R_i\right|&\geq \frac{1}{2}\left[-\frac{h}{\pi}\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4} + n_0 - (n_0-e_y(m_1))(m_0-\lfloor m_0 \rfloor)\right].
\end{align*}
Similarly
$$\left|\bigcup_{j=0}^{\eln-\lfloor n_0 \rfloor} S_j\right|\geq
    \frac{1}{2}\left[-\sqrt{\frac{\pi}{h}}\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}+ m_0 - (m_0-e_x(n_1))(n_0-\lfloor n_0 \rfloor)\right],
    $$
and
$$|T|\geq \frac{1}{2}\left[(m_0-\lfloor m_0 \rfloor)(n_0-e_y(m_1))+(n_0-\lfloor n_0 \rfloor)(m_0-e_x(n_1))\right].$$
Finally
\begin{alignat*}{3}
    \frac{1}{2}|E_+\setminus Q_+|&\geq \frac{1}{2}\bigg[&&-\frac{h}{\pi}\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4} + n_0 - (n_0-e_y(m_1))(m_0-\lfloor m_0 \rfloor)\\
        & & &-\sqrt{\frac{\pi}{h}}\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}+ m_0 - (m_0-e_x(n_1))(n_0-\lfloor n_0 \rfloor)\\
        & & & \hspace*{5mm}+\left(m_0-\lfloor m_0 \rfloor\right)(n_0-e_y(m_1))+(n_0-\lfloor n_0 \rfloor)(m_0-e_x(n_1))\bigg]\\
    &=\frac{1}{2}\Big[&&-\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4} + m_0 + n_0 \Big].
\end{alignat*}
We can now determine the points on the ellipse with slope $-1$, namely,
$$e_y'(m_0)=-1\Leftrightarrow \frac{h m_0}{\pi\sqrt{\lambda-m_0}} = 1 \Leftrightarrow m_0 = \frac{\sqrt{\lambda}}{\sqrt{(h/\pi)^2+1}}$$
$$n_0=e_y(m_0)=\frac{h}{\pi}\sqrt{\lambda-\frac{\lambda}{(h/\pi)^2+1}} = \frac{(h/\pi)^2\sqrt{\lambda}}{\sqrt{(h/\pi)^2+1}},$$
and substitute in the expression above to obtain
$$
\frac{1}{2}|E_+\setminus Q_+|\geq \frac{1}{2}\bigg[-\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4} + \frac{\sqrt{\lambda}}{\sqrt{(h/\pi)^2+1}} + \frac{(h/\pi)^2\sqrt{\lambda}}{\sqrt{(h/\pi)^2+1}} \bigg].
$$
From~\eqref{rEstimate} we have
\begin{align}
    R(\lambda)&\leq\frac{h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}-\frac{((h/\pi)^2+1)\sqrt{\lambda}}{\sqrt{(h/\pi)^2+1}}\nonumber \\
        &=\left(\fr{h}{\pi}-\sqrt{\left(\fr{h}{\pi}\right)^2+1}\right)\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\nonumber \\
        &=-\frac{\sqrt{h^2+\pi^2}-h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)
        \left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\label{polya-estim2}. \\
\end{align}
But
\begin{align*}
0&\geq-\frac{\sqrt{h^2+\pi^2}-h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\\
\Leftrightarrow \lambda^{1/4}&\geq \left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\frac{\pi}{\sqrt{h^2+\pi^2}-h}\\
&=\left(\fr{2}{3}\right)^{3/2}\frac{h+\pi^{3/2}\sqrt{1/h}}{\sqrt{h^2+\pi^2}-h}\\
\Leftrightarrow \sqrt{\lambda}&\geq\fr{8}{27}\frac{(h+\pi^{3/2}\sqrt{1/h})^2}{(\sqrt{h^2+\pi^2}-h)^2}\\
&=\fr{8}{27}\frac{(h/\pi+\sqrt{\pi/h})^2}{(\sqrt{(h/\pi)^2+1}-h/\pi)^2}
\end{align*}
and we have thus proven the following bound.
\begin{proposition}\label{secestim}
    $R(\lambda) \leq 0$ when $\sqrt{\lambda}\geq \fr{8}{27}\left(\fr{h/\pi+\sqrt{\pi/h}}{\sqrt{(h/\pi)^2+1}-h/\pi}\right)^2$.
\end{proposition}

\subsubsection{Lower bounds}
We have
$$\lambda_1 = \frac{\pi^2}{h^2} \Rightarrow \sqrt{\lambda}\geq\frac{\pi}{h}$$
and, for $h<\pi$,
%h>=1/9 (9 + 2 sqrt(6)) π
$$\frac{\pi}{h} \geq\frac{8\pi^3}{27h(\pi-h)^2}\Leftrightarrow
(\pi-h)^2 \geq\frac{8}{27}\pi^2\Leftrightarrow
h\leq \frac{1}{9}(9-2\sqrt{6})\pi<\pi.$$
Thus
$$\sqrt{\lambda} \geq \frac{8\pi^3}{27h(\pi-h)^2} \text{ when } h\leq \frac{1}{9}(9-2\sqrt{6})\pi,$$
and finally
$$R(\lambda) \leq 0 \text{ when } h\leq \frac{1}{9}(9-2\sqrt{6})\pi.$$
We have thus
\begin{proposition}
    $\SI$ satisfies Pólya's conjecture for $h\leq \left(1-\fr{2\sqrt{6}}{9}\right)\pi$.
\end{proposition}
For the remaining values $\frac{1}{9}(9-2\sqrt{6})\pi < h \leq \frac{\pi^2}{2}$ we first note that the
second estimate given in Proposition~\ref{secestim} is convex in $h$ and bounded above by
\begin{alignat*}{3}
    \left(\fr{2}{3}\right)^3\frac{(h/\pi+\sqrt{\pi/h})^2}{(\sqrt{(h/\pi)^2+1}-h/\pi)^2}
    &\leq \max\Bigg\{
    &&\left(\fr{2}{3}\right)^3\left.\frac{(h/\pi+\sqrt{\pi/h})^2}{(\sqrt{(h/\pi)^2+1}-h/\pi)^2}\right|_{h=\frac{1}
    {9}(9-2\sqrt{6})\pi},\\
    & &&\left(\fr{2}{3}\right)^3\left.\frac{(h/\pi+\sqrt{\pi/h})^2}{(\sqrt{(h/\pi)^2+1}-h/\pi)^2}\right|
    _{h=\frac{\pi^2}{2}}
    \Bigg\}\\
    &<20,&&
\end{alignat*}
yielding $R(\lambda) < 0$  whenever $\sqrt{\lambda}\geq 20.$
\begin{proposition}
    $\SI$  satisfies Pólya's conjecture for $\frac{1}{9}(9-2\sqrt{6})\pi < h \leq \frac{\pi^2}{2}$ and $\lambda \geq 400$
\end{proposition}
\subsection{Computational search} \label{subsec:polya/cs}
To determine the satisfiability when $\frac{1}{9}(9-2\sqrt{6})\pi < h \leq \frac{\pi^2}{2}$ and
$$\lambda < 400 \Rightarrow k = N(\lambda) \leq \frac{h}{2}\lambda +  \frac{h}{\pi}\sqrt{\lambda} = 400\frac{h}{2} + 20\frac{h}{\pi} < 1019$$
we first discretize the problem to reduce it to a finite number of cases, and then use a computer-aided search
to check that the conjecture holds in each of the resulting cases.
\subsubsection{$k$-intervals} Consider again the expression for the eigenvalues of $\ch$ given by~\eqref{eigcyl},
and define the $k$-intervals
\begin{align*}
I_{m,n}^k:&=\left\{h\in\mathds{R}^+ : k > \lambda_{m,n}\frac{h}{2}\right\}\\
&=\left\{h\in\mathds{R}^+ : k > m^2\frac{h}{2} + n^2\frac{\pi^2}{2h}\right\}.
\end{align*}
Intuitively, the $k$-interval $I_{m,n}^k$ is the range of values of $h$ for which the eigenvalue $\lambda_{m,n}$ would not satisfy Pólya's conjecture if it were the $k$-th eigenvalue.
It is guaranteed that these sets are indeed intervals since $m^2\frac{h}{2} + n^2\frac{\pi^2}{2h}$ is convex for $h\in(0, \infty)$.

Now we provide a necessary and sufficient condition for P\'{o}lya's conjecture to fail for a particular eigenvalue $\lambda_{k}$.
\begin{lemma}
For any fixed value of $h$, P\'{o}lya's conjecture fails for the $k$-th eigenvalue $\lambda_{k}$
if and only if $h$ is in at least $k$ $k$-intervals. More precisely, $\lambda_k < \frac{2k}{h}$ if and
only if $$h\in I_{m_1,n_1}^k\cap I_{m_2,n_2}^k\cap\dots\cap I_{m_k,n_k}^k$$
where $\lambda_{m_1,n_1}, \lambda_{m_2,n_2}, \dots, \lambda_{m_k,n_k}$ are the first $k$ eigenvalues.
\begin{proof}
    First note that for a fixed $h$, and if $(m,n)$ and $(m',n')$ are such that $\lambda_{m,n} < \lambda_{m',n'}$,
    if $h$ is in $I_{m',n'}^k$, then it must also belong to $I_{m,n}^k$, as
    $$  \lambda_{m,n}\frac{h}{2} < \lambda_{m',n'}\frac{h}{2} < k.$$
    If $k>\lambda_k\frac{h}{2}$, we know that $h$ is in the $k$-interval corresponding to $\lambda_k$. Using the previous observation we deduce that $h$ is also in all the $k$-intervals corresponding to $\lambda_1,\dots,\lambda_{k-1}$, thus, $h$ is in at least $k$ $k$-intervals.

    If $h$ is in at least $k$ $k$-intervals then at least one of them corresponds to an eigenvalue $\lambda_l,\; l\geq k$ and we can again use the previous result to conclude that $h$ is in all the $k$-intervals corresponding to any eigenvalue smaller than $\lambda_l$, specifically $\lambda_l > \lambda_k$ and thus $k>\lambda_k\frac{h}{2}$.
\end{proof}
\end{lemma}
\subsubsection{Search}
$\lambda_{m,n}$ is increasing over $\left|m\right|$ and $n$ so if $\lambda_{m,n}$ is the $k$-th smallest eigenvalue, we have
$$|m|, n \leq k$$
We only need to consider $k\leq 1019$ so it suffices to
\begin{enumerate}[i.]
    \item compute $I^k_{m,n}$ for $|m|, n, k\leq 1\,019$;
    \item determine all intersections of at least $k$ $k$-intervals for each $k=1,2,\dots,1\,019$
\end{enumerate}
to determine the satisfiability of Pólya's conjecture for $\SI$ in the remaining cases.

We can calculate this algebraically as we can determine exact expressions for every $k-$interval's endpoints. Implementing and running this search (details are included in Appendix~\ref{apx:impl}) gives us the intersections
\[
\begin{array}{ll}
 h\in\left(-\sqrt{-4\pi^2+64}+8,\sqrt{-\frac{\pi^2}{4}+4}+2\right) & \mbox{ for } k=8\eqskip
 h\in\left(-\sqrt{-9\pi^2+169}+13,\sqrt{-\pi^2+\frac{169}{16}}+\frac{13}{4}\right) & \mbox{ for } k=13.
\end{array}
\]

