\section{Li-Yau inequalities\label{liyau-sec}}

The Li-Yau inequalities for $\SI$ are given by~\eqref{liyau}.
Proceeding as in the case of the first eigenvalue for P\'{o}lya's inequality, we now see that for $h$ larger than
$\pi^2$ this cannot hold already for $k$ equal to one.
We will, however, show that~\eqref{liyau} holds for all $h\in(0,\pi^2]$. To do this, it is convenient to prove the result
separately on $(0,\pi^2/2]$ and then on $(\pi^2/2,\pi^2]$, and we will start with the former interval. We make use of the following two lemmas.
\begin{lemma}
    \label{lemma:liyau1}
    If the Li-Yau inequality~\eqref{liyau} holds up to $k-1$ and $\lambda_{k}$ satisfies Pólya's conjecture, then
    it also holds for $k$.
\end{lemma}
\begin{proof}
    Follows directly by induction.
\end{proof}

Using this lemma, and for the first range of $h$ under consideration, we only need to show that the inequality holds when
P\'{o}lya's conjecture is not satisfied (for $\lambda_8$ and $\lambda_{13}$) and then everything else will follow by
induction. To do this, we note that the following, slightly weaker version of Lemma~\ref{lemma:liyau1}, also holds.
\begin{lemma}
    \label{lemma:liyau2}
    If $\lambda_1,\lambda_2,\dots,\lambda_{k-1}$ all satisfy Pólya's conjecture and
    $$\lambda_{k}\geq\frac{k}{h},$$
    then the Li-Yau inequality holds for $\lambda_1,\lambda_2,\dots,\lambda_{k}$.
    \begin{proof}
        $$\sum_{i=1}^k \lambda_i \geq \frac{2(k-1)k}{h}+\frac{k}{h}=\frac{(2k-1)k}{h}\geq\frac{k^2}{h}$$
    \end{proof}
\end{lemma}
Thus, if the weaker version $\lambda_{k}\geq k/h$ holds for the only eigenvalues for which P\'{o}ly\'{a}'s conjecture
is not satisfied in this range, namely $\lambda_8$ and $\lambda_{13}$, we will have shown that~\eqref{liyau} holds on the first
interval.
It is straightforward to derive the precise values of $\lambda_{8}$ and $\lambda_{13}$ in the non-satisfiability intervals via direct
calculations yielding
\begin{align*}
    \lambda_8 &= \begin{cases}
        1 + 4 \frac{\pi^2}{h^2}\quad &h\in\big(8 - \sqrt{64 - 4 \pi^2}, \pi\big]\eqskip
        4 + \frac{\pi^2}{h^2} \quad &h\in\big[\pi, 2 + \sqrt{4 - \pi^2/4}\big)
    \end{cases}
\end{align*}
and
\begin{align*}
    \lambda_{13} &= \begin{cases}
        1 +  9 \frac{\pi^2}{h^2}\quad &h\in\big(13 - \sqrt{169 - 9 \pi^2}, \sqrt{5/3} \pi\big]\eqskip
        4 +  4 \frac{\pi^2}{h^2}\quad &h\in\big[\sqrt{5/3} \pi, 13/4 + \sqrt{169/16 - \pi^2}\big).
    \end{cases}.
\end{align*}
Since
\begin{align*}
    1 + 4 \frac{\pi^2}{h^2} \geq\frac{8}{h} &\Leftrightarrow (h-4)^2\geq 16-4\pi^2 \,(< 0)\\
    4 + \frac{\pi^2}{h^2} \geq\frac{8}{h} &\Leftrightarrow (h-1)^2\geq 1-\frac{\pi^2}{4} \,(< 0)\\
    1 +  9 \frac{\pi^2}{h^2} \geq\frac{13}{h} &\Leftrightarrow \left(h-\frac{13}{2}\right)^2\geq \frac{169}{4} - 9\pi^2 \,(< 0)\\
    4 +  4 \frac{\pi^2}{h^2} \geq\frac{13}{h} &\Leftrightarrow \left(h-\frac{13}{8}\right)^2\geq \frac{169}{64} - \pi^2 \,(< 0)\\
\end{align*}
we conclude that
$\lambda_8\geq\fr{8}{h}$ and $\lambda_{13}\geq\fr{13}{h}$ for $h\in(0,\pi^2/2]$.
Combining this with the previous two lemmas we obtain the following result.
\begin{proposition}
    The Li-Yau inequalities on $\SI$ are satisfied if $h$ belongs to
    $$\left(0,\frac{\pi^2}{2}\right]$$
\end{proposition}

To prove Li-Yau's satisfiability when $h$ belongs to $(\pi^2/2,\pi^2]$ we need a slightly stronger lemma
\begin{lemma}
    \label{lemma:liyau3}
    If the Li-Yau inequality~\eqref{liyau} holds up to $k-1$ and
    $$\lambda_{k}\geq\frac{2k-1}{h},$$
    then it also holds for $k$.
\end{lemma}
\begin{proof}
    Follows directly by induction.
\end{proof}

If we can guarantee Li-Yau's satisfiability where $\lambda_{k}<(2k-1)/h$ then the all other inequalities will follow by induction from this lemma.

From estimative~\eqref{polya-estim2} we obtain the bound
\begin{align*}
    R(\lambda)=N(\lambda)-\lambda\frac{h}{2}&\leq-\frac{\sqrt{h^2+\pi^2}-h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\\
    \Leftrightarrow k&\leq \lambda\frac{h}{2}-\frac{\sqrt{h^2+\pi^2}-h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}
\end{align*}
Now if
$$-\frac{\sqrt{h^2+\pi^2}-h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\leq\frac{1}{2},$$
then the lemma's condition is satisfied as
$$k\leq \lambda\frac{h}{2}+\frac{1}{2}\Leftrightarrow \lambda\geq\frac{2k-1}{h}.$$
It is thus enough to check that Li-Yau's inequalities hold for all values of $\lambda$ such that
\begin{align*}
    \frac{1}{2}&<-\frac{\sqrt{h^2+\pi^2}-h}{\pi}\sqrt{\lambda}+\left(\frac{h}{\pi}+\sqrt{\frac{\pi}{h}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}\\
    \Rightarrow \frac{1}{2}&<-\frac{\sqrt{\pi^4+\pi^2}-\pi^2}{\pi}\sqrt{\lambda}+\left(\frac{\pi^2}{\pi}+\sqrt{\frac{\pi}{\pi^2}}\right)\left(\fr{2}{3}\right)^{3/2}\lambda^{1/4}
\end{align*}
since the right--hand side is increasing in $h$ on the interval $(\pi^2/2,\pi^2]$. This is then equivalent to
\[
\frac{1}{2}<-(\liyauA)\sqrt{\lambda}+\liyauB\lambda^{1/4},
\]
which may be solved to yield
\begin{gather*}
    \fr{2\pi^{3/2}+2-\sqrt {-27\pi\sqrt {1 + \pi^2} + 8\pi^{3/2} + 4\pi^3 + 27\pi^2 + 4}} {3\sqrt {6\pi}\left (\sqrt {1 + \pi^2} - \pi  \right)}
    < \lambda^{1/4} < \fr{2\pi^{3/2} + 2+\sqrt {-27\pi\sqrt {1 + \pi^2} + 8\pi^{3/2} + 4\pi^3 + 27\pi^2 + 4}} {3\sqrt {6\pi}\left (\sqrt {1 + \pi^2} - \pi  \right)}.
%     \left(\frac{-\liyauB+\sqrt{\left(\liyauB\right)^2+2(\liyauA)}}{-2(\liyauA)} \right)^4\\
%     &\approx 26300.558395
\end{gather*}
The lower and upper ends of the above interval correspond to $\lambda\approx 0.004$ and
$\lambda\approx 26\,300.6$, respectively. We now determine which eigenvalues in this range do not satisfy the
condition in Lemma~\ref{lemma:liyau3}, namely,
$$\lambda\geq\frac{2k-1}{h}\Leftrightarrow k-\fr{1}{2}\leq\lambda\frac{h}{2}.$$
As this condition is of the same type as that for Pólya's conjecture, we can use the same algorithm as
in Section~\ref{bounds} to computationally check these remaining cases, with the modified $k$-intervals

$$\tilde{I}_{m,n}^k:=\left\{h\in\mathds{R}^+ : k-\fr{1}{2} > m^2\frac{h}{2} + n^2\frac{\pi^2}{2h}\right\}.$$

Since
$$k\leq\frac{h}{2}\lambda+\frac{h}{\pi}\sqrt{\lambda}<130\,298$$
we only need to consider the first $130\,297$ eigenvalues. To compute this we need the following improvements to the previous algorithm:

\begin{enumerate}[i.]
    \item Calculating the $k$-intervals, we only need to consider eigenvalues $\lambda=m^2+n^2(\pi^2/h^2)$ which can be smaller than $26\,300.6$ in the range $h\in(\pi^2/2,\pi^2]$ since we are only interested in intersecting $k$-intervals if $\lambda_k\lesssim26\,300.65 \Rightarrow \lambda_1,\dots,\lambda_k\lesssim26\,300.6$. This means we can skip values of $m,n$ when
    $$m^2+n^2\frac{1}{\pi^2}>26\,301(>26\,300.6)$$
    \item Since $\lambda=m^2+n^2(\pi^2/h^2)$ and $\lambda\lesssim26\,300.6$, we only ever need to consider values for $m, n$ in the ranges
    \begin{align*}
    |m|&\leq\sqrt{\lambda}<163\\
    n&\leq(h/\pi)\sqrt{\lambda}\leq\pi\sqrt{\lambda}<510
    \end{align*}
\end{enumerate}

Running this version of the algorithm (details are given in Appedix~\ref{apx:impl2}) we obtain that the only eigenvalue orders which do not satisfy the condition in Lemma~\ref{lemma:liyau1} in the range
$h\in(\pi^2/2,\pi^2], \lambda < 26\, 301$ are $7,10,77$, and $86$.
This means that we only need to check that the Li-Yau's inequalities hold up to $k=86$. For any fixed value of $h$ we can easily compute the exact values of $\lambda_1,\dots,\lambda_{86}$. In fact, for a range of values $h\in[h_0,h_1]$ if there are no eigenvalue ``crossovers'' of the form

$$\lambda_i = m_i^2 + n_i^2\frac{\pi^2}{h^2}=m_j^2 + n_j^2\frac{\pi^2}{h^2} = \lambda_j$$
for some $h\in(h_0,h_1)$ with $i,j\leq86$ and $(|m_1|,n_1)\neq(|m_2|,n_2)$ then we can determine the exact expressions of $\lambda_1,\dots,\lambda_{86}$ as functions of $h$ since the order of these expressions never changes; to do this we can choose the value $h_M=(h_0+h_1)/2$, consider each expression $m^2 + n^2\frac{\pi^2}{h^2}$ evaluated at $h=h_M$ and order them based on their exact values.

To partition $(\pi^2/2, \pi^2]$ into intervals without ``crossovers'' we may compute all the intersections between eigenvalues as follows: for each $(|m_1|,n_1)\neq(|m_2|,n_2)$ such that $N(\lambda_{m_1,n_1}),N(\lambda_{m_2,n_2})\leq 86$ we add the point
\[
\begin{array}{lll}
    \lambda_{m_1,n_1} = \lambda_{m_2,n_2} & \Leftrightarrow & m_1^2 + n_1^2\fr{\pi^2}{h^2}=m_2^2 + n_2^2\frac{\pi^2}{h^2}\eqskip
    & \Leftrightarrow & h = \pi\sqrt{\frac{n_2^2-n_1^2}{m_1^2-m_2^2}}
\end{array}
\]
to a list and after we sort it to form the partition.

On each interval $[h_0,h_1]$ of the partition we can now compute the exact expressions of the sums $\lambda_1,\lambda_1+\lambda_2,\dots,\sum_{i=1}^{86}\lambda_i$ which will be of the form

$$\sum_{i=1}^{k}\lambda_i = \sum_{i=1}^{k}m_i^2+n_i^2\frac{\pi^2}{h^2}=a_k+b_k\frac{1}{h^2}$$
for some constants $a_k, b_k$. Finally, we determine for which values of $h$ the Li-Yau inequality holds
\[
\begin{array}{lll}
    \dsum_{i=1}^{k}\lambda_i=a_k+b_k\frac{1}{h^2}\geq\frac{k^2}{h} & \Leftrightarrow & a_k h^2-k^2 h + b_k\geq0 \eqskip
    & \Leftrightarrow & h \in
\begin{cases}
    \left(-\infty, \frac{b_k}{k^2}\right] &\text{if $a_k=0$}\eqskip
    \left(-\infty, \frac{k^2-\sqrt{k^4-4a_kb_k}}{2a_k}\right] \cup \left[\frac{k^2+\sqrt{k^4-4a_kb_k}}{2a_k}, \infty\right) &\text{if $a_k\neq0$}\eqskip
\end{cases}
\end{array}
\]
and check if this region covers all the interval $[h_0, h_1]$.


The algorithm described in Appendix \ref{apx:impl3} implements all the verification steps and running it confirms that indeed the Li-Yau inequalities are satisfied up to $k=86$ when $h\in(\pi^2/2,\pi^2]$ and $\lambda < 26\,301$. Since the condition in Lemma~\ref{lemma:liyau3} holds for all $k>86$ when $h\in(\pi^2/2,\pi^2]$ we conclude that Li-Yau inequalities are satisfied for any $k$ when $h\in(\pi^2/2,\pi^2]$ as intended, thus finishing
the proof of Corollary~\ref{cor-liyau}.


\section{Remarks for other domains\label{other}}

\subsection{Domains on the cylindrical surface $\mathbb{S}^{1}\times \R$}

If a domain $\Omega\subset \mathbb{S}^{1}\times \R$ contains a cylindrical strip $\ch$ for some value of $h$,
we then have
$
 \lambda_{k}\left(\Omega\right) \leq \lambda_{k}\left(\ch\right)
$
and, in particular, $\lambda_{1}\left(\Omega\right) \leq \lambda_{1}\left(\ch\right)=\pi^2/h^2$. Hence, if $h$
is such that
\[
\fr{\pi^2}{h^2} \leq \fr{4\pi}{\left|\Omega\right|},
\]
it follows that $\Omega$ does not satisfy P\'{o}lya's conjecture. On the other hand, one class of domains for
which the conjecture will be satisfied will be those tiling a strip $\ch$ which itself satisfies the conjecture
-- see~\cite{fms} for the corresponding argument, for instance.

We shall now specifically consider the geodesic disk $D_{R}$ of radius $R$ defined on the cylindrical surface $\mathbb{S}^1\times \R$, for which it is known that it satisfies P\'{o}lya's conjecture for $R$ up to $
\pi$~\cite{flps}, and provide an upper bound for the value of $R$ where this stops being the case. Note that
since the area of the domain $\Omega$ in the expression above also depends on $h$, to apply this type
of argument it is necessary to solve an equation in $h$. However, the resulting value of $R$ is approximately $6.85504$ and we will use another method to derive a better estimate.
\begin{thm}
There exists a value of $R$, say $R_{1}$, such that the geodesic disk $D_{R}$ on the cylinder $\mathbb{S}^{1}\times \R$
does not satisfy P\'{o}lya's conjecture for $R>R_{1}$. The constant $R_{1}$ may be taken to be $3.76085$.
\end{thm}
\begin{proof} We use the function
\[
 u(x,y) = \cos\left (\fr {\pi   y} {2\sqrt {R^2 - x^2}} \right)
\]
as a test function for the corresponding Rayleigh quotient to obtain an upper bound for the first eigenvalue on $D_{R}$.
For $R$ larger than or equal to $\pi$, we have
\[
\begin{array}{lll}
 \dint_{D_{R}} u^{2}(x,y)\, {\rm d}y{\rm d}x & = & \pi\sqrt {R^2 - \pi^2} +
   R^2\arctan\left (\fr{\pi} {\sqrt {R^2 - \pi^2}} \right)\eqskip
%    & = & \fr{1}{2} \left| D_{R} \right|,
\end{array}
\]
while
\[
\begin{array}{lll}
 \dint_{D_{R}} \left|\nabla u\right|^{2}(x,y)\, {\rm d}y{\rm d}x & = &
 \fr {1} {6}\left[\fr {\pi\left (6 + \pi^2 \right)} {\sqrt {R^2 - \pi^2}} + 2\left (\pi^2 - 3 \right)
      \arctan\left (\fr {\pi} {\sqrt {R^2 - \pi^2}} \right) \right].
\end{array}
\]
We thus obtain
\[
\begin{array}{lll}
 \lambda_{1}\left(D_{R}\right) & \leq &
 \fr{\dint_{D} \left|\nabla u\right|^{2}(x,y)\, {\rm d}y{\rm d}x}{\dint_{D} u^{2}(x,y)\, {\rm d}y{\rm d}x }\eqskip
 & = & \fr{\fr {\pi\left (6 + \pi^2 \right)} {\sqrt {R^2 -
 \pi^2}} + 2\left (\pi^2 - 3 \right)\arctan\left (\fr {\pi} {\sqrt {R^2 - \pi^2}} \right)} {6\left[\pi\sqrt {R^2 -
 \pi^2} + R^2\arctan\left (\fr{\pi} {\sqrt {R^2 - \pi^2}} \right) \right]}.
\end{array}
\]
Combining this expression with $4\pi/\left|D_{R}\right|$ we obtain that for values of $R$ larger
than $\pi$ for which the quantity on the right-hand side of the inequality
\[
\begin{array}{lll}
 \fr{4\pi}{\left|D_{R}\right|}-\lambda_{1}\left(D_{R}\right) & \geq &
 \fr{\pi\left (12\sqrt {R^2 - \pi^2} - \pi^2 - 6 \right) - 2\left (\pi^2 - 3 \right)\sqrt {R^2 - \pi^2}
 \arctan\left (\fr {\pi} {\sqrt {R^2 - \pi^2}} \right)} {6\left[ \pi (R^2 -\pi^2)  + \sqrt {R^2 - \pi^2}  R^2
 \arctan\left (\fr {\pi} {\sqrt {R^2 - \pi^2}}  \right) \right]}
\end{array}
\]
is positive, the first eigenvalue of $D_{R}$ does not satisfy P\'{o}lya's conjecture. It is readily seen that
the denominator above is positive for $R$ larger than $\pi$, and so the sign of the whole expression is given
by the sign of the numerator. This may, in turn, be written in the form
\[
 c_{1} w -c_{2} - c_{3}w\arctan\left({\fr{\pi}{w}}\right),
\]
where $w=\sqrt{R^2-\pi^2}$ and $c_{i}$, $i=1,2,3$ are positive constants. It is not difficult to see that (for
these values of the constants $c_{i}$) this is an increasing function of $w$, which is negative when $w$ vanishes
and goes to plus infinity with $w$. The given value for $R_{1}$ may be obtained by solving (numerically) the equation
resulting from equating the numerator above to zero.
\end{proof}

\subsection{Higher dimensions: some estimates for general cylinders\label{higher}} Although similar studies may be
carried out for more general cylinders such as those of the form $\mathbb{S}^{n}\times I_{h}$ and
$\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h_{j}}$, the corresponding analysis becomes much more involved and we
will thus focus on two aspects which we believe already provide a global illustration of what is to be expected. On the
one hand, it is relatively straightforward to consider again the first eigenvalue by itself and see when P\'{o}lya's
conjecture fails in this case. We expect that in the former case, namely $\mathbb{S}^{n}\times I_{h}$, the values of
$h$ where P\'{o}lya's conjecture breaks down for $\lambda_{1}$ will decrease with $n$, while in the latter case
increasing the dimension will allow for higher values of the indices $h_{j}$ for which P\'{o}lya's conjecture holds.

\subsubsection{$\mathbb{S}^{n}\times I_{h}$}

In this instance, Pólya's conjecture reads as
\begin{align*}
    N(\lambda)&\leq \lambda^{\frac{n+1}{2}}\frac{\omega_{n+1}}{(2\pi)^{n+1}}|\mathbb{S}^{n}\times I_{h}|\\
    &= \lambda^{\frac{n+1}{2}}\frac{(n+1)\omega_{n+1}^2}{(2\pi)^{n+1}} h\\
    &= \lambda^{\frac{n+1}{2}}\frac{n+1}{2^{n+1}\Gamma\left(\frac{n+3}{2}\right)^2} h,
\end{align*}
while the first Dirichlet eigenvalue is again given by
$$\lambda_1(\mathbb{S}^{n}\times I_{h})=\frac{\pi^2}{h^2}.$$
The conjecture fails for this eigenvalue when
\begin{align*}
    1&>\left(\frac{\pi^2}{h^2}\right)^{\frac{n+1}{2}}\frac{n+1}{2^{n+1}\Gamma\left(\frac{n+3}{2}\right)^2} h\\
    \Leftrightarrow h &>\pi^{1+\frac{1}{n}}\frac{(n+1)^{\frac{1}{n}}}{2^{1+\frac{1}{n}}\Gamma\left(\frac{n+3}{2}\right)^{\frac{2}{n}}}\\
    &=\frac{\pi}{2}\left(\frac{\pi(n+1)}{2 \Gamma\left(\frac{n+3}{2}\right)^2}\right)^{\frac{1}{n}},
\end{align*}
and we conclude
\begin{proposition}
Pólya's conjecture on $\mathbb{S}^{n}\times I_{h}$ does not hold for $h$ larger than
$$\eta_{1}(n)=\fr{\pi}{2}\left(\frac{\pi(n+1)}{2 \Gamma\left(\frac{n+3}{2}\right)^2}\right)^{\frac{1}{n}}\approx \fr{e \pi}{n}+
\bo\left(\fr{\log(n)}{n^2}\right), \mbox{ as } n\to\infty.$$
\end{proposition}
We thus see that, as $n$ increases, the value of $h$ for which Pólya's conjecture is satisfied will decrease. We
remark that, just like in the case where $n$ is one, there might still exist gaps in the interval $(0,\eta_{1}(n))$
where Pólya's conjecture is not satisfied, similar to those corresponding to $\lambda_8$ and $\lambda_{13}$
for $\SI$.

\subsubsection{$\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h_{j}}$}

P\'{o}lya's conjecture %on $\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h_{j}}$
now reads as
\begin{align*}
    N(\lambda)&\leq \lambda^{\frac{n+1}{2}}\frac{\omega_{n+1}}{(2\pi)^{n+1}}\left|\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h_{j}}\right|\\
    &= \lambda^{\frac{n+1}{2}}\frac{h_1h_2\cdots h_n}{(2\pi)^n} \omega_{n+1}\\
    &= \lambda^{\frac{n+1}{2}}\frac{h_1h_2\cdots h_n}{2^n\pi^{\frac{n-1}{2}}\Gamma\left(\frac{n+3}{2}\right)}
\end{align*}
We shall again consider the first Dirichlet eigenvalue, now given by
$$\lambda_1\left(\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h_{j}}\right)=\frac{\pi^2}{h_1^2}+\frac{\pi^2}{h_2^2}+\dots+\frac{\pi^2}{h_n^2},$$
and see that the conjecture fails for this eigenvalue when
\begin{align*}
    1&>\left(\frac{\pi^2}{h_1^2}+\frac{\pi^2}{h_2^2}+\dots+\frac{\pi^2}{h_n^2}\right)^{\frac{n+1}{2}}\frac{h_1h_2\cdots h_n}{2^n\pi^{\frac{n-1}{2}}\Gamma\left(\frac{n+3}{2}\right)}\\
    &=\left(h_1^{-2}+h_2^{-2}+\dots+h_n^{-2}\right)^{\frac{n+1}{2}}h_1h_2\cdots h_n\frac{\pi^{\frac{n+3}{2}}}{2^n\Gamma\left(\frac{n+3}{2}\right)}\\
    \Leftrightarrow \frac{\pi^{1/2}}{2}\left(\frac{2\pi}{\Gamma\left(\frac{n+3}{2}\right)}\right)^{\frac{1}{n+1}} &<\left(h_1^{-2}+h_2^{-2}+\dots+h_n^{-2}\right)^{-1/2}(h_1h_2\cdots h_n)^{-\frac{1}{n+1}}.
\end{align*}
We thus have
\begin{proposition}
    Pólya's conjecture on $\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h_{j}}$ may be safisfied only if
    $$\frac{\pi^{1/2}}{2}\left(\frac{2\pi}{\Gamma\left(\frac{n+3}{2}\right)}\right)^{\frac{1}{n+1}} \geq\left(h_1^{-2}+h_2^{-2}+\dots+h_n^{-2}\right)^{-1/2}(h_1h_2\cdots h_n)^{-\frac{1}{n+1}}$$
\end{proposition}

In the particular case of the Cartesian product of $\mathbb{S}^{1}$ with a hypercube of side length $h$, that is
$h_1=h_2=\dots=h_n=h$, this becomes
\begin{align*}
    \frac{\pi^{1/2}}{2}\left(\frac{2\pi}{\Gamma\left(\frac{n+3}{2}\right)}\right)^{\frac{1}{n+1}} &<\left(h_1^{-2}+h_2^{-2}+\dots+h_n^{-2}\right)^{-1/2}(h_1h_2\cdots h_n)^{-\frac{1}{n+1}}\\
    \Leftrightarrow \frac{\pi^{1/2}}{2}\left(\frac{2\pi}{\Gamma\left(\frac{n+3}{2}\right)}\right)^{\frac{1}{n+1}}&<n^{-1/2}h^{\frac{1}{n+1}}\\
    h &> \frac{n^{\frac{n+1}{2}}\pi^{\frac{n+3}{2}}}{2^n\Gamma\left(\frac{n+3}{2}\right)}
\end{align*}
and we get
\begin{corollary}
    Pólya's conjecture on $\mathbb{S}^{1}\times {\ds\prod_{j=1}^{n}} I_{h}$ does not hold if $h$ is larger than
    $$\fr{n^{\frac{n+1}{2}}\pi^{\frac{n+3}{2}}}{2^n\Gamma\left(\frac{n+3}{2}\right)}\approx
    \fr{ \pi}{\sqrt{2n} }\left(\fr{e \pi}{2}\right)^{n/2}+\bo\left(\fr{1}{n^{3/2}}\left(\fr{e \pi}{2}\right)^{n/2}\right), \mbox{ as } n\to\infty.$$
\end{corollary}
\noindent As $n$ increases the values of $h$ for which P\'{o}lya's conjecture may be satisfied increase, but again
there might still exist gaps in this interval where the conjecture fails.

In this instance, and because the Li-Yau inequalities hold for $\mathbb{S}^{1}\times I_{h}$ for $h$
in $(0,\pi^2]$, we may, in fact, conclude that the conjecture will hold provided the smallest of the $h_{i}$
is in this interval.
\begin{proposition} Let $n$ be an integer greater than or equal to three, and
 let $h_{i}$, $i=1,\dots,n$ be positive real numbers, and $h_{0} := \min\left\{h_{1},\dots,h_{n}\right\}$. If
 $h_{0} \in(0,\pi^2]$, then P\'{o}lya's conjecture holds for $\mathbb{S}^{1}\times{\ds\prod_{j=1}^{n}} I_{h}$.
\end{proposition}
\begin{proof}
 We write $\mathbb{S}^{1}\times{\ds\prod_{j=1}^{n}} I_{h}$ as the Cartesian product of
 $\mathbb{S}^{1}\times I_{h_{0}}$
 with the remaining product of intervals. Then, because the former domain satisfies the Li-Yau inequalities while
 the latter satisfies P\'{o}lya's inequality and is in $\R^{d}$ with $d$ greater than or equal to two, we may apply
 the argument of~\cite[Theorem 2.8]{lapt} for Cartesian products, from which the result follows.
\end{proof}
\begin{remark}
If $\mathbb{S}^{1}\times I_{h_{1}}$ satisfies P\'{o}lya's conjecture, we may conclude that
$\mathbb{S}^{1}\times I_{h_{1}}\times I_{h_{2}}$ also satisfies the conjecture.
\end{remark}


\appendix
\section*{Appendices}
The software package \textit{Mathematica} was chosen to run all the computational searches due to its algebraic manipulation capabilities. Below we present the code for each of the three algorithms
used, together with some brief descriptions.
\section{Intersection with $k-$intervals: satisfiability of P\'{o}lya's conjecture}
\label{apx:impl}
 The main idea for an efficient implementation of the search for $k$ intersecting $k-$intervals is algebraically sorting all left and right endpoints of every $k-$interval under consideration (roughly $2\times 10^9$ points) and traversing these from left to right. We then keep count of the number of $k-$intervals containing the current
 point, adding or subtracting one each time we pass a left endpoint or a right endpoint, respectively.
 The concrete implementation used is given below.

\begin{lstlisting}[language=Mathematica]
getKIntervals[k_] := 
 Module[{intstart, intend, ints, cnt, flag, start, kInts},
  intstart = Flatten[Table[
     If[x == 0,
      {y^2*Pi/(4 k), 1},
      If[k^2/Pi^2 >= x^2*y^2,
       {(k/Pi - Sqrt[k^2/Pi^2 - x^2*y^2])/(2*x^2), 2},
       Null
       ]]
     , {x, 0, k }, {y, 1, k}], 1];
  intend = Flatten[Table[
     If[x == 0,
      {Infinity, -1},
      If[k^2/Pi^2 >= x^2*y^2,
       {(k/Pi + Sqrt[k^2/Pi^2 - x^2*y^2])/(2*x^2), -2},
       Null
       ]
      ]
     , {x, 0, k }, {y, 1, k}], 1];
  ints = Join[intstart, intend] /. Null -> Sequence[];
  ints = NumericalSort[ints];
  cnt = 0;
  flag = True;
  kInts = {};
  start = -1;
  Do[
   cnt = cnt + pnt[[2]];
   If[cnt >= k && flag,
    start = pnt[[1]];
    flag = False;
    ,
    If[cnt < k && ! flag,
      AppendTo[kInts, {start, pnt[[1]]}];
      start = -1;
      flag = True;
      ];
    ]
   , {pnt, ints}];
  kInts
  ]

Do[Print[{i, Select[getKIntervals[i], #[[1]] < Pi/4 &]}], {i, 1, 1019}]
\end{lstlisting}

\section{Intersection with $k-$intervals: weaker condition}
Further improvements were needed due to the larger inputs: \verb|Join[]| was used instead of \verb|Flatten[]| and other ways to reduce the number of $k$-intervals were implemented (described in Section \ref{liyau-sec}).

The search space is
\begin{itemize}
    \item $\lambda < 26\,301$
    \item $k \leq 130\, 298$
    \item $|m| \leq 162$
    \item $n \leq 509$
\end{itemize}

\label{apx:impl2}
\begin{lstlisting}[language=Mathematica]
getKIntervalsRelaxed[k_, low_, high_] := 
 Module[{val, int1, int2, int4, ints, cnt, flag, start, kInts},
  cnt = 0;
  int1 = Array[
    Function[y,
     val = y^2*Pi^2/(2 (k-1/2));
     If[val < low,
      cnt = cnt + 1; Null,
      If[val <= high,
       {val, 1},
       Null]
      ]]
    , 509];
  int2 = Join @@ Array[
     Function[{x, y},
      If[(k-1/2)^2 < x^2*y^2*Pi^2 || x^2 + y^2/Pi^2 > 26301,
       Null,
       val = ((k-1/2) - Sqrt[(k-1/2)^2 - x^2*y^2*Pi^2])/(x^2);
       If[val < low,
        cnt = cnt + 2; Null,
        If[val <= high,
         {((k-1/2) - Sqrt[(k-1/2)^2 - x^2*y^2*Pi^2])/(x^2), 2},
         Null
         ]
        ]
       ]
      ]
     , {162 , 509}];
  int4 = Join @@ Array[
     Function[{x, y},
      If[(k-1/2)^2 < x^2*y^2*Pi^2 || x^2 + y^2/Pi^2 > 26301,
       Null,
       val = ((k-1/2) + Sqrt[(k-1/2)^2 - x^2*y^2*Pi^2])/(x^2);
       If[val < low,
        cnt = cnt - 2; Null,
        If[val <= high,
         {((k-1/2) + Sqrt[(k-1/2)^2 - x^2*y^2*Pi^2])/(x^2), -2},
         Null
         ]
        ]
       ]
      ]
     , {162 , 509}];
  ints = (Join @@ {{{low, 0}}, int1, int2, 
       int4, {{high, -Infinity}}}) /. Null -> Sequence[];
  ints = NumericalSort[ints];
  flag = True;
  kInts = {};
  start = -1;
  Do[
   cnt = cnt + pnt[[2]];
   If[cnt >= k && flag,
    start = pnt[[1]];
    flag = False;
    ,
    If[cnt < k && ! flag,
      AppendTo[kInts, {start, pnt[[1]]}];
      start = -1;
      flag = True;
      ];
    ]
   , {pnt, ints}];
  kInts
  ]

Do[Print[{i, getKIntervals2[i, Pi^2/2, Pi^2]}], {i, 1, 130298}]
\end{lstlisting}

\section{Algorithm to check the Li-Yau inequalities}
\label{apx:impl3}
As described in Section~\ref{liyau-sec}, to check the Li-Yau inequalities we first compute all the intersections between eigenvalues (as functions of $h$) and sort them to form a partition of $(\pi^2/2,\pi^2]$. Then for each interval we calculate the exact values for the first $k=86$ eigenvalues and determine if Li-Yau is satisfied for the whole interval.

\begin{lstlisting}[language=Mathematica]
liYauInRange[k_, h0_, h1_] := 
 Module[{poi, ioi, ibeg, iend, hi, eigs, sm, sn, res},
  poi = Flatten[Table[
      If[Or[And[y1 > y0, x1 < x0], And[y1 < y0, x1 > x0]], 
       Sqrt[(y1^2 - y0^2)/(x0^2 - x1^2)]*Pi]
      , {x0, 0, 9 }, {y0, 1, 28}, {x1, 0, 9}, {y1, 0, 28}], 3] /. 
    Null -> Sequence[];
  poi = DeleteDuplicates[poi];
  poi = Table[
     If[And[v > h0, v < h1], v]
     , {v, poi}] /. Null -> Sequence[];
  PrependTo[poi, h0];
  AppendTo[poi, h1];
  poi = NumericalSort[poi];
  ioi = Table[{poi[[i]], poi[[i + 1]]}, {i, 1, Length[poi] - 1}];
  res = {};
  Do[
   ibeg = hh[[1]];
   iend = hh[[2]];
   hi = (ibeg + iend)/2;
   eigs = 
    Join @@ Table[{x^2 + y^2*Pi^2/hi, {x, y}}, {x, -9, 9}, {y, 1, 28}];
   eigs = NumericalSort[eigs];
   sm = 0; sn = 0;
   Do[
    sm = sm + eigs[[ki]][[2]][[1]]^2;
    sn = sn + Pi^2*eigs[[ki]][[2]][[2]]^2;
    If[sm == 0,
     If[iend > sn/(ki^2),
      AppendTo[res, {hh, ki}]
      ]
     ,
     If[ki^4 >= 4*sm*sn,
      If[(ki^2 + Sqrt[ki^4 - 4*sm*sn])/(2*sm) > 
         ibeg && (ki^2 - Sqrt[ki^4 - 4*sm*sn])/(2*sm) < iend,
       AppendTo[res, {hh, ki}]
       ]
      ]
     ];
    , {ki, 1, k}];
   , {hh, ioi}];
  res
  ]

liYauInRange[86, Pi^2/2, Pi^2]
\end{lstlisting}

