 (Wathen, 2, (820.9979833608267, 250042.0))
 (Wathen, 3, (1710.2298321182072, 251292.0))
 (Wathen, 4, (2579.9152224400186, 250083.0))
 (Pascal, 1, (1, 250958.0))
 (Pascal, 2, (5, 240958.0))
 (Pascal, 3, (19, 236167.0))
 (Pascal, 4, (69, 236583.0))
 (Minij, 1, (1, 235500.0))
