        \pgfmathsetmacro{\gval}{min(max(4*\normvalue - 0.5, 0), 1) - min(max(4*\normvalue - 2.5, 0), 1)}
        \pgfmathsetmacro{\bval}{1 - min(max(4*\normvalue - 1, 0), 1)}

        \definecolor{cellcolor}{rgb}{\rval,\gval,\bval};
        \fill[cellcolor] (\j,-\i) rectangle (\j+1,-\i-1);
      }
    }

    % Labels
    \foreach \i in {0,...,\matrixsize} {
      \node[xshift=0.375cm,yshift=0.25cm] at  (\i,0) {\i};
