\begin{thm} \label{functorF}
The map $F: \mathbf{OTa} \to \mathbf{LWeb}$ sending each object to itself and  sending any oriented $(\epsilon, \nu)$-tangle diagram $T$ to
$$\sum_{i=1}^{2^n} b_i \Gamma_i  + \langle N_1(\epsilon, \nu), N_2(\epsilon, \nu), N_3(\epsilon, \nu)\rangle,$$ where the $\Gamma_i$'s are the enumerated resolutions of tangle $T$ (as $(\epsilon, \nu)$-webs) and each $b_i$ is computed as explained in Fig~\ref{rule}, is a tensor-product-preserving functor.
\end{thm}

\begin{proof}


Since we have presentations for the categories $\mathbf{OTa}$ and $ \mathbf{LWeb}$ we can use Theorem ~\ref{genrel} to define a functor,
$\phi: \mathbf{OTa} \to \mathbf{LWeb},$ by requiring the following assignment on generators 
 \begin{align*}
         \raisebox{-6pt}{\includegraphics[scale = 0.4]{u-.pdf}} &\mapsto  \raisebox{-6pt} {\includegraphics[scale = 0.4]{u-.pdf} }&& \raisebox{-6pt}{\includegraphics[scale = 0.4]{u+.pdf}} \mapsto    \raisebox{-6pt}{\includegraphics[scale = 0.4]{u+.pdf}}\\
         \raisebox{-6pt}{\includegraphics[scale = 0.4]{n-.pdf}} &\mapsto    \raisebox{-6pt}{\includegraphics[scale = 0.4]{n-.pdf} }&& \raisebox{-6pt}{\includegraphics[scale = 0.4]{n+.pdf}} \mapsto    \raisebox{-6pt}{\includegraphics[scale = 0.4]{n+.pdf}}\\
          \raisebox{-9pt}{\includegraphics[scale = 0.4]{Pcross2.pdf}} &\mapsto  q^2 \raisebox{-9pt}{\includegraphics[scale = 0.4]{Vertbarup.pdf}} - q^3 \raisebox{-9pt}{\includegraphics[scale = 0.4]{Fcross2.pdf}} 
          &&\raisebox{-9pt}{\includegraphics[scale = 0.4]{Ncross2.pdf}} \mapsto   q^{-2} \raisebox{-9pt}{\includegraphics[scale = 0.4]{Vertbarup.pdf}} - q^{-3} \raisebox{-9pt}{\includegraphics[scale = 0.4]{Fcross2.pdf}}.\\       
    \end{align*}
To make sure that Theorem ~\ref{genrel} applies we must show that the relations of $\mathbf{OTa}$  still hold when taken through $\phi$. We will demonstrate why relations $(e_+)$, $(c)$ and $(b)$ in Theorem ~\ref{tanglerelations} hold in $\mathbf{LWeb}$. The other relations can be verified in a similar manner.


For the relation $(e_+)$, we wish to show that $\displaystyle{\phi \left(\raisebox{-7pt}{\includegraphics[height=.25in]{f1.pdf}} \right)  =  \phi\left( \raisebox{-7pt}{\includegraphics[height=.25in]{f2.pdf}} \right)}$. By the definition of $\phi$ note that we have the following:
$$ \phi \left(\raisebox{-15pt}{\includegraphics[height=.5in]{f1.pdf}} \right)  = q^2\raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-2.pdf}}  -q^3 \raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-1.pdf}}= q^2\raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-2.pdf}}  -q^3 \raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-3.pdf}} .$$

By the relations imposed on the morphisms of $\mathbf{LWeb}$ from quotienting by $N_1(\epsilon, \nu)$ and $N_2(\epsilon, \nu)$, we have
$$\raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-3.pdf}} = (q+q^{-1}) \raisebox{-15pt}{\includegraphics[height=.5in]{a2+.pdf}} \text{ and } \raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-2.pdf}} = (q^2 +1 +q^{-2}) \raisebox{-15pt}{\includegraphics[height=.5in]{a2+.pdf}}.
$$
Hence,
\[
q^2\raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-2.pdf}}  -q^3 \raisebox{-15pt}{\includegraphics[height=.5in]{Eq1-3.pdf}} = q^2(q^2 + 1 + q^{-1})\raisebox{-15pt}{\includegraphics[height=.5in]{a2+.pdf}} -q^{3} (q+q^{-1}) \raisebox{-15pt}{\includegraphics[height=.5in]{a2+.pdf}}
= \raisebox{-15pt}{\includegraphics[height=.5in]{a2+.pdf}} = \phi \left( \raisebox{-15pt}{\includegraphics[height=.5in]{a2+.pdf}}\right).
\]

Therefore, $\phi$ preserves relation $(e_+)$. To prove that $\phi$ preserves relation $(c)$, we need to show that 
$$\phi(X_+ \circ X_-) = \phi(X_- \circ X_+)  = \phi(I_+ \otimes I_+) = I_+ \otimes I_+ = I_{(+, +)}.$$
By definition, we require that $\phi$ preserves composition. Hence,
\begin{align*}
\phi(X_+ \circ X_-) &= \phi(X_+) \circ \phi( X_-)\\
&= \left(q^{2}\mychar{Vertbarup.pdf} - q^3\mychar{Fcross2.pdf} \right)\circ \left(q^{-2}\mychar{Vertbarup.pdf} - q^{-3}\mychar{Fcross2.pdf} \right)\\
&= \mychar{Vertbarup.pdf}\circ\mychar{Vertbarup.pdf} - q\mychar{Fcross2.pdf}\circ\mychar{Vertbarup.pdf} - q^{-1}\mychar{Vertbarup.pdf}\circ\mychar{Fcross2.pdf} + \mychar{Fcross2.pdf}\circ  \mychar{Fcross2.pdf}\\
&= \mychar{Vertbarup.pdf} - q\mychar{Fcross2.pdf} - q^{-1}\mychar{Fcross2.pdf} + \raisebox{-7pt}{\includegraphics[height=.35in]{Eq2-1.pdf}}\\
&= \mychar{Vertbarup.pdf} - (q+q^{-1})\mychar{Fcross2.pdf} + (q+q^{-1})\mychar{Fcross2.pdf}\\
&= \mychar{Vertbarup.pdf} = I_{(+, +)}.
\end{align*}
The proof showing that $\phi(X_- \circ X_+) =  I_{(+, +)}$ is done in a similar way, and thus we omit it to avoid repetition.
%Additionally, we have 
%\begin{align*}
%	\phi(X_+ \circ X_-) &= \left(q^{2}\mychar{Vertbarup.pdf} - q^3\mychar{Fcross2.pdf} \right)\circ \left(q^{-2}\mychar{Vertbarup.pdf} - q^{-3}\mychar{Fcross2.pdf} \right) \\
%	&= \mychar{Vertbarup.pdf}\circ\mychar{Vertbarup.pdf} - q\mychar{Fcross2.pdf}\circ\mychar{Vertbarup.pdf} - q^{-1}\mychar{Vertbarup.pdf}\circ\mychar{Fcross2.pdf} + \mychar{Fcross2.pdf}\circ  \mychar{Fcross2.pdf}\\
%	&= \left(q^{-2}\mychar{Vertbarup.pdf} - q^{-3}\mychar{Fcross2.pdf} \right) \circ \left(q^{2}\mychar{Vertbarup.pdf} - q^3\mychar{Fcross2.pdf} \right) = \phi(X_- \circ X_+).\\
%\end{align*} 
%So we have $\phi(X_+ \circ X_-) = \phi(X_- \circ X_+) =  I_{(+, +)}$, and thus $\phi$ preserves relation $(c)$. 


To verify that the functor $\phi$ preserves relation $(d)$, we need  to show the following:
$$\phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+) = \phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+). $$

By using the definition of the functor $\phi$ on the generators of the category $\mathbf{OTa}$, we obtain the following: 
\begin{align*}
	&\phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)\\
	&= \left(q^{2}\mychar{a2+}\mychar{a2+}\mychar{a2+} - q^3\mychar{Fcross2.pdf}\mychar{a2+} \right)\circ \left(q^{2}\mychar{a2+}\mychar{a2+}\mychar{a2+} - q^{3}\mychar{a2+}\mychar{Fcross2.pdf} \right) \left(q^{2}\mychar{a2+}\mychar{a2+}\mychar{a2+} - q^3\mychar{Fcross2.pdf}\mychar{a2+} \right)\\
	&= q^{6}\mychar{a2+}\mychar{a2+}\mychar{a2+} - q^7\mychar{Fcross2.pdf}\mychar{a2+} - q^7\mychar{a2+}\mychar{Fcross2.pdf} + q^8 \raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-2r.pdf}}
	-  q^7\mychar{Fcross2.pdf}\mychar{a2+} + q^8\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-3.pdf}}\\
	&+q^8 \raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-2.pdf}}-
	q^9\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-1.pdf}}. 
\end{align*}

Similarly, we have:
\begin{align*}
	& \phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)\\
	&= q^{6}\mychar{a2+}\mychar{a2+}\mychar{a2+} - q^7\mychar{a2+}\mychar{Fcross2.pdf} - q^7\mychar{Fcross2.pdf}\mychar{a2+} + q^8 \raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-2.pdf}}
	-  q^7\mychar{a2+}\mychar{Fcross2.pdf} + q^8\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-3r.pdf}}\\
	& + q^8 \raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-2r.pdf}}
	- q^9\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-1r.pdf}}.
\end{align*}

Now subtracting $\phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)$ from  $\phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)$, we get:
$$-  q^7\mychar{Fcross2.pdf}\mychar{a2+} + q^8\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-3.pdf}}-  q^9\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-1.pdf}} - \left( 	-  q^7\mychar{a2+}\mychar{Fcross2.pdf} + q^8\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-3r.pdf}}
- q^9\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-1r.pdf}} \right).$$
By using the digon relation imposed on $\mathbf{LWeb}$, we get 
  $$-  q^7\mychar{Fcross2.pdf}\mychar{a2+} + q^8\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-3.pdf}} = -  q^7\mychar{Fcross2.pdf}\mychar{a2+} + q^8(q + q^{-1})\mychar{Fcross2.pdf}\mychar{a2+} = q^9\mychar{Fcross2.pdf}\mychar{a2+}.$$
  Similarly, 
 $$-  q^7\mychar{a2+}\mychar{Fcross2.pdf} + q^8\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-3r.pdf}} = -  q^7\mychar{a2+}\mychar{Fcross2.pdf} + q^8(q + q^{-1})\mychar{a2+}\mychar{Fcross2.pdf} = q^9\mychar{a2+}\mychar{Fcross2.pdf}.$$

 This then simplifies the difference $\phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+) - \phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)$ to 
$$ q^9\mychar{Fcross2.pdf}\mychar{a2+} -  q^9\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-1.pdf}} -	 q^9\mychar{a2+}\mychar{Fcross2.pdf} 
+ q^9\raisebox{-6pt}{\includegraphics[scale = 0.4]{Eq3-1r.pdf}}.  \\ $$
Then, since
$$\raisebox{-16pt}{\includegraphics[height = 1.5cm]{Eq3-1.pdf}} \text{ is isotopic to } \raisebox{-16pt}{\includegraphics[height = 1.5cm]{Eq3-4.pdf}},$$
we can use the relation imposed on $\mathbf{Lweb}$ by quotienting the morphisms by $N_3(\epsilon, \nu)$, to obtain the following:
$$q^9\raisebox{-9pt}{\includegraphics[scale = 0.4]{Eq3-1.pdf}} = q^9\mychar{Fcross2.pdf}\mychar{a2+} +  q^9\raisebox{-9pt}{\includegraphics[scale = 0.3]{Eq3-5.pdf}},$$
$$q^9\raisebox{-9pt}{\includegraphics[scale = 0.4]{Eq3-1r.pdf}} = q^9\mychar{a2+}\mychar{Fcross2.pdf} +  q^9\raisebox{-9pt}{\includegraphics[scale = 0.3]{Eq3-5r.pdf}}.$$

Hence, 
\begin{align*}
	&\phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+) - \phi(I_+ \otimes X_+)\circ \phi(X_+ \otimes I_+)\circ\phi(I_+ \otimes X_+) \\
	&= q^9\mychar{Fcross2.pdf}\mychar{a2+} -  q^9\raisebox{-9pt}{\includegraphics[scale = 0.4]{Eq3-1.pdf}} -	 q^9\mychar{a2+}\mychar{Fcross2.pdf} 
	+ q^9\raisebox{-9pt}{\includegraphics[scale = 0.4]{Eq3-1r.pdf}}  \\
	&= q^9\mychar{Fcross2.pdf}\mychar{a2+} -   q^9\mychar{Fcross2.pdf}\mychar{a2+} -  q^9\raisebox{-6pt}{\includegraphics[scale = 0.3]{Eq3-5.pdf}}-	 q^9\mychar{a2+}\mychar{Fcross2.pdf} 
	+  q^9\mychar{a2+}\mychar{Fcross2.pdf} +  q^9\raisebox{-9pt}{\includegraphics[scale = 0.3]{Eq3-5r.pdf}}  \\
	&= q^9\raisebox{-9pt}{\includegraphics[scale = 0.3]{Eq3-5.pdf}} - q^9\raisebox{-9pt}{\includegraphics[scale = 0.3]{Eq3-5r.pdf}} = 0,
\end{align*}
where the last equality holds since the two webs are planar isotopic. Therefore, the functor $\phi$ preserves relation (d).

It remains to show that $F = \phi$. However, first we will modify notation. Let $T$ be any tangle diagram, we may request $T$ to be in general position. Then, if we order the crossings $(v_1, \ldots, v_n)$ in $T$ from top to bottom, there is a unique resolution of $T$ for any element of $\{0,1\}^n$. More explicitly, any element $(a_1, \ldots, a_n) \in \{0,1\}^n$ corresponds to the resolution of $T$ that takes the $jth$ crossing to $\mychar{Vertbarup.pdf}$ if $a_j = 0$ and to $\mychar{Fcross2.pdf}$ if $a_j = 1$. If we denote this resolution as $\Gamma_{(a_1, \ldots, a_n)}$ and similarly, we denote the coefficient associated with this resolution as $b_{(a_1, \ldots, a_n)}$, where the coefficient is determined by the rules in Fig.~\ref{rule}, then we may rewrite 
$$F(\Gamma) = \sum_{\alpha \in \{0,1\}^n} b_\alpha \Gamma_\alpha.$$

We need to show that $F(T) = \phi(T)$ for any $T \in \mathbf{OTa}$, and we prove this by induction on the number of crossings of $T$. 


\noindent
\textbf{Base Case:} If $T$ has zero crossings, then both $F(T) = T$ and $\phi(T) = T$, since we can regard $T$ as a web with no vertices. 


\noindent
\textbf{Inductive Step:} Suppose that $F(A) = \phi(A)$ for all $A \in \mathbf{OTa}$ that have less than $n$ crossings. Let $T$ be any tangle diagram with $n$ crossings. Then by Lemma ~\ref{generalform}, there exists generators $W_1, W_2,\ldots, W_m$, such that
\[ T= (I_{v_1}\otimes W_1 \otimes I_{u_1})\circ (I_{v_2}\otimes W_2 \otimes I_{u_2}) \circ \ldots \circ (I_{v_n}\otimes W_n \otimes I_{u_m}),\]
where the $v_i$'s and $u_i's$ are objects in $\mathbf{OTa}$. Let $k$ be the lowest number such that $W_k = X_+$ or $X_-$. Then we can write
\[ T = T' \circ (I_{v_{k}}\otimes W_k \otimes I_{u_{k}}) \circ T'',\]
where 
\[T' := (I_{v_1}\otimes W_1 \otimes I_{u_1})\circ \ldots \circ  (I_{v_{k-1}}\otimes W_{k-1} \otimes I_{u_{k-1}})\]
and 
\[T'' := (I_{v_{k+1}}\otimes W_{k+1} \otimes I_{u_{k+1}}) \circ \ldots \circ (I_{v_m}\otimes W_m \otimes I_{u_m}).\]
 That is, $T'$ has no crossings and $T''$ has $n-1$ crossings. Then we have 
\begin{align*}
F(T) &= \sum_{\alpha \in \{0,1\}^n} b_\alpha \Gamma_\alpha\\
&= \sum_{\alpha \in \{0\}\times\{0,1\}^{n-1}} b_\alpha \Gamma_\alpha + \sum_{\alpha \in \{1\}\times\{0,1\}^{n-1}} b_\alpha \Gamma_\alpha \\
&= \sum_{\alpha \in \{0,1\}^{n-1}} b_{(0\otimes \alpha)} \Gamma_{(0\otimes\alpha)} + \sum_{\alpha \in \{0,1\}^{n-1}} b_{(1 \otimes \alpha)} \Gamma_{(1 \otimes \alpha)}.
\end{align*}
Without loss of generality, let $W_k = X_+$. Then we have 
\begin{align*}
F(T) & =\sum_{\alpha \in \{0,1\}^{n-1}} b_{(0\otimes \alpha)} \Gamma_{(0\otimes\alpha)} + \sum_{\alpha \in \{0,1\}^{n-1}} b_{(1 \otimes \alpha)} \Gamma_{(1 \otimes \alpha)}\\
&= \sum_{\alpha \in \{0,1\}^{n-1}} q^2b_{\alpha}(T' \circ (I_{v_{k}}\otimes \mychar{Vertbarup.pdf} \otimes I_{u_{k}}) \circ \Gamma'')_{(0 \otimes \alpha)} \\
&- \sum_{\alpha \in \{0,1\}^{n-1}} q^3b_{ \alpha} (T' \circ (I_{v_{k}}\otimes \mychar{Fcross2.pdf}\otimes I_{u_{k}}) \circ \Gamma'')_{(1 \otimes \alpha)}\\
&= \sum_{\alpha \in \{0,1\}^{n-1}} q^2b_{\alpha}T' \circ (I_{v_{k}}\otimes \mychar{Vertbarup.pdf} \otimes I_{u_{k}}) \circ \Gamma''_{\alpha} \\
&- \sum_{\alpha \in \{0,1\}^{n-1}} q^3b_{\alpha}T' \circ (I_{v_{k}}\otimes \mychar{Fcross2.pdf} \otimes I_{u_{k}}) \circ \Gamma''_{\alpha},
\end{align*}
where $\Gamma''_{\alpha}$ are the $2^{n-1}$ resolutions of the tangle $T''$ containing $n-1$ crossings.

Using that composition is bilinear in $\mathbf{LWeb}$, we can rewrite the above sum as follows:
\begin{align*}
F(T) &= T' \circ(I_{v_{k}}\otimes q^2\mychar{Vertbarup.pdf} \otimes I_{u_{k}}) \circ \left( \sum_{\alpha \in \{0,1\}^{n-1}} b_{\alpha}  \Gamma''_{\alpha} \right)\\
&- T' \circ(I_{v_{k}}\otimes q^3\mychar{Fcross2.pdf} \otimes I_{u_{k}}) \circ \left(\sum_{\alpha \in \{0,1\}^{n-1}} b_{\alpha}  \Gamma''_{\alpha} \right)\\
&= T' \circ(I_{v_{k}}\otimes (q^2\mychar{Vertbarup.pdf} - q^3\mychar{Fcross2.pdf}) \otimes I_{u_{k}}) \circ \left( \sum_{\alpha \in \{0,1\}^{n-1}} b_{\alpha}  \Gamma''_{\alpha} \right)\\
&= F(T') \circ(I_{v_{k}}\otimes \phi(X_+) \otimes I_{u_{k}}) \circ F(T'').
\end{align*}
By the base case and inductive hypothesis, $\phi(T') = F(T')$ and  $\phi(T'') = F(T'')$. Moreover, by the functoriality of $\phi$, we obtain the following: 
$$F(T) =\phi(T') \circ (I_{v_{k}}\otimes \phi(X_+) \otimes I_{u_{k}}) \circ \phi(T'') = \phi(T' \circ (I_{v_{k}}\otimes X_+ \otimes I_{u_{k}}) \circ T'') = \phi(T).$$ 
Thus, the inductive step holds so by the principle of induction, $F = \phi$ and thus $F$ is a tensor-product-preserving functor. 
\end{proof}


