The verification theorem is stated as follows. To circumvent the technical complications arising from verifying convergence under the localization procedure for the Itô integral, we restrict our analysis to the class of bounded value functions—an assumption justified by the boundedness of the utility functions.

\begin{theorem}[Verification Theorem]
\label{thm:averi}
Let \( V \) be the solution to the Hamilton-Jacobi-Bellman equation \eqref{V_pb}, as characterized in Theorem~\ref{thm:V}. If \( V \) is bounded on \( \RR_T \), then it coincides with the value function of the optimal consumption-investment problem \eqref{value}.

Furthermore, let \( x^*(t,h) \) denote the optimal switching boundary defined in Theorem~\ref{thm:h}, and consider the controlled process \( \{(X^*_s, H^*_s, \Pi^*_s, C^*_s)\}_{t \leq s \leq T} \) governed by the following system:
\[
\left\{
\begin{array}{ll}
\mathrm{d} X^*_s = \big[r (X^*_s - \Pi^*_s) + \mu \Pi^*_s - C^*_s\big]\, \mathrm{d}s + \sigma \Pi^*_s\, \mathrm{d}W_s, \quad t \leq s \leq T, \\[1mm]
H^*_s = (x^*)^{-1}(s,\cdot)\left( \max\left\{ x^*(s,h),\; \max_{t \leq \theta \leq s} X^*_\theta \right\} \right), \\[1mm]
\Pi^*_s = \pi^*(X^*_s, s, H^*_s), \\[1mm]
C^*_s = c^*(X^*_s, s, H^*_s),
\end{array}
\right.
\]
where \( (x^*)^{-1}(s,\cdot) \) denotes the inverse function of \( x^*(s,\cdot) \), and the feedback control functions \( \pi^* \) and \( c^* \) are defined in \eqref{pi*} and \eqref{c*}, respectively. Then the strategy \( \{(\Pi^*_s, C^*_s)\}_{t \leq s \leq T} \) is optimal for Problem~\eqref{value}.
\end{theorem}

\begin{proof}
Let \( \widetilde{V}(x,t,h) \) denote the value function defined in \eqref{value}, and let \( V(x,t,h) \) be the solution to the PDE \eqref{V_pb}. We aim to prove that \( V(x,t,h) = \widetilde{V}(x,t,h) \).

Fix any \( (x,t,h) \in \mathbb{R}^+ \times [0,T) \times \mathbb{R}^+ \), and let \( \{(\Pi_s, C_s)\}_{t \leq s \leq T} \) be any admissible strategy. Define
\[
H_s = \max\left\{ h,\; \max_{t \leq \theta \leq s} C_\theta \right\}, \quad s \geq t,
\]
and let \( \{X_s\}_{s \geq t} \) be the solution to the wealth equation \eqref{Xt}.
For each \( n \in \mathbb{N} \), define the stopping time
\[
\tau_n := \inf \left\{ s \in [t, T] \;\middle|\; X_s + |\Pi_s| + |H_s| > n \text{ or } X_s < \frac{b h}{r} (1 - e^{-r(T - t)}) + \frac{1}{n} \right\}.
\]
Applying It\^o formula to \( V(X_s, s, H_s) \) on \( [t, \tau_n \wedge T] \) yields:
\begin{align*}
& V(x,t,h) =\mathbb{E} \left[ e^{-\rho(\tau_n \wedge T - t)} V(X_{\tau_n \wedge T}, \tau_n \wedge T, H_{\tau_n \wedge T}) \right] \\
& - \mathbb{E} \left[ \int_t^{\tau_n \wedge T} e^{-\rho(s - t)} \left( -V_t - \frac{1}{2} \sigma^2 \Pi_s^2 V_{xx} - (\mu - r) \Pi_s V_x + V_x C_s - r X_s V_x + \rho V \right)(X_s,s,H_s)\, \mathrm{d}s \right] \\
& - \mathbb{E} \left[ \int_t^{\tau_n \wedge T} e^{-\rho(s - t)} V_h(X_s,s,H_s)\, \mathrm{d}H_s \right] \\
& - \mathbb{E} \left[ \int_t^{\tau_n \wedge T} e^{-\rho(s - t)} \sigma \Pi_s V_x(X_s,s,H_s)\, \mathrm{d}W_s \right].
\end{align*}

The last term vanishes in expectation due to the integrability and boundedness of the integrand. From the variational inequality satisfied by \( V \), we have:
\begin{align*}
&\left( -V_t - \frac{1}{2} \sigma^2 \Pi_s^2 V_{xx} - (\mu - r) \Pi_s V_x + V_x C_s - r X_s V_x + \rho V \right)(X_s,s,H_s) \\
&\quad \geq \sup_{\pi, c} \left\{ -V_t - \frac{1}{2} \sigma^2 \pi^2 V_{xx} - (\mu - r) \pi V_x - r X_s V_x + \rho V - (U(c) - c V_x) \right\} + U(C_s) \\
&\quad \geq U(C_s),
\end{align*}
and since \( \mathrm{d}H_s \geq 0 \), we have \( -V_h(X_s,s,H_s) \mathrm{d}H_s \leq 0 \).
Hence,
\[
V(x,t,h) \geq \mathbb{E} \left[ \int_t^{\tau_n \wedge T} e^{-\rho(s - t)} U(C_s)\, \mathrm{d}s \right] + \mathbb{E} \left[ e^{-\rho(\tau_n \wedge T - t)} V(X_{\tau_n \wedge T}, \tau_n \wedge T, H_{\tau_n \wedge T}) \right].
\]
Since \( V \) is bounded, the dominated convergence theorem implies
\[
V(x,t,h) \geq \mathbb{E} \left[ \int_t^T e^{-\rho(s - t)} U(C_s)\, \mathrm{d}s + e^{-\rho(T - t)} U_T(X_T) \right].
\]
Because \( (\Pi_s, C_s) \) is arbitrary, we conclude \( V(x,t,h) \geq \widetilde{V}(x,t,h) \).

To establish the reverse inequality, consider the feedback strategy \( (\Pi^*_s, C^*_s) \) defined in the theorem. By construction,
\[
X^*_s \leq x^*(s, H^*_s), \quad \forall s \in [t, T],
\]
and the HJB equation holds with equality:
\[
\left( -V_t - \frac{1}{2} \sigma^2 (\Pi^*_s)^2 V_{xx} - (\mu - r) \Pi^*_s V_x + V_x C^*_s - r X^*_s V_x + \rho V \right)(X^*_s, s, H^*_s) = U(C^*_s).
\]
Moreover, since
\[
\mathrm{d}H^*_s = 0 \quad \text{if } X^*_s < x^*(s, H^*_s), \qquad V_h(X^*_s, s, H^*_s) = 0 \quad \text{if } X^*_s = x^*(s, H^*_s),
\]
it follows that
\[
-V_h(X^*_s, s, H^*_s)\, \mathrm{d}H^*_s = 0, \quad \forall s \in [t, T].
\]
Substituting into Itô’s formula and passing to the limit yields
\[
V(x,t,h) = \mathbb{E} \left[ \int_t^T e^{-\rho(s - t)} U(C^*_s)\, \mathrm{d}s + e^{-\rho(T - t)} U_T(X^*_T) \right] = \widetilde{V}(x,t,h).
\]
Thus, \( V = \widetilde{V} \), and the feedback strategy \( (\Pi^*_s, C^*_s) \) is indeed optimal.
\end{proof}

\section{Simplification of the Equation}\label{sec:S}
\setcounter{equation}{0}

To analyze the fully nonlinear three-dimensional variational inequality \eqref{V_pb}, we apply a dual transformation that reduces the problem to a linear obstacle problem \eqref{w_pb}. In this reformulation, the variable $h$ is treated as a parameter, thereby reducing \eqref{w_pb} to a two-dimensional problem. As a result, classical PDE methods can be employed to study both the solution and the associated free boundary.

Throughout this procedure, various a priori estimates on the solution will be used. We will rigorously establish the existence of solutions to Problem \eqref{w_pb}, and in Section~\ref{sec:V}, we construct a solution to Problem \eqref{V_pb} based on the solution to \eqref{w_pb}, while verifying the necessary a priori conditions.

Given the optimal feedback functions in \eqref{pi*} and \eqref{c*}, the variational inequality \eqref{V_pb} can be reformulated as
\begin{align}\label{V_pb1}
\left\{
\begin{array}{ll}
\displaystyle{\min\Bigg\{-V_t + \frac{1}{2} \kappa^2 \frac{V_x^2}{V_{xx}} - \wU(V_x,h) - r x V_x + \rho V,\; -V_h\Bigg\} = 0}, \quad (x,t,h) \in \RR_T, \\[2mm]
V(x,h,T) = U_T(x), \quad x > 0,\; h > 0,
\end{array}
\right.
\end{align}
where \( \kappa = (\mu - r)/\sigma > 0 \), and the function \( \wU(y,h) \) is defined by
\[
\wU(y,h) := \max_{b h \leq c \leq h} \big( U(c) - c y \big) =
\begin{cases}
U(h) - h y, & 0 < y \leq U'(h), \\
U((U')^{-1}(y)) - (U')^{-1}(y) y, & U'(h) < y < U'(b h), \\
U(b h) - b h y, & y \geq U'(b h).
\end{cases}
\]

Assuming the following priori estimates:
\[
\lim_{x \to \frac{b h}{r} (1 - e^{-r(T - t)})^+} V_x(x,t,h) = +\infty, \quad \lim_{x \to +\infty} V_x(x,t,h) = 0, \quad t \in [0,T),\; h > 0,
\]
we define the dual transform of \( V(x,t,h) \) as
\[
v(y,\tau,h) := \sup_{x > \frac{b h}{r}(1 - e^{-r(T - t)})} \left( V(x,t,h) - x y \right), \quad y > 0,\; h > 0,\; \tau = T - t \in (0,T].
\]

For fixed \( x, t, h \), let \( y := V_x(x,t,h) \). Then it follows that
\[
V(x,t,h) = v(y,\tau,h) + x y.
\]
By the convexity of \( v(y,\tau,h) \), we obtain the relations:
\[
x = -v_y(y,\tau,h), \quad
V(x,t,h) = v(y,\tau,h) - y v_y(y,\tau,h),
\]
\[
V_{xx}(x,t,h) = -\frac{1}{v_{yy}(y,\tau,h)}, \quad
V_t(x,t,h) = -v_\tau(y,\tau,h), \quad
V_h(x,t,h) = v_h(y,\tau,h).
\]
Substituting into \eqref{V_pb1}, we obtain the transformed variational inequality:
\begin{align}\label{v_pb}
\left\{
\begin{array}{ll}
\min \left\{ v_\tau - \LL v - \wU(y,h),\; -v_h \right\} = 0, \quad (y, \tau, h) \in \mathbb{R}^+ \times (0,T] \times \mathbb{R}^+, \\[2mm]
v(y, h, 0) = \wwU_T(y), \quad y > 0,\; h > 0,
\end{array}
\right.
\end{align}
where the operator \( \LL \) is given by
\[
\LL v := \frac{1}{2} \kappa^2 y^2 v_{yy} + (\rho - r) y v_y - \rho v,
\]
and the function \( \wwU_T(y) \) denotes the Legendre transform of the terminal utility \( U_T \), i.e.,
\begin{align}\label{wUT}
\wwU_T(y) := \sup_{x > 0} \big( U_T(x) - x y \big) =
\begin{cases}
U_T((U_T')^{-1}(y)) - (U_T')^{-1}(y) y, & 0 < y < U_T'(0+), \\
U_T(0), & y \geq U_T'(0+).
\end{cases}
\end{align}

To facilitate further analysis, we introduce the logarithmic transformation
\[
z = \ln y, \quad u(z, \tau, h) = v(y, \tau, h),
\]
under which the operator \( \LL \) becomes
\[
\TT u := \frac{1}{2} \kappa^2 u_{zz} + \left( \rho - r - \frac{1}{2} \kappa^2 \right) u_z - \rho u.
\]
Thus, the variational inequality for \( u(z, \tau, h) \) becomes:
\begin{align}\label{u_pb}
\left\{
\begin{array}{ll}
\min \left\{ u_\tau - \TT u - \wU(e^z, h),\; -u_h \right\} = 0, \quad (z, \tau, h) \in \mathbb{R} \times (0,T] \times \mathbb{R}^+, \\[2mm]
u(z, h, 0) = \wwU_T(e^z), \quad z \in \mathbb{R},\; h \in \mathbb{R}^+.
\end{array}
\right.
\end{align}

Define the function
\[
f(z, h) := \partial_h \wU(e^z, h) =
\begin{cases}
U'(h) - e^z, & \text{if } e^z \leq U'(h), \\
0, & \text{if } U'(h) < e^z < U'(b h), \\
b U'(b h) - b e^z, & \text{if } e^z \geq U'(b h).
\end{cases}
\]

In the region where \( u_\tau - \TT u - \wU(e^z, h) = 0 \), the function \( w := -u_h \) satisfies:
\[
w_\tau - \TT w + f(z, h) = -\partial_h(u_\tau - \TT u - \wU(e^z, h)) = 0.
\]
This motivates the study of the following obstacle problem for \( w \):
\begin{align}\label{w_pb}
\left\{
\begin{array}{ll}
\min \left\{ w_\tau - \TT w + f(z,h),\; w \right\} = 0, \quad (z, \tau) \in \mathbb{R} \times (0,T],\; h \in \mathbb{R}^+, \\[2mm]
w(z, h, 0) = 0, \quad z \in \mathbb{R},\; h \in \mathbb{R}^+.
\end{array}
\right.
\end{align}

We begin our analysis by examining Problem~\eqref{w_pb} to understand the structure of the solution and its associated free boundary, which in turn provides the foundation for constructing the solution to the original problem \eqref{V_pb}.

\section{The solution and the free boundary to the obstacle problem \eqref{w_pb}}\label{sec:E}
\setcounter{equation}{0}


In this section, we will employ the penalty approximation method to establish the existence and uniqueness of the solution to the obstacle problem \eqref{w_pb} and derive certain estimates of the solution. Subsequently, we can prove the existence and uniqueness of the free boundary and elucidate its properties, such as monotonicity, smoothness, and the position of its starting point.

\subsection{Existence and uniqueness of solution to Problem \eqref{w_pb}}



The problem \eqref{w_pb} is essentially a two - dimensional problem as the variable $h$ can be treated as a parameter. Therefore, in this subsection, we will fix a positive value for $h$.
To address Problem \eqref{w_pb}, we initially formulate the following penalty approximation problem for it within a bounded domain.
\begin{align}\label{we_pb}
\left\{
\begin{array}{ll}
w^\ep_\tau-\TT w^\ep + f(z,h) +\beta_\ep(w^\ep)=0,\quad(y,\tau)\in \Q_T^\ep,\\
w^\ep(-\frac{1}{\ep},\tau,h) =0,  \quad  \tau\in (0,T],\\
w^\ep_x(\frac{1}{\ep},\tau,h) = 0,  \quad   \tau\in (0,T],\\
w^\ep(z,0,h) =0, \quad   z\in (-\frac{1}{\ep},\frac{1}{\ep}),
\end{array}
\right.
\end{align}
where, the domain $\Q_T^\ep$ is defined as
$$\Q_T^\ep:=(-\frac{1}{\ep},\frac{1}{\ep})\times(0,T],$$
and $\beta _{\ep }(\cdot)$ is any penalty function satisfying the following properties
\begin{eqnarray*}
&&\beta _{\ep }(\cdot)\in C^{2}(-\infty,+\infty ), \quad\beta _{\ep}(0)=-U'(h)<0, \quad\beta _{\ep}(x)=0\; \text{ for } x\geq \ep, \\
&& \beta _{\ep
}(\cdot)\leq 0, \quad \beta _{\ep }^{\prime }(\cdot)\geq 0,\quad \beta _{\ep
}^{\prime \prime }(\cdot)\leq 0, \quad\lim\limits_{\ep \rightarrow 0} \beta _{\ep }(x)=\left\{
\begin{array}{ll}
0, & \mbox{if } x>0,\vspace{2mm} \\
-\infty, & \mbox{if } x<0,
\end{array}
\right.
\end{eqnarray*}%
\figref{fig1} demonstrates such a penalty function $\beta _{\ep }(\cdot)$.
