Subsequently, we are able to derive the following existence and uniqueness results for the approximation problem \eqref{we_pb}.
\begin{lemma}\label{thm:we}
For any $p>3$ and $0<\al<1$, the problem \eqref{we_pb} admits a unique solution $w^\ep\in W^{2,1}_p(\Q_T^\ep)\cap C^{1+\al,\frac{1+\al}{2}}(\overline{\Q_T^\ep})$. Furthermore, the solution satisfies the following estimations in $\Q_T^\ep$:
\begin{align}\label{we1}
0\leq &\;w^\ep\leq \frac{1}{r} e^z+\ep,\\
\label{we2}
&\; w^\ep_z \geq 0,\\
\label{we3}
&\; w^\ep_\tau \geq 0.
\end{align}
\end{lemma}
\begin{proof}
The existence and uniqueness of the solution can be established by applying the Schauder fixed - point theorem (see \cite{Ev16} Theorem 2 on page 502) and the comparison principle. Since the proof process follows a standard procedure, we omit the details here.

We start by proving the inequality \eqref{we1}. Denote the function $\phi(z,\tau)\equiv0$. Then, we can calculate
\begin{align*}
\phi_\tau-\TT \phi+f(z,h)+\beta_\ep(\phi)= f(z,h) - U'(h)\leq 0.
\end{align*}
According to the comparison principle, we conclude that $w^\ep\geq \phi =0$, which is the left - hand side inequality in \eqref{we1}.

Next, denote the function $\Phi(z,\tau)=e^z/r +\ep$. Notice that $\Phi(z,\tau)\geq \ep$ implies $\beta_\ep(\Phi)=0$. Then, we have
\begin{align*}
\Phi_\tau-\TT \Phi + f(z,h) +\beta_\ep(\Phi)
=e^z + \rho \ep + f(z,h)\geq 0.
\end{align*}
Applying the comparison principle, we obtain $w^\ep\leq \Phi$, which verifies the right - hand side inequality in \eqref{we1}.

Now, we turn to the proof of \eqref{we2}. Differentiating the equation in \eqref{we_pb} with respect to $z$, we obtain
$$
\p_\tau w^\ep_z -\TT w^\ep_z + \beta_\ep'(w^\ep)w^\ep_z = - \p_z f(z,h) \geq 0.
$$
Moreover, since $w^\ep\geq 0$ and $w^\ep(-1/\ep,\tau,h)=0$, we can infer that $w^\ep_z(-1/\ep,\tau,h)\geq 0$ for all $\tau\in(0,T]$. Then, by applying the comparison principle, we conclude that $w^\ep_z\geq 0$.

Finally, we prove \eqref{we3}. For any fixed $0<\Delta\tau<T$, we define $\wt{w}^\ep(z,\tau,h):=w^\ep(z,\tau+\Delta\tau,h)$. Note that $\wt{w}^\ep(z,0,h)=w^\ep(z,\Delta\tau,h)\geq 0$, and $\wt{w}^\ep$ satisfies the same equation and boundary conditions as $w^\ep$ in $Q_{T-\Delta\tau}^\ep$. Therefore, by using the comparison principle, we can deduce that $\wt{w}^\ep\geq w^\ep$ in $Q_{T-\Delta\tau}^\ep$, which implies \eqref{we3}.
\end{proof}

\begin{proposition}\label{pro:we4}
$w^\ep$ is non decreasing with respect to $h$.
\end{proposition}
\begin{proof}
Since $f(z,h)$ is non decreasing with respect to $h$, we have for $h'>h$,
$$
w^\ep_\tau (z,\tau,h')-\TT w^\ep (z,\tau,h') +\beta_\ep(w^\ep(z,\tau,h')) = - f(z,h') \geq - f(z,h),
$$
so $w^\ep(z,\tau,h')$ is a super solution of \eqref{we_pb}, i.e. $w^\ep(\cdot,\cdot,h')\geq w^\ep(\cdot,\cdot,h)$.
\end{proof}

\begin{proposition}\label{pro:we4'}
We have for $h'>h>0$,
$$
w^\ep (z,\tau,h')\leq w^\ep (z,\tau,h) + \frac{1}{\rho} K(h,h')\quad (z,\tau)\in \Q^\ep,
$$
where
$$
K(h,h'):=\max\Big\{U'(h)-U'(h'),\;b U'(b h)-  b U'(b h')\Big\}.
$$
\end{proposition}
\begin{proof}
It is not hard to check that
$$f(z,h)-f(z,h')\leq K(h,h').$$
Let $\psi(z,\tau):=w^\ep (z,\tau,h) + K(h,h')/\rho$, then it satisfies that
$$
\psi_\tau (z,\tau)-\TT \psi (z,\tau) +\beta_\ep(\psi (z,\tau)) \geq - f(z,h)+ K(h,h')\geq - f(z,h').
$$
So $\psi(z,\tau)$ is a super solution of Problem \eqref{we_pb}, i.e. $\psi(z,\tau)\geq w^\ep(\cdot,\cdot,h')$.
\end{proof}

Based on the above lemmas, let $\varepsilon\rightarrow0$, via the embedding theorem, we then obtain the following existence and uniqueness of solution to Problem \eqref{w_pb}.
\begin{theorem}\label{thm:w}
The problem \eqref{w_pb} has a unique solution $w\in C^{1+\al,\frac{1+\al}{2}}(\R\times[0,T])\bigcap W^{2,1}_{p,\;\mathrm{loc}}(\R\times(0,T])$, for any $p>3$ and $0<\al<1$. Furthermore,
\begin{align}\label{w1}
0\leq &\;w\leq \frac{1}{r} e^z,\\ \label{w2}
&\;w_z \geq 0,\\ \label{w3}
&\;w_\tau \geq 0,\\ \label{w4}
0\leq&\; w_h \leq { \frac{1}{\rho}\max\Big\{-U''(h), -b^2 U''(bh)\Big\}.}
\end{align}
\end{theorem}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Properties of the Free Boundary in Problem \eqref{w_pb}}

In the previous subsection, we established the existence and uniqueness of the solution to Problem~\eqref{w_pb}. Since the solution \( w \) is independent of the terminal time \( T \), we may, without loss of generality, extend the time variable to \( \tau \in (0, +\infty) \) in the analysis below.

Thanks to the monotonicity result \eqref{w2}, we define the free boundary of Problem~\eqref{w_pb} as
\begin{align}\label{eq:ytau}
z^*(\tau,h) := \sup \left\{ z \in \mathbb{R} \,\big|\, w(z,\tau,h) = 0 \right\}, \quad \tau, h \in \mathbb{R}^+.
\end{align}
Moreover, from inequalities \eqref{w3}--\eqref{w4}, it follows that \( z^*(\tau,h) \) is non-increasing in both \( \tau \) and \( h \).

We now demonstrate that the free boundary remains finite under all admissible inputs.

\begin{proposition}\label{pro:y_finite}
For any fixed \( h > 0 \), the limit
\[
z^*(+\infty,h) := \lim_{\tau \to +\infty} z^*(\tau,h)
\]
exists and is finite, i.e., \( z^*(+\infty,h) > -\infty \).
\end{proposition}

\begin{proof}
Since \( w \) is non-decreasing in \( \tau \) and uniformly bounded above for each fixed \( z \) and \( h \), there exists a limiting function \( w^\infty(z,h) := \lim_{\tau \to +\infty} w(z,\tau,h) \).

Assume for contradiction that \( w^\infty(z,h) > 0 \) for all \( z \in \mathbb{R} \). Then, by continuity and weak convergence,
\begin{align}\label{Luinfty}
- \TT w^\infty(z,h) + f(z,h) = - \lim_{\tau \to +\infty} w_\tau(z,\tau,h) \leq 0 \quad \text{in } \mathbb{R}.
\end{align}

Now consider \( z_0 < \ln(\tfrac{1}{2} U'(h)) \). Since \( f(z,h) = U'(h) - e^z \), we have \( f(z,h) > \tfrac{1}{2} U'(h) \) and therefore \( -\TT w^\infty(z,h) \leq -\tfrac{1}{2} U'(h) \) for all \( z < z_0 \).

But because \( w^\infty \geq 0 \) and \( w^\infty_z \geq 0 \), we obtain
\[
\frac{\kappa^2}{2} w^\infty_{zz}(z,h) + \rho w^\infty_z(z,h) \geq \frac{1}{2} U'(h), \quad z < z_0.
\]
Integrating both sides from \( y \) to \( y+1 \), and then integrating in \( y \) from \( N \) to \( N+1 \), yields
\begin{multline*}
\frac{\kappa^2}{2} \big(w^\infty(N+2,h) - 2w^\infty(N+1,h) + w^\infty(N,h)\big) \\
+ \rho \int_N^{N+1} \big(w^\infty(y+1,h) - w^\infty(y,h)\big) \mathrm{d}y \geq \frac{1}{2} U'(h).
\end{multline*}
However, the left-hand side tends to zero as \( N \to -\infty \), since \( w^\infty \) is non-decreasing and bounded, leading to a contradiction.
\end{proof}

\begin{proposition}\label{pro:zup}
For each \( h > 0 \), the free boundary satisfies the upper bound
\[
z^*(\tau,h) \leq \ln(U'(h)).
\]
\end{proposition}

\begin{proof}
We show that \( w(z,\tau,h) > 0 \) for all \( z > \ln(U'(h)) \). In this region, \( f(z,h) = U'(h) - e^z < 0 \), and hence
\[
w_\tau(z,\tau,h) - \TT w(z,\tau,h) \geq -f(z,h) > 0.
\]
Since \( w(z,\tau,h) \geq 0 \) and not identically zero in \( (\ln(U'(h)), +\infty) \), the strong maximum principle implies \( w(z,\tau,h) > 0 \) in this domain.
\end{proof}

\begin{proposition}\label{pro:y3}
The free boundary \( z^*(\tau,h) \) is continuous in \( (\tau, h) \in \mathbb{R}^+ \times \mathbb{R}^+ \), and satisfies
\[
\lim_{\tau \to 0+} z^*(\tau,h) = \ln(U'(h)).
\]
\end{proposition}

\begin{proof}
Suppose by contradiction that \( z^* \) is discontinuous at some point \( (\tau_0, h_0) \). Then there exists a sequence \( (\tau_n, h_n) \to (\tau_0, h_0) \) such that \( z^*(\tau_n, h_n) \not\to z^*(\tau_0, h_0) \). Denote
\[
\underline{z} = \min\big\{\lim z^*(\tau_n,h_n),\, z^*(\tau_0,h_0)\big\}, \quad
\overline{z} = \max\big\{\lim z^*(\tau_n,h_n),\, z^*(\tau_0,h_0)\big\}.
\]
Then for any \( z \in (\underline{z}, \overline{z}) \), we have \( w(z,\tau_0,h_0) = 0 \) and
\[
w_\tau(z,\tau_0,h_0) - \TT w(z,\tau_0,h_0) + f(z,h_0) = 0.
\]
However, since \( f(z,h_0) > 0 \) in this interval and \( w_\tau \geq 0 \), we obtain
\[
w_\tau + f > 0,
\]
contradicting the equation above. Thus \( z^*(\tau,h) \) is continuous.

To show \( \lim_{\tau \to 0+} z^*(\tau,h) = \ln(U'(h)) \), note that at \( \tau = 0 \), the initial condition \( w(z,0,h) = 0 \), and since \( f(z,h) > 0 \) when \( z < \ln(U'(h)) \), we must have \( z^*(\tau,h) \to \ln(U'(h)) \) as \( \tau \to 0+ \).
\end{proof}

\begin{proposition}\label{pro:y4}
The free boundary \( z^*(\tau,h) \) is strictly decreasing with respect to \( \tau \).
\end{proposition}

\begin{proof}
Assume for contradiction that \( z^*(\tau,h_0) = z_0 \) for all \( \tau \in [\tau_1, \tau_2] \). Then
\[
w(z_0,\tau,h_0) = 0, \quad w_z(z_0,\tau,h_0) = 0, \quad w_{z\tau}(z_0,\tau,h_0) = 0.
\]
Since \( w \) solves \( w_\tau - \TT w + f = 0 \) in \( z > z_0 \), we have $w_\tau$ that solves a linear equation with zero initial gradient at the boundary. By the Hopf lemma, we must have \( w_{\tau z}(z_0,\tau,h_0) > 0 \), which contradicts the fact that \( w_{\tau z} = 0 \). Thus, \( z^*(\tau,h) \) is strictly decreasing in \( \tau \).
\end{proof}

\begin{proposition}\label{pro:y5}
{ For each fixed \( h > 0 \), the function \( w_\tau(\cdot, \cdot, h) \in C(\mathbb{R}\times \R^+) \), and the free boundary \( z^*(\cdot,h) \in C^\infty(\mathbb{R}^+) \).}
\end{proposition}
{
\begin{proof}
Since $w_\tau \geq0$, $w\geq0$, and $f(\cdot,h)\in C^\infty$ near $z=z^*(\tau, h)$, we can take advantage of the same arguments in \cite{Fr75} to prove $w_\tau(\cdot,\cdot,h) $ is continuous across $z=z^*(\tau, h)$  and $z^*(\cdot, h)\in C^{\infty}(\R^+)$.
\end{proof}
}

\begin{proposition}\label{pro:y6}
The free boundary \( z^*(\tau,h) \) is strictly decreasing with respect to \( h \).
\end{proposition}

\begin{proof}
Suppose there exists \( h \in [h_1, h_2] \) such that \( z^*(\tau_0, h) = z_0 \) for all \( h \in [h_1, h_2] \). Then,
\[
w_z(z_0,\tau_0,h_1) = w_z(z_0,\tau_0,h_2) = 0.
\]
Let \( \psi(z,\tau) := w(z,\tau,h_2) - w(z,\tau,h_1) \).
{
Since $z^*(\tau,h_1)\geq z^*(\tau,h_2)$, the equation of $w$ gives
\[
\psi_\tau (z,\tau)-\TT \psi (z,\tau)=f(z,h_1)-f(z,h_2)\geq 0, \quad z\geq z^*(\tau,h_1).
\]
Since $\psi(z,\tau)\geq 0$ for $z\geq z^*(\tau,h_1)$ and $\psi(z_0,\tau_0)= 0$, and noting that $z^*(\cdot,h_1)\in C^\infty(\R^+)$, we adopt the Hopf Lemma to get $\psi_z(z_0,\tau_0)>0$, contradicting the previous conclusion. Therefore, \( z^*(\tau,h) \) is strictly decreasing in \( h \).
}
\end{proof}

To construct the solution to Problem~\eqref{u_pb}, we define
\[
h^*(z,\tau) := \sup \{ h \geq 0 \mid w(z,\tau,h) = 0 \}, \quad (z,\tau) \in \mathbb{R} \times (0,T].
\]
Then
\begin{align}\label{h*1}
h^*(z,\tau) =
\begin{cases}
(z^*(\tau, \cdot))^{-1}(z), & \text{if } z < z^*(\tau,0+), \\
0, & \text{if } z \geq z^*(\tau,0+).
\end{cases}
\end{align}

{ Since $z^*(\cdot,\cdot)$ is continuous and non increasing with respect to $\tau$ and $h$, we have}
\begin{proposition}\label{pro:y7}
The function \( h^*(z,\tau) \) is continuous and non-increasing in both \( z \) and \( \tau \).
\end{proposition}

\section{The Solution and the Free Boundary to the Dual Problem}\label{sec:E1}
\setcounter{equation}{0}

In this section, we aim to construct the solution to the dual problem \eqref{v_pb}, or its equivalent form \eqref{u_pb}, by utilizing the solution to the obstacle problem \eqref{w_pb}. Since $w = -u_h$, it is natural to obtain $u$ by integrating $w$ with respect to $h$. However, it is not feasible to identify a specific point $h_0$ to determine $u(\cdot,\cdot,h_0)$ or to evaluate $u(\cdot,\cdot,+\infty)$ as the initial value of the integration.

To overcome this difficulty, we introduce a new model that enhances the original by imposing a constraint on the consumption rate $C_t$ (or, equivalently, the maximum consumption rate $H_t$), restricting it to a bounded interval $(h,\hh]$. Under this restriction, when $H_t$ reaches the upper bound $\hh$, it remains fixed at this level. The dual problem reduces to a linear two-dimensional problem, whose solution can be determined by solving a linear PDE. This solution can then serve as the initial value for the abovementioned integration to solve this new problem. Then, by taking the limit $\hh \to \infty$, we eventually obtain the solution to the original problem \eqref{v_pb}, which imposes no upper bound on $h$.

We now turn our attention to the following linear problem for the function $\fh(z,\tau)$:
\begin{align}\label{fh_pb}
\left\{\begin{array}{ll}
\p_\tau \fh - \TT \fh - \wU (e^z, \hh) = 0, & (z,\tau) \in \R \times (0,T], \\
\fh(z,0) = \wwU_T (e^z), & z \in \R.
\end{array}\right.
\end{align}

According to standard PDE theory, this problem admits a unique solution $\fh \in C^{2,1}(\R \times [0,T])$ under the exponential growth condition. The solution to Problem \eqref{fh_pb} corresponds to an optimal control problem where the control variable $h$ is fixed at the constant level $\hh$.

Next, we consider the following approximation problem for \eqref{u_pb}:
\begin{align}\label{uh_pb}
\left\{\begin{array}{ll}
\min\Big\{\p_\tau \uh - \TT \uh - \wU(e^z,h),\;  -\p_h\uh\Big\} = 0, & (z,\tau,h) \in \R \times (0,T] \times (0,\hh), \\
\uh(z,0,h) = \wwU_T(e^z), & z \in \R,\; h \in (0,\hh), \\
\uh(z,\tau,\hh) = \fh(z,\tau), & (z,\tau) \in \R \times (0,T].
\end{array}\right.
\end{align}
The solution to Problem \eqref{uh_pb} represents an optimal control scenario where the control variable $h$ is restricted to the bounded interval $(0,\hh]$.

With solutions to Problems \eqref{fh_pb} and \eqref{w_pb} in hand, we are now in a position to construct the solution to Problem \eqref{uh_pb}. Suppose $\fh$ solves \eqref{fh_pb} and $w$ solves \eqref{w_pb}. Define
\begin{align}\label{uw}
\uh(z,\tau,h) := \fh(z,\tau) + \int_h^\hh w(z,\tau,s) \, \mathrm{d}s.
\end{align}

According to Theorem~\ref{thm:w} and Proposition~\ref{pro:y5}, we know that $w_z(\cdot,\cdot,h),\; w_\tau(\cdot,\cdot,h) \in C(\R \times (0,T])$ for every $h \in (0,\hh]$, and $w \in C(\R \times (0,T] \times \R^+)$. Moreover, we can easily find super-solutions for the PDEs involving $w_z$ and $w_\tau$ that are independent of $h$. As a result, we can apply the Lebesgue dominated convergence theorem to deduce that $\uh \in C^{1,1,1}(\R \times [0,T] \times (0,\hh])$. Additionally, we have the following result:

\begin{lemma}\label{lem:TuhR}
The function $\uh$ defined in \eqref{uw} belongs to $C^{2,1,1}(\R \times [0,T] \times (0,\hh])$ and solves Problem \eqref{uh_pb}.
\end{lemma}

\begin{proof}
The initial and boundary conditions in \eqref{uh_pb} are satisfied by construction. We now verify the variational inequality in \eqref{uh_pb}.

First, we note that $-\p_h \uh = w \geq 0$.

Second, observe that
\[
(w_\tau - \TT w)(z,\tau,h) =
\begin{cases}
-f(z,h) = -\p_h \wU(e^z,h), & h > h^*(z,\tau), \\
0, & h < h^*(z,\tau).
\end{cases}
\]
Applying \eqref{uw}, we obtain
\begin{align}
(\uh_\tau -\TT \uh)(z,\tau,h) =&\; (\fh_\tau -\TT \fh)(z,\tau)+ \int_h^{\hh} (w_\tau -\TT w)(z,\tau,s) \d s \nonumber\\ \label{Luh}
= &\; \wU(e^z,\hh) + \int_{h^*(z,\tau) \vee h}^{\hh} -\p_h\wU(e^z,s) \d s = \wU (e^z, h^*(z,\tau)\vee h).
\end{align}
Since $h^* \in C(\R \times (0,T])$ and $\uh \in C^{1,1,1}(\R \times (0,T] \times (0,\hh])$, we conclude that $\uh \in C^{2,1,1}(\R \times (0,T] \times (0,\hh])$.

If $-\p_h \uh(z,\tau,h) = w(z,\tau,h) > 0$, i.e., $h > h^*(z,\tau)$, then
\[
(\uh_\tau - \TT \uh)(z,\tau,h) = \wU(e^z,h).
\]
Conversely, if $-\p_h \uh(z,\tau,h) = w(z,\tau,h) = 0$, then $h \leq h^*(z,\tau)$, or equivalently, $z \leq z^*(\tau,h) \leq \ln U'(h)$. Since $\wU(e^z,h)$ is non-decreasing with respect to $h$ when $z \leq \ln U'(h)$, it follows that
\[
(\uh_\tau - \TT \uh)(z,\tau,h) = \wU(e^z,h^*(z,\tau)) \geq \wU(e^z,h).
\]
Therefore, the variational inequality in \eqref{uh_pb} is satisfied.
\end{proof}


In order to obtain the solution of \eqref{u_pb} by taking the limit of $\uh$ for $\hh\to +\infty$, we must find an upper bound of $\uh$ that is independent of $\hh$.
Define
\begin{align}\label{wwU}
\wwU(y)=\sup\limits_{c>0} \Big(U(c)-c y\Big)
\end{align}
and assume that $\uu(z,\tau)$ is the unique $C^{2,1}(\R \times[0,T])$ solution of
\begin{align}\label{uu_pb}
\left\{\begin{array}{ll}
\p_\tau \uu - \TT \uu-\wwU (e^z)=0,\quad (z,\tau)\in \R \times(0,T],\\
\uh(z,0)= \wwU_T (e^z),\quad z\in \R.
\end{array}\right.
\end{align}
under the exponential growth condition.
This problem corresponds to the model where there is no drawdown constraint on consumption.
Since
\begin{align}\label{wwUwU}
\wwU(y)\geq \wU (y,\hh),
\end{align}
by the comparison principle we have
\begin{align}\label{uhuh}
\uu \geq \fh.
\end{align}
Moreover, we have
\begin{lemma}\label{lem:uu}
For any $\hh\in\R^+$, there exists
\begin{align}\label{uu}
\uh(z,\tau,h) \leq \uu(z,\tau),\quad (z,\tau,h)\in \R\times[0,T]\times(0,\hh].
\end{align}
\end{lemma}
\begin{proof}
For any $\underline{h}\in(0,\hh)$, define
$$\zeta(z,\tau)=e^{\la z+ \eta \tau}+e^{-\la z+ \eta \tau},\quad (z,\tau)\in \R \times(0,T],$$
where $\la>0$ and $\eta>0$ are chosen to be large enough such that
$$
\lim\limits_{z\to \pm\infty}\max\limits_{(\tau,h)\in [0,T]\times [\underline{h},\hh]}\frac{|\uh(z,\tau,h)|+|\uu(z,\tau)|}{\zeta(z,\tau)}=0
$$
and
\begin{align}\label{Lphi}
\zeta_\tau -\TT \zeta \geq  0,\quad (z,\tau)\in \R \times(0,T].
\end{align}
We come to prove that for any $\ep>0$,
\begin{align}\label{v<=w}
\uh(z,\tau,h) \leq \uu(z,\tau)+\ep \zeta,\quad (z,\tau)\in \R \times(0,T],\;h\in [\underline{h},\hh].
\end{align}
We prove this by contradiction.  Suppose that \eqref{v<=w} is not true, let
$$M=\sup\limits_{(z,\tau,h)\in \R\times[0,T]\times [\underline{h},\hh]}(\uh-\uu-\ep \zeta)(z,\tau,h),$$
then $M>0$.
Note that $\uh-\uu-\ep \zeta$ is continuous and tends to $-\infty$ when $z\to\pm\infty$, and $(\uh-\uu-\ep\zeta)(z,0,h)=-\ep \zeta(z,0)<0$,
moreover, by \eqref{uhuh}, we further have
$(\uh-\uu-\ep\zeta)(z,\tau,\hh)\leq -\ep \zeta(z,\tau)<0$.
So $\uh-\uu-\ep\zeta$ attains its maximum value at a point $(z_0,\tau_0,h_0)\in \R\times(0,T]\times[\underline{h},\hh)$,
thus
$$
\p_\tau (\uh-\uu-\ep\zeta)(z_0,\tau_0,h_0)\geq 0,\quad \p_z (\uh-\uu-\ep\zeta)(z_0,\tau_0,h_0) = 0,\quad \p_{zz} (\uh-\uu-\ep\zeta)(z_0,\tau_0,h_0) \leq 0.
$$
then we get
\begin{align}\label{Luu>0}
\Big(\p_\tau (\uh-\uu-\ep\zeta)-\TT (\uh-\uu-\ep\zeta)\Big)(z_0,\tau_0,h_0) \geq \rho M >0.
\end{align}
On the other hand, we assume that $h_0$ satisfies
\begin{align*}
(\uh-\uu-\ep\zeta)(z_0,\tau_0,h)<M, \quad\forall\; h\in (h_0,\hh],
\end{align*}
which implies $w(z_0,\tau_0,h)>0$ for all $h \in (h_0,\hh]$, or equivalently, $z_0 \geq z^*(\tau_0,h_0)$. This  implies
$$\Big(\p_\tau \uh-\TT \uh\Big)(z_0,\tau_0,h_0) = \wU(e^{z_0},h_0).$$
Combining \eqref{uu_pb}, \eqref{Lphi} and \eqref{wwUwU} we get
$$
\Big(\p_\tau (\uh-\uu-\ep\zeta)-\TT (\uh-\uu-\ep\zeta)\Big)(z_0,\tau_0,h_0) \leq \wU(e^{z_0},h_0) - \wwU(e^{z_0})\leq 0,
$$
which contradicts \eqref{Luu>0}. So \eqref{v<=w} holds.
Sending $\ep\to0$ and then $\underline{h}\to0$ in \eqref{v<=w} we prove \eqref{uu}.
\end{proof}

By applying a similar argument, we can establish the following lemma:
\begin{lemma}\label{lem:uu}
For $\hh < \hh'$, we have
\begin{align*}
\uh(z,\tau,h) \leq u^{\hh'}(z,\tau,h), \quad (z,\tau,h)\in \R \times [0,T] \times (0,\hh].
\end{align*}
\end{lemma}

Since $\uh(z,\tau,h)$ is increasing in $\hh$ and uniformly bounded above for each $(z,\tau,h)\in \R \times (0,T] \times \R^+$, we define the limit function
\begin{align}\label{u_def}
u(z,\tau,h) := \lim_{\hh \to +\infty} \uh(z,\tau,h), \quad (z,\tau,h) \in \R \times [0,T] \times \R^+.
\end{align}

\begin{theorem}\label{u}
The function $u$ defined in \eqref{u_def} lies in $C^{2,1,1}(\R \times [0,T] \times \R^+)$ and solves Problem \eqref{u_pb}.
\end{theorem}

\begin{proof}
Letting $\hh \to \infty$ in \eqref{Luh}, we obtain
\begin{align}\label{TuR}
(u_\tau - \TT u)(z,\tau,h) = \wU(e^z, h^*(z,\tau) \vee h).
\end{align}
For any fixed $h_0 \in \R^+$, Schauder interior estimates (see \cite{Li96}, Theorem 4.9) imply $u(\cdot,\cdot,h_0) \in C^{2,1}(\R \times [0,T])$.

Furthermore, noting $u_h = -w$, we compute
\begin{align*}
\p_\tau u(z,\tau,h) &= \p_\tau u(z,\tau,h_0) - \int_{h_0}^h w_\tau(z,\tau,s) \, \d s, \\
\p_z u(z,\tau,h) &= \p_z u(z,\tau,h_0) - \int_{h_0}^h w_z(z,\tau,s) \, \d s.
\end{align*}
Since $w_z(\cdot,\cdot,h)$ and $w_\tau(\cdot,\cdot,h)$ are continuous in $\R \times (0,T]$ and uniformly bounded with respect to $h$, the Lebesgue dominated convergence theorem yields that $\p_\tau u$ and $\p_z u$ are continuous on $\R \times [0,T] \times \R^+$.
Moreover, combining \eqref{TuR}, we conclude that $u_{zz}$ is also continuous, hence $u \in C^{2,1,1}(\R \times [0,T] \times \R^+)$.

Finally, by the same arguments as in the proof of Lemma~\ref{lem:TuhR}, we verify that $u$ solves Problem \eqref{u_pb} using \eqref{TuR}.
\end{proof}

Define
\begin{align}\label{v_def}
v(y,\tau,h) := u(\ln y,\tau,h), \quad (y,\tau,h) \in \R^+ \times (0,T] \times \R^+.
\end{align}
Thanks to Lemma~\ref{u}, we obtain:
\begin{theorem}\label{v}
The function $v$ defined in \eqref{v_def} belongs to $C^{2,1,1}(\R^+ \times [0,T] \times \R^+)$ and is the solution to Problem \eqref{v_pb}.
\end{theorem}

To construct the solution to the original problem \eqref{V_pb} via inverse dual transformation, we now analyze several properties of the dual solution, including convexity and the asymptotic behavior of its derivative with respect to $y$ as $y \to 0$ and $y \to \infty$.

Observe that
\[
v_{yy}(y,\tau,h) = e^{-2z} \left( u_{zz}(z,\tau,h) - u_z(z,\tau,h) \right).
\]
To establish the convexity of $v$ in $y$, we first show:
\begin{lemma}\label{lem:unzz}
The solution $\uh$ to Problem~\eqref{uh_pb} defined by \eqref{uw} satisfies
\begin{align}\label{uzzuz}
\p_{zz} \uh(z,\tau,h) - \p_z \uh(z,\tau,h) \geq 0.
\end{align}
\end{lemma}

\begin{proof}
Set
\[
\psi^\hh(z,\tau,h) := \p_{zz} \uh(z,\tau,h) - \p_z \uh(z,\tau,h).
\]
We begin by verifying \eqref{uzzuz} for $h = \hh$. That is,
\begin{align}\label{psi>=0}
\psi^\hh(z,\tau,\hh) \geq 0.
\end{align}
Using the $C^{2+\alpha,1+\alpha/2}$ interior regularity for \eqref{fh_pb}, we see that $\psi^\hh(\cdot,\cdot,\hh)$ satisfies the exponential growth condition. Moreover, by direct computation:
\begin{align*}
\left\{
\begin{array}{ll}
\p_\tau \psi^\hh - \TT \psi^\hh = \wU_{yy}(e^z,\hh) e^{2z} \geq 0, & (z,\tau) \in \R \times (0,T], \\
\psi^\hh(z,0,\hh) = \wwU_T''(e^z) e^{2z} \geq 0, & z \in \R.
\end{array}
\right.
\end{align*}
Then the parabolic maximum principle yields \eqref{psi>=0}.

Next, we show that \eqref{uzzuz} holds on the free boundary:
\begin{align}\label{psiz}
\psi^\hh(z^*(\tau,h),\tau,h) \geq 0, \quad \text{for all } (\tau,h) \in [0,T] \times (0,h].
\end{align}
For any small $\ep>0$, define
\[
h_\varepsilon := \sup\left\{ h \in (0,\hh] \mid \exists \tau \in (0,T] \text{ such that } \psi^\hh(z^*(\tau,h),\tau,h) < -\varepsilon \right\}.
\]
We aim to prove $h_\varepsilon = 0$. Suppose for contradiction that $h_\varepsilon > 0$, and that for some $\tau_\varepsilon \in (0,T]$,
\begin{align}\label{psi>=-ep}
\psi^\hh(z^*(\tau_\varepsilon,h_\varepsilon),\tau_\varepsilon,h_\varepsilon) \leq -\varepsilon.
\end{align}
Let $z_\varepsilon := z^*(\tau_\varepsilon,h_\varepsilon)$.

Firstly, \eqref{psi>=0} implies $h_\ep< \hh$.
Note that
\begin{align*}
\left\{\begin{array}{ll}
(\p_\tau \psi^\hh  - \TT \psi^\hh)(z,\tau,h)  = \wU_{yy} (e^z,h) e^{2z}\geq 0,\quad z>z^*(\tau,h),\;h\in[h_\ep,\hh],\\
\psi^\hh (z^*(\tau,h),\tau,h)\geq -\ep,\quad h\in[h_\ep,\hh],\\
\psi^\hh (z,0,h)= \wwU_T'' (e^z) e^{2z}\geq 0,\quad z>z^*(0+,h)=\ln(U'(h)),\;h\in[h_\ep,\hh].
\end{array}\right.
\end{align*}
Applying the comparison principle we have
$$
\psi^\hh (z,\tau,h)\geq -\ep,\quad z\geq z^*(\tau,h),\;\tau\in [0,T],\;h\in[h_\ep,\hh].
$$


Since $w_\tau - \TT w + f(z,h) = 0$ for $z > z^*(\tau_\varepsilon,h_\varepsilon)$, and
\[
w(z_\varepsilon,\tau_\varepsilon,h_\varepsilon) = w_z(z_\varepsilon,\tau_\varepsilon,h_\varepsilon) = w_\tau(z_\varepsilon,\tau_\varepsilon,h_\varepsilon) = 0,
\]
and $z^*(\tau_\varepsilon,h_\varepsilon) < \ln U'(h_\varepsilon)$, it follows that
\[
\frac{\ka^2}{2} w_{zz}(z_\varepsilon^+,\tau_\varepsilon,h_\varepsilon) = f(z_\varepsilon,h_\varepsilon) \geq U'(h_\varepsilon) - e^{z_\varepsilon} > 0.
\]
Hence,
\begin{align}\label{psih}
\p_h \psi^\hh(z_\varepsilon^+,\tau_\varepsilon,h_\varepsilon) = - w_{zz}(z_\varepsilon^+,\tau_\varepsilon,h_\varepsilon) + w_z(z_\varepsilon,\tau_\varepsilon,h_\varepsilon) < 0.
\end{align}
This implies that there exists $h' > h_\varepsilon$ such that
\[
\psi^\hh(z_\varepsilon,\tau_\varepsilon,h_\varepsilon) > \psi^\hh(z_\varepsilon,\tau_\varepsilon,h') \geq -\varepsilon,
\]
which contradicts \eqref{psi>=-ep}. Therefore, $h_\varepsilon = 0$ and \eqref{psiz} holds.
\end{proof}

Now we prove that \eqref{uzzuz} holds for the case $z > z^*(\tau,h)$. Thanks to \eqref{psiz}, we have
\begin{align*}
\left\{
\begin{array}{ll}
(\p_\tau \psi^\hh - \TT \psi^\hh)(z,\tau,h) = \wU_{yy}(e^z,h) e^{2z} \geq 0, & z > z^*(\tau,h),\; h \in (0,\hh], \\
\psi^\hh(z^*(\tau,h),\tau,h) \geq 0, & h \in (0,\hh], \\
\psi^\hh(z,0,h) = \wwU_T''(e^z) e^{2z} \geq 0, & z > z^*(0+,h) = \ln(U'(h)),\; h \in (0,\hh].
\end{array}
\right.
\end{align*}
By the parabolic maximum principle, we conclude that
\[
\psi^\hh(z,\tau,h) \geq 0, \quad z \geq z^*(\tau,h),\; \tau \in [0,T],\; h \in [h_\varepsilon,\hh].
\]

Finally, we verify \eqref{uzzuz} for $z < z^*(\tau,h)$. Fix any $(z,\tau,h) \in \R \times (0,T] \times (0,\hh]$ such that $h < h^*(z,\tau)$. Since the function $\uh(\cdot,\cdot,h) - \uh(\cdot,\cdot,h^*(z,\tau))$ achieves its minimum at $(z,\tau)$, we have
\[
\uh(z,\tau,h) = \uh(z,\tau,h^*(z,\tau)), \quad \uh_z(z,\tau,h) = \uh_z(z,\tau,h^*(z,\tau)),
\]
and
\[
\uh_{zz}(z,\tau,h) \geq \uh_{zz}(z,\tau,h^*(z,\tau)).
\]
Hence,
\begin{align}\label{psipsi}
\psi^\hh(z,\tau,h) \geq \psi^\hh(z,\tau,h^*(z,\tau)) \geq 0.
\end{align}


\begin{proposition}\label{pro:vyy}
For any $(y,\tau,h) \in \R^+ \times (0,T] \times (0,h]$, we have
\begin{align}\label{vyy}
v_{yy}(y,\tau,h) > 0.
\end{align}
\end{proposition}

\begin{proof}
It suffices to show that for any $(z,\tau,h) \in \R \times (0,T] \times (0,h]$,
\begin{align}\label{uzzuz>0}
u_{zz}(z,\tau,h) - u_z(z,\tau,h) > 0.
\end{align}
Letting $\hh \to \infty$ in \eqref{uzzuz}, we obtain
\[
u_{zz}(z,\tau,h) - u_z(z,\tau,h) \geq 0.
\]
We now prove the inequality is strict. Define
\[
\psi(z,\tau,h) := u_{zz}(z,\tau,h) - u_z(z,\tau,h).
\]
From the regularity of $u$ and the PDE satisfied by $u$, we know that
\begin{align*}
\left\{
\begin{array}{ll}
(\p_\tau \psi - \TT \psi)(z,\tau,h) = \wU_{yy}(e^z,h) e^{2z} \geq 0, & z > z^*(\tau,h),\; \tau \in (0,T], \\
\psi(z^*(\tau,h),\tau,h) \geq 0, & \tau \in (0,T], \\
\psi(z,0,h) = \wwU_T''(e^z) e^{2z} \geq 0, & z > z^*(0+,h) = \ln(U'(h)).
\end{array}
\right.
\end{align*}
By the strong maximum principle, we obtain
\begin{align}\label{psi>0}
\psi(z,\tau,h) > 0, \quad z > z^*(\tau,h),\; \tau \in (0,T].
\end{align}

Moreover, analogous to the argument used for \eqref{psih}, we have
\[
\p_h \psi(z^*(\tau,h)^+,\tau,h) = -w_{zz}(z^*(\tau,h)^+,\tau,h) < 0, \quad \tau \in (0,T].
\]
Therefore, there exists $h' > h$ such that
\[
\psi(z^*(\tau,h),\tau,h) > \psi(z^*(\tau,h),\tau,h') \geq 0,
\]
which, together with \eqref{psi>0}, implies
\[
\psi(z^*(\tau,h),\tau,h) > 0, \quad \tau \in (0,T].
\]

Finally, for any $(z,\tau,h) \in \R \times [0,T] \times \R^+$ with $z < z^*(\tau,h)$, the function $u(\cdot,\cdot,h) - u(\cdot,\cdot,h^*(z,\tau))$ attains its minimum at $(z,\tau)$. Thus,
\[
u_z(z,\tau,h) = u_z(z,\tau,h^*(z,\tau)), \quad
u_{zz}(z,\tau,h) \geq u_{zz}(z,\tau,h^*(z,\tau)),
\]
which implies
\[
\psi(z,\tau,h) \geq \psi(z,\tau,h^*(z,\tau)) > 0.
\]
\end{proof}















\begin{proposition}\label{lem:vy}
For each $(\tau,h)\in (0,T]\times \R^+$, we have
\begin{align}\label{vy1}
\lim\limits_{y\to+\infty}v_y(y,\tau,h) = -\frac{bh}{r}(1-e^{-r\tau}),\\
\label{vy2}
\lim\limits_{y\to 0+}v_y(y,\tau,h) = -\infty.
\end{align}
\end{proposition}

\begin{proof}
Observe that $v_y(y,\tau,h)=e^{-z} u_z(z,\tau,h)$, where $z=\ln y$. Define
\[
\phi(z,\tau,h):= e^{-z} u_z(z,\tau,h) + \frac{bh}{r}(1-e^{-r\tau}).
\]
It suffices to prove:
\begin{align}
\label{p1}
\lim\limits_{z\to +\infty}\phi(z,\tau,h) = 0,\\
\label{p2}
\lim\limits_{z\to -\infty}\phi(z,\tau,h) = -\infty.
\end{align}

We first establish
\begin{align}\label{psi<=0}
\phi \leq 0.
\end{align}
From \eqref{TuR}, $\phi(z,\tau,h)$ satisfies the following PDE:
\begin{align}\label{psi_pb}
\left\{
\begin{array}{ll}
\p_\tau \phi - \JJ \phi = g(z,\tau,h), & (z,\tau) \in \R\times(0,T], \\
\phi(z,0,h) = g_T(z), & z \in \R,
\end{array}
\right.
\end{align}
where
\begin{align*}
\JJ \phi &:= \frac{1}{2} \kappa^2 \phi_{zz} + (\rho - r + \frac{1}{2} \kappa^2) \phi_z - r \phi, \\
g(z,\tau,h) &:= \wU_y(e^z,h^*(z,\tau)\vee h) + e^{-z} \wU_h(e^z,h^*(z,\tau)\vee h) \p_z(h^*(z,\tau)\vee h) + bh, \\
g_T(z) &:= \wwU_T'(e^z).
\end{align*}

We note that $\wU_h(e^z,h)> 0$ when $z < \ln U'(h)$, and
\[
\p_z(h^*(z,\tau)\vee h) =
\begin{cases}
\p_z h^*(z,\tau) \leq 0, & z < z^*(\tau,h), \\
0, & z > z^*(\tau,h),
\end{cases}
\]
Since $z^*(\tau,h) < \ln U'(h)$, we conclude:
\begin{align}\label{g2}
\wU_h(e^z,h^*(z,\tau)\vee h)\p_z(h^*(z,\tau)\vee h) \leq 0.
\end{align}
Using the bounds $-h \leq \wU_y \leq -bh$, we have $g(z,\tau,h) \leq 0$. Moreover, since $g_T(z) = \wwU_T'(e^z) \leq 0$, the parabolic maximum principle yields \eqref{psi<=0}.

To prove \eqref{p1}, fix $\epsilon > 0$. Note that for $z > \ln(U'(bh))$, we have $\wU_y(e^z,h) = -bh$ and $g(z,\tau,h) = 0$. Also, $g_T(z) \to 0$ as $z \to +\infty$. Choose $z_0 > \ln(U'(bh))$ such that $g_T(z) > -\epsilon/2$ for $z > z_0$. Then $\phi$ solves:
\begin{align}\label{psi_pb+}
\left\{
\begin{array}{ll}
\p_\tau \phi - \JJ \phi = 0, & (z,\tau) \in (z_0,+\infty) \times (0,T], \\
\phi(z,0,h) > -\epsilon/2, & z > z_0.
\end{array}
\right.
\end{align}

Define $M := \max_{\tau \in [0,T]} |\phi(z_0,\tau,h)|$. Then $-\epsilon/2 - M e^{z_0 - z}$ is a subsolution. Choosing $N = z_0 + \ln(2M/\epsilon)$ ensures
\[
\phi(z,\tau,h) \geq -\frac{\epsilon}{2} - M e^{z_0 - z} > -\epsilon, \quad z > N.
\]
Hence, \eqref{p1} holds.

To prove \eqref{p2}, fix $M > 0$ and define $z_0 := z^*(T,2Mr(1-e^{-r\tau})^{-1} + bh)$. Since $h^*(z,\tau)$ is strictly decreasing in $z$ and $\tau$, for $z \leq z_0$ and $s \in [0,T]$,
\[
h^*(z,s) \geq h^*(z_0,T) = 2Mr(1-e^{-r\tau})^{-1} + bh.
\]
Assuming $2Mr(1-e^{-r\tau})^{-1} + bh > h$, then $z_0 < z^*(s,h) < \ln U'(h)$ and for $z < z_0$,
\[
\wU_y(e^z,h^*(z,s)) = -h^*(z,s), \quad g(z,s,h) \leq -h^*(z,s) + bh \leq -2Mr(1-e^{-r\tau})^{-1}.
\]

Define $\lambda := \kappa^2 + \rho$, and the domain
\[
\Omega := \{(z,s) \mid z < z_0 - \lambda s,\; s \in (0,T]\} \subset (-\infty,z_0]\times[0,T].
\]
Then $\phi$ satisfies:
\begin{align}\label{psi_pb-}
\left\{
\begin{array}{ll}
\p_s \phi - \JJ \phi = g(z,s,h) \leq -2Mr(1-e^{-r\tau})^{-1}, & (z,s) \in \Omega, \\
\phi(z,s,h) < 0, & (z,s) \in \partial_p \Omega,
\end{array}
\right.
\end{align}
where $\partial_p \Omega$ denotes the parabolic boundary.

Define a supersolution:
\[
\Phi(z,s) := -2M(1-e^{-r\tau})^{-1}(1 - e^{z - z_0 + \lambda s})(1 - e^{-rs}).
\]
We compute:
\begin{align*}
\p_s \Phi - \JJ \Phi &= -2Mr(1-e^{-r\tau})^{-1}(1 - e^{z - z_0 + \lambda s}) \\
&\quad + 2Mr(1-e^{-r\tau})^{-1}(1 - e^{-rs}) e^{z - z_0 + \lambda s}(\lambda - \kappa^2 - \rho + r) \\
&\geq -2Mr(1-e^{-r\tau})^{-1}, \quad (z,s) \in \Omega.
\end{align*}
Since $\Phi = 0$ on $\partial_p \Omega$, we have $\phi \leq \Phi$ in $\Omega$.

Let $z_{\tau,h} := z_0 - \lambda \tau - \ln 2$, then
\[
\phi(z,\tau,h) \leq \Phi(z,\tau) = -2M(1 - e^{z - z_0 + \lambda \tau}) < -M, \quad z < z_{\tau,h}.
\]
This proves \eqref{p2}.
\end{proof}


\section{The Solution and the Free Boundary to the Original Problem}\label{sec:V}
\setcounter{equation}{0}

In this section, we present the proofs of \thmref{thm:V} and \thmref{thm:h}. Our strategy is to construct the solution and characterize the free boundary of the original problem \eqref{V_pb} using the solution and free boundary of the dual problem \eqref{v_pb}.

\subsection{Proof of Theorem~\ref{thm:V}}

Let $t = T - \tau$, and define
\begin{align}\label{V_def}
V(x,t,h) := \inf\limits_{y>0} (v(y,\tau,h) + yx),\quad \forall\; x > \frac{bh}{r}(1 - e^{-r(T - t)}),\; t \in [0,T).
\end{align}
We aim to prove that the function $V(x,t,h)$ defined in \eqref{V_def} solves Problem \eqref{V_pb}.

Using \eqref{vyy}, \eqref{vy1}, and \eqref{vy2}, the unique minimizer of \eqref{V_def}, denoted $I(x,t,h)$, satisfies
\begin{align*}
I(x,t,h) := \argmin\limits_{y>0} (v(y,\tau,h) + yx) = (v_y(\cdot,\tau,h))^{-1}(-x),\quad (x,t,h) \in \RR_T,
\end{align*}
where $(v_y(\cdot,\tau,h))^{-1}(\cdot)$ denotes the inverse function of $v_y(\cdot,\tau,h)$. Hence,
\begin{align*}
V(x,t,h) = v(I(x,t,h),\tau,h) + xI(x,t,h).
\end{align*}
This leads to the following derivatives:
\begin{align}\label{Vx}
V_x(x,t,h) &= v_y(I(x,t,h),\tau,h) I_x(x,t,h) + xI_x(x,t,h) + I(x,t,h) = I(x,t,h) > 0, \\
\label{Vxx}
V_{xx}(x,t,h) &= I_x(x,t,h) = \partial_x[(v_y(\cdot,\tau,h))^{-1}(-x)] = \frac{-1}{v_{yy}(I(x,t,h),\tau,h)} < 0, \\
\label{Vt}
V_t(x,t,h) &= -v_\tau(I(x,t,h),\tau,h), \\
V_h(x,t,h) &= v_h(I(x,t,h),\tau,h).
\end{align}
Thus, \eqref{V1} holds and $V \in C^{2,1,1}(\RR_T)$.

Moreover,
\begin{align*}
& \Big(-V_t + \frac{1}{2}\kappa^2 \frac{V_x^2}{V_{xx}} - \wU(V_x,h) - r x V_x + \rho V\Big)(x,t,h) \\
=& \Big(v_\tau - \frac{1}{2} \kappa^2 y^2 v_{yy} - (\rho - r) y v_y + \rho v - \wU(y,h)\Big)(I(x,t,h), \tau, h),
\end{align*}
showing that $V$ satisfies the variational inequality \eqref{V_pb1}.

We now verify the terminal condition:
\[
\lim\limits_{t \to T^-} V(x,t,h) = U_T(x)
\]
for any $x > 0$ and $h > 0$. Suppose by contradiction that this limit does not hold. Then there exist sequences $\tau_n \to 0^+$, $x_n \to x$, and $h_n \to h$ such that
\begin{align}\label{not}
K := \lim\limits_{n \to \infty} V(x_n, T - \tau_n, h_n) \neq U_T(x).
\end{align}
Let $y_n := (v_y(\cdot, \tau_n, h_n))^{-1}(-x_n)$. We analyze three cases:

\textbf{Case 1:} $y_n \to +\infty$ (or a sub sequence of $y_n$ tends to $+\infty$). For any fixed $y > 0$, for sufficiently large $n$ we have $y < y_n$ and thus $v_y(y, \tau_n, h_n) < v_y(y_n, \tau_n, h_n) = -x_n$. Taking $n \to \infty$ gives $\wwU_T'(y) = v_y(y, 0, h) \leq -x$, and further letting $y \to \infty$ yields $\wwU_T'(\infty) \leq -x$, contradicting $\wwU_T'(\infty) = 0$.

\textbf{Case 2:} $y_n \to 0+$ (or a sub sequence of $y_n$ tends to $0+$). Then for any $y > 0$, sufficiently large $n$ yields $y > y_n$, implying $v_y(y, \tau_n, h_n) > -x_n$, and thus $\wwU_T'(y) = v_y(y,0,h) \geq -x$. Taking $y \to 0+$ implies $\wwU_T'(0+) \geq -x$. If $U_T \not\equiv 0$, then $\wwU_T'(0+) = -\infty$, a contradiction. If $U_T \equiv 0$, then $\wwU_T(y) \equiv 0$, and since $v_y < 0$:
\[
V(x_n, T - \tau_n, h_n) = v(y_n, \tau_n, h_n) + y_n x_n > v(y, \tau_n, h_n) + y_n x_n \to 0,
\]
while
\[
V(x_n, T - \tau_n, h_n) \leq v(y, \tau_n, h_n) + y x_n \to y x.
\]
Since $y > 0$ is arbitrary, we conclude $\lim_{n \to \infty} V(x_n, T - \tau_n, h_n) = 0 = U_T(x)$, contradicting \eqref{not}.

\textbf{Case 3:} $y_n$ remains in $[a,b]$ for some $a,b > 0$. Then a subsequence, still denoted by $y_n$ that $y_n \to y_0 > 0$, which implies
\[
V(x_{n}, T - \tau_{n}, h_{n}) = v(y_{n}, \tau_{n}, h_{n}) + y_{n} x_{n} \to \wwU_T(y_0) + y_0 x \geq U_T(x),
\]
and for any $y > 0$,
\[
V(x_{n}, T - \tau_{n}, h_{n}) \leq v(y, \tau_{n}, h_{n}) + y x_{n} \to \wwU_T(y) + y x.
\]
Taking infimum over $y > 0$ yields $\lim_{n \to \infty} V(x_n, T - \tau_n, h_n) = U_T(x)$, again contradicting \eqref{not}.

We now prove the bounds in \eqref{V}. The growth condition \eqref{U2} implies
\[
\wwU(y), \; \wwU_T(y) \leq K\left[1 + \frac{\gamma}{1 - \gamma} \left(\frac{y}{K}\right)^{-\frac{1 - \gamma}{\gamma}}\right].
\]
Then by the comparison principle to the linear problem \eqref{uu_pb} we can prove
$$
\uu(z,\tau) \leq e^{\la \tau} K \left[ 1 + \frac{\gamma}{1-\gamma} \left( \frac{y}{K} \right)^{-\frac{1-\gamma}{\gamma}} \right]
$$
for some large $\la>0$, which combining \eqref{uu} gives
$$
v(y,\tau,h)\leq e^{\la \tau} K \left[ 1 + \frac{\gamma}{1-\gamma} \left( \frac{y}{K} \right)^{-\frac{1-\gamma}{\gamma}} \right].
$$
Plugging into \eqref{V_def} yields the second inequality in \eqref{V}.

To prove the first inequality, define
\[
\uv(y, \tau) = \frac{U(bh)}{\rho}(1 - e^{-\rho \tau}) - \frac{bh}{r}(1 - e^{-r \tau})y + K^{1/\theta} \frac{\theta}{1 - \theta} y^{1 - 1/\theta} e^{\lambda \tau} - K e^{-\rho \tau},
\]
where
\[
\lambda = -\frac{\kappa^2}{2} \frac{\theta - 1}{\theta^2} + (\rho - r) \frac{\theta - 1}{\theta} - \rho.
\]
This solves
\begin{align}\label{uv_pb}
\left\{
\begin{array}{ll}
\uv_\tau - \LL \uv = U(bh) - bhy, & (y, \tau) \in \R^+ \times (0,T], \\
\uv(y,0) = K^{1/\theta} \frac{\theta}{1 - \theta} y^{1 - 1/\theta} - K, & y > 0.
\end{array}
\right.
\end{align}
Since $\wU(y,h) \geq U(bh) - bhy$ and $\wwU_T(y) \geq \uv(y,0)$ (by \eqref{U3}), and $v$ is a supersolution of \eqref{uv_pb}, it follows that
\begin{align*}
V(x,t,h) \geq \inf_{y>0} (\uv(y,\tau) + yx)
= \frac{K}{1 - \theta} e^{\lambda \theta \tau} \left(x - \frac{bh}{r}(1 - e^{-r\tau})\right)^{1 - \theta}
+ \frac{U(bh)}{\rho}(1 - e^{-\rho \tau}) - K e^{-\rho \tau},
\end{align*}
proving the first inequality in \eqref{V}.

\subsection{Proof of Theorem~\ref{thm:h}}

Let $t = T - \tau$. Define the free boundary of the original problem \eqref{V_pb} as
\begin{align}\label{x^*}
x^*(t,h) := -v_y(e^{z^*(\tau,h)}, \tau, h), \quad t \in [0, T),\; h \in \R^+.
\end{align}
Since $v \in C^{2,1,1}(\R^+ \times (0,T] \times \R^+)$ and $z^* \in C((0,T] \times \R^+)$, it follows that $x^* \in C([0,T) \times \R^+)$.

Noting that $v_y < -\frac{bh}{r}(1 - e^{-r \tau})$, we obtain $x^*(t,h) > \frac{bh}{r}(1 - e^{-r(T - t)})$. Furthermore, since $z^*(\tau,h)$ is strictly decreasing in $h$ and $v_{yh} \leq 0$, we deduce that $x^*(t,h)$ is strictly increasing in $h$.

Define
\begin{align}\label{xHL}
x^H(t,h) := -v_y(U'(h), \tau, h), \quad x^L(t,h) := -v_y(U'(bh), \tau, h), \quad t \in [0, T),\; h \in \R^+.
\end{align}
Then both $x^H(t,h)$ and $x^L(t,h)$ are continuous in $(t,h)$ and strictly decreasing in $h$. Taking the limit as $t \to T-$, we obtain:
\[
x^H(T-, h) = -\widehat{U}_T'(U'(h)), \quad x^L(T-, h) = -\widehat{U}_T'(U'(bh)),
\]
and
\[
x^*(T-, h) = -\widehat{U}_T'(U'(h)),
\]
which establishes the terminal behavior of the free boundary.


