\begin{algorithm}[!h]
   \caption{\textsc{PromptQuine}'s Generational GA (GGA) implementation for Prompt Subsequence Search}
   \label{alg:PromptQuine-GGA}
\begin{algorithmic}
   \STATE {\bfseries Input:} Initial population $\mathcal{P}$, with population size $\#p$, number of maximal iterations $\#n$, minimal prompt length threshold $\#l$, training dataset $\mathcal{D}_{train}$, fitness function $f$, offspring size $\#c$, language model $\mathcal{M}$, tournament selection ratio $\#k$, mean population prompt length calculation function $h$\\
   \STATE {\bfseries Output:} Prompt History $\mathcal{H}$

   \STATE History $\mathcal{H} \leftarrow \mathcal{P}$.

   \FOR{$i=1$ {\bfseries to} $\#n$}
    %\begin{enumerate}
    \STATE Initialize $g \leftarrow Empty$.
    \STATE Initialize mean population prompt length $L \leftarrow h(\mathcal{P})$.
    \IF{$L < \#l$} 
    \STATE \textbf{break}
    \ENDIF
    \FOR{$j=1$ {\bfseries to} $\#c$}
   \STATE $\text{Parent} \leftarrow \texttt{Tournament-Selection(}\texttt{$\mathcal{P}$}, \texttt{$\#k$)}$.
   \STATE $\text{Child} \leftarrow 
   \texttt{copy-then-mutate(}\text{Parent}\texttt{)}$.
   \STATE $\text{Score} \leftarrow 
   \texttt{evaluate(}\text{Child}, \texttt{$M$}, \texttt{$f$}, \texttt{$\mathcal{D}_{train}$)}$.
   \STATE $g, \mathcal{H} \leftarrow 
   \texttt{push(}\text{Child}, \text{Score}$\texttt{)}.
   \ENDFOR
   \STATE Sort $g$ in descending order of $\text{Score}$.
   \STATE Update population $\mathcal{P} \leftarrow g[:\#p]$.
    \ENDFOR
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!h]
   \caption{\textsc{PromptQuine}'s Steady-state GA (SSGA) implementation for Prompt Subsequence Search}
   \label{alg:PromptQuine-SSGA}
\begin{algorithmic}
   \STATE {\bfseries Input:} Initial population $\mathcal{P}$, with population size $\#p$, number of maximal iterations $\#n$, minimal prompt length threshold $\#l$, training dataset $\mathcal{D}_{train}$, fitness function $f$, offspring size $\#c$, language model $\mathcal{M}$, tournament selection ratio $\#k$, mean population prompt length calculation function $h$\\
   \STATE {\bfseries Output:} Prompt History $\mathcal{H}$

   \STATE History $\mathcal{H} \leftarrow \mathcal{P}$.

   \FOR{$i=1$ {\bfseries to} $\#n$}
    %\begin{enumerate}
    \STATE Initialize mean population prompt length $L \leftarrow h(\mathcal{P})$.
    \IF{$L < \#l$} 
    \STATE \textbf{break}
    \ENDIF
    \FOR{$j=1$ {\bfseries to} $\#c$}
   \STATE $\text{Parent} \leftarrow \texttt{Tournament-Selection(}\texttt{$\mathcal{P}$}, \texttt{$\#k$)}$.
   \STATE $\text{Child} \leftarrow 
   \texttt{copy-then-mutate(}\text{Parent}\texttt{)}$.
   \STATE $\text{Score} \leftarrow 
   \texttt{evaluate(}\text{Child}, \texttt{$M$}, \texttt{$f$}, \texttt{$\mathcal{D}_{train}$)}$.
   \STATE $\mathcal{P}, \mathcal{H} \leftarrow 
   \texttt{push(}\text{Child}, \text{Score}$\texttt{)}.
   \ENDFOR
   \STATE Initialize $g \leftarrow \mathcal{P}[\#p:]$.
   \STATE Sort $g$ in descending order of $\text{Score}$.
   \STATE Update population $\mathcal{P} \leftarrow g[:\#p]$.
    \ENDFOR
\end{algorithmic}
\end{algorithm}
