\section{Introduction}
\numberwithin{equation}{section}

The solution to the Schrödinger equation
\begin{equation}\label{0}
	\left\{\begin{array}{ll}
		i u_{t}-\Delta u=0 & (x, t) \in \mathbb{R} \times \mathbb{R}, \\
		u(x, 0)=f(x) & x \in \mathbb{R},
	\end{array}\right.
\end{equation}
can be formally written as
\begin{equation}\label{1}
	e^{i t (-\Delta)} f(x)=\frac{1}{2\pi}\int_{ \mathbb{R}} e^{i\left(x  \xi+t|\xi|^{2}\right)} \widehat{f}(\xi) d \xi.
\end{equation}
Investigating the optimal value   \( s \)  for $f\in H^s\left(\mathbb{R}\right)$ to ensure \( \underset{t \rightarrow 0} {\lim} e^{i t (-\Delta)} f(x)=f(x) \quad a.e. \)  was first put forward by Carleson \cite{MR0576038}, and he proved convergence holding for \( s \geq \frac{1}{4} \), which is optimal according to the counterexample constructed by Dahlberg and Kenig \cite{MR0654188}.

Lee-Rogers \cite{MR2871144} studied the following associated operator
\begin{equation}\label{2}
	U_\Gamma f(x,t)=\frac{1}{2\pi}\int_{ \mathbb{R}}  e^{i\left(\Gamma(x,t)  \xi+t|\xi|^{2}\right)} \widehat{f}(\xi) d \xi.
\end{equation}
Here, \( \Gamma \) is a continuous function such that
\(
\Gamma: \mathbb{R} \times[-1,1] \rightarrow \mathbb{R}, \quad \Gamma(x, 0)=x.
\)
We always assume that the curve $\Gamma(x,t)$ is bilipschitz continuous in \( x \), that is
\begin{equation}\label{3}
	C_{1}\left|x-x^{\prime}\right| \leq\left|\Gamma(x, t)-\Gamma\left(x^{\prime}, t\right)\right| \leq C_{2}\left|x-x^{\prime}\right|, \quad t \in[-1,1], \quad x, x^{\prime} \in \mathbb{R} .
\end{equation}
The curve will be divided into tangential case $(0<\alpha<1)$ and non-tangential case $(\alpha=1)$ according to the Hölder continuous condition \( \alpha \in(0,1] \) in \( t \) , that is
\begin{equation}\label{4}
	\left|\Gamma(x, t)-\Gamma\left(x, t^{\prime}\right)\right| \leq C_{3}\left|t-t^{\prime}\right|^{\alpha}, \quad x \in \mathbb{R}, \quad t, t^{\prime} \in[-1,1].
\end{equation}

	When $\Gamma(x,t)$ is bilipschitz  continuous in in \( x \) and Lipschitz  continuous in \( t \), the convergence problem of  (\ref{2}) is essentially equivalent to the traditional convergence problem  of (\ref{1}). In the tangential case, Cho-Lee-Vargas \cite{MR2970037} showed \( s>\max \left\{\frac{1}{4}, \frac{1-2 \alpha}{2}\right\} \) is the sharp sufficient condition.  

 Sjölin \cite{MR2549801} first raised   the almost everywhere convergence problem of Schrödinger operator with complex time by replacing $t$ with $t+it^{\gamma}$ in (\ref{1}), that is
 \[
 	P_{\gamma} f(x,t):=\frac{1}{2\pi}\int_{\mathbb{R}} e^{i\left(x \xi+ t|\xi|^{2}\right)} e^{-t^{\gamma}|\xi|^{2}}\hat{f}(\xi) d \xi,
 \] where $\gamma>0$.  And he showed that when $0<\gamma \le 1$, $f\in L^2$ is optimal.  Bailey \cite{MR3047427} pointed that $s>\min\left\{\frac{1}{4},\frac{1}{2}\left(1-\frac{1}{\gamma}\right)^+ \right\}$ is the sharp result.  In addition, some related problems  have also been studied. For example,  Pan--Sun \cite{MR4844992,Pan-Sun}  investigated sequential convergence and  convergence rate of Schrödinger operator with complex time, which were  improved to sharp by Chen--Li--Wang--Wang \cite{Chen-Li-Wang-Wang}.

In this paper, we investigate the convergence properties of Schrödinger operator with complex time along curves
\begin{equation}\label{5}
	P_{\gamma} f(\Gamma(x,t),t):=\frac{1}{2\pi}\int_{\mathbb{R}} e^{i\left(\Gamma(x,t)  \xi+ t|\xi|^{2}\right)} e^{-t^{\gamma}|\xi|^{2}}\hat{f}(\xi) d \xi.
\end{equation}
Niu-Xue \cite{MR4052710} proved $s>\min\left\{\frac{1}{2}\left(1-\frac{1}{\gamma}\right)^+ ,\frac{1}{4}\right\}$ is sharp  for $\alpha\in[\frac{1}{2},1]$. We consider the case $\alpha\in(0,\frac{1}{2})$	and simplify the proof of case $\alpha\in[\frac{1}{2},1]$. Here are the main results of our article.

\subsection{Pointwise convergence of Schrödinger operator with complex time along curves.}
\numberwithin{equation}{section}
\begin{theorem}\label{theorem1}(\cite{MR4052710})
	Let $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t): \mathbb{R}\times[-1,1] \rightarrow \mathbb{R} $ which is bilipschitz continuous in \( x \) and  $\alpha$-Hölder continuous in \( t \) with \(  \frac{1}{2}\leq \alpha \leq 1\),
	we have
	\begin{equation}\label{pointwise convergence 1}
		\lim _{t \rightarrow 0} P_{\gamma} f(\Gamma(x,t),t)=f(x) \text { a.e. } x \in \mathbb{R} ,\quad \forall f \in H^{s}\left(\mathbb{R}\right)
	\end{equation}
	whenever  $ s>s(\gamma)=\min\{\frac{1}{2}(1-\frac{1} {\gamma})^{+}, \frac{1}{4}\}$. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence 1}) fails whenever $s<s(\gamma)$. 

\end{theorem}

\begin{theorem}\label{theorem2}
	Let $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ 0 < \alpha \leq \frac{1}{4} $, we have convergence result 
	(\ref{pointwise convergence 1}) whenever  $ s>s(\gamma)=\min\{(\frac{1}{2 }-\frac{\alpha} {\gamma})^{+}, 	\frac{1}{2}-\alpha \}$. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence 1}) fails whenever $s<s(\gamma)$. 
\end{theorem}

\begin{theorem}\label{theorem3}
	Let $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ \frac{1}{4} < \alpha < \frac{1}{2} $, we have convergence result 
	(\ref{pointwise convergence 1}) whenever  $ s>s(\gamma)$. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence 1}) fails whenever $s<s(\gamma)$. Here
	\begin{equation}
		s(\gamma)=\begin{cases}
			0             \quad  & \gamma \in(0,2\alpha), \\ 
			\frac{1}{2}-\frac{\alpha} {\gamma}   \quad   & \gamma \in[2\alpha,1),  \\
			\frac{1}{2}-\alpha       \quad   & \gamma \in[1,\frac {1} {2\alpha}),  \\
			\frac{1}{2 }(1-\frac{1} {\gamma})   \quad   & \gamma \in[\frac {1} {2\alpha},2),  \\
			\frac{1}{4}  \quad   & \gamma \in[2,\infty). \
		\end{cases}
	\end{equation}
\end{theorem}

\subsection{Fractional cases.}
~\\
The pointwise  convergence of  fractional Schrödinger operator has also been studied extentsivly. The fractional Schrödinger operator  is defined as
\begin{equation}\label{frac m}
e^{i t (-\Delta)^{\frac{m}{2}}} f(x):=\frac{1}{2\pi}\int_{\mathbb{R}} e^{i \left(x\xi+ t|\xi|^{m}\right)}  \hat{f}(\xi) d \xi
\end{equation}
where $m>0$. Sjölin \cite{MR0904948} and Walther \cite{MR1347033} showed that  $s\ge \frac{1}{4}$ when $m>1$ and $s> \frac{m}{4}$ when $0<m<1$ are sharp results.  When $m=1$,  Rogers-Villarroya \cite{MR2379688} proved that $s>\frac{1}{2}$ is  sufficient enough. The convergence problem of fractional Schrödinger operator along curves has also been analyzed. Cho-Shiraki \cite{MR4307013} and Yuan-Zhao \cite{MR4359958} pointed $s>\max\{ \frac{1}{4},\frac{1-m\alpha}{2}\}$ when $m>1$ and $s>\max\{ \frac{2-m}{4},\frac{1-m\alpha}{2}\}$ when $0<m<1$ can get a.e. convergence.  For  convergence problem of fractional Schrödinger operator with complex time,  Bailey \cite{MR3047427} pointed that $s>\min\left\{\frac{1}{4},\frac{m}{4}\left(1-\frac{1}{\gamma}\right)^+ \right\}$ is the sharp result when $m>1$. Yuan-Zhao-Zheng \cite{MR4222395} extended it to $0<m<1$ and got result $s>\frac{1}{2}\left(1-\frac{1}{\gamma}\right)^+$ when $m=1$. The fractional form of (\ref{5}) is
\[
P^m_{\gamma}f(\Gamma(x,t),t):=\frac{1}{2\pi}\int_{\mathbb{R}} e^{i \left(\Gamma(x,t)+ t|\xi|^{m}\right)} e^{-t^{\gamma}|\xi|^{m}}\hat{f}(\xi) d \xi.
\]

When $m>2$ and $\alpha\in[\frac{1}{m},1]$, Niu-Xue \cite{MR4052710} considered the pointwise convergence problem. We extend the results to $m>0$ and $\alpha\in(0,1]$. Since proof method  is similar to the proof of Theorem \ref{theorem1}, Theorem \ref{theorem2} and Theorem \ref{theorem3}, we will only prensent the results in Section \ref{chap4} while omit the proof.


~\\
\textbf{Outline.} In the following part, we will deal with sufficiency in Section \ref{chap2} and necessity in Section \ref{chap3}. The  fractional cases is presented in Section \ref{chap4}.\\
~\\
\textbf{Notation.} Throughout this article, we write \( A \gg B \) to mean if there is a large constant \( G \), which does not depend on \( A \) and \( B \), such that \( A \geq G B \). We write $A \lesssim B$  to mean that there exists a constant $C$ such that $A \leq C B$. We write $A \gtrsim B$  to mean that there exists a constant $C$ such that $A \geq C B$. We write \( A \sim B \), and mean that \( A \) and \( B \) are comparable.  We write  supp \( \hat{f} \subset\left\{\xi:|\xi| \sim \lambda \right\} \) to mean  supp \( \hat{f} \subset\left\{\xi: \frac{\lambda}{2}\le |\xi| \le 2\lambda \right\} \) and we will always assume $\lambda\gg1$. We write $C_{X}$ to denote a constant that depends on $X$, where $X$ is a variable. We write $A \lesssim_{\varepsilon} B$ to mean, there exists a constant $C_{\varepsilon}$ such that $A \leq C_{\varepsilon} B$.	

