\section{Proof of upper bounds for maximal functions}\label{chap2}
\numberwithin{equation}{section}
Via a standard smooth approximation argument and  Littlewood-Paley decomposition, Theorem \ref{theorem1}, Theorem \ref{theorem2} and Theorem \ref{theorem3} can be reduced to the following three maximal estimates. These estimates reveal the improved temporal localization phenomenon caused by the addition of term $e^{-t^\gamma \xi^2}$  in oscillatory integration.
\begin{proposition}\label{proposition1}
	Let $\gamma$, $\Gamma$ satisfy assumptions in Theorem \ref{theorem1}. For any $\varepsilon>0$, we have
	\begin{equation}\label{2.1}
	\left\|\sup _{t \in [0,1] }\left|P_{\gamma} f(\Gamma(x,t),t)\right|\right\|_{L^{2}([-1,1])} \lesssim_{\varepsilon} \left\{\begin{matrix}
		\|f\|_{L^{2}} &  \gamma \in(0,1),		\\	\lambda^{\frac{1}{2}(1-\frac{1}{\gamma})+\varepsilon} \|f\|_{L^{2}} &  \gamma \in[1, 2),\\
		\lambda^{\frac{1}{4}} \|f\|_{L^{2}} &\gamma \in[2,\infty),
	\end{matrix}\right.
	\end{equation}
	for all \( f \) with supp \( \hat{f} \subset\left\{\xi:|\xi|\sim \lambda \right\} \). 
\end{proposition}
\begin{proposition}\label{proposition2}
	Let $\gamma$, $\Gamma$ satisfy assumptions in Theorem \ref{theorem2}. For any $\varepsilon>0$, we have

	\begin{equation}\label{2.2}
		\left\|\sup _{t \in [0,1] }\left|P_{\gamma} f(\Gamma(x,t),t)\right|\right\|_{L^{2}([-1,1])} \lesssim_{\varepsilon} \left\{\begin{matrix}
		\|f\|_{L^{2}} &  \gamma \in(0,2\alpha),		\\	\lambda^{{\frac{1}{2}}-\frac{\alpha}{\gamma}+\varepsilon} \|f\|_{L^{2}} &  \gamma \in[2 \alpha,1),\\
		\lambda^{\frac{1}{2}-\alpha} \|f\|_{L^{2}} &\gamma \in[1,\infty),
	\end{matrix}\right.
	\end{equation}
	for all \( f \) with supp \( \hat{f} \subset\left\{\xi:|\xi|\sim \lambda \right\} \). 
\end{proposition}
\begin{proposition}\label{proposition3}
	Let $\gamma$, $\Gamma$ satisfy assumptions in Theorem \ref{theorem3}. For any $\varepsilon>0$, we have

	\begin{equation}\label{2.3}
	\left\|\sup _{t \in [0,1] }\left|P_{\gamma} f(\Gamma(x,t),t)\right|\right\|_{L^{2}([-1,1])} \lesssim_\varepsilon
	\left\{\begin{matrix}
		\|f\|_{L^{2}} &  \gamma \in(0,2\alpha),		\\	\lambda^{{\frac{1}{2}}-\frac{\alpha}{\gamma}+\varepsilon} \|f\|_{L^{2}} &  \gamma \in[2 \alpha,1),\\
		\lambda^{\frac{1}{2}-\alpha} \|f\|_{L^{2}} &\gamma \in[1,\frac{1}{2\alpha}),\\
		\lambda^{\frac{1}{2}(1-\frac{1}{\gamma})+\varepsilon} \|f\|_{L^{2}}
		&\gamma \in	[\frac{1}{2\alpha},2),\\
		\lambda^\frac{1}{4} \|f\|_{L^{2}}
		&\gamma \in [2,\infty),
	\end{matrix}\right.
\end{equation}
for all \( f \) with supp \( \hat{f} \subset\left\{\xi:|\xi|\sim \lambda \right\} \). 
\end{proposition}

Next we handle the three maximal estimates mentioned above. \\

\textbf{Proof of Proposition \ref{proposition1}, Proposition \ref{proposition2} and Proposition \ref{proposition3}.}\\

 	By linearizing the maximal operator, \( x \mapsto t(x) \) be a measurable function with values in \( [0,1] \), using the $TT^{*}$ method, we only need to consider the kernel, denoted by 

  	\[
  	K\left(x, y, t(x), t(y)\right)=\int e^{i\left(\left(\Gamma(x, t(x))-\Gamma\left(y, t(y)\right)\right)  \xi+\left(t(x)-t(y)\right)|\xi|^{2}\right)} e^{-\left(t(x)^\gamma +t(y)^\gamma \right)|\xi|^{2} } \Psi(\frac{\xi}{\lambda}  ) d \xi,
  	\]
  	where \( \Psi \in C_{0}^{\infty}\left(\left(-2,-\frac{1}{2}\right) \cup\left(\frac{1}{2}, 2\right)\right) \) is a positive function.
   \\
  	Next we will prove that for any $\beta_1,\beta_2\geq 0$, $x,y\in[-1,1]$ we have  
   \begin{equation}\label{estimate}
   \left|K\left(x, y, t(x), t(y)\right)\right| \lesssim_{\beta_1,\beta_2}\max\left\{ \min{\left\{   \frac{\lambda^{-2\beta_1}}{\left|x-y\right|^{\frac{\gamma \beta_1}{\alpha}+\frac{1}{2\alpha}}}, \frac{\lambda^{1-2\beta_1}}{{\left|x-y\right|}^{\frac{\gamma \beta_1}{\alpha}}}  \right\}}, \frac{\lambda^{\frac{1}{2}-2\beta_2+\gamma\beta_2}}{|x-y|^{\frac{1}{2}+\gamma\beta_2}} \right\}.
      \end{equation}


  	 Changing  variables \( \xi \rightarrow \lambda \xi \) shows
  	\[
  	K\left(x, y, t(x), t(y)\right) =\lambda \int e^{i\left(\lambda\left(\Gamma(x, t(x))-\Gamma\left(y, t(y)\right)\right)  \xi+\lambda^{2}\left(t(x)-t(y)\right)|\xi|^{2}\right)} e^{-\lambda^2 \left(t(x)^\gamma +t(y)^\gamma \right)|\xi|^{2} } \Psi(\xi ) d \xi.	\]
  	Set
  	\[
  	\varphi(\xi)=\lambda\left(\Gamma(x, t(x))-\Gamma\left(y, t(y)\right)\right)  \xi+\lambda^{2}\left(t(x)-t(y)\right)|\xi|^{2},
  	\]
  	\[
  	G(\xi)=e^{-\lambda^2 \left(t(x)^\gamma +t(y)^\gamma \right)|\xi|^{2} } \Psi(\xi ) ,
  	\]
  	to rewrite $K\left(x, y, t(x), t(y)\right)$ as
  	\[ K\left(x, y, t(x), t(y)\right)=\lambda \int e^{i\varphi(\xi)}G(\xi) d \xi.\] It is evident that $K\left(x, y, t(x), t(y)\right) \lesssim \lambda$.
  	Since \( t(x), t(y) \in [0,1] \), recalling our assumptions on curves, we notice  that
  	\[
  	\begin{aligned}
  		\centering
  		\Gamma(x, t(x))-\Gamma\left(y, t(y)\right) & =\left(\Gamma(x, t(x)-\Gamma\left(x, t(y)\right)\right)+\left(\Gamma\left(x, t(y)\right)-\Gamma\left(y, t(y)\right)\right), \\
  		\left|\Gamma(x, t(x))-\Gamma\left(x, t(y)\right)\right| & \lesssim\left|t(x)-t(y)\right|^{\alpha}, \\
  		\left|\Gamma\left(x, t(y)\right)-\Gamma\left(y, t(y)\right)\right| & \sim|x-y|.
  	\end{aligned}
  	\]

  	We consider two cases \( |x-y| \lesssim\left|t(x)-t(y)\right|^{\alpha},|x-y| \gg\left|t(x)-t(y)\right|^{\alpha} \) separately. 
  	For the first case \( |x-y| \lesssim\left|t(x)-t(y) \right|^{\alpha} \), we have \( \left|\frac{d^{2}}{d \xi^{2}} \varphi\right| \gtrsim \lambda^{2}\left|t(x)-t(y)\right| \). Thus van der Corput's lemma shows	
  	\begin{equation}\label{K2.1}
  		\left|K\left(x, y, t(x), t(y)\right)\right|  \lesssim  \frac{\lambda}{\left(1+\lambda^{2}\left|t(x)-t(y)\right|\right)^{1 / 2}} \left( \sup _{|\xi|\sim 1}|G(\xi)|+\int_{|\xi|\sim 1}\left|G^{\prime}(\xi)\right| d \xi\right) .
  \end{equation}\\  
 Next, we claim that for any $\beta\ge0$, there exists a positive number $C_\beta$ such that
  	\begin{equation}\label{supG}
  		\left( \sup _{|\xi|\sim 1}|G(\xi)|+\int_{|\xi|\sim 1}\left|G^{\prime}(\xi)\right| d \xi\right)\leq  \frac{C_\beta}{\left( \lambda^2 \left|t(x)-t(y)\right|^\gamma \right)^\beta}.
  	\end{equation}			
  	First, observing that $t(x)^{\gamma}+t(y)^{\gamma}\gtrsim\left(t(x)+t(y)\right)^{\gamma} \geqslant \left| t(x)-t(y)\right|^{\gamma}$, and noting that for any \( y>0, \beta\ge0 \), the inequality
  	\[
  	e^{-y} \lesssim_{\beta} y^{-\beta},
  	\]
  	we can get
  	\[
  	\sup _{|\xi|\sim 1}|G(\xi)|\lesssim e^{-\lambda^2 \left|t(x)-t(y)\right|^\gamma } \leq\frac{C_\beta^{'}}{\left( \lambda^2 \left|t(x)-t(y)\right|^\gamma \right)^\beta}.
  	\]
  	As for the second term, we can choose $\beta^{\prime}=\beta+1$ such that
  	\[
  	\begin{aligned}
  		\int_{|\xi|\sim 1}\left|G^{\prime}(\xi)\right| d \xi&\lesssim \int_{|\xi|\sim 1}\sup _{|\xi|\sim 1}|G(\xi)|d\xi+\int_{|\xi|\sim 1} \frac{ C_{\beta^{\prime}}^{\prime}\lambda^{2}\left(t(x)^\gamma +t(y)^\gamma \right)}{\left( \lambda^2 \left(t(x)^\gamma +t(y)^\gamma \right) \right)^{\beta+1}}d\xi\\
  		&\lesssim \frac{C_{\beta}^{\prime}}{\left( \lambda^2 \left|t(x)-t(y)\right|^\gamma \right)^\beta},
  	\end{aligned}
  	\]
  	which completes the proof of (\ref{supG}). \\
  Recalling \( |x-y| \lesssim \left|t(x)-t(y)\right|^{\alpha} \), we combine (\ref{K2.1}) and (\ref{supG}) to get
    		\begin{equation}
  		\begin{aligned}\label{in2.1}
  			\left|K\left(x, y, t(x), t(y)\right)\right|  &\lesssim  \frac{\lambda}{\left(1+\lambda^{2}\left|t(x)-t(y)\right|\right)^{1 / 2}} \left( \sup _{|\xi|\sim 1}|G(\xi)|+\int_{|\xi|\sim 1}\left|G^{\prime}(\xi)\right| d \xi\right) \\
  			&\lesssim \min{\left\{  \frac{1}{\left|t(x)-t(y)\right|^{\frac{1}{2}}}, \lambda  \right\}}
  		 \frac{1}{\lambda^{2\beta_1}\left|t(x)-t(y)\right|^{\gamma \beta_1}}\\
  			& \lesssim \min{\left\{   \frac{\lambda^{-2\beta_1}}{\left|x-y\right|^{\frac{\gamma \beta_1}{\alpha}+\frac{1}{2\alpha}}}, \frac{\lambda^{1-2\beta_1}}{{\left|x-y\right|}^{\frac{\gamma \beta_1}{\alpha}}}  \right\}} .\\
  		\end{aligned}
  	\end{equation}\\
 for any $\beta_1\geq 0$.

    For the second case \( |x-y| \gg\left|t(x)-t(y)\right|^{\alpha} \), we still need to consider two cases 
   \(|x-y| \gg \lambda \left|t(x)-t(y)\right|\) and  \(|x-y| \lesssim \lambda \left|t(x)-t(y)\right| \). If \( |x-y| \gg \lambda\left|t(x)-t(y)\right| \), noticing $\left|\frac{d}{d \xi} \varphi(\xi)\right|\gtrsim \lambda|x-y|$, hence for any $N$ we
   have 
   \[ \left|K\left(x, y, t(x), t(y)\right)\right| \lesssim \frac{\lambda}{(1+\lambda|x-y|)^{N}}\]
by non stationary phase method. If \( |x-y|\lesssim \lambda\left|t(x)-t(y)\right| \), by van der Corput's lemma again for any $\beta_2 \geq 0$, we have
  \begin{equation}\label{in2.2}
\begin{aligned}
\left|K\left(x, y, t(x), t(y)\right)\right| \lesssim &\frac{ \lambda}{\left(1+\lambda^{2}\left|t(x)-t(y)\right|\right)^{1 / 2}}\left( \sup _{|\xi|\sim 1}|G(\xi)|+\int_{|\xi|\sim 1}\left|G^{\prime}(\xi)\right| d \xi\right) \\
\lesssim &\frac{\lambda^{\frac{1}{2}-2\beta_2+\gamma\beta_2}}{|x-y|^{\frac{1}{2}+\gamma\beta_2}}.
\end{aligned}
\end{equation}	\\

Combining estimates (\ref{in2.1}) and (\ref{in2.2}) above, we finish the proof of (\ref{estimate}).\\

  	Using  (\ref{estimate}), we have
  	\begin{equation}\label{K}
  		\begin{aligned}
  			I(x)= &\int_{[-1,1]}\left|K(x, y,t(x),t(y))\right| d y \\
  		\leq&\int_{[-1,1]}  \min{\left\{   \frac{1}{\lambda^{2\beta_1}\left|x-y\right|^{\frac{\gamma \beta_1}{\alpha}+\frac{1}{2\alpha}}}, \frac{\lambda^{1-2\beta_1}}{{\left|x-y\right|}^{\frac{\gamma \beta_1}{\alpha}}}  \right\}}+\frac{\lambda^{\frac{1}{2}-2\beta_2+\gamma\beta_2}}{|x-y|^{\frac{1}{2}+\gamma\beta_2}}dy \\
  		    		\lesssim &\int_{\substack{\ |x-y|\lesssim   \lambda^{-2\alpha}   }}\frac{\lambda^{1-2\beta_1}}{\left|x-y\right|^{\frac{\gamma \beta_1}{\alpha}}}  d y+\int_{\substack{\lambda^{-2\alpha} \ll |x-y|\lesssim 1  }}	\frac{\lambda^{-2\beta_1}}{\left|x-y\right|^{\frac{\gamma \beta_1}{\alpha}+\frac{1}{2\alpha}}} d y\\&+\int_{\substack{0 \leq |x-y|\lesssim 1 }} \frac{\lambda^{\frac{1}{2}-2\beta_2+\gamma\beta_2}}{|x-y|^{\frac{1}{2}+\gamma\beta_2}} dy  .   \\
  		%	\lesssim & \lambda^{1-2\alpha+2\beta_1(\gamma-1)}	+\lambda^{\frac{1}{2}-2\beta_2}.
  		\end{aligned}
  	\end{equation}	

 When $\alpha\in [\frac{1}{2},1], \gamma\in[1,2)$, recalling that $K\left(x, y, t(x), t(y)\right)\lesssim \lambda$, we can choose $\beta_1=0$, $\beta_2=\frac{1}{2\gamma}$ and  small enough $\varepsilon>0$  to get
 \[
 I(x) \lesssim_{\varepsilon}   \lambda^{1-2\alpha}+\lambda^{1-\frac{1}{\gamma}+\varepsilon}\lesssim_{\varepsilon}   \lambda^{1-\frac{1}{\gamma}+\varepsilon}.
 \]		
 Therefore we have
 \begin{equation}\label{schurtest}
 	\underset{x \in [-1,1]}{sup } \int\left|K(x, y)\right| d y \lesssim_{\varepsilon} \lambda^{1-\frac{1}{\gamma}+\varepsilon}.
 \end{equation}
 By symmetry we get the same bound for \( \underset{y\in[-1,1]}{\sup} \int\left|K(x, y)\right| d x \). Hence Schur's test gives the required bound (\ref{proposition1}) when $\gamma\in[1,2)$. 

 The following table presents under different  pairs of  $(\alpha, \gamma)$, what $(\beta_1,\beta_2)$  we  should choose to  ensure estimates of $I(x)$ are optimal. 
