\section{Necessary conditions}\label{chap3}
In order to prove necessity in Theorem \ref{theorem1}, Theorem   \ref{theorem2} and Theorem  \ref{theorem3} , we
use arguments from Niki\v{s}hin-Stein theory, which means we only need to construct counterexamples of maximal functions. Here are the two counterexamples.
\begin{theorem}\label{theorem3.1}
	Let  $\Gamma(x,t)=x-t^{\alpha}$ with $\alpha\in(0,1]$. The following maximal estimate 
		\begin{equation}\label{3.1}
		\left\|\sup _{t \in [0,1] }\left|P_{\gamma} f(\Gamma(x,t),t)\right|\right\|_{L^{2}([-1,1])} \lesssim 
		\left|\left|f\right|\right|_{H^{s}}
	\end{equation}
	 yields 
	 \begin{equation}
	 	s\geq\begin{cases}
	 		\max\left\{\frac{1}{2}-\frac{\alpha} {\gamma},0\right\}   \quad   & \gamma \in(0,1),  \\
	 		\max\left\{\frac{1}{2}-\alpha,0\right\}      \quad   & \gamma \in[1,\infty).\
	 	\end{cases}
	 \end{equation}

\end{theorem}

	\begin{proof}
		Let \( g \in  C_0^{\infty} \) is a standard bump function with supp $g\subset [0,\frac{1}{2}]$ such that \( g(\xi) \geq 0 \) and \( \int g(\xi) d \xi=1 \). We construct a family of functions \( f_{ R} \) with large \( R  \), defined by
		\[
		\widehat{f}_{R}(\eta)=\frac{1}{R} g\left( \frac{\eta}{R}\right).
		\]
		It is easy to calculate the Sobolev norm of ${f}_{R}$
			\[			
		\left\|f_{R}\right\|_{H^{s}} \lesssim R^{s-\frac{1}{2}}.
		\]
		After scaling  $\frac{\eta}{R}\to \xi$, we have
		\[
		\begin{aligned}
	\left|P_{\gamma} f(\Gamma(x,t),t)\right|= &\left|\int e^{i\left((x-t^{\alpha})  \eta+ t|\eta|^{2}\right)} e^{-t^{\gamma}|\eta|^{2}}\frac{1}{R} g\left( \frac{\eta}{R}\right) \frac{d \eta}{2 \pi}\right|\\
	=&\left|\int e^{i\left((x-t^{\alpha})  R \xi+ tR^{2}|\xi|^{2}\right)} e^{-t^{\gamma}R^{2}|\xi|^{2}}g(\xi) \frac{d \xi}{2 \pi}\right|.
\end{aligned}	
\]
Set 
\[
\phi_R(\xi,x,t)=(x-t^{\alpha})R\xi+tR^2\xi^2,\quad \Phi_R(\xi,t)=-t^{\gamma}R^2|\xi|^{2}.
\]
Next we will choose suitable $t$ depending on $x$, which we label $t_x$ to ensure  $\phi_R(\xi,x,t)$ and $\Phi_R(\xi,t)$ considerablely small.
When $\gamma\in(0,1)$, one can find $t^{\gamma}R^2 \geq tR^2$ for $t\in[0,1]$. For some suitably small constant c, let
\[
A=\{x:0 <x<cR^{-\frac{2\alpha}{\gamma}}\}.
\]
Set 
\begin{equation}\label{3.3}
	t_x=x^{\frac{1}{\alpha}},
\end{equation}
 we can find $t_x\in(0,cR^{-\frac{2}{\gamma}})$ to have  $t_xR^{2}|\xi|^2\leq c$ and  $t_x^\gamma R^{2}|\xi|^2\leq c$. Thus
		\begin{equation}\label{3.4}
			\begin{aligned}
			\sup _{t\in[0,1]}\left|P_{\gamma} f(\Gamma(x,t),t)\right|
			& \geq\left|P_{\gamma} f(\Gamma(x,t_x),t_x)\right| \\
			& \geq \left|\int g(\xi)\frac{d \xi}{2 \pi}\right|-\int \left|e^{i\phi_R(\xi,x,t_x)} e^{\Phi_R(\xi,t_x)}-1\right| g(\xi) \frac{d \xi}{2 \pi} \\
			 & \geq \frac{1}{4\pi}.
			\end{aligned}
	\end{equation}
Let $R \to \infty$, (\ref{3.1}) yields\\
		 \begin{equation}\label{3.5}
		 	s\geq\frac{1}{2}-\frac{\alpha}{\gamma}.
		 \end{equation}\\

		When $\gamma\in [1,\infty)$, we can find $t^{\gamma}R^2 \leq tR^2$. Consider \[
		B=\{x:0 <x<cR^{-2\alpha}\}.
		\]Set (\ref{3.3}) as before, we can find  $\phi_R(\xi,x,t)$ and $\Phi_R(\xi,t)$ small enough to get (\ref{3.4}). Let $R \to \infty$, (\ref{3.1}) yields\\
		\begin{equation}\label{3.6}
			s\geq\frac{1}{2}-\alpha.
		\end{equation}\\
	Finally, set $t=0$ and $x<\frac{c}{R}$, we have (\ref{3.4}) as well to get 
	\begin{equation}\label{3.7}
		s\geq0.
	\end{equation}\\
  Combing (\ref{3.5}), (\ref{3.6}) and (\ref{3.7}), we finish the proof.
	\end{proof}

\begin{theorem}\label{theorem3.2}
	Let $\gamma\in[1,\infty)$, $\Gamma(x,t)=x-t^{\alpha}$ with $\alpha\in(\frac{1}{4},1]$. The  maximal estimate (\ref{3.1}) yields  \begin{equation}
		s\geq\begin{cases}
			\frac{1}{2}(1-\frac{1} {\gamma})   \quad   & \gamma \in\left[\max\{\frac{1}{2\alpha},1\},2\right),  \\
			\frac{1}{4}      \quad   & \gamma \in[2,\infty).\
		\end{cases}
	\end{equation}
\end{theorem}
\begin{proof}
	Let  \( g \in  C_0^{\infty} \) is a standard bump function with supp $g\subset [0,\frac{1}{2}]$ such that \( g(\xi) \geq 0 \) and \( \int g(\xi) d \xi=1 \). We construct a family of functions \( f_{ R} \) with large \( R  \), defined by
	\[
	\widehat{f}_{R}(\eta)=\frac{1}{R} g\left( \frac{\eta+R^b}{R}\right).
	\]
		Here $b\in[1,\infty)$. It is easy to calculate the Sobolev norm of ${f}_{R}$
	\[			
	\left\|f_{R}\right\|_{H^{s}} \lesssim R^{bs-\frac{1}{2}}.
	\]
	After scaling  $\frac{\eta+R^b}{R}\to\xi$, we have
	\[
	\begin{aligned}
		\left|P_{\gamma} f(\Gamma(x,t),t)\right|= &\left|\int e^{i\left((x-t^{\alpha})  \eta+ t|\eta|^{2}\right)} e^{-t^{\gamma}|\eta|^{2}}\frac{1}{R} g\left( \frac{\eta+R^b}{R}\right) \frac{d \eta}{2 \pi}\right|\\
		=&\left|\int e^{i\left((x-t^{\alpha})  (R \xi-R^b)+t|R\xi-R^b|^2\right)} e^{-t^{\gamma}|R\xi-R^b|^{2}}g(\xi) \frac{d \xi}{2 \pi}\right|\\
		=&\left|\int e^{i\left((x-t^{\alpha}-2R^bt)  R \xi+t|R\xi|^2\right)} e^{-t^{\gamma}|R\xi-R^b|^{2}}g(\xi) \frac{d \xi}{2 \pi}\right|.
	\end{aligned}	
	\]
	Set\[ \phi_R(\xi,x,t)=(x-t^{\alpha}-2R^bt)R\xi+tR^2\xi^2,    
	   \Phi_R(\xi,t)=-t^{\gamma}|R\xi-R^b|^{2}.\]
	When $\gamma\in[\max\{\frac{1}{2\alpha},1\},2)$, we set $b=\gamma$. For
	  \[x\in
	A=\{x:0 <x<c^\alpha R^{-2\alpha}+2cR^{\gamma-2}\},
	\]
we can find a $t_x\in(0,cR^{-2})$ satisfying 
\[x-t_x^{\alpha}-2R^\gamma t_x=0.\] 
Thus we have  $\phi_R(\xi,x,t_x)$ and $\Phi_R(\xi,t_x)$ small enough to get (\ref{3.4}) as well on $x\in A$.  Notice that $R^{-2\alpha} \leq R^{\gamma-2}$, $|A| \geq 2cR^{\gamma-2}$.  Let $R \to \infty$, (\ref{3.1}) yields
\begin{equation}\label{3.9}
	s\geq \frac{1}{2}\left(1-\frac{1}{\gamma}\right).
\end{equation}\\
	When $\gamma\in[2,\infty)$, we set $b=2$.  For
	\[x\in
	B=\{x:0 <x<c^\alpha R^{-2\alpha}+2c\},
	\]
	we can find a $t_x\in(0,cR^{-2})$ satisfying 
	\[x-t_x^{\alpha}-2R^2 t_x=0.\]
	Thus we have  $\phi_R(\xi,x,t_x)$ and $\Phi_R(\xi,t_x)$ small enough to get (\ref{3.4}) as well on $x\in B$. Notice that $R^{-2\alpha} \leq 1$ and $|B| \geq 2c$.  Let $R \to \infty$, (\ref{3.1}) yields
	\begin{equation}\label{3.10}
	s\geq \frac{1}{4}.
\end{equation}\\
	Combing (\ref{3.9}), (\ref{3.10}), we finish the proof.
	\end{proof}



\section{Convergence  of fractional Schrödinger operator with complex time along curves}\label{chap4}
The similar method can also handle the convergence  of fractional Schrödinger operator with complex time along curves. Here, we only present results while omit the proof.  


When $m\in(0,1)$, we have the following two theorems.
\begin{theorem}\label{theorem4.1}
	Let $m\in(0,1)$ and $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t): \mathbb{R}\times[-1,1] \rightarrow \mathbb{R} $ which is bilipschitz continuous in \( x \) and  $\alpha$-Hölder continuous in \( t \) with \(  0< \alpha \leq \frac{1}{2}\),
	we have
	\begin{equation}\label{pointwise convergence mcass}
		\lim _{t \rightarrow 0} P^m_{\gamma} f(\Gamma(x,t),t)=f(x) \text { a.e. } x \in \mathbb{R} ,\quad \forall f \in H^{s}\left(\mathbb{R}\right)
	\end{equation}
	whenever  $ s>s(\gamma)=\min \left\{\frac{1}{2 }(1-m\alpha), \frac{1}{2 }\left(1-\frac{m\alpha}{\gamma} \right)^{+} \right\} $. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$. 
\end{theorem}

\begin{theorem}\label{theorem4.2}
	Let $m\in(0,1)$ and $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ \frac{1}{2} < \alpha \leq 1 $, we have convergence result 
	(\ref{pointwise convergence mcass}) whenever  $ s>s(\gamma)=\min\{\frac{2-m}{4}+\frac{m(1-2\alpha)}{4\gamma} , \frac{1}{2 }\left(1-\frac{m\alpha}{\gamma} \right)^{+} \}$. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$.

\end{theorem}
When $m=1$, we have the following theorem.
\begin{theorem}\label{theorem4.3}
	Let $m=1$ and   $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ \alpha\in (0,1]$, we have convergence result 
	(\ref{pointwise convergence mcass}) whenever  $  s>s(\gamma)=\frac{1}{2 }\left(1-\frac{\alpha}{\gamma} \right)^{+}$. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$. 
\end{theorem}
When $m\in(1,\infty)$, we have the following  theorems.
\begin{theorem}\label{theorem4.4}
	Let $m\in(1,\infty)$ and  $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ 0 < \alpha \leq \frac{1}{2m} $, we have convergence result 
	(\ref{pointwise convergence mcass}) whenever  $ s>s(\gamma)=\min \left\{\frac{1}{2 }(1-m\alpha), \frac{1}{2 }\left(1-\frac{m\alpha}{\gamma} \right)^{+} \right\} $. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$. 
\end{theorem}
\begin{theorem}\label{theorem4.5}
Let $m\in(1,\infty)$ and  $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ \frac{1}{2m} < \alpha < \min\{\frac{1}{2},\frac{1}{m} \}$, we have convergence result 
(\ref{pointwise convergence mcass}) whenever  $ s>s(\gamma) $. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$. Here
	\begin{equation}
		s(\gamma)=\begin{cases}
			0             \quad  & \gamma \in(0,m\alpha), \\ 
			\frac{1}{2 }-\frac{m\alpha} {2\gamma}  \quad   & \gamma \in[m\alpha,1),  \\
			\frac{1-m\alpha}{2}       \quad   & \gamma \in[1,\frac {m} {m-2+2m\alpha}),  \\
			\frac{m}{4}(1-\frac{1} {\gamma})   \quad   & \gamma \in[\frac {m} {m-2+2m\alpha},\frac {m}{m-1}),  \\
			\frac{1}{4}  \quad   & \gamma \in[\frac {m}{m-1},\infty). \
		\end{cases}
	\end{equation}
\end{theorem}

\begin{theorem}\label{theorem4.7}
	Let $m\in(1,\infty)$ and  $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ \frac{1}{m} \leq \alpha \leq 1$, we have convergence result 
	(\ref{pointwise convergence mcass}) whenever  $ s>s(\gamma)=\min\{\frac{1}{4},\frac{m}{4}(1-\frac{1} {\gamma})^{+}\} $. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$. 
\end{theorem}

\begin{theorem}\label{theorem4.6}
	Let $m\in(1,2)$ and $\gamma\in(0,\infty)$. For any curve  $\Gamma(x,t) $ which is bilipschitz continuous in \( x \) and   $\alpha$-Hölder continuous in \( t \) with $ \frac{1}{2} \leq \alpha <\frac{1}{m} $, we have convergence result 
	(\ref{pointwise convergence mcass}) whenever  $ s>s(\gamma) $. Conversely, there exists a curve satisfying the previous assumptions, while (\ref{pointwise convergence mcass}) fails whenever $s<s(\gamma)$. Here
	\begin{equation}
		s(\gamma)=\begin{cases}
			0             \quad  & \gamma \in(0,m\alpha), \\ 
			\frac{1}{2 }-\frac{m\alpha} {2\gamma}  \quad   & \gamma \in[m\alpha,1),  \\
			\frac{2-m}{4}+\frac{m(1-2\alpha)}{4\gamma}       \quad   & \gamma \in[1,\frac {m(1-\alpha)} {m-1}),  \\
			\frac{m}{4}(1-\frac{1} {\gamma})   \quad   & \gamma \in[\frac {m(1-\alpha)} {m-1},\frac {m}{m-1}),  \\
			\frac{1}{4}  \quad   & \gamma \in[\frac {m}{m-1},\infty). \
		\end{cases}
	\end{equation}
\end{theorem}
