\title{Non-Abelian Gauge Effect for 2D Non-Hermitian Hatano-Nelson Model in Cylinder Type}

\author{Yiming Zhao}
\affiliation{School of Science, Qingdao University of Technology, Shandong, China}
\author{Yazhuang Miao}
