\section{Methodology} 
\label{Sec:methods}
{

\subsection{Solid mechanics of multi-phase materials}
\label{Sec:ProblemStatement}

\hspace{\parindent}
An architected multi-phase material domain $\Omega_{0}$ formed by the subdomains $\Omega_{1}$ and $\Omega_{2}$ is considered, with base material properties $E^{1}$, $\nu^{1}$ (Young's modulus and Poisson's ratio, $\Omega_{1}$, Fig.\,\,\ref{fig:bvp}), and $E^{2}$, $\nu^{2}$ ($\Omega_{2}$, Fig.\,\,\ref{fig:bvp}). The second material phase is defined as the union of $N$ non-intersecting simply-connected domains $\Omega_{2}^{i}$ ($i=1,2,...,N$), i.e: $\Omega_{2} = \bigcup_{i=1} \Omega_{2}^{i}$, while the boundary of each domain is given as $\Gamma_{1} = \partial\Omega_{0} \cup \Gamma_{I}^{1}$, and $\Gamma_{2} = \Gamma_{I}^{2}$ (Fig.\ref{fig:bvp}). Accordingly, the interface boundary between the two material phases, $\Omega_{1}$ and $\Omega_{2}$ is defined as $\Gamma_{I} = \Gamma_{I}^{1} \cap \Gamma_{I}^{2}$. Considering a homogeneous and linearly isotropic material for each of the phases and in the absence of distributed elastic body loads, the elastostatic displacement field $\mathbf{u}:\mathbf{x} \in \Omega_{0}\longmapsto (u_{1}(\mathbf{x}),u_{2}(\mathbf{x}))$ satisfies the following system of equilibrium, constitutive and kinematic equations \cite{EslamiBook}:
%
\begin{equation} \label{eq:21e1}
\begin{aligned}
\begin{matrix}
\Div \boldsymbol{\Sigma}(\mathbf{u}) = \mathbf{0}
\\
\boldsymbol{\Sigma}(\mathbf{u}) = \uplambda \text{tr} \big[\mathbf{E}(\mathbf{u})\big] \Tilde{\mathbf{I}} + 2\upmu\mathbf{E}(\mathbf{u})
\\
\mathbf{E}(\mathbf{u}) = \frac{1}{2}\big(\nabla \mathbf{u} + \mathbf{u} \nabla)
\end{matrix}
, \hspace{0.2cm} \mathbf{x} \in \Omega_{0} \hspace{0.2cm}
\end{aligned}
\end{equation}
%
where:
\begin{equation} \label{eq:21e2}
\begin{aligned}
\uplambda &= \frac{\mathrm{E} \upnu}{(1+\upnu)(1-2\upnu)}
,  \hspace{0.1cm}
\upmu &= \frac{\mathrm{E}}{2(1+\upnu)}
\end{aligned}
\end{equation}
%
and $\boldsymbol{\Sigma}(\mathbf{u}) = \Sigma_{ij}(\mathbf{u})\hat{\mathbf{x}}_{i} \otimes \hat{\mathbf{x}}_{j}$ and $\mathbf{E}(\mathbf{u}) = E_{ij}(\mathbf{u})\hat{\mathbf{x}}_{i} \otimes \hat{\mathbf{x}}_{j}$ denote the stress and strain second-rank tensors, respectively, with $\otimes$ being the tensor product operator and $\hat{\mathbf{x}}_{i}$ $(i=1,2)$ representing the Cartesian unit vectors. In Eq. \eqref{eq:21e1}, $\nabla$ stands for the nabla operator, $\text{tr}(\cdot)$ for the trace operator, while $\Tilde{\mathbf{I}} = \hat{\mathbf{x}}_{1} \otimes \hat{\mathbf{x}}_{1} + \hat{\mathbf{x}}_{2} \otimes \hat{\mathbf{x}}_{2}$ for the unit tensor. The interface  boundary $\Gamma_{I}$ as well as the exterior boundary $\partial\Omega_{0} = \Gamma_{D} \cup \Gamma_{N}$ are subject to the following conditions:
%
\begin{equation}\label{eq:21e3}
\begin{aligned}
\left.\begin{matrix}
\mathbf{u}^{1} = \mathbf{u}^{2}
\\ 
\mathbf{t}^{1}(\mathbf{u}) + \mathbf{t}^{2}(\mathbf{u}) = \mathbf{0}
\end{matrix}\right\}
, \hspace{0.1cm} \mathbf{x} \in \Gamma_{I}
  \hspace{0.5cm}
\begin{matrix}
\mathbf{u} = \mathbf{u}^{0}, \hspace{0.1cm} \mathbf{x} \in \Gamma_{D}
\\ 
\mathbf{t}(\mathbf{u}) = \mathbf{t}^{0}, \hspace{0.1cm} \mathbf{x} \in \Gamma_{N}
\end{matrix},
\hspace{0.2cm}
\partial \Omega_{0} = \Gamma_{D} \cup \Gamma_{N}
\end{aligned}
\end{equation}
%
where $\Gamma_{D}$ and $\Gamma_{N}$ correspond to the boundary parts where Dirichlet and Neumann boundary conditions are prescribed, respectively. In Eq. \eqref{eq:21e3}, the vector $\mathbf{t}(\mathbf{u}) = \nv \cdot \boldsymbol{\Sigma}(\mathbf{u})$ stands for the surface traction, and $\cdot$ and $\times$ represent the dot and cross products, respectively. The weak formulation of the solid mechanics problem is obtained by multiplying with an arbitrary vector function $\mathbf{w}: \Omega_{0} \rightarrow \mathbb{R}^{2}$: %The weak formulation of the solid mechanics problem is obtained by multiplying with a vector function $\mathbf{w} \in [H_{0}^{1}(\Omega_{0})]^{2}$:
%..............%
\begin{equation}  \label{eq:21e4a}
\begin{aligned}
\int_{\Omega_{0}} \mathbf{w} \cdot \Big[ \Div \boldsymbol{\Sigma}(\mathbf{u}) \Big] d\Omega = 0
\end{aligned}
\end{equation}
%..............%
Considering the vector identity $\mathbf{w} \cdot \big[ \Div \boldsymbol{\Sigma}^{T} \big] = \Div \big[\mathbf{w}\cdot \boldsymbol{\Sigma}\big] - \nabla \mathbf{w}:\boldsymbol{\Sigma}$ and the symmetry relation $\boldsymbol{\Sigma}^{T} = \boldsymbol{\Sigma}$, and implementing the divergence theorem, we obtain the following Petrov-Galerkin weak formulation for a pair of Hilbert spaces $V$ and $W$:
%..............%
\begin{equation}  \label{eq:21e4b}
\begin{aligned}
&\text{Find} \hspace{0.1cm} \mathbf{u} \in V \hspace{0.1cm} \text{such that}
\hspace{0.1cm}\\
&\mathcal{W}_{\Omega_{0}}(\mathbf{u};\mathbf{w}) = \int_{\partial\Omega_{0}} \mathbf{w} \cdot \mathbf{t}(\mathbf{u}) d\Gamma - \int_{\Omega_{0}} \nabla \mathbf{w} : \boldsymbol{\Sigma}(\mathbf{u}) d\Omega = 0 \hspace{0.1cm},  \forall \hspace{0.1cm} \mathbf{w} \in W
\end{aligned}
\end{equation}
%..............%
As the test function $\mathbf{w}$ should be chosen in such a way that the Dirichlet conditions on $\Gamma_{D}$ are satisfied, the space $W$ can be defined as the following Sobolev space $W = \{ \mathbf{w} \in [H^{1}(\Omega_{0})]^{2} \big | \mathbf{w} = \mathbf{0} \hspace{0.1cm} \text{on} \hspace{0.1cm} \Gamma_{D}\}$ \cite{evans10}. The definition of the solution space $V$ depends on the choice of the trial function. An appropriate space, that is the basis to define a finite element method is: $V = \{ \mathbf{u} \in [H^{1}(\Omega_{0})]^{2} \big | \mathbf{u} = \mathbf{u}_{0} \hspace{0.1cm} \text{on} \hspace{0.1cm} \Gamma_{D}\}$.
%
