\subsection{Variational Physics Informed Neural Networks (VPINN)}
\label{Sec:VarPINN}

%\hspace{\parindent}
In this sequel, the machine learning based Variational Physics Informed Neural Network (VPINN) formulation is presented.
\subsubsection{Formulation}
\label{Sec:vpinn}
\hspace{\parindent}
The displacement field is approximated by a deep feedforward neural network, i.e. $\mathbf{u} \cong \mathcal{N}:\Omega_{m}\times H_{\lambda}\longrightarrow \mathbb{R}^{2}$, where:
%..............%
\begin{equation} \label{eq:221e1}
\begin{aligned}
\mathcal{N}: (\mathbf{x};\boldsymbol{\lambda}) \longmapsto g^{N} \circ g^{N-1} \circ \cdots \circ g^{1}(\mathbf{x})
\end{aligned}
\end{equation}
%..............%
where $\boldsymbol{\lambda} = [\mathbf{W},\mathbf{b} ]  \in H_{\lambda}$ denotes the trainable parameters $\mathbf{W}$ and $\mathbf{b}$, while $g^{i} = \sigma^{i}(\mathbf{W}^{i} \cdot \mathbf{z}^{i} + \mathbf{b}^{i})$ denotes the $i^{th}$ layer maps of the $N^{th}$ neural network layer, respectively, with $\sigma^{i}$ being the corresponding activation function, whereas $\mathbf{z}^{i}$ denotes the layer inputs. The PINN framework requires the addition of information arising from the physical model to the loss function. More specifically, the output of the neural network is forced to satisfy the partial differential operator of a specific physics problem on a selected set of points that are interior to the domain of interest \cite{RAISSI2019686,RAISSI2018125,712178}. Hence, the loss function $\mathcal{L}(\boldsymbol{\lambda})$ is expressed as the weighted sum of the loss term concerning the physics $\mathcal{E}$, the loss terms of the boundary $\mathcal{B}$, and domain data $\mathcal{D}$, as follows:
%
\begin{equation} \label{eq:221e2}
\begin{aligned}
\mathcal{L}(\boldsymbol{\lambda}) = w_{1}\mathcal{E}(\boldsymbol{\lambda}) + w_{2}\mathcal{B}(\boldsymbol{\lambda}) + w_{3}\mathcal{D}(\boldsymbol{\lambda})
\end{aligned}
\end{equation}
%
where the weights $w_{1},w_{2},w_{3}$ range between $[0,1]$ and are adjusted accordingly to provide a different weight to each of the loss terms. 

In a Variational Physics Informed Neural Network, instead of the differential operator, the weak formulation of the physical problem is forced to be satisfied \cite{KHARAZMI2021113547,pmlr-v120-khodayi-mehr20a}. Based on Eq. \eqref{eq:21e4b} and considering a set of $N_{w}$ test functions $\mathbf{w}^{k} \in W$ ($k=1,2,...,N_{w}$), the physics-based loss term $\mathcal{E}(\boldsymbol{\lambda})$ takes the form:
%
\begin{equation} \label{eq:221e4}
\begin{aligned}
&\mathcal{E}(\boldsymbol{\lambda}) = \sum_{\Omega_{m}} \sum_{k=1}^{N_{w}}
\Big (   
\int_{\Omega_{m}} \nabla \mathbf{w}^{k} : \boldsymbol{\Sigma}(\mathcal{N}(\mathbf{x};\boldsymbol{\lambda})) d\Omega - 
\int_{\partial\Omega_{m}} \mathbf{w}^{k} \cdot \mathbf{t}(\mathcal{N}(\mathbf{x};\boldsymbol{\lambda})) d\Gamma
\Big ) ^{2}
\end{aligned}
\end{equation}
%
Here the neural network $\mathcal{N}$ approximates the weak PDE solution $\mathbf{u}$, therefore, an appropriate solution Hilbert space for Eq. \eqref{eq:21e4b} is $V = \{ \mathcal{N}:\Omega_{m}\times H_{\lambda}\rightarrow \mathbb{R}^{2} \} \cap H^{1}(\Omega_{0})$ \cite{rojas2024}.

The choice of the test function $\mathbf{w}$ leads to a specific variational formulation \cite{KHARAZMI2021113547}. Focusing on a local Petrov-Galerkin formulation, for each domain $\Omega_{m}$, a discretization $\mathcal{T}(\Omega_{m})$ is required, whereas for each subdomain $E \in \mathcal{T}(\Omega_{m})$, the test function $\mathbf{w}_{E}^{k}$ is defined as: $\mathbf{w}_{E}^{k} = [\Psi_{E}^{k}(\boldsymbol{\xi}), \Psi_{E}^{k}(\boldsymbol{\xi})]^{T}$. For the present study, the shape functions of the linear 4-node element are employed as test functions, therefore, $N_{w} = 4$ and $\Psi_{E}^{k}(\boldsymbol{\xi})$ denotes the shape function that corresponds to the $k^{th}$ node of the subdomain $E$. It should be noted that in the case of the strong form PINN formulation, the loss term $\mathcal{E}$ of Eq. \eqref{eq:221e2} concerns the Navier differential operator:
\begin{equation} \label{eq:221e4b}
\begin{aligned}
&\mathcal{E}(\boldsymbol{\lambda}) = \frac{1}{\#P_{\Omega}} \sum_{i=1}^{\#P_{\Omega}} \big \| \upmu \nabla^{2}\mathcal{N}(\mathbf{x}^{i};\boldsymbol{\lambda}) + (\uplambda + \upmu) \nabla \nabla \cdot \mathcal{N}(\mathbf{x}^{i};\boldsymbol{\lambda})  \big \|^{2}
\end{aligned}
\end{equation}
%
where $P_{\Omega}$ in Eq. \eqref{eq:221e4b} is a set of points $\mathbf{x} \in \Omega_{0}$, that are used for the collocation of the Navier's differential operator. In order to define the remaining loss terms of Eq. \eqref{eq:221e2}, a set of points $S_{\partial \Omega}$ is considered, located on the boundary $\partial \Omega_{0} \cup \Gamma_{I}$ where the target values of the displacement field are given. Moreover, a set of additional auxiliary points $S_{\Omega}$, interior to the $\Omega_{0}$ domain, with known displacement vector is considered. As such, the following training sets $D_{\partial\Omega} = \{ (\mathbf{x}^{i}, \mathbf{u}^{i}) | \mathbf{x}^{i} \in S_{\partial \Omega}, \hspace{0.1cm} \mathbf{u} = \mathbf{u}(\mathbf{x}^{i})  \}$ and domain data $D_{\Omega} = \{ (\mathbf{x}^{i}, \mathbf{u}^{i}) | \mathbf{x}^{i} \in S_{\Omega}, \hspace{0.1cm} \mathbf{u} = \mathbf{u}(\mathbf{x}^{i})  \}$ are defined. Given the aforementioned training sets, the present work employs the Mean Squared Error (MSE) expressions for the loss terms $\mathcal{B}$ and $\mathcal{D}$, i.e.:
%
\begin{equation} \label{eq:221_mse}
\begin{aligned}
&\mathcal{B}(\boldsymbol{\lambda}) = \frac{1}{\#D_{\partial\Omega}} \sum_{i=1}^{\#D_{\partial\Omega}} \big \|\mathcal{N}(\mathbf{x}^{i};\boldsymbol{\lambda}) - \mathbf{u}^{i} \big \|^{2}
, \hspace{0.5cm}
&\mathcal{D}(\boldsymbol{\lambda}) = \frac{1}{\#D_{\Omega}} \sum_{i=1}^{\#D_{\Omega}} \big \| \mathcal{N}(\mathbf{x}^{i};\boldsymbol{\lambda}) - \mathbf{u}^{i} \big \|^{2}
\end{aligned}
\end{equation}
%

The training process aims to find the parameters $\boldsymbol{\lambda}^{*}$ such that:
%
\begin{equation} \label{eq:221e5}
\begin{aligned}
\boldsymbol{\lambda}^{*} = \argminA_{\boldsymbol{\lambda}} \mathcal{L}(\boldsymbol{\lambda})
\end{aligned}
\end{equation}
%

The minimization problem \eqref{eq:221e5} is solved iteratively through a gradient-based procedure, employing the Adam (Adaptive Moment Estimation) optimization algorithm \cite{DBLP:journals/corr/KingmaB14}. The derivatives of Eq. \eqref{eq:221e4} with respect to the position vector $\mathbf{x}$, as well as the gradient components of the loss function (Eq. \eqref{eq:221e2}) with respect to the network parameters $\boldsymbol{\lambda}$ are computed by implementing automatic differentiation \cite{JMLR:v18:17-468}, implemented in Tensorflow \cite{tensorflow2015-whitepaper}.
Figure \ref{fig:training} summarizes the training process of the VPINN. The neural network takes as input the position vector that belongs to the subdomains $\Omega_{1},\Omega_{2}$ or on their boundaries $\partial\Omega_{1},\partial\Omega_{2}$, while the displacement vector field is calculated as the network output. Then, for the interior integration points, the stress tensor is calculated, evaluating the derivatives of the displacement components.
%
\begin{figure}[H]
\centering
\includegraphics[scale=0.4]{fig2_new.png} 
\caption{The training process of the Neural Network based on a Variational formulation.}
\label{fig:training}
\end{figure}
%

\subsubsection{Tree-based integration}
\label{Sec:tree}
\hspace{\parindent}
An indispensable part of the formulation is the evaluation of the weak-form integrals of Eq. \eqref{eq:221e4}. In the present work, a tree-based integration algorithm is developed for the numerical integration of the weak formulation. The starting point of the algorirthm concerns the segmentation of the subdomains $\Omega_{1}$ and $\Omega_{2}$ with the aid of a quadtree $\mathcal{Q}(\Omega_{0})$, as depicted in Fig. \ref{fig:integration}a. Considering the cells $E$ as the vertices of the quadtree $\mathcal{Q}(\Omega_{0})$, the set $S(E)$ is formed by the sons $\tau$ of each vertex cell $E$, containing $4$ square cells of half size. The segmentation is obtained recursively as follows:
\begin{enumerate}
    \item Setting the bounding box $E = r$ as the root cell, i.e.: $r \subseteq \Omega_{0}$, the level $0$ ($l_{0}$) of the quadtree is defined. 
    \item A set of points $\boldsymbol{\chi}$ is distributed uniformly in $E$. Then, the following sets are defined: $\Xi_{1} = \{ \boldsymbol{\chi} \in E | E \cap \Omega_{1} \neq \emptyset \}$ and $\Xi_{2} = \{ \boldsymbol{\chi} \in E | E \cap \Omega_{2} \neq \emptyset \}$
    \item The following splitting criterion is defined: If $\Xi_{1} \neq \emptyset$ and $\Xi_{2} \neq \emptyset$ then split the cell $E=r$: $E \mapsto S(E)$. For each of the sons $\tau \in S(E)$ repeat the steps 2 and 3. If the splitting criterion is not satisfied then the set of sons is empty $S(E) = \emptyset$.  
    \item Upon completing the segmentation process, the set of the tree leafs is defined as $\mathcal{T}(\Omega_{0}) = \{ E \in \mathcal{Q}(\Omega_{0}) | S(E) = \emptyset \}$. The set of integration cells is defined as the disjoint set $\mathcal{T}(\Omega_{1}) \sqcup \mathcal{T}(\Omega_{2}) \subset \mathcal{T}(\Omega_{0})$ containing the leafs $\{E \in \mathcal{T}(\Omega_{0}) | E \cap \Omega_{1} = \emptyset, E \cap \Omega_{2} = \emptyset\}$.
\end{enumerate}

For each cell $E$, a quadrature rule $\mathcal{G}(E) = \{ (\boldsymbol{\xi}, h(\boldsymbol{\xi})) \}$ is employed to generate the integration points $\boldsymbol{\xi}$ and weights $h(\boldsymbol{\xi})$. Thus, the sets $\mathcal{G}(\mathcal{T}(\Omega_{1})) = \bigcup_{E \in \mathcal{T}(\Omega_{1})} \mathcal{G}(E)$ and $\mathcal{G}(\mathcal{T}(\Omega_{2})) = \bigcup_{E \in \mathcal{T}(\Omega_{2})} \mathcal{G}(E)$ are formed, containing the pairs $(\boldsymbol{\xi}, h(\boldsymbol{\xi})) \in \mathcal{G}(E)$ for all $E \in \mathcal{T}(\Omega_{1}) \sqcup \mathcal{T}(\Omega_{2})$, as shown in Fig. \ref{fig:integration}b. Mapping the pair of each cell $(\boldsymbol{\xi}, h(\boldsymbol{\xi}))$ to the global sets of integration points $\mathcal{G}(\mathcal{T}(\Omega_{1}))$, $\mathcal{G}(\mathcal{T}(\Omega_{2}))$, the integration of a function $f: \Omega \longrightarrow \mathbb{R}$ can be represented as the following matrix multiplication:
%
\begin{equation} \label{eq:222e1}
\begin{aligned}
\int_{\Omega}f d\Omega \cong \sum_{E\in \mathcal{T}(\Omega)} \int_{E} f d\Omega \cong \sum_{E\in \mathcal{T}(\Omega)} \sum_{(\boldsymbol{\xi},h(\boldsymbol{\xi})) \in \mathcal{G}(E)} h(\xi)f(\xi) = \sum_{(\boldsymbol{\xi},h(\boldsymbol{\xi})) \in \mathcal{G}(\Omega)} h(\boldsymbol{\xi})f(\boldsymbol{\xi}) = \mathbf{h}^{T} \cdot \mathbf{f}
\end{aligned}
\end{equation}
%
\noindent where the vectors $\mathbf{f}$ and $\mathbf{h}$ contain the function evaluations $f(\xi)$ on the integration points and the corresponding weights $h(\xi)$. Therefore, the weak form integral of Eq. \eqref{eq:221e4} is evaluated as:
%
\begin{equation} \label{eq:222e2}
\begin{aligned}
\int_{\Omega_{m}} \nabla \mathbf{w}^{k} : \boldsymbol{\Sigma}(\mathcal{N}(\mathbf{x};\boldsymbol{\lambda})) d\Omega 
&\cong
\sum_{E\in \mathcal{T}(\Omega)}
\int_{E} \nabla \mathbf{w}_{E}^{k} : \boldsymbol{\Sigma}(\mathcal{N}(\mathbf{x};\boldsymbol{\lambda})) d\Omega = \sum_{(\boldsymbol{\xi},h(\boldsymbol{\xi})) \in \mathcal{G}(\Omega)} h(\boldsymbol{\xi})f(\boldsymbol{\xi}) = \mathbf{h}^{T} \cdot \mathbf{f}
\\
&f(\boldsymbol{\xi}) = \nabla \mathbf{w}_{E}^{k}(\boldsymbol{\xi}) : \boldsymbol{\Sigma}(\mathcal{N}(\boldsymbol{\xi};\boldsymbol{\lambda}))
\end{aligned}
\end{equation}
%

The adaptive sizing of the integration cells due to the quadtree structures offers the advantage of computational efficiency during the integration procedure, as smaller cells are used near the domain boundaries, where refinement is required, while a coarser distribution of cells is used for the rest of the domain. Furthermore, the generation of quadtree representations requires only boundary information, providing substantial flexibility in the treatment of different multi-phase materials with complex inner architetctures, without the use of extra CAD tools.
%
