%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\newsection{ \large Bosonic continuous-spin field in $AdS_{d+1}$, $d>3$}\label{lc-action}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\noindent {\bf Field content}. To discuss a light-cone gauge bosonic CSF in $AdS_{d+1}$, $d>3$, we introduce the following set of fields:%
%
\footnote{ We use the Poincar\'e parametrization of AdS: $ds^2=R^2(-dx_0^2+dx_i^2+dx_{d-1}^2+dz^2)/z^2$ and light-cone coordinates $x^\pm$,  $x^\pm:=(x^{d-1} \pm x^0)/\sqrt{2}$, where
$x^+$ stands for a light-cone time. For the coordinates and derivatives we use the conventions: $x^I= (x^i, x^d$), $x^d \equiv z$,
$\partial^i=\partial_i\equiv\partial/\partial x^i$,
$\partial_z\equiv\partial/\partial z$, $\partial^\pm=\partial_\mp
\equiv \partial/\partial x^\mp$, where indices take the values
$i,j =1,\ldots, d-2$; $I,J,K,L=1,2,\ldots,d-2, d$. Vectors of the $so(d-1)$
algebra are decomposed as $X^I=(X^i,X^z)$, $X^I Y^I = X^i Y^i + X^zY^z$. %
Our fields are singlets of internal symmetries. We expect that internal symmetries can be incorporated by using the standard methods considered, e.g., in Refs.\cite{Konstein:1989ij}-\cite{Skvortsov:2020wtf}). For $n_\minrm=0$, we note the intriguing matching of field content \rf{09062025-man02-01} and the one in higher-spin theory in Refs.\cite{Vasiliev:1990en}. For the recent development in this topic, see Refs.\cite{Tatarenko:2024csa}-\cite{DeFilippi:2019jqq}. Other interesting related studies may be found in Refs.\cite{Didenko:2021vui}-\cite{Tran:2025uad}.
%
}
%
{\small
%
\be \label{09062025-man02-01}
%
\sum_{n=n_{\min}}^\infty \oplus \,\,\phi^{I_1\ldots I_n}(x,z)\,, \hspace{3cm}  \phi^{III_3\ldots I_n}(x,z) = 0\,,
%
\ee
%
}
%
\!\!where $n_\minrm$ depends on type of CSF and may be read from the last column in Table I, while  fields $\phi^{I_1\ldots I_n}(x,z)$ are scalar, vector, and {\it traceless} totally symmetric tensor fields of the $so(d-1)$ algebra. To use a index free notation we introduce a unit vector $u^I$, $u^Iu^I=1$ which describes a sphere $S^{N-1}$ embedded in $\Eo^N$, $N=d-1$. The continuous-spin field $\phi(x,z,u)$ is defined as
%
{\small
%
\beq
%
\label{09062025-man02-05} && \phi(x,z,u) = \sum_{n=n_\minrm}^\infty \phi_n(x,z,u)\,,\quad \ \phi_n(x,z,u): = \frac{1}{ n!\sqrt{\mu_n\tau_n S_{N-1}^{\phantom{1}} } } u^{I_1} \ldots u^{I_n} \phi^{I_1\ldots I_n}(x,z)\,,
%
\nonumber\\
%
&& \hspace{1.3cm} \tau_n = \frac{ \Gamma(\frac{N}{2}) }{ 2^n\Gamma(\frac{N}{2}+n) }\,,\qquad S_{N-1} =  \frac{ 2\pi^{N/2} }{ \Gamma(\frac{N}{2}) }\,, \qquad N:= d-1\,,
%
\eeq
%
}
\!where $S_{N-1}$ stands for surface area of the sphere $S^{N-1}$ of radius 1 embedded in $\Eo^N$.



\noinbf{Light-cone gauge action and spin operators}. Light-cone gauge action for CSF takes the form%
%
\footnote{Light-cone gauge approach for fields in AdS was developed in Refs.\cite{Metsaev:1999ui}.  For the update presentation, see Ref.\cite{Metsaev:2019opn}.
%
}
%
{\small
\be \label{09062025-man02-10}
%
S  = \int dz d^dx du\, \phi^*(x,z,u) \bigl(\Box + \partial_z^2 - \frac{1}{z^2}A\bigr)\phi(x,z,u)\,, \qquad \Box = 2\partial^+\partial^- + \partial^i\partial^i \,,
%
\ee
%
}
%
\!where $du$ is the rotation invariant measure on the sphere $S^{N-1}$.
Operator $A$ is expressible in terms of operators $M^{IJ}$, $B^I$ which we refer to as spin operators. The operators $M^{IJ}$ obey commutators of the $so(d-1)$ algebra, while the operators $B^I$ are AdS cousins of a spin boost operators in flat space. Using the decompositions $M^{IJ}= M^{zi}, M^{ij}$, $B^I= B^z, B^i$, we note the relation for the $A$:
%
\be \label{09062025-man02-14}
%
A  = \CC_2 + 2B^z + 2M^{zi}M^{zi}+\frac{1}{2}M^{ij}M^{ij} +\frac{d^2-1}{4}\,,
%
\ee
%
where $\CC_n$ stands for eigenvalue of the $n$th order Casimir of the $so(d,2)$ algebra. The $\CC_2$ and $\CC_4$ can be presented in terms of labels $p$ and $q$ which are complex-valued in general,%
%
\footnote{$p$ and $q$ are related to conformal dimension $\Delta$ and spin $s$ as $(\Delta - \frac{N+1}{2})^2=p^2$, $(s+\frac{N-1}{2})^2 = q^2$.}
%
{\small
\be \label{09062025-man02-17}
%
\CC_2 =  p^2 + q^2 - \frac{N^2+1}{2}\,,\qquad  \CC_4 = \big( p^2 - \frac{(N-1)^2}{4} \big) \big(q^2 - \frac{(N-1)^2}{4} \big)\,.
%
\ee
%
}
%
\!From \rf{09062025-man02-10}, \rf{09062025-man02-14}, we see that in order to fix the  action one needs to find the spin operators $M^{IJ}$, $B^I$ which should satisfy eqs.(2.13),(2.14) in Ref.\cite{Metsaev:2019opn}. Solution to the operators $M^{IJ}$ is obvious,
%
\be \label{09062025-man02-19}
%
M^{IJ} = u^I \PP^J -  u^J \PP^I\,,\qquad [\PP^I,u^J]= \theta^{IJ}\,, \qquad \theta^{IJ}:=\delta^{IJ} - u^I u^J\,,
%
\ee
%
where, $\PP^I$ stands for the derivative of the unit vector $u^I$. It is finding of the operator $B^I$ that requires some efforts. We find the following solution for the operator $B^I$:
%
{\small
\be \label{09062025-man02-21}
%
B^I = -(p + q)\big( \PP^I + \frac{1-N}{2} u^I\big)  - \Big( pq + \frac{(N-1)(N-3)}{4}\Big) u^I + \half \{u^I,\PP^2\}\,,
%
\ee
%
}
\!where $\{a,b\}:=ab+ba$, $\PP^2:=\PP^I\PP^I$. Remarkably, in contrast to the somewhat complicated expression for $B^I$ in the oscillator approach in Ref.\cite{Metsaev:2019opn}, operator $B^I$ \rf{09062025-man02-21} is realized as a simple differential operator. As side remarks: \abf) $B^I$ can be rewritten as {\small $ B^I = - p M^I + \half \{M^{IJ},M^J\}$, $M^I:=\PP^I + (\frac{1-N}{2}+q)u^I$}; \bbf) field $\phi_n$ \rf{09062025-man02-05} obeys the relation $(\PP^2+n(n+N-2))\phi_n=0$.


The field $\phi^*$ entering action \rf{09062025-man02-10} and an inner scalar product for field \rf{09062025-man02-05} are defined as
%
{\small
\be \label{09062025-man02-23}
%
\phi^*(x,z,u) := \sum_{n=n_\minrm}^\infty \mu_n  \phi_n^\dagger(x,z,u)\,, \qquad
(\phi,\phi): = \sum_{n=n_\minrm}^\infty \mu_n \int du\, \phi_n^\dagger(x,z,u) \phi_n(x,z,u)\,,
%
\ee
%
}
%
\!where $\mu_n$ are presented below, while the inner scalar product can be rewritten as  $(\phi,\phi) = \int du \phi^* \phi$.

\noinbf{Classification of classically unitary CSFs}. Using inner scalar product \rf{09062025-man02-23}, we note that, if the operators $A$, $B^I$, $M^{IJ}$ and the measure  $\mu_n$ meet the following two requirements
%
{\small
\be
%
\label{09062025-man02-27} \abf)\quad A^\dagger = A\,, \quad B^{I\dagger} = B^I\,,\quad M^{IJ\dagger} = - M^{IJ}\,, \qquad   \bbf) \quad \mu_n>0\,, \ \ \ n=n_\minrm,n_\minrm+1,\ldots,\infty, \quad
%
\ee
%
}
%
\!then we refer to our CSF as {\it classically unitary} CSF. The requirement $\abf)$ in \rf{09062025-man02-27} implies that light-cone gauge action \rf{09062025-man02-10} is real-valued, while the requirement $\bbf)$ in \rf{09062025-man02-27} tells us that the kinetic terms of the fields $\phi_n(x,z,u)$ should enter the action with the correct sign.

Using \rf{09062025-man02-21}, \rf{09062025-man02-27} we can find all allowed values of the labels $p$, $q$ and solution for the $\mu_n$ and hence to introduce a classification of the classically unitary CSFs. To this end, first, by requiring the $\CC_2$ and $\CC_4$ to be real-valued, we find the restrictions on the labels $p$, $q$,
%
{\small
\beq
%
&& \hspace{-1cm} \ibf: \ \ \Re p =0, \ \ \Re q=0; \hspace{1cm}  \iibf: \ \ p^*= q; \hspace{3cm} \iiibf: \ \ p^*= -q\,;
%
\nonumber\\[-11pt]
%
\label{09062025-man02-30} &&
%
\\[-9pt]
%
&& \hspace{-1cm} \ivbf: \ \ \Re p =0,\ \  \Im q=0; \hspace{0.8cm} \vbf: \ \ \Im p=0, \ \  \Re q=0\,; \hspace{1.1cm} \vibf: \ \ \Im p=0, \ \  \Im q=0.\qquad
%
\nonumber
%
\eeq
%
}
%
\!Second, using restrictions imposed by the classical unitarity \rf{09062025-man02-27}, we find the $\mu_n$ and additional restrictions on the labels $p$, $q$. Our results are summarized in  Table I.

\noinbf{Flat space limit}. We use the notation $B_\flatrm^I$ for the flat space cousin of the operator $B^I$ \rf{09062025-man02-21} and the notation CSF${}_\flatrm$ for CSF in the flat space. In the flat space limit, $R\sim \infty$, the asymptotic behaviour of the $B^I$ takes the form $B^I \sim R B_\flatrm^I$, where $R$ is a radius of AdS space.
For massless CSF${}_\flatrm$, $B_\flatrm^I = \kappa u^I$, $\Im\, \kappa=0$, while, for massive CSF${}_\flatrm$, {\small $B_\flatrm^I = -\irm |m| (\PP + (\frac{1-N}{2}+q)u^I)$, $\Re\, m=0$}.
In the flat space limit, we note that
%
\abf) for $p\sim R$, $q\sim R^0$, the series $\ibf\hbox{-}\pbf$ are reduced to massive CSF${}_\flatrm$, while for $p=-q$, $q\sim R$, to massless CSF${}_\flatrm$;
%
\bbf) for $p\sim R^{1/2}$, the series $\iibf\hbox{-}\pbf$, $\iiibf\hbox{-}\pbf$ are reduced to massless CSF${}_\flatrm$;
%
\cbf) for $p \sim R$, the series $\ivbf\hbox{-}\cbf$ and $\ivbf\hbox{-}\dbf$ are reduced to massive CSF${}_\flatrm$ of the complementary and discrete series, while, for $q\sim R$, the series $\vbf\hbox{-}\cbf$, $\vbf\hbox{-}\dbf$ are reduced to massive CSF${}_\flatrm$ of the complementary and discrete series;
%
\dbf) for $p \sim R^a$, $q \sim R^{1-a}$, $0< a < 1$, the series $\vibf\hbox{-}\cbf\hbox{-}1$ are reduced to massless CSF${}_\flatrm$;
%
\ebf) for $p \sim R^{1/2}$, the series $\vibf\hbox{-}\cbf\hbox{-}2^\pm$ are reduced to massless CSF${}_\flatrm$;
%
\fbf) the series  $\vibf\hbox{-}\cbf$, $\vibf\hbox{-}\dbf$, and  $\vibf\hbox{-}\dbf^*$ are not reduced to CSF${}_\flatrm$.

Now we just conjecture two of the possible definitions of masslessness for CSF in AdS.

\noinbf{Masslessness in AdS. I}. For massless CSF${}_\flatrm$ we note that \abf) the $\PP^I$-term does not contribute to $B_\flatrm^I=\kappa u^I$; \bbf) $n_\minrm=0$ in \rf{09062025-man02-01}. This motivates us to define the massless CSF in AdS by the relations $p=-q$ in \rf{09062025-man02-21} and $n_\minrm=0$ in \rf{09062025-man02-01}. From Table I, we learn then that the massless CSFs in AdS could be related to series $\ibf\hbox{-}\pbf$ and $\vibf\hbox{-}\cbf\hbox{-}2_k^-$, where we should add the additional restriction $p=-q$ in series $\ibf\hbox{-}\pbf$. Note that the $\{u^I,\PP^2\}$-term \rf{09062025-man02-21} is unavoidable in  AdS.


\noinbf{Masslessness in AdS. II}. The series $\iibf$, $\iiibf$ \rf{09062025-man02-30} are represented as the series $\iibf\hbox{-}\pbf$, $\iiibf\hbox{-}\pbf$ in Table I.  In the flat space limit, these series are reduced to massless CSF${}_\flatrm$. Therefore, in principle, the series $\iibf\hbox{-}\pbf$, $\iiibf\hbox{-}\pbf$ could also be selected as the candidates for massless CSF in AdS.

\noinbf{Comparison with oscillator formulation}. We compare the restrictions on $p,q$ in Table I and the ones in the oscillator approach in Ref.\cite{Metsaev:2019opn}. The restrictions on $p$, $q$ for series $\ibf$, $\iibf$, $\iiibf$ in Table I and Ref.\cite{Metsaev:2019opn} coincide. For series $\ivbf$, the oscillator formulation leads to the restrictions only on $|q|$. Therefore we compare only the restrictions on $|q|$. We then note that, for series $\ivbf$, the restrictions on $|q|$ in Table I coincide with the ones given in (3.25), (3.33), (3.46) in Ref.\cite{Metsaev:2019opn}. If we make the replacement $q\rightarrow p$ and use (3.26), (3.34), (3.47) in Ref.\cite{Metsaev:2019opn}, then all we said for series $\ivbf$ remains to be valid for series $\vbf$. For series $\vibf\hbox{-}\cbf$, $\vibf\hbox{-}\cbf\hbox{-}1$, $\vibf\hbox{-}\cbf\hbox{-}2^\pm$, the restrictions on $|p|$, $|q|$ in Table I coincide with the ones given in (3.27), (3.28), (3.29) in Ref.\cite{Metsaev:2019opn}.

We note the seeming disagreement between the restrictions on $|p|$ and $|q|$ for series $\vibf\hbox{-}\dbf\hbox{-}1$, $\vibf\hbox{-}\dbf\hbox{-}2$ in Table I and their cousins in (3.36), (3.38) in Ref.\cite{Metsaev:2019opn}.  Resolution of this puzzle is trivial. In Ref.\cite{Metsaev:2019opn}, starting with the field {\small $\phi^{0,\infty}$, $\phi^{M,N}:=\sum_{n=M}^N \phi_n$} and setting $q_n^2=x_n$,  we used the decomposition $\phi^{0,\infty} = \phi^{0,s}+\phi^{s+1,\infty}$ and  imposed the classical unitarity restrictions on the both fields - the finite component field $\phi^{0,s}$ and CSF $\phi^{s+1,\infty}$. This leads to restrictions (3.36), (3.38) in Ref.\cite{Metsaev:2019opn}. However, if we ignore the field $\phi^{0,s}$ and consider the classical unitarity restrictions only for the CSF $\phi^{s+1,\infty}$, then restrictions on $p_n^2$ in (3.38) in Ref.\cite{Metsaev:2019opn} should be replaced by the restriction $p_n^2 < x_{n+1}$. Doing so, we find the  agreement between restrictions on $|p|$, $|q|$ for series $\vibf\hbox{-}\dbf\hbox{-}1$, $\vibf\hbox{-}\dbf\hbox{-}2$ in Table I and their cousin in (3.36) in Ref.\cite{Metsaev:2019opn} and the restriction $p_n^2 < x_{n+1}$. All we said for series $\vbf\hbox{-}\dbf$ is replicated for  series $\vibf\hbox{-}\dbf^*$ in Table I and their cousins in (3.35), (3.37) in Ref.\cite{Metsaev:2019opn}.





