\noinbf{Massive spin-$s$ field, $s\in\No_0$}. Massive spin-$s$ field in $AdS_{d+1}$ is associated with series $\vibf$. For such field, we find $ \phi = \sum_{n=0}^s \phi_n$,
where $\phi_n$ and $B^I$ take the same form as in \rf{09062025-man02-05}, \rf{09062025-man02-21}. For spin-$s$ massive field, $s\in \No$, using the Pochhammer symbol $(a)_b$,  we obtain
%
{\small
\be  \label{09062025-man02-50}
%
q =  s + \frac{N-1}{2}\,, \qquad  |p| >  s + \frac{N-3}{2} \,, \quad \mu_n =  \frac{(s-n)!}{(s + N - 1 + n)_{s-n}}\frac{ (p - s- \frac{N-3}{2})_{s-n} }{ (p + \frac{N-1}{2}+n)_{s-n} } \,.
%
\ee
%
}
\!The label $p$ is related to mass as $p^2 = R^2 m^2 + (s+ \frac{N-3}{2})^2$ where the massless limit is defined as $m^2\rightarrow 0$.
For massive scalar field $\phi=\phi_0$, we get $B^I\phi=0$, $q=\frac{N-1}{2}$, $p^2= R^2m^2 + \frac{(N+1)^2}{4}$, where the massless limit is defined as $R^2 m^2\rightarrow - \frac{N(N+2)}{4}$ and we recall the BF-bound, $R^2m^2 > - \frac{(N+1)^2}{4}$.
As side remark, for spin-$s$ massless field, $s\in \No_0$, our study in Ref.\cite{Metsaev:1999ui} implies that $B^I=0$.



\vspace{-0.2cm}
\newsection{ \large Bosonic and fermionic continuous-spin fields in $AdS_4$}



\noindent {\bf Field content}. To discuss light-cone gauge bosonic and fermionic CSFs propagating in $AdS_4$  we find it convenient to use helicity fields denoted as
%
\be
%
\phi_{n+\epsilon}(x,z), \quad \epsilon = 0 \ \ \hbox{for bosons}\,,  \quad \epsilon = \half \ \ \hbox{for fermions}\,, \quad n \in \Zo\,,
%
\ee
%
where the field $\phi_{n+\epsilon}(x,z)$ has helicity equal to $n+\epsilon$. We then use an angle coordinate  $\varphi=[0,2\pi]$ which parameterize a sphere $S^1$ and introduce the CSF denoted as $\phi(x,z,\varphi)$,
%
{\small
\be \label{18062025-man02-05}
%
\phi(x,z,\varphi) = \sum_{n} \phi_{n+\epsilon}(x,z,\varphi) e_n  \,, \qquad e_n := \frac{e^{\irm n\varphi}}{\sqrt{2\pi \mu_n}} \,,
%
\ee
%
}
%
\!where values of $n$ and measures $\mu_n$ depend on type of CSF and may be found in Table II.

\noinbf{Light-cone gauge action}. Light-cone gauge action for CSF in $AdS_4$ takes the form
%
{\small
\beq
%
&& S  = \int dz d^3x d\varphi\, \phi^*(x,z,\varphi) \Big(\frac{\irm }{\partial^+}\Big)^{2\epsilon} \bigl(\Box + \partial_z^2 - \frac{1}{z^2}A\bigr)\phi(x,z,\varphi)\,,\quad  \Box = 2\partial^+\partial^- + \partial^1\partial^1 \,,\qquad
%
\nonumber\\
%
\label{18062025-man02-14} && \hspace{4cm} A  =  \CC_2 + \irm \sqrt{2}(B^\Lsm-B^\Rsm) -  2M^{\Rsm\Lsm}M^{\Rsm\Lsm} + 2\,,
%
\eeq
%
}
%
%
\!where $M^{\Rsm\Lsm}$ is a helicity operator, while $B^{\Rsm,\Lsm}$ are helicity boost operators. Eigenvalues of the 2nd and 4th order Casimirs of the $so(3,2)$ algebra $\CC_2$ and $\CC_4$ are obtained by setting $N=2$ in \rf{09062025-man02-17},
%
{\small
\be \label{18062025-man02-17}
%
\CC_2 =  p^2 + q^2 - \frac{5}{2}\,,\qquad  \CC_4 = \big( p^2 - \frac{1}{4} \big) \big(q^2 - \frac{1}{4} \big)\,.
%
\ee
%
}
%
\!For more details of the light-cone gauge approach in $AdS_4$, see Sec.5 in Ref.\cite{Metsaev:2022ndg}. In order to fix action \rf{18062025-man02-14} we have to find the spin operators which should satisfy equations given below in \rf{21062025-man02-01}. We find the following realization of spin operators on CSF \rf{18062025-man02-05}:
%
{\small
\beq
%
\label{18062025-man02-21} && B^\Rsm = -\frac{e^{\irm \varphi}}{\sqrt{2}} (\rh-q)(\rh-p)\,,\hspace{1cm} B^\Lsm = -\frac{e^{-\irm \varphi}}{\sqrt{2}} (\rh -1 + q)(\rh -1 + p)\,,
%
\nonumber\\
%
&& M^{\Rsm\Lsm} = -\irm \partial_\varphi + \epsilon\,, \hspace{2.7cm} \rh:= -\irm \partial_\varphi+ \half +\epsilon\,, \qquad \partial_\varphi:=\partial/\partial\varphi\,.
%
\eeq
}
%
\!The field $\phi^*$ in \rf{18062025-man02-14} and an inner scalar product for field \rf{18062025-man02-05} are defined by the relations
%
{\small
\be
%
\label{18062025-man02-23} \phi^*(x,z,\varphi) := \sum_n \mu_n  \phi_{n+\epsilon}^\dagger(x,z,\varphi)\,, \qquad (\phi,\phi): = \sum_n \mu_n \int_0^{2\pi}\!\! d\varphi\, \phi_{n+\epsilon}^\dagger(x,z,\varphi) \phi_{n+\epsilon}(x,z,\varphi)\,,
%
\ee
%
}
%
\!where $\mu_n$ are presented below, while the inner scalar product can be rewritten as  $(\phi,\phi) = \int du \phi^* \phi$.

\noinbf{Classification of classically unitary CSFs}. If operators $A$, $B^{\Rsm,\Lsm}$, $M^{\Rsm\Lsm}$ and the measure $\mu_n$ meet the following two requirements
%
{\small
\be \label{18062025-man02-27}
%
\abf)\quad A^\dagger = A\,, \qquad B^{\Rsm\dagger} = B^\Lsm\,,\qquad M^{\Rsm\Lsm\dagger} = M^{\Rsm\Lsm}\,; \qquad \bbf) \quad \mu_n>0 \ \hbox{for all allowed} \ n\,,
%
\ee
%
}
\!then we refer to our CSF as {\it classically unitary CSF}. Requiring the $\CC_2$, $\CC_4$ to be real-valued we find restrictions on $p$, $q$ given in \rf{09062025-man02-30}. Using then the classical unitarity restrictions \rf{18062025-man02-27}, we find measures $\mu_n$ and additional restrictions on $p$ and $q$. Our results are given in the Table II and \rf{18062025-man02-50}.



