\section{General inequalities}
\label{sec.ineq}


In this section we provide a number of inequalities relating the eigenvalues $\diri{k}{m,t}$ for different values of $m$ and $t$. In particular,
Theorems~\ref{increasing},~\ref{sameorder} and~\ref{upperthm} contain the proofs of the three inequalities in Theorem~\ref{thmE}.

To this end, we recall that the weak formulation of the problem defined by~\eqref{dirichletbuckling} is given by
\begin{equation}
\label{first}
\int_{\Omega}D^m u: D^m\phi=\diri{ }{m,t}\int_\Omega D^{m-t} u: D^{m-t}\phi,\ \forall \phi\in H^m_0(\Omega),
\end{equation}
where $D^m u: D^m\phi$ denotes the Frobenius product (we recall that $\alpha !=\alpha_1 !\cdot\alpha_2 !\cdots\alpha_d!$)
$$
D^m u: D^m\phi=\sum_{|\alpha|=m}\frac{m!}{\alpha !}\fr{\partial^\alpha u}{\partial x^\alpha}\fr{\partial^\alpha \phi}{\partial x^\alpha}.
$$
Note that equation \eqref{first} is associated with a self-adjoint operator with compact resolvent for any domain $\Omega$ of finite measure in $\mathbb R^d$,
so that its spectrum is discrete and consists of a diverging sequence of positive eigenvalues of finite multiplicities. In particular, the eigenfunctions form an orthogonal basis for both $H^m_0(\Omega)$ and $H^{m-t}_0(\Omega)$. Moreover, if we set
\begin{equation*}
%\label{notation}
\nabla^m \phi=
\left\{\begin{array}{ll}
\Delta^k\phi,&\text{if\ }m=2k,\eqskip
\nabla\Delta^k\phi,&\text{if\ }m=2k+1,
\end{array}\right.
\end{equation*}
then, using the fact that the ambient space is $H^m_0(\Omega)$, we have that equation \eqref{first} is equivalent to
\begin{equation*}
%\label{secondbuckling}
\int_{\Omega}\nabla^m u\cdot \nabla^m\phi=\diri{}{m,t}\int_\Omega \nabla^{m-t}u\cdot\nabla^{m-t}\phi,\ \forall \phi\in H^m_0(\Omega).
\end{equation*}
In this notation, the index $m$ represents the highest differential order appearing in the operator, while the index $t$ is the difference between the differential
orders of the two operators involved. Because of this, $t$ is the relevant index to be considered when studying the asymptotic properties of eigenvalues,
as may be seen in the asymptotic expression~\eqref{weylmt}. For this reason, we will refer to the index $t$ as half the Weyl order of the eigenvalues,
while the index $m$ will be referred to as half the differential order.


We also recall that, for any positive integers $m$ and $t$ with $1\le t\le m$, the sequence of eigenvalues of problem~\eqref{dirichletbuckling}
may be characterized variationally as follows
\begin{equation}\label{rayleighbuckling}
\diri{k}{m,t}(\Omega)=\min_{\substack{V\subset H^m_0(\Omega)\\ \dim V=k}}\ \max_{0\neq u\in V}\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^{m-t}	u|^2}.
\end{equation}

In addition, we note that the characterization \eqref{rayleighbuckling} yields the following rescaling property
\begin{equation}
\label{scaling}
\lambda_k^{(m,t)}(\varrho\Omega)=\varrho^{-2t}\lambda_k^{(m,t)}(\Omega),
\end{equation}
for any $\varrho>0$.



Throughout, we will make extensive use of the following inequality 
\begin{equation}
\label{basic}
\int_\Omega |\nabla^m u|^2=\left|\int_\Omega\nabla^{m-1}u\cdot\nabla^{m+1}u\right|\leq\left(\int_\Omega|\nabla^{m-1}u|^2\right)^{\frac{1}{2}}
\left(\int_\Omega|\nabla^{m+1}u|^2\right)^{\frac{1}{2}},
\end{equation}
which is a direct consequence from the Cauchy--Schwarz inequality and is valid for any function $u\in H^{m+1}(\Omega)\cap H^m_0(\Omega)$.






%As for lower bounds of Li-Yau type, we also observe that the following holds in general smooth domains (see \cite[formula (1.9)]{kukutan})
%\begin{equation}
%\label{kukutang}
%\lambda_k\ge \fr {16 N\pi^4} {N+4}\left(\fr k{\omega_N|\Omega|}\right)^{\fr 4 N}.
%\end{equation}



We can now show that the eigenvalues are monotone with respect to the order $t$.
\begin{thm}
\label{increasing}
For any $k,t,m \in\mathbb N$, $t\le m\in\mathbb N$, and for any domain $\Omega\in\mathbb R^d$ of finite measure,
\begin{equation}
\label{secondinequality}
\left[\diri{k}{m,t}(\Omega)\right]^{\fr{1}{t}}\leq\left[\diri{k}{m+1,t+1}(\Omega)\right]^{\fr{1}{t+1}}.
\end{equation}
\end{thm}
%\begin{remark}\label{newpsrem}
%Theorem~\ref{increasing} deals with increasing the Weyl order of the eigenvalues, and in particular, for the purely polyharmonic problem (namely $t=m$),
%inequality~\eqref{secondinequality} becomes
%\begin{equation*}
%\label{secondinequalitypoly}
%\left[\diri{k}{m}(\Omega)\right]^{\fr{1}{m}}\leq\left[\diri{k}{m+1}(\Omega)\right]^{\fr{1}{m+1}}.
%\end{equation*}
%
%More generally, we see that if we fix the order $m-t$ of the operator on the right-hand side of~\eqref{dirichletbuckling} then we obtain an increasing sequence of eigenvalues (for any fixed $k$).
%\end{remark}

\begin{proof}
We will first show that, for a fixed $h\le m$, a function $u\in H^{m+1}(\Omega)\cap H^m_0(\Omega)$ satisfies
\begin{equation}
\label{firststep}
\left(\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^{h} u|^2}\right)^{\fr 1 {m-h}}\leq\left(\fr{\int_\Omega|\nabla^{m+1}u|^2}{\int_\Omega |\nabla^{h} u|^2}\right)^{\fr 1 {m-h+1}}.
\end{equation}
From inequality~\eqref{basic} we have
\begin{equation}
\label{firststep1}
\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^{h} u|^2}\leq\left(\fr{\int_\Omega|\nabla^{m-1}u|^2}{\int_\Omega |\nabla^{h} u|^2}\right)^{\fr 1 2}
\left(\fr{\int_\Omega|\nabla^{m+1}u|^2}{\int_\Omega |\nabla^{h} u|^2}\right)^{\fr 1 2},
\end{equation}
so that when $m-1=h$ claim~\eqref{firststep} follows. Otherwise, arguing by induction on $m$, inequality~\eqref{firststep1} yields
\begin{equation*}
\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^{h} u|^2}\leq\left(\fr{\int_\Omega|\nabla^{m}u|^2}{\int_\Omega |\nabla^{h} u|^2}\right)^{\fr{m-h-1}{2m-2h}}
\left(\fr{\int_\Omega|\nabla^{m+1}u|^2}{\int_\Omega |\nabla^{h} u|^2}\right)^{\frac 1 2},
\end{equation*}
which again implies \eqref{firststep}.

It is clear that inequality \eqref{firststep} yields
\begin{equation}
\label{onlymax}
\max_V\left(\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^hu|^2}\right)^{\fr 1 {m-h}}\leq\max_V\left(\fr{\int_\Omega|\nabla^{m+1}u|^2}
{\int_\Omega |\nabla^hu|^2}\right)^{\fr 1 {m-h+1}},
\end{equation}
for any subspace $V$ of $H^{m+1}_0(\Omega)$ (which is a subspace of $H^{m+1}(\Omega)\cap H^m_0(\Omega)$) of given finite dimension. Taking now the infimum of~\eqref{onlymax}
over subspaces of dimension $k$ and substituting $h=m-t$ gives \eqref{secondinequality}, since the exponents can be taken out of the minimax.
\end{proof}

As already stated, Theorem~\ref{increasing} deals with chains of eigenvalues where the Weyl order increases. If instead we consider eigenvalues with the
same Weyl order but where the differential order increases, we obtain the following

\begin{thm}
\label{sameorder}
For any $k,t,m\in\mathbb N$, $t\le m\in\mathbb N$, and for any domain $\Omega\in\mathbb R^d$ of finite measure,
\begin{equation*}
%\label{secondinequalitysame}
\diri{k}{m,t}(\Omega)\leq\diri{k}{m+1,t}(\Omega).
\end{equation*}
\end{thm}

%\begin{remark}
%Notice that, even though the results of Theorems~\ref{increasing} and~\ref{sameorder} are of similar type, there is still a major difference: in Theorem~\ref{increasing} the eigenvalues have a different Weyl order, and this is taken into account by means of normalizing the eigenvalues (namely,the inequality involves the $(2t)$-roots of the eigenvalues). On the other hand, the eigenvalues considered in~Theorem~\ref{sameorder} all have the same Weyl order, so there is no need for a normalization.
%\end{remark}

\begin{proof}
From \eqref{basic} we get that a function $u\in H^{m+1}(\Omega)\cap H^m_0(\Omega)$ satisfies
\begin{equation}
\label{firststepsame1}
\fr{\int_\Omega |\nabla^h u|^2}{\int_\Omega |\nabla^{h-1} u|^2}\leq\fr{\int_\Omega|\nabla^{h+1}u|^2}{\int_\Omega |\nabla^h u|^2},
\end{equation}
for any $h\le m$. By iterating inequality \eqref{firststepsame1} for $m-t+1\le h\le m$ we obtain
\begin{equation*}
%\label{firststepsame1}
\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^{m-t} u|^2}\leq\fr{\int_\Omega|\nabla^{m+1}u|^2}{\int_\Omega |\nabla^{m-t+1} u|^2}.
\end{equation*}
The proof of the theorem can now be done following that of Theorem \ref{increasing}.
\end{proof}

We have now a generalization of a claim made by Payne~\cite[formula (63)]{payne}.

\begin{thm}
\label{lower}
For any $k,t,m\in\mathbb N$, $t\le m\in\mathbb N$, and for any domain $\Omega\in\mathbb R^d$ of finite measure,
\begin{equation}
\label{generalizedpayne}
\diri{k}{m,t}(\Omega)\ge\diri{k}{m,1}(\Omega)\dprod_{h=m-t+1}^{m-1}\diri{1}{h,1}(\Omega). 
\end{equation}
\end{thm}

%\begin{remark}
%It is understood that one may have also different ways of producing a right-hand side for~\eqref{generalizedpayne} by taking different steps in the
%splitting procedure (here we are taking step $1$).
%\end{remark}

\begin{proof}
It suffices to observe that the Rayleigh quotient of $\diri{k}{m,t}(\Omega)$ can be split as follows 
$$
\fr{\int_\Omega|\nabla^m u|^2}{\int_\Omega |\nabla^{m-t} u|^2}=\dprod_{h=m-t+1}^{m}\fr{\int_\Omega|\nabla^h u|^2}{\int_\Omega |\nabla^{h-1}u|^2}
\ge  \fr{\int_\Omega|\nabla^m u|^2}{\int_\Omega |\nabla^{m-1}u|^2}\dprod_{h=m-t+1}^{m-1}\diri{1}{h,1}(\Omega),
$$
where in the last inequality we used the fact that
$$
\diri{1}{h,1}(\Omega)=\inf_{0\neq u\in H^m_0(\Omega)} \fr{\int_\Omega|\nabla^h u|^2}{\int_\Omega |\nabla^{h-1}u|^2}
=\min_{0\neq u\in H^h_0(\Omega)} \fr{\int_\Omega|\nabla^h u|^2}{\int_\Omega |\nabla^{h-1}u|^2}.
$$
The result now follows applying the minimax.
\end{proof}

While in~\cite{payne} there are some considerations on how sharp the inequality is for the case $m=2,k=1$, it is not clear how good the bound~\eqref{generalizedpayne}
is in the general case.

As a counterpart to Theorem \ref{lower} we have the following generalization of an inequality between the Dirichlet bilaplacian and buckling eigenvalues
(see e.g., \cite{liuineq}; see also \cite[Remark 2.12]{blps}).
\begin{thm}
\label{upperthm}
For any domain $\Omega$ in $\mathbb R^d$ of finite measure, for any $k,m\in\mathbb N$, and for any $1\le t\le s\le m$
\begin{equation}
\label{bucklingboundgen}
\left[\diri{k}{m,s}(\Omega)\right]^{\frac{1}{s} }\le \left[\diri{k}{m,t}(\Omega)\right]^{\frac{1}{t} }. 
\end{equation}
In particular,
\begin{equation}
\label{bucklingbound}
\diri{k}{m}(\Omega)\le \left[\diri{k}{m,1}(\Omega)\right]^m. 
\end{equation}
\end{thm}
\begin{proof}
The proof is based on the Gagliardo-Nirenberg-type inequality of Theorem \ref{gntineqthm} below. From \eqref{gntineq} we get
$$
\left(\fr{\int_\Omega |\nabla^m u|^2}{\int_\Omega |\nabla^{m-s} u|^2}\right)^{\fr 1 s}\leq\left(\fr{\int_\Omega|\nabla^m u|^2}{\int_\Omega |\nabla^{m-t} u|^2}\right)^{\fr 1 t}.
$$
Taking the standard minimax in $H^m_0(\Omega)$ and observing that the exponents can be taken out of the minimax, we obtain \eqref{bucklingboundgen}. Finally, equation \eqref{bucklingbound} follows from \eqref{bucklingboundgen} with $t=1$ and $s=m$.
\end{proof}


\begin{remark}
We observe that combining Theorems~\ref{increasing} and~\ref{upperthm} we get and alternative proof for Theorem \ref{sameorder}: in fact, considering $s=t+1$,
$$
\left[\diri{k}{m,t}(\Omega)\right]^{\frac{1}{t} }\le \left[\diri{k}{m+1,t+1}(\Omega)\right]^{\frac{1}{t+1} }\le \left[\diri{k}{m+1,t}(\Omega)\right]^{\frac{1}{t} }. 
$$
\end{remark}


We now provide a very general Gagliardo-Nirenberg-type inequality for polyharmonic operators on $H^m_0(\Omega)$.

\begin{thm}
\label{gntineqthm}
Let $m,t,s\in\mathbb N$ be such that $0\le t\le s\le m$, and let $u\in H^m_0(\Omega)$. Then
\begin{equation}
\label{gntineq}
\left(\int_\Omega |\nabla^{m-t} u|^2\right)^{s}\le \left(\int_\Omega |\nabla^{m-s} u|^2\right)^{t}\left(\int_\Omega |\nabla^m u|^2\right)^{s-t}.
\end{equation}
Equivalently, for any $0\le q\le p\le m$,
\begin{equation*}
\left(\int_\Omega |\nabla^{p} u|^2\right)^{m-q}\le \left(\int_\Omega |\nabla^{q} u|^2\right)^{m-p}\left(\int_\Omega |\nabla^m u|^2\right)^{p-q}.
\end{equation*}
\end{thm}
\begin{remark}
We observe two important points that make Theorem \ref{gntineqthm} peculiar: on the one hand, it does not involve generic derivatives but specific combinations involving
polyharmonic operators, and it specifically applies to $H^m_0$-functions only; on the other hand, there are no unknown constants depending on the indices or on the
geometry of $\Omega$.
\end{remark}

\begin{proof}
The proof is quite involved since it is done by induction on the three indices $t,s,m$. We divide it into 5 steps.

{\bf Step 1: $t=1$, $s=m$.} We want to prove here that
\begin{equation}
\label{caso1-1}
\left(\int_\Omega |\nabla^{m-1} u|^2\right)^{m}\le \left(\int_\Omega |u|^2\right)\left(\int_\Omega |\nabla^m u|^2\right)^{m-1}.
\end{equation}
We proceed by induction on $m$. Clearly for $m=1$ the inequality is trivial, while for $m=2$ it immediately follows from \eqref{basic}. Again by induction on~\eqref{basic} we have
\begin{equation}
\label{caso1-2}
\begin{array}{lll}
\left(\dint_\Omega |\nabla^{m} u|^2\right)^{2} & \le & \left(\dint_\Omega |\nabla^{m-1}u|^2\right)\left(\dint_\Omega |\nabla^{m+1} u|^2\right)\eqskip
& \le & \left(\dint_\Omega |u|^2\right)^{\fr 1 m}\left(\dint_\Omega |\nabla^m u|^2\right)^{\fr{m-1}{m}}\left(\dint_\Omega |\nabla^{m+1} u|^2\right).
\end{array}
\end{equation}
Rearranging the terms in \eqref{caso1-2} we obtain \eqref{caso1-1} where $m$ is replaced by $m+1$, concluding the induction.

{\bf Step 2: $t=2$, $s=m$.} This is similar to step 1: we want to prove that
\begin{equation}
\label{caso2-1}
\left(\dint_\Omega |\nabla^{m-2} u|^2\right)^{m}\le \left(\dint_\Omega |u|^2\right)^2\left(\dint_\Omega |\nabla^m u|^2\right)^{m-2}.
\end{equation}
We proceed by induction on $m$. Clearly for $m=2$ the inequality is trivial, while for $m=3$ it immediately follows from \eqref{basic}. Once more by induction on~\eqref{basic} we have
\begin{equation}
\label{caso2-2}
\begin{array}{lll}
\left(\dint_\Omega |\nabla^{m-1} u|^2\right)^{2} & \le & \left(\dint_\Omega |\nabla^{m-2}u|^2\right)\left(\dint_\Omega |\nabla^{m} u|^2\right)\eqskip
& \le & \left(\dint_\Omega |u|^2\right)^{\fr 2 m}\left(\dint_\Omega |\nabla^m u|^2\right)^{2\fr{m-1}{m}}\eqskip
& \le & \left(\dint_\Omega |u|^2\right)^{\fr 2 m}\left(\dint_\Omega |\nabla^{m-1} u|^2\right)^{\fr{m-1}{m}}\left(\dint_\Omega |\nabla^{m+1} u|^2\right)^{\fr{m-1}{m}}.
\end{array}
\end{equation}
Rearranging the terms in \eqref{caso2-2} we obtain \eqref{caso2-1} where $m$ is replaced by $m+1$, concluding the induction.


{\bf Step 3: $s=m$, general $t$.} Here we want to prove that
\begin{equation}
\label{caso3-1}
\left(\int_\Omega |\nabla^{m-t} u|^2\right)^{m}\le \left(\int_\Omega |u|^2\right)^{t}\left(\int_\Omega |\nabla^m u|^2\right)^{m-t}.
\end{equation}
We proceed by a double induction on $t$ and $m$ as follows. We take steps 1 and 2 as bases together with the case $t=m$ (which is trivial). We
therefore assume that formula \eqref{caso3-1} is valid for any $m$ for $\bar t< t$ and for $\bar m\le m$ for $\bar t=t$. We have
\begin{equation}
\label{caso3-2}
\left(\int_\Omega |\nabla^{m+1-t} u|^2\right)^{2}\le \left(\int_\Omega |\nabla^{m-t}u|^2\right)\left(\int_\Omega |\nabla^{m+2-t} u|^2\right).
\end{equation}
Considering $m+2-t=m-(t-2)$, by induction on $t$ inequality~\eqref{caso3-2} becomes
\begin{multline*}
%\label{caso3-3}
\begin{array}{lll}
\left(\int_\Omega |\nabla^{m+1-t} u|^2\right)^{2} &
\le & \left(\int_\Omega |u|^2\right)^{\fr{t}{m}}\left(\int_\Omega |\nabla^{m} u|^2\right)^{\fr{m-t}{m}}
\left(\int_\Omega |u|^2\right)^{\fr{t-2}{m}}\left(\int_\Omega |\nabla^{m} u|^2\right)^{\fr{m-t+2}{m}}\eqskip
& = &
\left(\int_\Omega |u|^2\right)^{\fr{2t-2}{m}}\left(\int_\Omega |\nabla^{m} u|^2\right)^{2\fr{m-t+1}{m}}\eqskip
& \le & \left(\int_\Omega |u|^2\right)^{\fr{2t-2}{m}}\left(\int_\Omega |\nabla^{m-1} u|^2\right)^{\fr{m-t+1}{m}} \left(\int_\Omega |\nabla^{m+1} u|^2\right)^{\fr{m-t+1}{m}}.
\end{array}
\end{multline*}
Now, by considering $m-1=(m+1)-(2)$ and applying inequality \eqref{caso2-1} we see that
$$
\left(\int_\Omega |\nabla^{m-1} u|^2\right)^{m+1}\le \left(\int_\Omega |u|^2\right)^2 \left(\int_\Omega |\nabla^{m+1} u|^2\right)^{m-1},
$$
yielding
\begin{equation}
\label{caso3-4}
\left(\int_\Omega |\nabla^{m+1-t} u|^2\right)^{2}\le \left(\int_\Omega |u|^2\right)^{\fr{2t}{m+1}}\left(\int_\Omega |\nabla^{m+1} u|^2\right)^{2\fr{m-t+1}{m+1}}.
\end{equation}
Rearranging the terms in \eqref{caso3-4} we obtain \eqref{caso3-1} where $m$ is replaced by $m+1$, concluding the induction.



{\bf Step 4: $t=1$, general $s$ and $m$.} We want to prove that
\begin{equation}
\label{caso4-1}
\left(\int_\Omega |\nabla^{m-1} u|^2\right)^{s}\le \left(\int_\Omega |\nabla^{m-s}u|^2\right)\left(\int_\Omega |\nabla^m u|^2\right)^{s-1}.
\end{equation}
Inequality \eqref{caso4-1} is trivial for $s=1,2$ for any $m$. In order to proceed by induction we rewrite equation \eqref{caso4-1} as follows
\begin{equation}
\label{caso4-2}
\left(\int_\Omega |\nabla^{m-1} u|^2\right)^{m-p}\le \left(\int_\Omega |\nabla^{p}u|^2\right)\left(\int_\Omega |\nabla^m u|^2\right)^{m-p-1},
\end{equation}
which we want to prove for any $0\le p< m$. We already know that \eqref{caso4-2} is valid for any $p\in\mathbb N$ and for $m=p+1,p+2$. By induction on $m$
\begin{equation}
\label{caso4-3}
\begin{array}{lll}
\left(\int_\Omega |\nabla^{m} u|^2\right)^{2} & \le & \left(\int_\Omega |\nabla^{m-1}u|^2\right)\left(\int_\Omega |\nabla^{m+1} u|^2\right)\eqskip
& \le & 
\left(\int_\Omega |\nabla^{p} u|^2\right)^{\fr 1 {m-p}}\left(\int_\Omega |\nabla^m u|^2\right)^{\fr{m-p-1}{m-p}}\left(\int_\Omega |\nabla^{m+1} u|^2\right).
\end{array}
\end{equation}
Rearranging the terms in \eqref{caso4-3} we obtain \eqref{caso4-2} where $m$ is replaced by $m+1$, concluding the induction. 


{\bf Step 5: conclusion.} We now proceed to the general case \eqref{gntineq}. It is clear from step 1 that the inequality is true for any $t$ and for any $s$, and for
$m=s$. Also, from step 4 it is clear that it is valid for for $t=1$ and for any $s$ and $m$. Supposing now that the inequality is valid for any $s,m$ when $\bar t<t$ and
for any $s\le\bar m\le m$ for $\bar t=t$, observing that $(m+1)-t=m-(t-1)$, we have
\begin{equation}
\label{caso5-1}
\left(\int_\Omega |\nabla^{m+1-t} u|^2\right)^{s}\le \left(\int_\Omega |\nabla^{m+1-s}u|^2\right)^{s\fr{t-1}{s-1}}\left(\int_\Omega |\nabla^m u|^2\right)^{s\fr{s-t}{s-1}}.
\end{equation}
Similarly, since $m=(m+1)-1$, we have
\begin{equation}
\label{caso5-2}
\left(\int_\Omega |\nabla^{m} u|^2\right)^{s}\le \left(\int_\Omega |\nabla^{m+1-s}u|^2\right)\left(\int_\Omega |\nabla^{m+1} u|^2\right)^{s-1}.
\end{equation}
Combining \eqref{caso5-1} with \eqref{caso5-2} we obtain \eqref{gntineq} where $m$ is replaced by $m+1$, concluding the induction. This concludes the proof.
\end{proof}












