\subsection{Improved eigenvalue upper bounds}\label{sec:ub}

%In this section we compute improved upper bounds for the first eigenvalue of problem \eqref{dirichletbuckling} on the unit ball by means of a test function argument. This
%will be broken into two parts, as we first consider the case of $\diri{1}{m}(\mathbb B)$, and only then go on to address the more involved case of $\diri{1}{m,m-h}(\mathbb B)$.
%Although the test function used is the same in both cases and the first of these bounds may be obtained as a consequence of the second, the proof of the bound for 
%$\diri{1}{m,m-h}(\mathbb B)$ is basically a continuation of the same argument, now needing the calculation of a more complicated integral. Because of this, we believe it to be clearer to separate the two proofs.


We provide here an improved upper bound for $\diri{1}{m,m-h}(\mathbb B)$ by means of specific test functions.


\begin{thm}\label{ballupperb}
For any $m,h\in\mathbb N$ with $h<m$ we have
$$
% \diri{1}{m-h}(\mathbb B)\le
\begin{array}{lll}
\diri{1}{m,m-h}(\mathbb B)& \le & \fr{2^{2m-2h}\Gamma^2(m-h+1)\Gamma(2m-h+1+d/2)}{(m+d/2)\Gamma(h+d/2)\Gamma(2m-2h+1)}\eqskip
& = & 2^{\frac d 2-h}\fr{2\pi}{\Gamma(h+d/2)} 2^{2m}  e^{-2m} m^{2m+\frac{ d}{ 2}-h}\left(1+\bo(m^{-1})\right),
\end{array}
$$
as $m\to\infty$.
\end{thm}
\begin{proof}
 The first inequality is obtained using $f(x)=(1-|x|^2)^m$ as a test function in the Rayleigh quotient,
and then using Lemma \ref{hyperlemma}.

In order to prove the asymptotic expression, we recall the Stirling approximation (see also \cite[Formula 5.11.8]{nist})
\begin{equation}
\label{stirlingnist}
\log \Gamma (z+h)=\left(z+h-\frac 1 2\right)\log z-z+\frac1 2\log(2\pi)+\bo(z^{-1}),
\end{equation}
or alternatively
\begin{equation}
\label{stirlingnist2}
\Gamma(z+h)=\sqrt{ 2 \pi}z^{z+h-\frac 1 2}e^{-z}\left(1+\bo(z^{-1})\right),
\end{equation}
where $h$ is a fixed value.

From the Stirling approximation~\eqref{stirlingnist2} we obtain
\begin{gather*}
 \begin{array}{lll}
  \fr{2^{2m-2h}\Gamma^2(m-h+1)\Gamma(2m-h+1+d/2)}{(m+d/2)\Gamma(h+d/2)\Gamma(2m-2h+1)}\eqskip
\hspace*{10mm}=\fr{2^{2m-2h}\left(\sqrt{2\pi}m^{m-h+1/2}e^{-m}\right)^2\sqrt{2\pi}(2m)^{2m-h+(d+1)/2}e^{-2m}}
{m\Gamma(h+d/2)\sqrt{2\pi}(2m)^{2m-2h+1/2}e^{-2m}} \left(1+\bo(m^{-1})\right)\eqskip
\hspace*{10mm}= 2^{\frac d 2 -h}\fr{2\pi}{\Gamma(d/2)} 2^{2m}  e^{-2m} m^{2m-h+\frac{ d}{ 2}}\left(1+\bo(m^{-1})\right).
 \end{array}
\end{gather*}
%$$
%\log \left(\fr{2^{2m-2h}\Gamma^2(m-h+1)\Gamma(2m-h+1+d/2)}{(m+d/2)\Gamma(h+d/2)\Gamma(2m-2h+1)}\right)=\log\left( 2^{2m}\right)+(2m-h+d/2)\log m -2m+\bo(1),
%$$
yielding the asymptotic behaviour indicated.
\end{proof}



