\subsection{Eigenvalue lower bounds\label{sec:lowbounds}}

Let us consider the following problem

\begin{equation}
\label{auxbuck}
\begin{cases}
(-\Delta)^mu=\navi{}{m,t} (-1)^{m-t}\nabla^{m-t}\fr{1}{(1-|x|^2)^t}\nabla^{m-t}u, & {\rm \ in\ }\mathbb B,\eqskip
u=\fr{\partial u}{\partial \nu}=\dots=\fr{\partial^{m-1} u}{\partial \nu^{m-1}}=0, & {\rm \ on\ }\partial \mathbb B.
\end{cases}
\end{equation}
We observe that problem \eqref{auxbuck} admits the following weak formulation
\begin{equation*}
%\label{auxbuckw}
\int_{\mathbb B} \nabla^m u\nabla^m v=\navi{}{m,t} \int_{\mathbb B} \fr{1}{(1-|x|^2)^t}\nabla^{m-t}u\nabla^{m-t}v, \forall v\in \tilde H^{m,t}(\mathbb B),
\end{equation*}
where $\tilde H^{m,t}(\mathbb B)=H^m_0(\mathbb B)\cap H^{m-t}(\mathbb B,(1-|x|^2)^{-t})$. Notice that, since the weight $(1-|x|^2)^{-t}$ is not in $L^\infty(\mathbb B)$
we cannot automatically conclude that $\tilde H^{m,t}(\mathbb B)=H^m_0(\mathbb B)$; in general, it could be a strict subspace of $H^m_0(\mathbb B)$. Nevertheless, $\tilde H^{m,t}(\mathbb B)$
is a Hilbert space  containing $C^\infty_c(\mathbb B)$ as a dense set and,
in particular problem~\eqref{auxbuck} is associated with a self-adjoint operator with compact resolvent. Therefore, it admits a diverging sequence of positive eigenvalues of
finite multiplicity, whose associated eigenfunctions form an orthonormal basis for $\tilde H^{m,t}(\mathbb B)$. In addition, they can be defined variationally by
$$
\navi{k}{m,t}=\min_{\substack{V\subset \tilde H^{m,t}(\mathbb B)\\ \dim V=k}}\max_{0\neq u\in V}\fr{\int_{\mathbb B} |\nabla^m u|^2}{\int_{\mathbb B} |\nabla^{m-t} u|^2 (1-|x|^2)^{-t}}.
$$


%\txtr{\soutb{
%It is immediate to observe the following inequality, due to the respective variational characterizations:}
%$$
%\soutb{\navi{k}{m,t}\le \diri{k}{m,t}(\mathbb B),\quad\forall m,t,k.}
%$$}

%We proceed now with the identification of the fundamental tone and the associated eigenspace of~\eqref{auxbuck}.

%For general values of $m$ and $t$ it is natural to conjecture that the eigenvalue identified in Lemma \ref{fund} should be the fundamental tone, even though it is not clear how to formally prove such a claim. However, whenever $m=t$, we have the following

\begin{thm}
For $m=t$, the fundamental tone of problem \eqref{auxbuck} is simple and is that identified in Lemma \ref{fund}, that is
$$
\navi{1}{m,m}=2^{2m}\fr{\Gamma(m+1)\Gamma(m+d/2)}{\Gamma(d/2)}.
$$
\end{thm}
\begin{proof}
First of all, we observe that when $m=t$ problem~\eqref{auxbuck} enjoys the so-called positivity preserving property, namely if $f$ is a positive
function then the solution $u$ of the problem
\begin{equation*}
\begin{cases}
(-\Delta)^mu=\fr{f}{(1-|x|^2)^{m}}, & {\rm \ in\ }\mathbb B,\eqskip
u=\fr{\partial u}{\partial \nu}=\dots=\fr{\partial^{m-1} u}{\partial \nu^{m-1}}=0, & {\rm \ on\ }\partial \mathbb B,
\end{cases}
\end{equation*}
is positive, i.e., $u>0$. This can be proved following verbatim the arguments of \cite[Section 5.1]{ggs}. This, in particular, allows us to mimic the arguments
in~\cite[Theorem 3.7]{ggs}, deducing that the first eigenvalue of problem \eqref{auxbuck} is simple and its associated eigenfunction is positive. Lemma~\ref{fund}
then leads to the conclusion.
\end{proof}

\begin{remark}\label{krarg}
We observe that, since for the case $m=t$ the use of a Krein-Rutman-type argument allows us to show that the first eigenfunction of the ball is positive,
it is expected that the case $m>t$ shows a similar behaviour, although it is not clear whether this argument could be adapted.
\end{remark}

We may thus use $\navi{1}{m,m}$ to obtain a lower bound for $\diri{1}{m}(\mathbb B)$.
\begin{thm}\label{eineqaux}
For any $m\in\mathbb N$, we have
\begin{equation}
\label{lb-est}
\diri{1}{m}(\mathbb B)\ge\navi{1}{m,m}=2^{2m}\fr{\Gamma(m+1)\Gamma(m+d/2)}{\Gamma(d/2)}.
\end{equation}
\end{thm}

\begin{proof}
We observe that, for any $u\in C^\infty_c(\mathbb B)$,
$
\int_{\mathbb B} u^2\le\int_{\mathbb B}\fr{u^2}{(1-|x|^2)^m},
$
from which we obtain
$$
\diri{1}{m}(\mathbb B)=\inf_{u\in C^\infty_c(\mathbb B)}\fr{\int_{\mathbb B} |\nabla^m u|^2}{\int_{\mathbb B} u^2}\ge\inf_{u\in C^\infty_c(\mathbb B)}\fr{\int_{\mathbb B}
|\nabla^m u|^2}{\int_{\mathbb B}\fr{u^2}{(1-|x|^2)^m}}=\navi{1}{m,m}.%\qedhere
$$
\end{proof}



\begin{remark}
Exploiting the argument used in the proof of Theorem \ref{eineqaux}, it is in fact possible to obtain the more general inequality
$$
\navi{k}{m,t}\le \diri{k}{m,t}(\mathbb B),\quad\forall m,t,k.
$$
\end{remark}


As in the case of the upper bound, we shall now determine the asymptotic behaviour of the expression obtained above.



\begin{lem}\label{lemeineqaux}
As $m\to\infty$ we have
\begin{equation}
\label{prelasympt2}
2^{2m}\fr{\Gamma(m+1)\Gamma(m+d/2)}{\Gamma(d/2)}\approx \frac{2\pi}{\Gamma(d/2)} 2^{2m}  e^{-2m} m^{2m+\frac{d}{2}}.
\end{equation}
%\sout{and as a consequence,}
%\begin{equation}
%\label{compl-asympt}
%\sout{\left[\diri{1}{m}(\mathbb B)\right]^{\fr{1}{2m}}=\fr{2m}{e}+\so(m).}
%\end{equation}
\end{lem}

\begin{proof}
Using \eqref{stirlingnist2} we get
\[
\begin{array}{lll}
2^{2m}\fr{\Gamma(m+1)\Gamma(m+d/2)}{\Gamma(d/2)} & = & \frac{2^{2m}}{\Gamma(d/2)}\sqrt{2\pi}m^{m+1/2}e^{-m}\sqrt{2\pi}m^{m+(d-1)/2}e^{-m}\left(1+\bo(m^{-1})\right)\eqskip
& = & \fr{2\pi}{\Gamma(d/2)} 2^{2m}  e^{-2m} m^{2m+\frac{d}{2}}\left(1+\bo(m^{-1})\right),
\end{array}
\]
from which \eqref{prelasympt2} holds.%, and \eqref{compl-asympt} follows by taking the $(2m)$-th root and combining with~\eqref{upperasympt}.
\end{proof}

\begin{cor}
We have
$$
\diri{1}{m}(\mathbb B) = \Theta\left(2^{2m}  e^{-2m} m^{2m+\frac{d}{2}}\right),
$$
and in particular
\begin{equation}
\label{precise}
\left[\diri{1}{m}(\mathbb B)\right]^{\fr{1}{2m}}=\fr{2m}{e}+\frac{d}{2e}\log m +\bo(1),
\end{equation}
as $m\to\infty$. 
\end{cor}

\begin{proof}
To get the expansion~\eqref{precise} we combine the upper and lower bounds from Theorem~\ref{thmA} together with the expansion~\eqref{stirlingnist}. In particular,
\[
\begin{array}{lll}
\log\left(\fr{2^{2m}\Gamma^2(m+1)\Gamma(2m+d/2+1)}{(m+d/2)\Gamma(d/2)\Gamma(2m+1)}\right) & = & 2m\log2+(2m+1)\log m-2m +\log(2\pi)\eqskip
& & \hspace*{5mm}  +(2m+(d+1)/2)\log(2m)-2m+\log\sqrt{2\pi} \eqskip
& & \hspace*{10mm}-\log m-\log\Gamma(d/2)-(2m+1/2)\log(2m)\eqskip
& & \hspace*{15mm} +2m-\log\sqrt{2\pi}+\bo(m^{-1})\eqskip
& = & 2m\log\fr{2m}{e} +\fr{d}{2}\log m+\log\fr{2^{d/2}2\pi}{\Gamma(d/2)}+\bo(m^{-1}),
\end{array}
\]
and
\[
\begin{array}{lll}
\log\left(\fr{2^{2m}\Gamma(m+1)\Gamma(m+d/2)}{\Gamma(d/2)}\right) & = & 2m\log2+(m+1/2)\log m-m+\log\sqrt{2\pi}\eqskip
& & \hspace*{5mm}  +(m+(d-1)/2)\log m-m+\log\sqrt{2\pi}+\bo(m^{-1})\eqskip
& = & 2m\log\fr{2m}{e} +\fr{d}{2}\log m+\log\fr{2\pi}{\Gamma(d/2)}+\bo(m^{-1}),
\end{array}
\]
from which we get
\[
\begin{array}{lll}
\left[\diri{1}{m}(\mathbb B)\right]^{\fr{1}{2m}} & = & \exp\left(\log\fr{2m}{e} +\fr{d}{4m}\log m+\bo(m^{-1})\right)\eqskip
& = & \fr{2m}{e}\left(1+\fr{d}{4m}\log m+\bo\left(\fr{(\log m)^2}{m^2}\right)\right)\left(1+\bo(m^{-1})\right)\eqskip
& = & \fr{2m}{e}+\fr{d}{2e}\log m +\bo(1).  %\qedhere
\end{array}
\]
\end{proof}

By combining the upper bound from Theorem~\ref{ballupperb} and the lower bound in Theorem~\ref{eineqaux}, it is also possible to obtain an estimate in the more general case
of $\diri{1}{m,m-h}(\mathbb B)$ where $h$ is fixed and $m\to\infty$.

\begin{thm}\label{ballasympt}
For any $m,h\in\mathbb N$ with $h<m$ we have
$$
\diri{1}{m-h}(\mathbb B)\le\diri{1}{m,m-h}(\mathbb B) = \bo\left(2^{2m}e^{-2m}m^{2m-h+\frac{d}{2}}\right),
$$
and similarly,
$$
\left[\diri{1}{m,m-h}(\mathbb B)\right]^{\fr{1}{2(m-h)}}=\fr{2m}{e}+\bo(\log m),
$$
as $m\to\infty$ (and fixed $h$).
\end{thm}

\begin{proof}
 The inequality
$$
\diri{1}{m-h}(\mathbb B)\le\diri{1}{m,m-h}(\mathbb B)
$$
comes directly from Theorem \ref{sameorder}. We observe that $\diri{1}{m-h}(\mathbb B)=\Theta\left(2^{2m}e^{-2m}m^{2m-2h+\frac{d}{2}}\right)$ and
$$
\left(\diri{1}{m-h}(\mathbb B)\right)^{1/(2m-2h)}=\frac{2m}{e}+\frac{d}{4e}\log m+\bo (1).
$$

On the other hand, from Theorem~\ref{ballupperb}
$$
\begin{array}{lll}
\left[\diri{1}{m,m-h}(\mathbb B)\right]^{\frac{1}{2(m-h)}} & \le & \left(\fr{2^{2m-2h}\Gamma^2(m-h+1)\Gamma(2m-h+1+d/2)}{(m+d/2)\Gamma(h+d/2)\Gamma(2m-2h+1)}\right)^{\frac{1}{2(m-h)}}\eqskip
& = & \fr{2m}{e}+\fr{2h+d}{4e}\log m+\bo(1).%\qedhere
\end{array}
$$
\end{proof}

\begin{remark}
Should the behaviour of the first eigenvalue of problem~\eqref{auxbuck} be as suggested in Remark~\ref{krarg}, namely, that
the corresponding eigenfunction is of one sign also when $m>t$, then Lemma~\ref{fund} would also provide a lower bound in this
case. Since this has the same asymptotic behaviour as the upper bound in the above theorem, namely, $\sigma=\Theta\left(2^{2m}e^{-2m}m^{2m-h+\frac{d}{2}}\right)$,
this would then give the precise behaviour for $\diri{1}{m,m-h}(\mathbb B)$.
\end{remark}




