\subsection{Other asymptotic estimates: general domains and hyperrectangles}

Using the above results together with the rescaling property \eqref{scaling}, we may now discuss the case of a general domain, as well as the behaviour of eigenvalues
other than the fundamental tone. To do this, we shall use an inclusion argument which is basically a variant of that used by P\'{o}lya in~\cite{polya}.
More precisely, given a bounded domain $\Omega$, it is always possible to enclose it by a disjoint union of $k$ identical balls
$\overline\Omega={\ds \bigsqcup_{p=1}^k} \varrho_e \mathbb B$, where the parameter $\varrho_e$ can be chosen to be half the diameter of $\Omega$. In fact, it is possible
to consider the circumscribed ball to $\Omega$ together with $(k-1)$ disjoint copies. This then implies
$$
\lambda_k^{(m,m-h)}(\Omega)\ge \lambda_k^{(m,m-h)}(\overline\Omega)=\varrho_e^{-2(m-h)}\lambda_1^{(m,m-h)}(\mathbb B).
$$
On the other hand, it is also possible to find $k$ identical balls $\underline\Omega={\ds \bigsqcup_{p=1}^k} \varrho_i \mathbb B$ enclosed in $\Omega$ (the parameter
$\varrho_i$ can be taken to be the $k$-th part of the inradius). This implies
$$
\lambda_k^{(m,m-h)}(\Omega)\le \lambda_k^{(m,m-h)}(\underline\Omega)=\varrho_i^{-2(m-h)}\lambda_1^{(m,m-h)}(\mathbb B),
$$
proving Theorem~\ref{maingeral}.




% \begin{cor}
% Let $\Omega\subseteq\mathbb R^d$ be a bounded domain, and let $k\in\mathbb N$. Then, for $t$ fixed and $m\to\infty$,
% $$
% \lambda_k^{(m,t)}(\Omega)=\Theta(m^{2t}),
% $$
% while for $h$ fixed and $m\to\infty$,
% $$
% \lambda_k^{(m,m-h)}(\Omega)=\Theta(2^{2m}e^{-2m}m^{2m-2h+\fr d 2}).
% $$
% \end{cor}

On the other hand, the scaling property~\eqref{scaling} together with Theorem~\ref{ballasympt} immediately yield the following asymptotic expansion
$$
\left[\diri{1}{m,m-h}(\varrho\mathbb B)\right]^{\fr{1}{2(m-h)}}=\fr{2m}{e\varrho }+\bo(\log m),
$$
where $\varrho\mathbb B$ is the ball of radius $\varrho$ centred at the origin. For this reason, and also influenced by the scaling in the Weyl asymptotics~\eqref{weylmt},
it would be natural to conjecture that (at least) the first term in the order asymptotic would depend on the volume $|\Omega|$. However, as was already pointed out in
the~Introduction, we see that this is not the case. More precisely, we show that in the case of hyperrectangles the only geometric quantity to appear in this first term
is related to its inradius.

\begin{thm}\label{hrect}
Let $R\subseteq\mathbb R^d$ be the hyperrectangle
$
R={\ds \prod_{p=1}^d}(-a_p,a_p),
$
where $\min_p a_p=\ab$. Then
$$
\left[\lambda_1^{(m)}(R)\right]^{\frac{1}{2m}}=\frac{2m}{e\ab }+\bo(\log m),
$$
for $m\to\infty$.
\end{thm}

\begin{proof}
We first note that, since $\ab\mathbb B\subseteq R$, from the Rayleigh quotient we have
$
\lambda_1^{(m)}(R)\le\lambda_1^{(m)}(\ab \mathbb B),
$
while for a lower bound we make careful use of the one-dimensional bounds. From~\eqref{lb-est} we have
\begin{equation*}
%\label{ineqp}
\int_{-1}^1u^{(m)}(x)^2dx\ge (2m)!\int_{-1}^1u(x)^2dx,
\end{equation*}
for any function $u\in C^m_0(-1,1)$, implying that
$$
\int_{-a_p}^{a_p}u^{(m)}(x)^2dx\ge (2m)! a_p^{-2m}\int_{-a_p}^{a_p} u(x)^2dx,
$$
for any function $u\in C^m_0(-a_p,a_p)$. Therefore, applying Fubini's theorem we obtain
\begin{equation*}
%\label{ineqpd}
\int_{R}\partial^\alpha u(x)^2dx\ge (2\alpha)!a^{-2\alpha}\int_{R}u(x)^2dx,
\end{equation*}
for any function $u\in C^m_0(R)$, and for any multi-index $\alpha$ such that $|\alpha|\le m$, where we have used
the multi-index notation $a^{-2\alpha}=\prod_p (a_p)^{-2\alpha_p}$. Now, integrating by parts we obtain
$$
\int_R|\nabla^m u|^2=\int_R|D^m u|^2,
$$
where $D^m u$ represents the tensor of derivatives of order $m$, and in particular
$
|D^mu|^2=\dsum_{|\alpha|=m}\frac{m!}{\alpha!}|\partial^\alpha u|^2.
$
Therefore
\begin{equation*}
%\label{ineqpdm}
\fr{\int_{R}|D^m u(x)|^2dx}{\int_{R}|u(x)|^2dx}
\ge \sum_{|\alpha|=m}\frac{m!(2\alpha)!}{\alpha!}a^{-2\alpha}\ge (2m)!\sum_{p=1}^d\frac 1{a_p^{2m}},
\end{equation*}
for any $u\in C^{m}_0(R)$, so taking the infimum we obtain
$$
\lambda_1^{(m)}(R)\ge (2m)!\sum_{p=1}^d\frac 1{a_p^{2m}}\ge \frac{(2m)!}{\ab^{2m}}.
$$
Since
$
\left[(2m)!\right]^{\fr{1}{2m}}=\fr{2m}{e}+\fr 1 e \log m+\bo(1),
$
this implies
$
\left[\lambda_1^{(m)}(R)\right]^{\fr{1}{2m}}=\fr{2m}{e\ab}+\bo(\log m).
$
\end{proof}






