\begin{lem}\label{hyperlemma}
Let $f(x)=(1-|x|^2)^m$, and let $0\le t \le m$. Then
\begin{equation} \label{hypergeometric}
\int_{\mathbb B}|\nabla^t f|^2=2\pi\omega_{d-1}\frac{2^{2t-1}\Gamma^2(m+1)\Gamma(t+d/2)\Gamma(2m-2t+1)}{\Gamma^2(m-t+1)\Gamma(2m-t+1+d/2)}.
\end{equation}
\end{lem}

\begin{proof}
Setting $g(r)=(1-r^2)^m$, we have
$$
(-\Delta)^t f(x)=\left(-\fr 1 {r^{d-1}}\fr{\partial\ }{\partial r}\left(r^{d-1}\fr{\partial\ }
{\partial r}\right)\right)^t g(|x|),
$$
hence
$$
\int_{\mathbb B}|\nabla^t f|^2=\int_{\mathbb B}f(-\Delta)^t f=2\pi\omega_{d-1}\int_0^1g(r)\left(-\fr 1 {r^{d-1}}\fr{\partial\ }{\partial r}\left(r^{d-1}\fr{\partial\ }
{\partial r}\right)\right)^t g(r)r^{d-1}dr.
$$

We now observe that
\begin{equation}
\label{delta-f}
\left(\fr 1 {r^{d-1}}\fr{\partial\ }{\partial r}\left(r^{d-1}\fr{\partial\ }{\partial r}\right)\right)^t g(r)
=\sum_{h=t}^m\binom{m}{h}(-1)^{h}r^{2h-2t}\frac{(2h)!!}{(2h-2t)!!}\frac{(2h+d-2)!!}{(2h+d-2t-2)!!},
\end{equation}
from which we obtain
\begin{gather*}
\begin{array}{lll}
\dintd{0}{1}g(r)\left(-\fr 1 {r^{d-1}}\fr{\partial\ }{\partial r}\left(r^{d-1}\fr{\partial\ }{\partial r}\right)\right)^t g(r)r^{d-1}dr
& = & 2^{m+t}(m!)\dsum_{h=t}^m\binom{m}{h}(-1)^{h-t}\fr{h!}{(h-t)!}\frac{(2h+d-2)!!}{(2m+2h+d-2t-2)!!}\eqskip
& = & 2^{2t-1}\fr{(m!)^2}{(m-t)!}\dsum_{p=0}^{m-t}\binom{m-t}{p}\fr{(-1)^p}{\prod_{j=0}^{m-t}(t+p+d/2+j)}.
\end{array}
\end{gather*}
At this point we observe that, for any $p\ge 0$,
$$
\fr{1}{\prod_{j=0}^{m-t}(t+p+d/2+j)}=\fr{1}{\prod_{j=0}^{m-t}(t+d/2+j)}\frac{(t+d/2)_p}{(m+1+d/2)_p}=\fr{\Gamma(t+d/2)}{\Gamma(m+1+d/2)}\frac{(t+d/2)_p}{(m+1+d/2)_p},
$$
where $(a)_p$ is the usual Pochhammer symbol defined by $(a)_p={\ds \prod_{j=0}^{p-1}}(a+j)$. Now we use \cite[formula 15.2.4]{nist} to deduce that
$$
\sum_{p=0}^{m-t}\binom{m-t}{p}(-1)^{h-t}\fr{(-1)^p}{\prod_{j=0}^{m-t}(t+p+d/2+j)}=\frac{\Gamma(t+d/2)}{\Gamma(m+1+d/2)} F(-m+t,t+d/2;m+1+d/2;1),
$$
where $F(a,b;c;z)$ is the hypergeometric function, for which we recall~\cite[formula 15.4.20]{nist}
$$
F(a,b;c;1)=\fr{\Gamma(c)\Gamma(c-a-b)}{\Gamma(c-a)\Gamma(c-b)}\quad\text{if\ }c>a+b.
$$
Collecting all these formulas yields identity~\eqref{hypergeometric}.
\end{proof}


\begin{lem}
\label{fund}
Let $f(x)=(1-|x|^2)^m$. Then $f$ is an eigenfunction for~\eqref{auxbuck}, and its associated eigenvalue is
\begin{equation}\label{sigmaeigen}
\sigma=
\begin{cases}
\fr{(m+t)!!(m+t+d-2)!!}{(m-t)!!(m-t+d-2)!!}, & \text{ if } m-t \text{ is even},\eqskip
\fr{(m+t-1)!!(m+t+d-1)!!}{(m-t-1)!!(m-t+d-1)!!}, & \text{ if } m-t \text{ is odd}.
\end{cases}
\end{equation}
In particular, if $m=t$, then
$$
\sigma=
\fr{(2m)!!(2m+d-2)!!}{(d-2)!!}=2^{2m}\fr{\Gamma(m+1)\Gamma(m+d/2)}{\Gamma(d/2)},
$$
and for $d=1$,
$$
\sigma=
\begin{cases}
\fr{(m+t)!}{(m-t)!}, & \text{ if } m\neq t,\eqskip
(2m)!, & \text{ if } m=t.
\end{cases}
$$
\end{lem}


\begin{remark}
Denoting by $\left \lfloor{x}\right \rfloor $ the integer part of $x$, the value of $\sigma$ in~~\eqref{sigmaeigen} may be written as
$$
\sigma=2^{2t} \fr{\Gamma\left(\left\lfloor\frac{m+t+2}{2}\right\rfloor\right)\Gamma\left(\left\lfloor\frac{m+t+1}{2}\right\rfloor+\frac d 2\right)}{\Gamma\left(\left\lfloor\frac{m-t+2}{2}\right\rfloor\right)\Gamma\left(\left\lfloor\frac{m-t+1}{2}\right\rfloor+\frac d 2\right)},
$$
for all possible values of $m$ and $t$.
\end{remark}


\begin{proof}
From \eqref{delta-f} we already know that
$$
(-\Delta)^m f=\fr{(2m+d-2)!!(2m)!!}{(d-2)!!},
$$
so we are left with computing $(-1)^{m-t}\nabla^{m-t}\fr{1}{(1-|x|^2)^t}\nabla^{m-t}f$. We must distinguish two cases.

{\bf Case $m-t$ even.} Write $k=\fr{m-t}{2}$. We have to compute
$
(-1)^{m-t}\Delta_r^{k}\fr{1}{(1-r^2)^t}\Delta_r^{k}g,
$
where we have put $g(|x|)=f(x)$ and $\Delta_r=\left(\fr 1 {r^{d-1}}\fr{\partial\ }{\partial r}\left(r^{d-1}\fr{\partial\ }{\partial r}\right)\right)$.

We first show (by induction) that, if $m\ge 2k$, then
\begin{equation}
\label{evenoddcomp}
\Delta_r^{k}g(r) =(1-r^2)^{m-2k} P_k(r),
\end{equation}
where $P_k$ is an even polynomial of degree $2k$. Naturally the claim holds for $k=0$, so now we consider the claim valid for $k-1$. We have
\begin{equation*}
 \begin{array}{lll}
\Delta_r^{k}g(r) =\Delta_r(\Delta_r^{k-1}g(r)) & = & \Delta_r\left( (1-r^2)^{m-2k+2} P_{k-1}(r)\right)\eqskip
& = & (1-r^2)^{m-2k+2}\left(P_{k-1}''(r)+(d-1)r^{-1}P_{k-1}'(r)\right)\eqskip
& & \hspace*{5mm}-2(m+2k-2)(1-r^2)^{m-2k+1}\left(dP_{k-1}(r)+2rP_{k-1}'(r)\right)\eqskip
& & \hspace*{10mm} +4(m-2k+2)(m-2k+1)(1-r^2)^{m-2k}r^2P_{k-1}(r),
 \end{array}
\end{equation*}
proving the claim. Notice in particular that, since $P_{k-1}$ is even, then $P_{k-1}'$ is odd, meaning that  $r^{-1}P_{k-1}'(r)$ is an even polynomial.

It is now clear that  $\Delta_r^{k}\fr{1}{(1-r^2)^t}\Delta_r^{k}g$ will be a constant, hence we only have to keep track of the higher order monomial.
We will write $R(r)$ to indicate lower order terms that will eventually vanish. Employing formula~\eqref{delta-f}, we obtain
\begin{gather*}
\begin{array}{lll}
\Delta_r^{k}\fr{1}{(1-r^2)^t}\Delta_r^{k}g & = & \Delta_r^{k}\fr{1}{(1-r^2)^t}\Delta_r^{k} ((-1)^m r^{2m}+R(r))\eqskip
& = &(-1)^m \Delta_r^k\fr1{(1-r^2)^t}\left(r^{m+t}\dprod_{j=0}^{k-1}(2m-2j)\dprod_{j=1}^{k}(2m+d-2j)+R(r)\right)\eqskip
& = & (-1)^{m-t} \dprod_{j=0}^{k-1}(2m-2j)\dprod_{j=1}^{k}(2m+d-2j)\Delta_r^k\left(r^{m-t}+R(r)\right)\eqskip
%& = &(-1)^{m-t} \dprod_{j=0}^{k-1}(2m-2j)\dprod_{j=1}^{k}(2m+d-2j)\dprod_{j=0}^{k-1}(m-t-2j)\dprod_{j=1}^{k}(m-t+d-2j)\eqskip
& = & (-1)^{m-t}\fr{(2m)!!(2m+d-2)!!}{(m+t)!!(m+t+d-2)!!}(m-t)!!(m-t+d-2)!!\; .
\end{array}
\end{gather*}

{\bf Case $m-t$ odd.} Write $k=\fr{m-t-1}{2}$. We have to compute
$
(-1)^{m-t}\Delta_r^{k}r^{1-d}\partial_r\fr{r^{d-1}}{(1-r^2)^t}\partial_r\Delta_r^{k}g.
$
We first show that, if $m\ge 2k$, then
$$
\partial_r\Delta_r^{k}g(r) =(1-r^2)^{m-2k-1} r Q_k(r),
$$
where $Q_k$ is an even polynomial of degree $2k$. This follows directly from~\eqref{evenoddcomp}. 

It is now clear that  $\Delta_r^{k}r^{1-d}\partial_r\fr{r^{d-1}}{(1-r^2)^t}\partial_r\Delta_r^{k}g$ will be a constant, hence we only have to keep track of the higher order monomial.
We will write $R(r)$ to indicate lower order terms that will eventually vanish. Using formula~\eqref{delta-f}, we obtain
\begin{gather*}
 \begin{array}{lll}
\Delta_r^{k}r^{1-d}\partial_r\fr{r^{d-1}}{(1-r^2)^t}\partial_r\Delta_r^{k}g & = &\Delta_r^{k}r^{1-d}\partial_r\fr{r^{d-1}}{(1-r^2)^t}\partial_r\Delta_r^{k} ((-1)^m r^{2m}+R(r))\eqskip
& = & (-1)^m \Delta_r^kr^{1-d}\partial_r\fr{r^{d-1}}{(1-r^2)^t}\left((m+t+1)r^{m+t}\dprod_{j=0}^{k-1}(2m-2j)\dprod_{j=1}^{k}(2m+d-2j)+R(r)\right)\eqskip
& = & (-1)^{m-t} (m+t+1) (m-t+d-1)\dprod_{j=0}^{k-1}(2m-2j)\dprod_{j=1}^{k}(2m+d-2j)\Delta_r^k\left(r^{m-t-1}+R(r)\right)\eqskip
%& = & (-1)^{m-t} (m+t+1) (m-t+d-1)\dprod_{j=0}^{k-1}(2m-2j)\dprod_{j=1}^{k}(2m+d-2j)\eqskip
%& & \hspace*{5mm} \times \dprod_{j=0}^{k-1}(m-t-1-2j)\dprod_{j=1}^{k}(m-t-1+d-2j)\eqskip
& = & (-1)^{m-t}\fr{(2m)!!(2m+d-2)!!}{(m+t+1)!!(m+t+d-1)!!}(m-t-1)!!(m-t+d-1)!!.%\qedhere
\end{array}
\end{gather*}
\end{proof}





