%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Introduction}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Quasi-Hamiltonian geometry \cite{alekseev1998lie} can be thought of as a ``multiplicative analogue'' of Hamiltonian geometry \cite{marsden1974reduction}, where the dual $\g^*$ of the Lie algebra $\g$ is replaced by the group $G$ integrating $\g$.
As such, many natural spaces in Hamiltonian geometry have multiplicative analogues in quasi-Hamiltonian geometry.
A prominent example is the double $D(G) = G \times G$ of a Lie group $G$, which is a quasi-Hamiltonian $G \times G$-space analogous to the cotangent bundle $T^*G$.
Similarly, conjugacy classes in $G$ are quasi-Hamiltonian spaces analogous to the coadjoint orbits in $\g^*$ (see e.g.\ \cite{BM} and the references therein for more examples).
The goal of this paper is to connect such pairs via smooth deformations.

In more detail, we define a Hamiltonian deformation of a quasi-Hamiltonian $G$-space $M$ to a Hamiltonian $G$-space $N$ as a smooth $G$-manifold $\D$ with a submersion $\pi : \D \to \R$, a smooth family of $2$-forms $\widehat{\omega}_t$ on the fibers $\D_t = \pi^{-1}(t)$ and a ``moment map'' $\widehat{\mu} : \D \to (G \times \R^\times) \sqcup (\g \times \{0\})$ (where the codomain is the deformation space of $G$ at $1$ as defined in \S\ref{lq5uqbl3}), such that $\D_t$ smoothly interpolates from $M$ at $t = 1$ to $N$ at $t = 0$; see Definition \ref{swcoikg4} for the precise formulation.

We provide the following examples of Hamiltonian deformations.

\begin{Thm}
Let $G$ be a Lie group equipped with an invariant, non-degenerate, symmetric bilinear form on its Lie algebra $\g$.
\begin{enumerate}[label={\textup{(\roman*)}}]
\item
The double $D(G) = G \times G$ admits a Hamiltonian deformation to the cotangent bundle $T^*G$ \textup{(Theorem \ref{ikr142qd})}.
\item
Let $x \in \g$ be such that $d\exp_{tx}$ is invertible for all $t \in [0, 1]$.
Then the conjugacy class $C_{e^x} \subset G$ admits a Hamiltonian deformation to the coadjoint orbit $\O_x \subset \g \cong \g^*$ \textup{(Theorem \ref{thnlzgh9})}.
\item
Let $\Sigma$ be a compact connected oriented surface of genus $g$ with $r + 1$ boundary components and suppose that $G$ is compact.
The moduli space of flat $G$-connections on $\Sigma$ (resp.\ with holonomies on the boundaries in fixed conjugacy classes) admits a Hamiltonian deformation to $T^*G^{r+g}$ (resp.\ to a symplectic reduction of $T^*G^{r+g}$) \textup{(Corollary \ref{lstnw1kj} and Corollary \ref{rupcqbmj})}.
\end{enumerate}
\end{Thm}

The third part follows from more general results about deformations of fusion products and reductions.

\begin{Thm}
\
\begin{enumerate}[label={\textup{(\roman*)}}]
\item
\textbf{Fusion.}
Suppose that there are Hamiltonian deformations of quasi-Hamiltonian $G \times H_i$-spaces $M_i$ to Hamiltonian $G \times H_i$-spaces $N_i$ for $i = 1, 2$. 
Then there is a Hamiltonian deformation of the fusion product $M_1 \circledast M_2$ to $N_1 \times N_2$ \textup{(Corollary \ref{6mj8ptsk})}.
\item
\textbf{Reduction.}
Suppose that there is a Hamiltonian deformation of a quasi-Hamiltonian $G \times H$-space $M$ to a Hamiltonian $G \times H$-space $N$.
Under suitable conditions, the quasi-Hamiltonian reduction $M_{e^x}$ for $x \in \g$ admits a Hamiltonian deformation to the Hamiltonian reduction $N_x$ \textup{(Theorem \ref{oi2khfoe})}.
\end{enumerate}
\end{Thm}

